fn request_refreshes_visible_writes(request: &RestRequest) -> bool {
    request
        .query_params
        .get("refresh")
        .is_some_and(|value| value == "wait_for" || value == "true")
}

fn request_reports_forced_refresh(request: &RestRequest) -> bool {
    request
        .query_params
        .get("refresh")
        .is_some_and(|value| value == "true")
}

fn validate_doc_write_refresh_query_param(request: &RestRequest) -> Option<RestResponse> {
    let Some(raw) = request.query_params.get("refresh") else {
        return None;
    };
    if raw.is_empty() || raw == "true" || raw == "false" || raw == "wait_for" {
        return None;
    }
    let reason = format!("Failed to parse value [{raw}] for [refresh] as only [true], [false], or [wait_for] are allowed.");
    Some(RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "illegal_argument_exception",
                "reason": reason,
                "root_cause": [{
                    "type": "illegal_argument_exception",
                    "reason": reason,
                }],
            },
            "status": 400,
        }),
    ))
}

fn tier_route_is_feature_flag_disabled(path: &str, method: RestMethod) -> bool {
    if path == "/_tier/all" && method == RestMethod::Get {
        return true;
    }
    if path
        .trim_matches('/')
        .strip_suffix("/_tier")
        .is_some_and(|index| !index.is_empty())
        && method == RestMethod::Get
    {
        return true;
    }
    if path
        .trim_matches('/')
        .split_once("/_tier/")
        .is_some_and(|(index, target_tier)| !index.is_empty() && !target_tier.is_empty())
        && method == RestMethod::Post
    {
        return true;
    }
    path.trim_matches('/')
        .strip_prefix("_tier/_cancel/")
        .is_some_and(|index| !index.is_empty())
        && method == RestMethod::Post
}

fn feature_flag_disabled_tier_route_response(path: &str, method: RestMethod) -> RestResponse {
    RestResponse::json(
        400,
        serde_json::json!({
            "error": format!("no handler found for uri [{path}] and method [{}]", method.as_str())
        }),
    )
}

fn seq_primary_term_conflict_reason(
    id: &str,
    expected_seq_no: Option<i64>,
    expected_primary_term: Option<i64>,
    current: Option<&StoredDocument>,
) -> String {
    let required_seq_no = expected_seq_no.unwrap_or(-2);
    let required_primary_term = expected_primary_term.unwrap_or(0);
    match current {
        Some(record) => format!(
            "[{id}]: version conflict, required seqNo [{required_seq_no}], primary term [{required_primary_term}]. current document has seqNo [{}] and primary term [{}]",
            record.seq_no, record.primary_term
        ),
        None => format!(
            "[{id}]: version conflict, required seqNo [{required_seq_no}], primary term [{required_primary_term}]. but no document was found"
        ),
    }
}

