#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct DiscoveryPeer {
    pub node_id: String,
    pub node_name: String,
    pub host: String,
    pub port: u16,
    pub cluster_name: String,
    pub cluster_uuid: String,
    pub version: Version,
    pub cluster_manager_eligible: bool,
    pub membership_epoch: u64,
}

impl DiscoveryPeer {
    pub fn transport_address(&self) -> String {
        format!("{}:{}", self.host, self.port)
    }
}

fn is_placeholder_seed_node_id(node_id: &str) -> bool {
    node_id.starts_with("seed-")
}

fn initial_voting_configuration(
    config: &DiscoveryConfig,
    joined: &[DiscoveryPeer],
) -> BTreeSet<String> {
    if !config.cluster_manager_eligible {
        return BTreeSet::new();
    }
    let mut voting = BTreeSet::from([config.local_node_id.clone()]);
    for peer in joined {
        if peer.cluster_manager_eligible && !is_placeholder_seed_node_id(&peer.node_id) {
            voting.insert(peer.node_id.clone());
        }
    }
    voting
}

impl Default for DiscoveryPeer {
    fn default() -> Self {
        Self {
            node_id: String::new(),
            node_name: String::new(),
            host: String::new(),
            port: 0,
            cluster_name: String::new(),
            cluster_uuid: String::new(),
            version: Version::from_id(0),
            cluster_manager_eligible: false,
            membership_epoch: 0,
        }
    }
}

