#[derive(Clone, Debug, Default, Eq, PartialEq, Serialize, Deserialize)]
pub struct ClusterCoordinationState {
    pub current_term: i64,
    pub last_accepted_version: i64,
    pub last_accepted_state_uuid: String,
    pub cluster_manager_node_id: Option<String>,
    pub last_accepted_voting_configuration: BTreeSet<String>,
    pub last_committed_voting_configuration: BTreeSet<String>,
    pub voting_config_exclusions: BTreeSet<String>,
    pub liveness: LivenessState,
    pub fault_detection: CoordinationFaultDetectionState,
    pub joined: Vec<DiscoveryPeer>,
    pub pending_voting_config_additions: BTreeSet<String>,
    #[serde(default)]
    pub pending_voting_config_removals: BTreeSet<String>,
    pub active_publication_round: Option<CompletedPublicationRound>,
    pub last_completed_publication_round: Option<CompletedPublicationRound>,
}

impl ClusterCoordinationState {
    fn lagging_publication_catch_up_targets(
        round: &CompletedPublicationRound,
        local_node_id: &str,
    ) -> BTreeSet<String> {
        round
            .missing_nodes
            .iter()
            .chain(round.apply_transport_failures.keys())
            .filter(|node_id| node_id.as_str() != local_node_id)
            .filter(|node_id| round.target_nodes.contains(*node_id))
            .filter(|node_id| !round.proposal_transport_failures.contains_key(*node_id))
            .filter(|node_id| {
                !round
                    .acknowledgement_transport_failures
                    .contains_key(*node_id)
            })
            .cloned()
            .collect()
    }

    fn publication_round_is_complete(round: &CompletedPublicationRound) -> bool {
        round.committed
            && round.missing_nodes.is_empty()
            && round.proposal_transport_failures.is_empty()
            && round.acknowledgement_transport_failures.is_empty()
            && round.apply_transport_failures.is_empty()
            && round.target_nodes.is_subset(&round.applied_nodes)
    }

    fn rewrite_publication_round_node_id(
        round: &mut CompletedPublicationRound,
        old_id: &str,
        new_id: &str,
    ) {
        fn rewrite_set(values: &mut BTreeSet<String>, old_id: &str, new_id: &str) {
            if values.remove(old_id) {
                values.insert(new_id.to_string());
            }
        }

        fn rewrite_map(values: &mut BTreeMap<String, String>, old_id: &str, new_id: &str) {
            if let Some(value) = values.remove(old_id) {
                values.insert(new_id.to_string(), value);
            }
        }

        rewrite_set(&mut round.target_nodes, old_id, new_id);
        rewrite_set(&mut round.acknowledged_nodes, old_id, new_id);
        rewrite_set(&mut round.applied_nodes, old_id, new_id);
        rewrite_set(&mut round.missing_nodes, old_id, new_id);
        rewrite_map(&mut round.proposal_transport_failures, old_id, new_id);
        rewrite_map(
            &mut round.acknowledgement_transport_failures,
            old_id,
            new_id,
        );
        rewrite_map(&mut round.apply_transport_failures, old_id, new_id);
    }

    fn rewrite_member_identity(&mut self, old_id: &str, new_id: &str) {
        if self.cluster_manager_node_id.as_deref() == Some(old_id) {
            self.cluster_manager_node_id = Some(new_id.to_string());
        }
        if self.last_accepted_voting_configuration.remove(old_id) {
            self.last_accepted_voting_configuration
                .insert(new_id.to_string());
        }
        if self.last_committed_voting_configuration.remove(old_id) {
            self.last_committed_voting_configuration
                .insert(new_id.to_string());
        }
        if self.pending_voting_config_additions.remove(old_id) {
            self.pending_voting_config_additions
                .insert(new_id.to_string());
        }
        if self.pending_voting_config_removals.remove(old_id) {
            self.pending_voting_config_removals
                .insert(new_id.to_string());
        }
        if let Some(round) = self.active_publication_round.as_mut() {
            Self::rewrite_publication_round_node_id(round, old_id, new_id);
        }
        if let Some(round) = self.last_completed_publication_round.as_mut() {
            Self::rewrite_publication_round_node_id(round, old_id, new_id);
        }
        if let Some(tick) = self.fault_detection.leader_nodes.remove(old_id) {
            self.fault_detection
                .leader_nodes
                .insert(new_id.to_string(), tick);
        }
        if let Some(tick) = self.liveness.leader_checks.remove(old_id) {
            self.liveness.leader_checks.insert(new_id.to_string(), tick);
        }
    }

    fn effective_accepted_voting_nodes(&self) -> BTreeSet<String> {
        self.last_accepted_voting_configuration
            .iter()
            .filter(|node_id| !self.voting_config_exclusions.contains(*node_id))
            .cloned()
            .collect()
    }

    fn effective_committed_voting_nodes(&self) -> BTreeSet<String> {
        self.last_committed_voting_configuration
            .iter()
            .filter(|node_id| !self.voting_config_exclusions.contains(*node_id))
            .cloned()
            .collect()
    }

    fn quorum_for_voting_nodes(nodes: &BTreeSet<String>) -> u64 {
        let eligible = nodes.len().max(1) as u64;
        (eligible / 2) + 1
    }

    fn required_quorum(&self) -> u64 {
        Self::quorum_for_voting_nodes(&self.effective_accepted_voting_nodes()).max(
            Self::quorum_for_voting_nodes(&self.effective_committed_voting_nodes()),
        )
    }

    fn joint_quorum_satisfied_by(&self, voters: &BTreeSet<String>) -> bool {
        let accepted = self.effective_accepted_voting_nodes();
        let committed = self.effective_committed_voting_nodes();
        Self::joint_quorum_satisfied_for(&accepted, &committed, voters)
    }

    fn joint_quorum_satisfied_for(
        accepted: &BTreeSet<String>,
        committed: &BTreeSet<String>,
        voters: &BTreeSet<String>,
    ) -> bool {
        let accepted_votes = voters.intersection(&accepted).count() as u64;
        let committed_votes = voters.intersection(&committed).count() as u64;
        accepted_votes >= Self::quorum_for_voting_nodes(&accepted)
            && committed_votes >= Self::quorum_for_voting_nodes(&committed)
    }

    pub fn bootstrap(config: &DiscoveryConfig) -> Self {
        let mut joined = config.seed_peers.clone();
        joined.push(DiscoveryPeer {
            node_id: config.local_node_id.clone(),
            node_name: config.local_node_name.clone(),
            host: "127.0.0.1".to_string(),
            port: 0,
            cluster_name: config.cluster_name.clone(),
            cluster_uuid: config.cluster_uuid.clone(),
            version: config.local_version,
            cluster_manager_eligible: config.cluster_manager_eligible,
            membership_epoch: config.local_membership_epoch,
        });
        let voting_configuration = initial_voting_configuration(config, &joined);
        Self {
            current_term: 0,
            last_accepted_version: 0,
            last_accepted_state_uuid: String::new(),
            cluster_manager_node_id: Some(config.local_node_id.clone()),
            last_accepted_voting_configuration: voting_configuration.clone(),
            last_committed_voting_configuration: voting_configuration,
            voting_config_exclusions: BTreeSet::new(),
            liveness: LivenessState::default(),
            fault_detection: CoordinationFaultDetectionState::default(),
            joined,
            pending_voting_config_additions: BTreeSet::new(),
            pending_voting_config_removals: BTreeSet::new(),
            active_publication_round: None,
            last_completed_publication_round: None,
        }
    }

    pub fn restore_publication_state(&mut self, state: PersistedPublicationState) {
        self.current_term = state.current_term;
        self.last_accepted_version = state.last_accepted_version;
        self.last_accepted_state_uuid = state.last_accepted_state_uuid;
        self.cluster_manager_node_id = state.cluster_manager_node_id;
        self.last_accepted_voting_configuration = state.last_accepted_voting_configuration;
        self.last_committed_voting_configuration = state.last_committed_voting_configuration;
        self.voting_config_exclusions = state.voting_config_exclusions;
        self.liveness.local_fence_reason = state.local_fence_reason;
        self.liveness.quorum_lost_at_tick = state.quorum_lost_at_tick;
        self.fault_detection = state.fault_detection;
        self.active_publication_round =
            state
                .active_publication_round
                .map(|round| CompletedPublicationRound {
                    version: round.version,
                    state_uuid: round.state_uuid,
                    term: round.term,
                    target_nodes: round.target_nodes,
                    acknowledged_nodes: round.acknowledged_nodes,
                    applied_nodes: round.applied_nodes,
                    missing_nodes: round.missing_nodes,
                    proposal_transport_failures: round.proposal_transport_failures,
                    acknowledgement_transport_failures: round.acknowledgement_transport_failures,
                    apply_transport_failures: round.apply_transport_failures,
                    required_quorum: round.required_quorum,
                    committed: round.committed,
                });
        self.last_completed_publication_round =
            state
                .last_completed_publication_round
                .map(|round| CompletedPublicationRound {
                    version: round.version,
                    state_uuid: round.state_uuid,
                    term: round.term,
                    target_nodes: round.target_nodes,
                    acknowledged_nodes: round.acknowledged_nodes,
                    applied_nodes: round.applied_nodes,
                    missing_nodes: round.missing_nodes,
                    proposal_transport_failures: round.proposal_transport_failures,
                    acknowledgement_transport_failures: round.acknowledgement_transport_failures,
                    apply_transport_failures: round.apply_transport_failures,
                    required_quorum: round.required_quorum,
                    committed: round.committed,
                });
    }

    pub fn capture_publication_state(&self) -> PersistedPublicationState {
        PersistedPublicationState {
            current_term: self.current_term,
            last_accepted_version: self.last_accepted_version,
            last_accepted_state_uuid: self.last_accepted_state_uuid.clone(),
            cluster_manager_node_id: self.cluster_manager_node_id.clone(),
            last_accepted_voting_configuration: self.last_accepted_voting_configuration.clone(),
            last_committed_voting_configuration: self.last_committed_voting_configuration.clone(),
            voting_config_exclusions: self.voting_config_exclusions.clone(),
            active_publication_round: self.active_publication_round.clone().map(|round| {
                PublicationRoundState {
                    version: round.version,
                    state_uuid: round.state_uuid,
                    term: round.term,
                    target_nodes: round.target_nodes,
                    acknowledged_nodes: round.acknowledged_nodes,
                    applied_nodes: round.applied_nodes,
                    missing_nodes: round.missing_nodes,
                    proposal_transport_failures: round.proposal_transport_failures,
                    acknowledgement_transport_failures: round.acknowledgement_transport_failures,
                    apply_transport_failures: round.apply_transport_failures,
                    required_quorum: round.required_quorum,
                    committed: round.committed,
                }
            }),
            last_completed_publication_round: self.last_completed_publication_round.clone().map(
                |round| PublicationRoundState {
                    version: round.version,
                    state_uuid: round.state_uuid,
                    term: round.term,
                    target_nodes: round.target_nodes,
                    acknowledged_nodes: round.acknowledged_nodes,
                    applied_nodes: round.applied_nodes,
                    missing_nodes: round.missing_nodes,
                    proposal_transport_failures: round.proposal_transport_failures,
                    acknowledgement_transport_failures: round.acknowledgement_transport_failures,
                    apply_transport_failures: round.apply_transport_failures,
                    required_quorum: round.required_quorum,
                    committed: round.committed,
                },
            ),
            local_fence_reason: self.liveness.local_fence_reason.clone(),
            quorum_lost_at_tick: self.liveness.quorum_lost_at_tick,
            fault_detection: self.fault_detection.clone(),
        }
    }

    pub fn elect_cluster_manager_with_live_pre_votes(
        &mut self,
        config: &DiscoveryConfig,
        local_node_id: &str,
        _connect_timeout: Duration,
    ) -> ElectionResult {
        self.current_term = self.current_term.saturating_add(1).max(1);
        let votes = BTreeSet::from([config.local_node_id.clone()]);
        let elected_node_id = self
            .joint_quorum_satisfied_by(&votes)
            .then(|| local_node_id.to_string());
        self.cluster_manager_node_id = elected_node_id.clone();
        ElectionResult {
            elected_node_id,
            term: self.current_term,
            votes,
            required_quorum: self.required_quorum(),
        }
    }

    pub fn joined_nodes(&self) -> Vec<DiscoveryPeer> {
        self.joined.clone()
    }

    pub fn join_peer(
        &mut self,
        _config: &DiscoveryConfig,
        peer: DiscoveryPeer,
    ) -> std::io::Result<()> {
        if let Some(existing_index) = self
            .joined
            .iter()
            .position(|existing| existing.transport_address() == peer.transport_address())
        {
            let old_id = self.joined[existing_index].node_id.clone();
            let old_was_placeholder = is_placeholder_seed_node_id(&old_id);
            if old_id != peer.node_id {
                if old_was_placeholder {
                    if peer.cluster_manager_eligible {
                        self.pending_voting_config_additions
                            .insert(peer.node_id.clone());
                    }
                } else {
                    self.rewrite_member_identity(&old_id, &peer.node_id);
                }
            }
            self.joined[existing_index] = peer;
        } else if !self
            .joined
            .iter()
            .any(|existing| existing.node_id == peer.node_id)
        {
            self.joined.push(peer);
        }
        Ok(())
    }

    pub fn remove_joined_peer(&mut self, node_id: &str) -> std::io::Result<bool> {
        let before = self.joined.len();
        self.joined.retain(|peer| peer.node_id != node_id);
        Ok(self.joined.len() != before)
    }

    pub fn propose_voting_config_addition(&mut self, _node_id: &str) -> std::io::Result<()> {
        self.pending_voting_config_additions
            .insert(_node_id.to_string());
        self.pending_voting_config_removals.remove(_node_id);
        Ok(())
    }

    pub fn propose_voting_config_removal(&mut self, node_id: &str) -> std::io::Result<()> {
        self.pending_voting_config_removals
            .insert(node_id.to_string());
        self.pending_voting_config_additions.remove(node_id);
        Ok(())
    }

    pub fn apply_voting_config_reconfiguration_proposals(&mut self) {
        let pending: Vec<String> = self
            .pending_voting_config_additions
            .iter()
            .cloned()
            .collect();
        for node_id in pending {
            let is_eligible = self
                .joined
                .iter()
                .any(|peer| peer.node_id == node_id && peer.cluster_manager_eligible);
            if is_eligible {
                self.last_accepted_voting_configuration
                    .insert(node_id.clone());
            }
            self.pending_voting_config_additions.remove(&node_id);
        }
        let pending: Vec<String> = self
            .pending_voting_config_removals
            .iter()
            .cloned()
            .collect();
        for node_id in pending {
            self.last_accepted_voting_configuration.remove(&node_id);
            self.pending_voting_config_removals.remove(&node_id);
        }
    }

    pub fn rollback_voting_config_reconfiguration_proposals(&mut self) {
        let had_pending_reconfiguration = !self.pending_voting_config_additions.is_empty()
            || !self.pending_voting_config_removals.is_empty();
        self.pending_voting_config_additions.clear();
        self.pending_voting_config_removals.clear();
        if !had_pending_reconfiguration
            && self.last_accepted_voting_configuration != self.last_committed_voting_configuration
        {
            self.last_accepted_voting_configuration =
                self.last_committed_voting_configuration.clone();
            self.voting_config_exclusions
                .retain(|node_id| self.last_committed_voting_configuration.contains(node_id));
        }
    }

    pub fn publish_committed_state(
        &mut self,
        state_uuid: String,
        version: i64,
        mut target_nodes: BTreeSet<String>,
    ) -> PublicationCommit {
        if version <= self.last_accepted_version {
            return PublicationCommit {
                committed: false,
                acked_nodes: BTreeSet::new(),
                missing_nodes: target_nodes,
            };
        }
        target_nodes.retain(|node_id| !self.voting_config_exclusions.contains(node_id));
        let required_quorum = self.required_quorum();
        let committed = self.joint_quorum_satisfied_by(&target_nodes);
        if let Some(active_round) = self
            .active_publication_round
            .take()
            .filter(Self::publication_round_is_complete)
        {
            self.last_completed_publication_round = Some(active_round);
        }
        if committed {
            self.last_committed_voting_configuration =
                self.last_accepted_voting_configuration.clone();
            self.voting_config_exclusions
                .retain(|node_id| self.last_committed_voting_configuration.contains(node_id));
        }
        self.last_accepted_version = version;
        self.last_accepted_state_uuid = state_uuid.clone();
        self.active_publication_round = Some(CompletedPublicationRound {
            version,
            state_uuid: state_uuid.clone(),
            term: self.current_term,
            target_nodes: target_nodes.clone(),
            acknowledged_nodes: target_nodes.clone(),
            applied_nodes: BTreeSet::new(),
            missing_nodes: BTreeSet::new(),
            proposal_transport_failures: BTreeMap::new(),
            acknowledgement_transport_failures: BTreeMap::new(),
            apply_transport_failures: BTreeMap::new(),
            required_quorum,
            committed,
        });
        PublicationCommit {
            committed,
            acked_nodes: target_nodes,
            missing_nodes: BTreeSet::new(),
        }
    }

    pub fn publish_transport_publication_round(
        &mut self,
        state_uuid: String,
        version: i64,
        mut target_nodes: BTreeSet<String>,
        mut acknowledged_nodes: BTreeSet<String>,
    ) -> PublicationCommit {
        if version <= self.last_accepted_version {
            return PublicationCommit {
                committed: false,
                acked_nodes: BTreeSet::new(),
                missing_nodes: target_nodes,
            };
        }
        target_nodes.retain(|node_id| !self.voting_config_exclusions.contains(node_id));
        acknowledged_nodes.retain(|node_id| target_nodes.contains(node_id));
        let required_quorum = self.required_quorum();
        let committed = self.joint_quorum_satisfied_by(&acknowledged_nodes);
        if let Some(active_round) = self
            .active_publication_round
            .take()
            .filter(Self::publication_round_is_complete)
        {
            self.last_completed_publication_round = Some(active_round);
        }
        if committed {
            self.last_committed_voting_configuration =
                self.last_accepted_voting_configuration.clone();
            self.voting_config_exclusions
                .retain(|node_id| self.last_committed_voting_configuration.contains(node_id));
        }
        self.last_accepted_version = version;
        self.last_accepted_state_uuid = state_uuid.clone();
        self.active_publication_round = Some(CompletedPublicationRound {
            version,
            state_uuid: state_uuid.clone(),
            term: self.current_term,
            target_nodes: target_nodes.clone(),
            acknowledged_nodes: acknowledged_nodes.clone(),
            applied_nodes: BTreeSet::new(),
            missing_nodes: target_nodes
                .difference(&acknowledged_nodes)
                .cloned()
                .collect(),
            proposal_transport_failures: BTreeMap::new(),
            acknowledgement_transport_failures: BTreeMap::new(),
            apply_transport_failures: BTreeMap::new(),
            required_quorum,
            committed,
        });
        PublicationCommit {
            committed,
            acked_nodes: acknowledged_nodes,
            missing_nodes: target_nodes,
        }
    }

    pub fn record_publication_proposal_transport_failure(&mut self, node_id: &str, reason: String) {
        let accepted = self.effective_accepted_voting_nodes();
        let committed_config = self.effective_committed_voting_nodes();
        if let Some(round) = self.active_publication_round.as_mut() {
            if !round.target_nodes.contains(node_id) {
                return;
            }
            round.missing_nodes.insert(node_id.to_string());
            round.acknowledged_nodes.remove(node_id);
            round
                .proposal_transport_failures
                .insert(node_id.to_string(), reason);
            round.committed = Self::joint_quorum_satisfied_for(
                &accepted,
                &committed_config,
                &round.acknowledged_nodes,
            );
        }
    }

    pub fn record_publication_acknowledgement_transport_failure(
        &mut self,
        node_id: &str,
        reason: String,
    ) {
        let accepted = self.effective_accepted_voting_nodes();
        let committed_config = self.effective_committed_voting_nodes();
        if let Some(round) = self.active_publication_round.as_mut() {
            if !round.target_nodes.contains(node_id) {
                return;
            }
            round.missing_nodes.insert(node_id.to_string());
            round.acknowledged_nodes.remove(node_id);
            round
                .acknowledgement_transport_failures
                .insert(node_id.to_string(), reason);
            round.committed = Self::joint_quorum_satisfied_for(
                &accepted,
                &committed_config,
                &round.acknowledged_nodes,
            );
        }
    }

    pub fn record_publication_apply_transport_failure(&mut self, node_id: &str, reason: String) {
        if let Some(round) = self.active_publication_round.as_mut() {
            if !round.target_nodes.contains(node_id) {
                return;
            }
            round.missing_nodes.insert(node_id.to_string());
            round.applied_nodes.remove(node_id);
            round
                .apply_transport_failures
                .insert(node_id.to_string(), reason);
        }
    }

    pub fn record_publication_apply(&mut self, node_id: &str) -> bool {
        if let Some(round) = self.active_publication_round.as_mut() {
            if !round.committed
                || !round.target_nodes.contains(node_id)
                || round.proposal_transport_failures.contains_key(node_id)
                || round
                    .acknowledgement_transport_failures
                    .contains_key(node_id)
                || round.apply_transport_failures.contains_key(node_id)
            {
                return false;
            }
            round.missing_nodes.remove(node_id);
            round.applied_nodes.insert(node_id.to_string());
            return true;
        }
        false
    }

    pub fn last_completed_publication_round(&self) -> Option<&CompletedPublicationRound> {
        self.last_completed_publication_round.as_ref()
    }

    pub fn active_publication_round(&self) -> Option<&CompletedPublicationRound> {
        self.active_publication_round.as_ref()
    }

    pub fn catch_up_rejoining_follower_publication(
        &mut self,
        node_id: &str,
    ) -> Option<PublicationCatchUpResult> {
        let round = self.active_publication_round.as_mut()?;
        if !round.committed
            || !round.target_nodes.contains(node_id)
            || round.proposal_transport_failures.contains_key(node_id)
            || round
                .acknowledgement_transport_failures
                .contains_key(node_id)
            || round.apply_transport_failures.contains_key(node_id)
        {
            return None;
        }

        let applied = round.applied_nodes.insert(node_id.to_string());
        round.missing_nodes.remove(node_id);
        Some(PublicationCatchUpResult {
            node_id: node_id.to_string(),
            version: round.version,
            state_uuid: round.state_uuid.clone(),
            applied,
        })
    }

    pub fn catch_up_lagging_follower_publication(
        &mut self,
        node_id: &str,
    ) -> Option<PublicationCatchUpResult> {
        let committed_by_acknowledgement = self
            .active_publication_round
            .as_ref()
            .is_some_and(|round| self.joint_quorum_satisfied_by(&round.acknowledged_nodes));
        let round = self.active_publication_round.as_mut()?;
        if (!round.committed && !committed_by_acknowledgement)
            || !round.target_nodes.contains(node_id)
            || round.proposal_transport_failures.contains_key(node_id)
            || round
                .acknowledgement_transport_failures
                .contains_key(node_id)
        {
            return None;
        }

        round.apply_transport_failures.remove(node_id);
        round.missing_nodes.remove(node_id);
        let applied = round.applied_nodes.insert(node_id.to_string());
        round.committed = true;
        Some(PublicationCatchUpResult {
            node_id: node_id.to_string(),
            version: round.version,
            state_uuid: round.state_uuid.clone(),
            applied,
        })
    }

    pub fn catch_up_reachable_lagging_publication_followers(
        &mut self,
        config: &DiscoveryConfig,
        connect_timeout: Duration,
    ) -> Vec<PublicationCatchUpResult> {
        let Some(round) = self.active_publication_round.as_ref() else {
            return Vec::new();
        };
        let lagging_targets =
            Self::lagging_publication_catch_up_targets(round, &config.local_node_id);
        if lagging_targets.is_empty() {
            return Vec::new();
        }

        let reachable_lagging_targets = self
            .joined
            .iter()
            .filter(|peer| lagging_targets.contains(&peer.node_id))
            .filter(|peer| {
                let Ok(address) = format!("{}:{}", peer.host, peer.port).parse() else {
                    return false;
                };
                std::net::TcpStream::connect_timeout(&address, connect_timeout).is_ok()
            })
            .map(|peer| peer.node_id.clone())
            .collect::<Vec<_>>();

        let results = reachable_lagging_targets
            .into_iter()
            .filter_map(|node_id| self.catch_up_lagging_follower_publication(&node_id))
            .collect::<Vec<_>>();
        for result in &results {
            self.liveness
                .publication_catch_up_due_ticks
                .remove(&result.node_id);
            self.liveness
                .publication_catch_up_attempts
                .remove(&result.node_id);
        }
        results
    }

    pub fn schedule_lagging_publication_catch_up(
        &mut self,
        local_node_id: &str,
        tick: u64,
    ) -> Vec<PublicationCatchUpScheduleResult> {
        let Some(round) = self.active_publication_round.as_ref() else {
            return Vec::new();
        };
        let lagging_targets = Self::lagging_publication_catch_up_targets(round, local_node_id);
        let version = round.version;
        let state_uuid = round.state_uuid.clone();
        self.liveness
            .publication_catch_up_due_ticks
            .retain(|node_id, _| lagging_targets.contains(node_id));
        self.liveness
            .publication_catch_up_attempts
            .retain(|node_id, _| lagging_targets.contains(node_id));

        let mut scheduled = Vec::new();
        for node_id in lagging_targets {
            if self
                .liveness
                .publication_catch_up_due_ticks
                .get(&node_id)
                .is_some_and(|existing_due_tick| *existing_due_tick > tick)
            {
                continue;
            }
            let attempts = self
                .liveness
                .publication_catch_up_attempts
                .entry(node_id.clone())
                .and_modify(|attempts| *attempts = attempts.saturating_add(1))
                .or_insert(1);
            if *attempts > PUBLICATION_CATCH_UP_MAX_ATTEMPTS {
                continue;
            }
            let delay = PUBLICATION_CATCH_UP_BASE_DELAY_TICKS
                .checked_shl(attempts.saturating_sub(1).min(6) as u32)
                .unwrap_or(PUBLICATION_CATCH_UP_BASE_DELAY_TICKS);
            let due_tick = tick.saturating_add(delay);
            self.liveness
                .publication_catch_up_due_ticks
                .insert(node_id.clone(), due_tick);
            scheduled.push(PublicationCatchUpScheduleResult {
                node_id,
                due_tick,
                attempts: *attempts,
                version,
                state_uuid: state_uuid.clone(),
            });
        }
        scheduled
    }

    pub fn has_pending_lagging_publication_catch_up(&self, local_node_id: &str, tick: u64) -> bool {
        let Some(round) = self.active_publication_round.as_ref() else {
            return false;
        };
        let lagging_targets = Self::lagging_publication_catch_up_targets(round, local_node_id);
        lagging_targets.iter().any(|node_id| {
            self.liveness
                .publication_catch_up_due_ticks
                .get(node_id)
                .is_some_and(|due_tick| *due_tick > tick)
        })
    }

    pub fn retry_publication_after_failed_node_left(
        &mut self,
        cluster_uuid: &str,
        local_node_id: &str,
    ) -> Option<PublicationCommit> {
        let failed_nodes = self.active_publication_round.as_ref().map(|round| {
            round
                .missing_nodes
                .iter()
                .chain(round.proposal_transport_failures.keys())
                .chain(round.acknowledgement_transport_failures.keys())
                .chain(round.apply_transport_failures.keys())
                .filter(|node_id| node_id.as_str() != local_node_id)
                .cloned()
                .collect::<BTreeSet<_>>()
        })?;

        if failed_nodes.is_empty() {
            return None;
        }

        for node_id in failed_nodes {
            let _ = self.remove_joined_peer(&node_id);
            let _ = self.propose_voting_config_removal(&node_id);
            self.fault_detection.leader_nodes.remove(&node_id);
            self.liveness.leader_checks.remove(&node_id);
            self.liveness
                .publication_catch_up_due_ticks
                .remove(&node_id);
            self.liveness.publication_catch_up_attempts.remove(&node_id);
        }
        self.apply_voting_config_reconfiguration_proposals();

        let next_version = self.last_accepted_version.saturating_add(1);
        let state_uuid = format!("{cluster_uuid}-dev-state-{next_version}");
        let mut target_nodes = self.effective_accepted_voting_nodes();
        if self
            .effective_committed_voting_nodes()
            .contains(local_node_id)
            || target_nodes.is_empty()
        {
            target_nodes.insert(local_node_id.to_string());
        }
        Some(self.publish_committed_state(state_uuid, next_version, target_nodes))
    }

    pub fn apply_live_transport_liveness_checks(
        &mut self,
        config: &DiscoveryConfig,
        tick: u64,
        _connect_timeout: Duration,
    ) {
        if self.liveness.local_fence_reason.is_some() {
            return;
        }
        let Some(manager_node_id) = self.cluster_manager_node_id.clone() else {
            return;
        };

        if manager_node_id == config.local_node_id {
            let mut reachable_voters = BTreeSet::new();
            if self
                .effective_accepted_voting_nodes()
                .contains(&config.local_node_id)
                || self
                    .effective_committed_voting_nodes()
                    .contains(&config.local_node_id)
            {
                reachable_voters.insert(config.local_node_id.clone());
            }
            reachable_voters.extend(
                self.joined
                    .iter()
                    .filter(|peer| {
                        peer.node_id != config.local_node_id && peer.cluster_manager_eligible
                    })
                    .filter(|peer| {
                        let Ok(address) = format!("{}:{}", peer.host, peer.port).parse() else {
                            return false;
                        };
                        std::net::TcpStream::connect_timeout(&address, _connect_timeout).is_ok()
                    })
                    .map(|peer| peer.node_id.clone()),
            );
            if !self.joint_quorum_satisfied_by(&reachable_voters) {
                self.liveness.record_quorum_loss(
                    tick,
                    format!(
                        "leader lost live voter quorum against manager [{}]: reachable_voters={} required_quorum={}",
                        manager_node_id,
                        reachable_voters.len(),
                        self.required_quorum()
                    ),
                );
            }
            return;
        }

        self.liveness
            .leader_checks
            .insert(manager_node_id.clone(), tick);

        let manager_faulted = self
            .fault_detection
            .leader_nodes
            .get(&manager_node_id)
            .is_some_and(|record| record.phase == CoordinationFaultPhase::Faulted);
        if manager_faulted || tick >= 2 {
            self.liveness.record_quorum_loss(
                tick,
                format!(
                    "leader check failed repeatedly against manager [{}]",
                    manager_node_id
                ),
            );
        }
    }

    pub fn apply_publication_health_to_liveness(&mut self, local_node_id: &str, tick: u64) {
        if self.liveness.local_fence_reason.is_some() {
            return;
        }

        let Some(round) = self.active_publication_round.as_ref() else {
            return;
        };

        let failed_nodes: BTreeSet<String> = round
            .missing_nodes
            .iter()
            .chain(round.proposal_transport_failures.keys())
            .chain(round.acknowledgement_transport_failures.keys())
            .chain(round.apply_transport_failures.keys())
            .cloned()
            .collect();

        if failed_nodes.is_empty() {
            return;
        }

        let manager_node_id = self
            .cluster_manager_node_id
            .clone()
            .unwrap_or_else(|| local_node_id.to_string());
        let local_is_manager = manager_node_id == local_node_id;
        let applied_quorum = self.joint_quorum_satisfied_by(&round.applied_nodes);
        let target_quorum = self.joint_quorum_satisfied_by(&round.target_nodes);

        if local_is_manager {
            for node_id in &failed_nodes {
                if node_id != local_node_id {
                    self.fault_detection.record_leader_failure(
                        node_id,
                        tick,
                        format!(
                            "publication round {} failed for follower [{}]",
                            round.version, node_id
                        ),
                    );
                }
            }

            if !target_quorum || !applied_quorum {
                self.liveness.record_quorum_loss(
                    tick,
                    format!(
                        "publication round {} failed: committed={} target_quorum={} applied_quorum={} failed_nodes={}",
                        round.version,
                        round.committed,
                        target_quorum,
                        applied_quorum,
                        failed_nodes.iter().cloned().collect::<Vec<_>>().join(",")
                    ),
                );
            }
            return;
        }

        if failed_nodes.contains(local_node_id) || !round.committed {
            self.fault_detection.record_leader_failure(
                &manager_node_id,
                tick,
                format!(
                    "publication round {} failed from manager [{}]",
                    round.version, manager_node_id
                ),
            );
            self.liveness.record_quorum_loss(
                tick,
                format!(
                    "publication round {} failed from manager [{}]",
                    round.version, manager_node_id
                ),
            );
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct DevelopmentDiscoveryRuntime {
    config: DiscoveryConfig,
}

impl DevelopmentDiscoveryRuntime {
    pub fn with_prober(
        config: DiscoveryConfig,
        _prober: Arc<LiveTransportDiscoveryPeerProber>,
    ) -> Self {
        Self { config }
    }

    pub fn admit_seed_peers(&mut self) -> bool {
        true
    }

    pub fn into_coordination(self) -> ClusterCoordinationState {
        let mut joined = self.config.seed_peers.clone();
        joined.push(DiscoveryPeer {
            node_id: self.config.local_node_id.clone(),
            node_name: self.config.local_node_name.clone(),
            host: "127.0.0.1".to_string(),
            port: 0,
            cluster_name: self.config.cluster_name.clone(),
            cluster_uuid: self.config.cluster_uuid.clone(),
            version: self.config.local_version,
            cluster_manager_eligible: self.config.cluster_manager_eligible,
            membership_epoch: self.config.local_membership_epoch,
        });
        let voting_configuration = initial_voting_configuration(&self.config, &joined);
        ClusterCoordinationState {
            current_term: 0,
            last_accepted_version: 0,
            last_accepted_state_uuid: String::new(),
            cluster_manager_node_id: Some(self.config.local_node_id.clone()),
            last_accepted_voting_configuration: voting_configuration.clone(),
            last_committed_voting_configuration: voting_configuration,
            voting_config_exclusions: BTreeSet::new(),
            liveness: LivenessState::default(),
            fault_detection: CoordinationFaultDetectionState::default(),
            joined,
            pending_voting_config_additions: BTreeSet::new(),
            pending_voting_config_removals: BTreeSet::new(),
            active_publication_round: None,
            last_completed_publication_round: None,
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct ElectionSchedulerConfig {
    pub initial_timeout: Duration,
    pub backoff_time: Duration,
    pub max_timeout: Duration,
    pub duration: Duration,
}

impl Default for ElectionSchedulerConfig {
    fn default() -> Self {
        Self {
            initial_timeout: Duration::from_millis(10),
            backoff_time: Duration::from_millis(5),
            max_timeout: Duration::from_millis(20),
            duration: Duration::from_millis(3),
        }
    }
}

#[derive(Clone, Debug, Default, Eq, PartialEq, Serialize, Deserialize)]
pub struct ElectionAttemptWindow {
    pub attempt: u64,
    pub delay: Duration,
    pub duration: Duration,
}

#[derive(Clone, Debug, Default, Eq, PartialEq, Serialize, Deserialize)]
pub struct ElectionResult {
    pub elected_node_id: Option<String>,
    pub term: i64,
    pub votes: BTreeSet<String>,
    pub required_quorum: u64,
}

#[derive(Clone, Debug, Default, Eq, PartialEq, Serialize, Deserialize)]
pub struct ElectionScheduler {
    attempts: u64,
    config: ElectionSchedulerConfig,
}

impl ElectionScheduler {
    pub fn new(config: ElectionSchedulerConfig) -> Self {
        Self {
            attempts: 0,
            config,
        }
    }

    pub fn next_attempt(&mut self) -> ElectionAttemptWindow {
        self.attempts += 1;
        let backoff_multiplier = self.attempts.saturating_sub(1) as u32;
        let delay = (self.config.initial_timeout
            + self.config.backoff_time.saturating_mul(backoff_multiplier))
        .min(self.config.max_timeout);
        ElectionAttemptWindow {
            attempt: self.attempts,
            delay,
            duration: self.config.duration,
        }
    }

    pub fn attempts(&self) -> u64 {
        self.attempts
    }
}

