    pub fn with_rest_config(mut self, config: RestServerConfig) -> Self {
        self.rest_config = Some(config);
        self
    }

    pub fn with_extension_registry(mut self, registry: ExtensionBoundaryRegistry) -> Self {
        self.extension_registry = registry;
        self.extension_lifecycle_executions
            .lock()
            .expect("extension lifecycle execution lock poisoned")
            .clear();
        self.activate_registered_extensions();
        self
    }

    pub fn with_remote_transport_queue_gate(mut self, gate: Arc<RemoteTransportQueueGate>) -> Self {
        self.remote_transport_queue_gate = Some(gate);
        self
    }

    pub fn spawn_pit_expiry_reaper_until<F>(
        &self,
        interval: Duration,
        should_stop: F,
    ) -> std::thread::JoinHandle<()>
    where
        F: Fn() -> bool + Send + 'static,
    {
        let contexts = Arc::clone(&self.pit_contexts);
        let pit_native_snapshots = Arc::clone(&self.pit_native_snapshots);
        let pit_time_millis_by_index = Arc::clone(&self.pit_time_millis_by_index);
        let metadata_manifest_state = Arc::clone(&self.metadata_manifest_state);
        std::thread::spawn(move || loop {
            {
                let now_millis = current_epoch_millis();
                let mut contexts = contexts.lock().expect("pit contexts lock poisoned");
                let expired_contexts = drain_expired_pit_contexts(&mut contexts, now_millis);
                let active_ids = contexts.keys().cloned().collect::<BTreeSet<_>>();
                drop(contexts);
                pit_native_snapshots
                    .lock()
                    .expect("pit native snapshots lock poisoned")
                    .retain(|pit_id, _| active_ids.contains(pit_id));
                record_pit_context_time_millis_with_lookup(
                    &pit_time_millis_by_index,
                    &expired_contexts,
                    now_millis,
                    |index| {
                        index_primary_shard_count_from_manifest(&metadata_manifest_state, index)
                    },
                );
            }
            if should_stop() {
                break;
            }
            std::thread::sleep(interval);
        })
    }

    pub fn extension_lifecycle_execution_transcript(&self) -> Vec<ExtensionLifecycleExecution> {
        self.extension_lifecycle_executions
            .lock()
            .expect("extension lifecycle execution lock poisoned")
            .clone()
    }

