    fn activate_registered_extensions(&self) {
        self.execute_registered_extension_lifecycle_phase("startup", "activate");
        self.execute_registered_extension_lifecycle_phase("steady_state", "activate");
    }

    pub fn deactivate_registered_extensions_for_shutdown(&self) {
        self.execute_registered_extension_lifecycle_phase("shutdown", "deactivate");
    }

    pub fn mark_registered_extensions_recovery_failed(&self) {
        self.execute_registered_extension_lifecycle_phase("recovery", "recovery_failed");
    }

    fn execute_registered_extension_lifecycle_phase(
        &self,
        phase: &'static str,
        action: &'static str,
    ) {
        for descriptor in self.extension_registry.rust_native_extension_descriptors() {
            for hook in descriptor.lifecycle_hooks {
                let Some(runtime_hook) = RUNTIME_LIFECYCLE_HOOKS
                    .iter()
                    .find(|runtime_hook| runtime_hook.phase == phase && runtime_hook.hook == *hook)
                else {
                    continue;
                };
                let status = self.execute_registered_extension_lifecycle_hook(runtime_hook.hook);
                self.extension_lifecycle_executions
                    .lock()
                    .expect("extension lifecycle execution lock poisoned")
                    .push(ExtensionLifecycleExecution {
                        module: descriptor.module,
                        phase,
                        hook: runtime_hook.hook,
                        action,
                        status,
                    });
            }
        }
    }

    fn execute_registered_extension_lifecycle_hook(&self, hook: &str) -> &'static str {
        match hook {
            "sync_shared_runtime_state_from_disk" => {
                self.sync_shared_runtime_state_from_disk();
                "executed"
            }
            "refuse_task_submission_if_unavailable" => {
                if self.refuse_task_submission_if_unavailable().is_some() {
                    "refused"
                } else {
                    "admitted"
                }
            }
            "set_live_shutdown_in_progress" => {
                self.set_live_shutdown_in_progress(true);
                "executed"
            }
            "set_shared_runtime_state_recovery_failed" => {
                self.set_shared_runtime_state_recovery_failed(true);
                "executed"
            }
            _ => "unavailable",
        }
    }

    pub fn with_gateway_backed_development_metadata_store(
        mut self,
        metadata_path: impl AsRef<Path>,
        gateway_manifest_path: impl AsRef<Path>,
        cluster_view: DevelopmentClusterView,
    ) -> std::io::Result<Self> {
        self.cluster_view = Some(cluster_view);
        self.development_data_path = metadata_path.as_ref().parent().map(Path::to_path_buf);
        self.shared_runtime_state_path = self
            .development_data_path
            .as_ref()
            .map(|data_path| data_path.join("shared-runtime-state.json"));
        if let Ok(bytes) = std::fs::read(metadata_path.as_ref()) {
            if let Ok(value) = serde_json::from_slice::<Value>(&bytes) {
                *self
                    .metadata_manifest_state
                    .lock()
                    .expect("metadata manifest state lock poisoned") = value.clone();
                let indices = value
                    .get("indices")
                    .and_then(Value::as_object)
                    .cloned()
                    .unwrap_or_default();
                *self
                    .created_indices_state
                    .lock()
                    .expect("created indices state lock poisoned") =
                    indices.keys().cloned().collect();
                let cluster_settings = value
                    .get("cluster_settings")
                    .cloned()
                    .unwrap_or_else(default_cluster_settings_state);
                *self
                    .cluster_settings_state
                    .lock()
                    .expect("cluster settings state lock poisoned") = cluster_settings;
            }
        }
        if let Ok(Some(persisted)) = load_gateway_state_manifest(gateway_manifest_path.as_ref()) {
            if let Some(metadata_state) = persisted.metadata_state {
                *self
                    .cluster_settings_state
                    .lock()
                    .expect("cluster settings state lock poisoned") = serde_json::json!({
                    "persistent": metadata_state.cluster_settings.persistent,
                    "transient": metadata_state.cluster_settings.transient,
                });
            }
            *self
                .task_queue_state
                .lock()
                .expect("task queue state lock poisoned") =
                persisted.task_queue_state.map(pruned_task_queue_state);
        }
        Ok(self)
    }

    pub fn with_production_membership_store(
        mut self,
        membership_path: PathBuf,
        membership_state: ProductionMembershipState,
    ) -> std::io::Result<Self> {
        if let Some(parent) = membership_path.parent() {
            fs::create_dir_all(parent)?;
        }
        let temp_path = membership_path.with_extension("tmp");
        fs::write(
            &temp_path,
            serde_json::to_vec_pretty(&membership_state)
                .map_err(|error| std::io::Error::new(std::io::ErrorKind::InvalidData, error))?,
        )?;
        fs::rename(&temp_path, &membership_path)?;
        self.membership_state = Some(membership_state);
        self.membership_state_path = Some(membership_path);
        Ok(self)
    }

    pub fn register_default_dev_endpoints(&mut self, _cluster_name: String, _cluster_uuid: &str) {}

    pub fn register_development_cluster_endpoints(&mut self, cluster_view: DevelopmentClusterView) {
        if let Some(task_queue_state) = cluster_view
            .coordination
            .as_ref()
            .and_then(|coordination| coordination.task_queue_state.clone())
        {
            *self
                .task_queue_state
                .lock()
                .expect("task queue state lock poisoned") =
                Some(pruned_task_queue_state(task_queue_state));
        }
        self.cluster_view = Some(cluster_view);
    }

