    fn handle_cluster_state_route(&self, request: &RestRequest) -> RestResponse {
        if let Some(response) = validate_cluster_state_query_params(request) {
            return response;
        }
        let mut scoped_request = request.clone();
        if let Some(metric_segment) = request.path.strip_prefix("/_cluster/state/") {
            if !metric_segment.is_empty() {
                let (metric, indices) = metric_segment
                    .split_once('/')
                    .map(|(metric, indices)| (metric.to_string(), Some(indices.to_string())))
                    .unwrap_or_else(|| (metric_segment.to_string(), None));
                scoped_request
                    .path_params
                    .insert("metric".to_string(), metric);
                if let Some(indices) = indices {
                    scoped_request
                        .path_params
                        .insert("indices".to_string(), indices);
                }
            }
        }
        match cluster_state_route_registration::invoke_cluster_state_live_route(
            &scoped_request,
            &self.cluster_state_body(),
        ) {
            Ok(mut response) => {
                if request
                    .query_params
                    .contains_key("wait_for_metadata_version")
                {
                    if let Some(object) = response.body.as_object_mut() {
                        object.insert("wait_for_timed_out".to_string(), Value::Bool(false));
                    }
                }
                response
            }
            Err(response) => response,
        }
    }

    fn handle_dev_cluster_route(&self) -> RestResponse {
        let cluster_view = self.cluster_view.clone().unwrap_or_default();
        let node_count = cluster_view.nodes.len() as u64;
        let mut body = serde_json::to_value(cluster_view)
            .unwrap_or_else(|_| Value::Object(Default::default()));
        if let Some(object) = body.as_object_mut() {
            object.insert("number_of_nodes".to_string(), Value::from(node_count));
            object.insert("formed".to_string(), Value::Bool(node_count > 0));
        }
        RestResponse::json(200, body)
    }

