    fn handle_cluster_health_route(&self, request: &RestRequest) -> RestResponse {
        if let Some(response) = validate_cluster_health_query_params(request) {
            return response;
        }
        let target = request
            .path
            .strip_prefix("/_cluster/health/")
            .filter(|value| !value.is_empty());
        let Some(mut body) = self.cluster_health_body(target) else {
            return RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IndexNotFound,
                target.unwrap_or_default(),
            );
        };
        let current_nodes = body
            .get("number_of_nodes")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        let current_status = body.get("status").and_then(Value::as_str).unwrap_or("red");
        let wait_for_nodes = request
            .query_params
            .get("wait_for_nodes")
            .and_then(|value| parse_wait_for_nodes(value));
        let wait_for_status = request
            .query_params
            .get("wait_for_status")
            .map(String::as_str);
        let timeout_requested = request.query_params.contains_key("timeout");
        let timed_out = timeout_requested
            && (wait_for_nodes.is_some_and(|expected| expected > current_nodes)
                || wait_for_status.is_some_and(|expected| {
                    cluster_health_status_rank(current_status)
                        < cluster_health_status_rank(expected)
                }));
        if let Some(object) = body.as_object_mut() {
            object.insert("timed_out".to_string(), Value::Bool(timed_out));
        }
        RestResponse::json(if timed_out { 408 } else { 200 }, body)
    }

    fn handle_create_index_route(&self, request: &RestRequest) -> RestResponse {
        let index = request.path.trim_start_matches('/').trim_end_matches('/');
        if index.chars().any(|ch| ch.is_ascii_uppercase()) {
            return RestResponse::opensearch_error(
                400,
                "invalid_index_name_exception",
                format!("invalid index name [{index}], must be lowercase"),
            );
        }
        for key in request.query_params.keys() {
            match key.as_str() {
                "wait_for_active_shards"
                | "timeout"
                | "cluster_manager_timeout"
                | "master_timeout" => {}
                _ => {
                    return RestResponse::opensearch_error_kind(
                        os_rest::RestErrorKind::IllegalArgument,
                        format!("unsupported create index parameter [{key}]"),
                    );
                }
            }
        }
        for param in ["timeout", "cluster_manager_timeout", "master_timeout"] {
            let Some(raw_value) = request.query_params.get(param) else {
                continue;
            };
            if parse_time_value_millis(raw_value).is_none() {
                return RestResponse::opensearch_error_kind(
                    os_rest::RestErrorKind::IllegalArgument,
                    format!(
                        "failed to parse setting [{param}] with value [{raw_value}] as a time value"
                    ),
                );
            }
        }
        if request.query_params.contains_key("master_timeout")
            && request.query_params.contains_key("cluster_manager_timeout")
        {
            return RestResponse::opensearch_error(
                400,
                "parse_exception",
                "Please only use one of the request parameters [master_timeout, cluster_manager_timeout].",
            );
        }
        let request_body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        let mut bounded_subset =
            create_index_route_registration::build_create_index_body_subset(&request_body);
        if let Some(settings) = bounded_subset.get("settings").cloned() {
            bounded_subset["settings"] = stringify_leaf_scalars(&settings);
        }
        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let mut index_entry = Self::build_composable_template_index_entry(&manifest, index);
        merge_object_with_null_reset(&mut index_entry, &bounded_subset);
        if let Err(error) = self.native_engine.create_index(CreateIndexRequest {
            index: index.to_string(),
            settings: index_entry
                .get("settings")
                .cloned()
                .unwrap_or_else(|| serde_json::json!({})),
            mappings: index_entry
                .get("mappings")
                .cloned()
                .unwrap_or_else(|| serde_json::json!({})),
        }) {
            return RestResponse::opensearch_error(
                error.status_code(),
                error.opensearch_error_type(),
                error.opensearch_reason(),
            );
        }
        self.created_indices_state
            .lock()
            .expect("created indices state lock poisoned")
            .insert(index.to_string());
        self.documents_state
            .lock()
            .expect("documents state lock poisoned")
            .retain(|key, _| !key.starts_with(&format!("{index}:")));
        *self.next_seq_no.lock().expect("seq_no lock poisoned") = 0;
        self.next_seq_no_by_index
            .lock()
            .expect("per-index seq_no lock poisoned")
            .insert(index.to_string(), 0);
        let indices = manifest
            .as_object_mut()
            .expect("metadata manifest object expected")
            .entry("indices".to_string())
            .or_insert_with(|| serde_json::json!({}));
        indices[index] = Self::normalize_index_manifest_entry(index, index_entry);
        drop(manifest);
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(
            200,
            serde_json::json!({
                "acknowledged": true,
                "shards_acknowledged": true,
                "index": index,
            }),
        )
    }

    fn handle_get_index_route(&self, request: &RestRequest) -> RestResponse {
        let target = request.path.trim_matches('/');
        for field in ["ignore_unavailable", "allow_no_indices"] {
            if let Some(response) = validate_opensearch_named_boolean_query_param(
                field,
                request.query_params.get(field),
            ) {
                return response;
            }
        }
        let ignore_unavailable =
            query_param_is_true(request.query_params.get("ignore_unavailable"));
        let expand_wildcards = request
            .query_params
            .get("expand_wildcards")
            .map(String::as_str)
            .unwrap_or("open");
        let allow_no_indices = query_param_is_true(request.query_params.get("allow_no_indices"))
            || expand_wildcards == "hidden";
        let matched = match self.resolve_index_metadata_targets(
            target,
            ignore_unavailable,
            allow_no_indices,
            expand_wildcards,
        ) {
            Ok(matched) => matched,
            Err(response) => return response,
        };
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let body = get_index_route_registration::build_get_index_metadata_response_for_names(
            &manifest["indices"],
            &matched,
        );
        let mut body = body;
        stringify_opensearch_setting_number_readbacks(&mut body);
        RestResponse::json(200, body)
    }

    fn handle_delete_index_route(&self, request: &RestRequest) -> RestResponse {
        let target = request.path.trim_matches('/');
        if target.is_empty() {
            return action_request_validation_error(vec!["index / indices is missing"]);
        }
        for field in ["ignore_unavailable", "allow_no_indices"] {
            if let Some(response) = validate_opensearch_named_boolean_query_param(
                field,
                request.query_params.get(field),
            ) {
                return response;
            }
        }
        let ignore_unavailable =
            query_param_is_true(request.query_params.get("ignore_unavailable"));
        let allow_no_indices = query_param_is_true(request.query_params.get("allow_no_indices"));
        let requested_expand_wildcards = request
            .query_params
            .get("expand_wildcards")
            .map(String::as_str)
            .unwrap_or("open");
        let hidden_only = requested_expand_wildcards == "hidden";
        let resolver_expand_wildcards = if hidden_only {
            "open,hidden"
        } else {
            requested_expand_wildcards
        };
        let mut matched = match self.resolve_index_metadata_targets(
            target,
            ignore_unavailable,
            allow_no_indices,
            resolver_expand_wildcards,
        ) {
            Ok(matched) => matched,
            Err(response) => return response,
        };
        if hidden_only {
            let manifest = self
                .metadata_manifest_state
                .lock()
                .expect("metadata manifest state lock poisoned");
            matched.retain(|index| index_metadata_is_hidden(&manifest["indices"][index]));
        }
        if matched.is_empty() {
            return delete_index_route_registration::build_delete_index_success_response();
        }
        {
            let mut created = self
                .created_indices_state
                .lock()
                .expect("created indices state lock poisoned");
            let mut docs = self
                .documents_state
                .lock()
                .expect("documents state lock poisoned");
            let mut manifest = self
                .metadata_manifest_state
                .lock()
                .expect("metadata manifest state lock poisoned");
            for index in matched {
                let _ = self.native_engine.delete_index(&index);
                created.remove(&index);
                docs.retain(|key, _| !key.starts_with(&format!("{index}:")));
                manifest["indices"]
                    .as_object_mut()
                    .map(|m| m.remove(&index));
            }
        }
        self.persist_shared_runtime_state_to_disk();
        delete_index_route_registration::build_delete_index_success_response()
    }

    fn handle_index_block_route(&self, index: &str, block: &str) -> RestResponse {
        if !Self::valid_index_block_name(block) {
            return RestResponse::opensearch_error(
                400,
                "illegal_argument_exception",
                format!("No block found with name {block}"),
            );
        }
        let matched = match self.resolve_index_metadata_targets(index, false, false, "open") {
            Ok(matched) => matched,
            Err(response) => return response,
        };
        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        for matched_index in &matched {
            manifest["indices"][matched_index]["blocks"][block] = Value::Bool(true);
        }
        drop(manifest);
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(
            200,
            serde_json::json!({
                "acknowledged": true,
                "shards_acknowledged": true,
                "indices": matched
            }),
        )
    }

    fn valid_index_block_name(block: &str) -> bool {
        matches!(
            block,
            "read_only" | "read" | "write" | "metadata" | "read_only_allow_delete" | "search_only"
        )
    }

    fn handle_index_resize_route(
        &self,
        source: &str,
        target: &str,
        operation: &str,
        request: &RestRequest,
    ) -> RestResponse {
        if let Some(response) = validate_index_resize_query_params(request) {
            return response;
        }
        let matched = match self.resolve_index_metadata_targets(source, false, false, "open") {
            Ok(matched) => matched,
            Err(response) => return response,
        };
        let Some(source_index) = matched.first().cloned() else {
            return delete_index_route_registration::build_delete_index_missing_response(source);
        };
        let request_body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        if operation == "shrink"
            && index_primary_shard_count_from_manifest(&self.metadata_manifest_state, &source_index)
                <= 1
        {
            return RestResponse::opensearch_error(
                400,
                "illegal_argument_exception",
                "can't shrink an index with only one shard",
            );
        }
        if operation == "split" && !index_resize_body_sets_number_of_shards(&request_body) {
            return RestResponse::opensearch_error(
                400,
                "action_request_validation_exception",
                "Validation Failed: 1: index.number_of_shards is required for split operations;",
            );
        }
        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let source_body = manifest["indices"][&source_index].clone();
        manifest["indices"][target] = source_body;
        manifest["indices"][target]["resize_source"] = Value::String(source_index.clone());
        manifest["indices"][target]["resize_operation"] = Value::String(operation.to_string());
        manifest["indices"][target]["state"] = Value::String("open".to_string());
        drop(manifest);
        self.created_indices_state
            .lock()
            .expect("created indices state lock poisoned")
            .insert(target.to_string());
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(
            200,
            serde_json::json!({
                "acknowledged": true,
                "shards_acknowledged": true,
                "index": target
            }),
        )
    }

    fn handle_index_scale_route(&self, source: &str, request: &RestRequest) -> RestResponse {
        let body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        let Value::Object(object) = body else {
            return RestResponse::opensearch_error(
                400,
                "illegal_argument_exception",
                "Request body must be valid JSON",
            );
        };
        for (field, _) in &object {
            if field != "search_only" {
                return RestResponse::opensearch_error(
                    400,
                    "illegal_argument_exception",
                    format!("Unknown parameter [{field}]. Only [search_only] is allowed."),
                );
            }
        }
        let Some(search_only) = object.get("search_only") else {
            return RestResponse::opensearch_error(
                400,
                "illegal_argument_exception",
                "Parameter [search_only] is required",
            );
        };
        let Some(search_only) = search_only.as_bool() else {
            return RestResponse::opensearch_error(
                400,
                "illegal_argument_exception",
                "Parameter [search_only] must be a boolean (true or false)",
            );
        };

        let matched = match self.resolve_index_metadata_targets(source, false, false, "open") {
            Ok(matched) => matched,
            Err(response) => return response,
        };
        let Some(index) = matched.first().cloned() else {
            return delete_index_route_registration::build_delete_index_missing_response(source);
        };

        {
            let manifest = self
                .metadata_manifest_state
                .lock()
                .expect("metadata manifest state lock poisoned");
            let index_metadata = &manifest["indices"][&index];
            if search_only && !index_remote_store_enabled_from_metadata(index_metadata) {
                return RestResponse::opensearch_error(
                    400,
                    "illegal_argument_exception",
                    format!(
                        "To scale to zero, index.remote_store.enabled must be enabled for index: {index}"
                    ),
                );
            }
            if !search_only && !index_search_only_enabled_from_metadata(index_metadata) {
                return RestResponse::opensearch_error(
                    500,
                    "illegal_state_exception",
                    format!("Index [{index}] is not in search-only mode"),
                );
            }
        }

        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        manifest["indices"][&index]["settings"]["index.blocks.search_only"] =
            Value::Bool(search_only);
        manifest["indices"][&index]["blocks"]["search_only"] = Value::Bool(search_only);
        drop(manifest);
        self.persist_shared_runtime_state_to_disk();

        RestResponse::json(200, serde_json::json!({ "acknowledged": true }))
    }

    fn handle_head_index_route(&self, request: &RestRequest) -> RestResponse {
        let target = request.path.trim_matches('/');
        for field in ["ignore_unavailable", "allow_no_indices"] {
            if let Some(response) = validate_opensearch_named_boolean_query_param(
                field,
                request.query_params.get(field),
            ) {
                return response;
            }
        }
        let ignore_unavailable =
            query_param_is_true(request.query_params.get("ignore_unavailable"));
        let allow_no_indices = query_param_is_true(request.query_params.get("allow_no_indices"));
        let expand_wildcards = request
            .query_params
            .get("expand_wildcards")
            .map(String::as_str)
            .unwrap_or("open");
        match self.resolve_index_metadata_targets(
            target,
            ignore_unavailable,
            allow_no_indices,
            expand_wildcards,
        ) {
            Ok(matched) if !matched.is_empty() => RestResponse::empty(200),
            Ok(_) => RestResponse::empty(404),
            Err(response) if response.status == 404 => RestResponse::empty(404),
            Err(response) => response,
        }
    }

    fn resolve_index_metadata_targets(
        &self,
        target: &str,
        ignore_unavailable: bool,
        allow_no_indices: bool,
        expand_wildcards: &str,
    ) -> Result<Vec<String>, RestResponse> {
        let (include_open, include_hidden, include_closed) =
            parse_index_expand_wildcards(expand_wildcards)?;

        let selectors = if target == "_all" {
            vec!["*"]
        } else {
            target
                .split(',')
                .map(str::trim)
                .filter(|selector| !selector.is_empty())
                .collect::<Vec<_>>()
        };

        let created = self
            .created_indices_state
            .lock()
            .expect("created indices state lock poisoned")
            .iter()
            .cloned()
            .collect::<Vec<_>>();
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");

        let mut matched = Vec::new();
        for selector in selectors {
            let mut selector_matches = created
                .iter()
                .filter(|index| {
                    if selector != *index && !wildcard_match(selector, index) {
                        return false;
                    }
                    let state = manifest["indices"][*index]["state"]
                        .as_str()
                        .unwrap_or("open");
                    if state != "close" && !include_open {
                        return false;
                    }
                    if state == "close" && !include_closed {
                        return false;
                    }
                    if index_metadata_is_hidden(&manifest["indices"][*index]) && !include_hidden {
                        return false;
                    }
                    true
                })
                .cloned()
                .collect::<Vec<_>>();
            selector_matches.sort();
            selector_matches.dedup();
            if selector_matches.is_empty() && !(ignore_unavailable || allow_no_indices) {
                return Err(
                    delete_index_route_registration::build_delete_index_missing_response(selector),
                );
            }
            matched.extend(selector_matches);
        }
        matched.sort();
        matched.dedup();
        if matched.is_empty() && !(ignore_unavailable || allow_no_indices) {
            return Err(
                delete_index_route_registration::build_delete_index_missing_response(target),
            );
        }
        Ok(matched)
    }

