    fn handle_mapping_put_route(&self, index: &str, request: &RestRequest) -> RestResponse {
        let body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        let subset = mapping_route_registration::build_mapping_update_body_subset(&body);
        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let existing_properties = manifest["indices"][index]["mappings"]["properties"]
            .as_object()
            .cloned()
            .unwrap_or_default();
        let update_properties = subset["properties"]
            .as_object()
            .cloned()
            .unwrap_or_default();
        for (field, update_definition) in &update_properties {
            let Some(existing_definition) = existing_properties.get(field) else {
                continue;
            };
            let existing_type = existing_definition.get("type").and_then(Value::as_str);
            let update_type = update_definition.get("type").and_then(Value::as_str);
            if existing_type.is_some() && update_type.is_some() && existing_type != update_type {
                return RestResponse::json(
                    400,
                    serde_json::json!({
                        "error": {
                            "type": "illegal_argument_exception",
                            "reason": format!(
                                "mapper [{field}] cannot be changed from type [{}] to [{}]",
                                existing_type.unwrap_or_default(),
                                update_type.unwrap_or_default()
                            ),
                            "root_cause": [
                                {
                                    "type": "illegal_argument_exception",
                                    "reason": format!(
                                        "mapper [{field}] cannot be changed from type [{}] to [{}]",
                                        existing_type.unwrap_or_default(),
                                        update_type.unwrap_or_default()
                                    )
                                }
                            ]
                        },
                        "status": 400
                    }),
                );
            }
        }
        if let Some(dynamic) = subset.get("dynamic") {
            manifest["indices"][index]["mappings"]["dynamic"] = dynamic.clone();
        }
        if let Some(meta) = subset.get("_meta") {
            let existing_meta = manifest["indices"][index]["mappings"]
                .get("_meta")
                .cloned()
                .unwrap_or_else(|| serde_json::json!({}));
            let mut merged_meta = existing_meta;
            merge_object_with_null_reset(&mut merged_meta, meta);
            manifest["indices"][index]["mappings"]["_meta"] = merged_meta;
        }
        if !manifest["indices"][index]["mappings"].is_object() {
            manifest["indices"][index]["mappings"] = serde_json::json!({});
        }
        if !manifest["indices"][index]["mappings"]["properties"].is_object() {
            manifest["indices"][index]["mappings"]["properties"] = serde_json::json!({});
        }
        let merged_properties = manifest["indices"][index]["mappings"]["properties"]
            .as_object_mut()
            .expect("index mappings properties must be an object");
        for (field, update_definition) in update_properties {
            merged_properties.insert(field, update_definition);
        }
        drop(manifest);
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(200, serde_json::json!({ "acknowledged": true }))
    }

    fn handle_settings_get_route(
        &self,
        target: Option<&str>,
        name_filter: Option<&str>,
        flat_settings: bool,
        include_defaults: bool,
        ignore_unavailable: bool,
        allow_no_indices: bool,
        expand_wildcards: &str,
    ) -> RestResponse {
        let effective_allow_no_indices = allow_no_indices
            || target.is_some_and(|target| {
                expand_wildcards == "hidden" || self.target_names_hidden_index(target)
            });
        let matched_targets = if let Some(target) = target {
            match self.resolve_index_metadata_targets(
                target,
                ignore_unavailable,
                effective_allow_no_indices,
                expand_wildcards,
            ) {
                Ok(matched) => Some(matched),
                Err(response) => return response,
            }
        } else {
            None
        };
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let filtered_indices = if let Some(matched) = matched_targets {
            let mut subset = serde_json::Map::new();
            for index in matched {
                subset.insert(index.clone(), manifest["indices"][&index].clone());
            }
            Value::Object(subset)
        } else {
            let mut subset = serde_json::Map::new();
            for (index, body) in manifest["indices"].as_object().into_iter().flatten() {
                if !index_metadata_is_hidden(body) {
                    subset.insert(index.clone(), body.clone());
                }
            }
            Value::Object(subset)
        };
        RestResponse::json(
            200,
            settings_route_registration::build_named_settings_readback_response(
                &filtered_indices,
                None,
                name_filter,
                flat_settings,
                include_defaults,
            ),
        )
    }

    fn target_names_hidden_index(&self, target: &str) -> bool {
        if target.contains('*') || target.contains('?') || target.contains(',') {
            return false;
        }
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        index_metadata_is_hidden(&manifest["indices"][target])
    }

    fn validate_settings_update_body(
        &self,
        body: &Value,
        index_label: &str,
    ) -> Option<RestResponse> {
        if let Some(index_settings) = body.get("index").and_then(Value::as_object) {
            for key in index_settings.keys() {
                if key != "number_of_replicas"
                    && key != "refresh_interval"
                    && key != "max_result_window"
                    && key != "number_of_routing_shards"
                {
                    return Some(RestResponse::json(
                        400,
                        serde_json::json!({
                            "error": {
                                "type": "illegal_argument_exception",
                                "reason": format!(
                                    "Can't update non dynamic settings [[index.{key}]] for open indices [[{index_label}]]"
                                ),
                                "root_cause": [
                                    {
                                        "type": "illegal_argument_exception",
                                        "reason": format!(
                                            "Can't update non dynamic settings [[index.{key}]] for open indices [[{index_label}]]"
                                        )
                                    }
                                ]
                            },
                            "status": 400
                        }),
                    ));
                }
            }
        }
        None
    }

    fn apply_settings_update_to_targets(&self, targets: &[String], body: &Value) -> RestResponse {
        let subset = settings_route_registration::build_settings_update_body_subset(&body);
        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        for index in targets {
            let existing_settings = manifest["indices"][index]["settings"].clone();
            let mut merged_settings = existing_settings;
            merge_object_with_null_reset(&mut merged_settings, &stringify_leaf_scalars(&subset));
            manifest["indices"][index]["settings"] = merged_settings;
        }
        drop(manifest);
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(200, serde_json::json!({ "acknowledged": true }))
    }

    fn handle_settings_put_route(&self, index: &str, request: &RestRequest) -> RestResponse {
        let body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        if let Some(response) = self.validate_settings_update_body(&body, index) {
            return response;
        }
        for field in ["ignore_unavailable", "allow_no_indices"] {
            if let Some(response) = validate_opensearch_named_boolean_query_param(
                field,
                request.query_params.get(field),
            ) {
                return response;
            }
        }
        let ignore_unavailable =
            query_param_is_true(request.query_params.get("ignore_unavailable"));
        let allow_no_indices = query_param_is_true(request.query_params.get("allow_no_indices"));
        let expand_wildcards = request
            .query_params
            .get("expand_wildcards")
            .map(String::as_str)
            .unwrap_or("open");
        let targets = match self.resolve_index_metadata_targets(
            index,
            ignore_unavailable,
            allow_no_indices,
            expand_wildcards,
        ) {
            Ok(targets) => targets,
            Err(response) => return response,
        };
        self.apply_settings_update_to_targets(&targets, &body)
    }

    fn handle_global_settings_put_route(&self, request: &RestRequest) -> RestResponse {
        let body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        if let Some(response) = self.validate_settings_update_body(&body, "_all") {
            return response;
        }
        let targets = self
            .created_indices_state
            .lock()
            .expect("created indices state lock poisoned")
            .iter()
            .cloned()
            .collect::<Vec<_>>();
        self.apply_settings_update_to_targets(&targets, &body)
    }

    fn handle_alias_read_route(
        &self,
        index_target: Option<&str>,
        alias_target: Option<&str>,
        request: &RestRequest,
    ) -> RestResponse {
        if let Some(response) = validate_alias_get_query_params(request) {
            return response;
        }
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let mut body = alias_read_route_registration::build_alias_readback_response(
            &manifest["indices"],
            index_target,
            alias_target,
        );
        let missing_aliases =
            alias_read_route_registration::missing_explicit_aliases(&body, alias_target);
        if missing_aliases.is_empty() {
            return RestResponse::json(200, body);
        }
        let message = if missing_aliases.len() == 1 {
            format!("alias [{}] missing", missing_aliases.join(","))
        } else {
            format!("aliases [{}] missing", missing_aliases.join(","))
        };
        if let Some(object) = body.as_object_mut() {
            object.insert("error".to_string(), Value::String(message));
            object.insert("status".to_string(), Value::from(404));
        }
        RestResponse::json(404, body)
    }

    fn handle_alias_head_route(&self, alias: &str, request: &RestRequest) -> RestResponse {
        if let Some(response) = validate_alias_get_query_params(request) {
            return response;
        }
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let found = manifest["indices"]
            .as_object()
            .into_iter()
            .flatten()
            .any(|(_, body)| {
                body["aliases"]
                    .as_object()
                    .is_some_and(|aliases| aliases.contains_key(alias))
            });
        if found {
            RestResponse::text(200, "")
        } else {
            RestResponse::text(404, "")
        }
    }

