    fn mtermvectors_doc_response(
        &self,
        docs: &DocumentMap,
        requested_index: &str,
        id: &str,
        routing: &str,
        selected_fields: Option<&BTreeSet<String>>,
    ) -> Value {
        let resolved_index = self.resolve_index_or_alias(requested_index);
        let key = format!("{resolved_index}:{id}:{routing}");
        let record = docs.get(&key).or_else(|| {
            if routing.is_empty() {
                docs.iter()
                    .find(|(candidate, _)| {
                        candidate.starts_with(&format!("{resolved_index}:{id}:"))
                    })
                    .map(|(_, record)| record)
            } else {
                None
            }
        });
        if let Some(record) = record {
            let fields = termvectors_fields_from_source(&record.source, selected_fields);
            serde_json::json!({
                "_index": self.write_response_index(requested_index, &resolved_index),
                "_id": id,
                "_version": record.version,
                "found": true,
                "term_vectors": fields
            })
        } else {
            serde_json::json!({
                "_index": self.write_response_index(requested_index, &resolved_index),
                "_id": id,
                "found": false
            })
        }
    }

    fn artificial_termvectors_doc_response(
        &self,
        index: &str,
        doc: &Value,
        selected_fields: Option<&BTreeSet<String>>,
    ) -> Value {
        serde_json::json!({
            "_index": index,
            "_id": "_na_",
            "found": true,
            "term_vectors": termvectors_fields_from_source(doc, selected_fields)
        })
    }

    fn handle_search_template_route(
        &self,
        target: Option<&str>,
        request: &RestRequest,
    ) -> RestResponse {
        match self.search_template_search_body(target, request, None) {
            Ok(body) => RestResponse::json(200, body),
            Err(response) => response,
        }
    }

    fn handle_msearch_route(&self, target: Option<&str>, request: &RestRequest) -> RestResponse {
        match self.parse_msearch_requests(request) {
            Ok(Some(requests)) => {
                let mut responses = Vec::new();
                for parsed in requests {
                    let effective_target = parsed.target.as_deref().or(target).unwrap_or("_all");
                    let search_path = if parsed.target.is_some() || target.is_some() {
                        format!("/{effective_target}/_search")
                    } else {
                        "/_search".to_string()
                    };
                    let has_pit = parsed.body.get("pit").is_some();
                    let mut search_request =
                        RestRequest::new(RestMethod::Post, search_path).with_json_body(parsed.body);
                    search_request.headers = request.headers.clone();
                    search_request.query_params = request.query_params.clone();
                    search_request.query_params.extend(parsed.query_params);
                    let response =
                        self.handle_index_search_route(effective_target, &search_request);
                    if has_pit && is_msearch_pit_request_validation_response(&response) {
                        return response;
                    }
                    responses.push(msearch_response_with_status(response));
                }
                return RestResponse::json(200, serde_json::json!({ "responses": responses }));
            }
            Ok(None) => {}
            Err(response) => return response,
        }
        RestResponse::json(200, {
            let effective_target = target.unwrap_or("_all");
            let search_path = if target.is_some() {
                format!("/{effective_target}/_search")
            } else {
                "/_search".to_string()
            };
            let mut search_request = RestRequest::new(RestMethod::Post, search_path)
                .with_json_body(serde_json::json!({
                    "query": { "match_all": {} }
                }));
            search_request.headers = request.headers.clone();
            search_request.query_params = request.query_params.clone();
            serde_json::json!({
                "responses": [msearch_response_with_status(
                    self.handle_index_search_route(effective_target, &search_request)
                )]
            })
        })
    }

    fn handle_msearch_template_route(
        &self,
        target: Option<&str>,
        request: &RestRequest,
    ) -> RestResponse {
        match self.parse_msearch_requests(request) {
            Ok(Some(requests)) => {
                let responses = requests
                    .into_iter()
                    .map(|parsed| {
                        let effective_target = parsed.target.as_deref().or(target);
                        if !search_template_payload_has_script(&parsed.body) {
                            return Err(search_template_malformed_response());
                        }
                        match self.search_template_payload_body(
                            effective_target,
                            &parsed.body,
                            request,
                            None,
                        ) {
                            Ok(body) => {
                                Ok(msearch_response_with_status(RestResponse::json(200, body)))
                            }
                            Err(response) => Ok(msearch_response_with_status(response)),
                        }
                    })
                    .collect::<Result<Vec<_>, _>>();
                let responses = match responses {
                    Ok(responses) => responses,
                    Err(response) => return response,
                };
                return RestResponse::json(200, serde_json::json!({ "responses": responses }));
            }
            Ok(None) => {}
            Err(response) => return response,
        }
        match self.search_template_search_body(target, request, None) {
            Ok(body) => RestResponse::json(
                200,
                serde_json::json!({
                    "responses": [body]
                }),
            ),
            Err(response) => response,
        }
    }

    fn handle_render_template_route(
        &self,
        template_id: Option<&str>,
        request: &RestRequest,
    ) -> RestResponse {
        let payload = if request.body.is_empty() {
            Value::Object(serde_json::Map::new())
        } else {
            serde_json::from_slice::<Value>(&request.body)
                .unwrap_or_else(|_| Value::Object(serde_json::Map::new()))
        };
        let template_output = match self.resolve_template_source(
            template_id,
            &payload,
            TemplateSourceValidation::AllowNonObject,
        ) {
            Ok(source) => source,
            Err(response) => return response,
        };
        let mut body = serde_json::json!({
            "template_output": template_output
        });
        if let Some(id) = template_id {
            body["_id"] = Value::String(id.to_string());
        }
        RestResponse::json(200, body)
    }

    fn parse_msearch_requests(
        &self,
        request: &RestRequest,
    ) -> Result<Option<Vec<ParsedMsearchRequest>>, RestResponse> {
        if request.body.is_empty() {
            return Ok(None);
        }
        let raw = std::str::from_utf8(&request.body).map_err(|_| {
            build_x_content_parse_search_response("failed to parse msearch ndjson payload")
        })?;
        let lines = raw
            .lines()
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .collect::<Vec<_>>();
        if lines.is_empty() {
            return Ok(None);
        }
        let request_line_count = lines.len() - (lines.len() % 2);
        let mut requests = Vec::new();
        let mut index = 0;
        while index < request_line_count {
            let header = serde_json::from_str::<Value>(lines[index]).map_err(|_| {
                build_x_content_parse_search_response("failed to parse msearch ndjson payload")
            })?;
            let header_object = header.as_object();
            let body = serde_json::from_str::<Value>(lines[index + 1])
                .map_err(|_| build_unexpected_end_of_input_search_response())?;
            let target = header_object
                .and_then(|header_object| {
                    header_object
                        .get("index")
                        .or_else(|| header_object.get("indices"))
                })
                .and_then(|value| match value {
                    Value::String(single) => Some(single.clone()),
                    Value::Array(values) => Some(
                        values
                            .iter()
                            .filter_map(Value::as_str)
                            .collect::<Vec<_>>()
                            .join(","),
                    ),
                    _ => None,
                })
                .filter(|target| !target.is_empty());
            if header_object.is_some_and(|header_object| {
                header_object.contains_key("index") || header_object.contains_key("indices")
            }) && target.is_none()
            {
                return Err(build_parsing_search_response("malformed msearch header"));
            }
            let query_params = header_object
                .map(Self::msearch_header_query_params)
                .unwrap_or_default();
            requests.push(ParsedMsearchRequest {
                target,
                body,
                query_params,
            });
            index += 2;
        }
        Ok(Some(requests))
    }

    fn msearch_header_query_params(
        header_object: &serde_json::Map<String, Value>,
    ) -> BTreeMap<String, String> {
        let mut query_params = BTreeMap::new();
        for (header_key, query_key) in [
            ("routing", "routing"),
            ("preference", "preference"),
            ("search_type", "search_type"),
            ("searchType", "search_type"),
            ("request_cache", "request_cache"),
            ("requestCache", "request_cache"),
            (
                "allow_partial_search_results",
                "allow_partial_search_results",
            ),
            ("phase_took", "phase_took"),
            ("cancel_after_time_interval", "cancel_after_time_interval"),
            ("cancelAfterTimeInterval", "cancel_after_time_interval"),
            ("ignore_unavailable", "ignore_unavailable"),
            ("ignoreUnavailable", "ignore_unavailable"),
            ("allow_no_indices", "allow_no_indices"),
            ("allowNoIndices", "allow_no_indices"),
            ("expand_wildcards", "expand_wildcards"),
            ("expandWildcards", "expand_wildcards"),
            ("ignore_throttled", "ignore_throttled"),
            ("ignoreThrottled", "ignore_throttled"),
            ("ccs_minimize_roundtrips", "ccs_minimize_roundtrips"),
            ("ccsMinimizeRoundtrips", "ccs_minimize_roundtrips"),
        ] {
            if let Some(value) = header_object
                .get(header_key)
                .and_then(Self::msearch_header_value_as_query_param)
            {
                query_params.insert(query_key.to_string(), value);
            }
        }
        query_params
    }

    fn msearch_header_value_as_query_param(value: &Value) -> Option<String> {
        match value {
            Value::String(value) => Some(value.clone()),
            Value::Bool(value) => Some(value.to_string()),
            Value::Number(value) => Some(value.to_string()),
            Value::Array(values) => {
                let values = values.iter().filter_map(Value::as_str).collect::<Vec<_>>();
                (!values.is_empty()).then(|| values.join(","))
            }
            Value::Null | Value::Object(_) => None,
        }
    }

    fn handle_search_pipeline_collection_get_route(&self, request: &RestRequest) -> RestResponse {
        if let Some(response) = validate_search_pipeline_query_params(request) {
            return response;
        }
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let entries = manifest["search_pipelines"]
            .as_object()
            .into_iter()
            .flat_map(|pipelines| pipelines.iter())
            .map(|(name, value)| {
                serde_json::json!({
                    "id": name,
                    "pipeline": value
                })
            })
            .collect::<Vec<_>>();
        RestResponse::json(200, serde_json::json!({ "pipelines": entries }))
    }

    fn handle_search_pipeline_get_route(
        &self,
        pipeline_id: &str,
        request: &RestRequest,
    ) -> RestResponse {
        if let Some(response) = validate_search_pipeline_query_params(request) {
            return response;
        }
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let Some(pipeline) = manifest["search_pipelines"].get(pipeline_id).cloned() else {
            return RestResponse::json(
                404,
                serde_json::json!({
                    "error": {
                        "type": "resource_not_found_exception",
                        "reason": format!("search pipeline [{pipeline_id}] is missing")
                    },
                    "status": 404
                }),
            );
        };
        RestResponse::json(200, serde_json::json!({ pipeline_id: pipeline }))
    }

    fn handle_search_pipeline_put_route(
        &self,
        pipeline_id: &str,
        request: &RestRequest,
    ) -> RestResponse {
        if let Some(response) = validate_search_pipeline_query_params(request) {
            return response;
        }
        let mut body = match serde_json::from_slice::<Value>(&request.body) {
            Ok(body) => body,
            Err(error) => {
                return RestResponse::json(
                    400,
                    serde_json::json!({
                        "error": {
                            "type": "parse_exception",
                            "reason": error.to_string()
                        },
                        "status": 400
                    }),
                );
            }
        };
        self.metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned")["search_pipelines"][pipeline_id] =
            body;
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(200, serde_json::json!({ "acknowledged": true }))
    }

    fn handle_search_pipeline_delete_route(
        &self,
        pipeline_id: &str,
        request: &RestRequest,
    ) -> RestResponse {
        if let Some(response) = validate_search_pipeline_query_params(request) {
            return response;
        }
        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let removed = manifest["search_pipelines"]
            .as_object_mut()
            .and_then(|pipelines| pipelines.remove(pipeline_id));
        if removed.is_none() {
            return RestResponse::json(
                404,
                serde_json::json!({
                    "error": {
                        "type": "resource_not_found_exception",
                        "reason": format!("search pipeline [{pipeline_id}] is missing")
                    },
                    "status": 404
                }),
            );
        }
        drop(manifest);
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(200, serde_json::json!({ "acknowledged": true }))
    }

