    fn handle_remote_store_restore_route(&self, request: &RestRequest) -> RestResponse {
        if let Some(response) = validate_remote_store_restore_query_params(request) {
            return response;
        }
        let body = if request.body.is_empty() {
            serde_json::json!({})
        } else {
            match serde_json::from_slice::<Value>(&request.body) {
                Ok(body) => body,
                Err(_) => {
                    return RestResponse::opensearch_error(
                        400,
                        "illegal_argument_exception",
                        "Failed to parse request body",
                    );
                }
            }
        };
        let indices = match parse_remote_store_restore_indices(&body) {
            Ok(indices) => indices,
            Err(response) => return response,
        };
        let wait_for_completion =
            query_param_is_true(request.query_params.get("wait_for_completion"));
        let restore_all_shards =
            query_param_is_true(request.query_params.get("restore_all_shards"));
        if wait_for_completion {
            return RestResponse::opensearch_error(
                400,
                "illegal_argument_exception",
                "wait_for_completion=true requires remote-store restore completion listener support",
            );
        }
        if restore_all_shards {
            return RestResponse::opensearch_error(
                400,
                "illegal_argument_exception",
                "restore_all_shards=true requires remote-store shard restore planning support",
            );
        }
        self.record_remote_store_restore_acceptance(
            &indices,
            wait_for_completion,
            restore_all_shards,
        );
        RestResponse::json(200, serde_json::json!({ "accepted": true }))
    }

    fn record_remote_store_restore_acceptance(
        &self,
        indices: &[String],
        wait_for_completion: bool,
        restore_all_shards: bool,
    ) {
        let resolved_indices = self.resolve_remote_store_restore_indices(indices);
        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        if !manifest.is_object() {
            *manifest = serde_json::json!({});
        }
        let Some(manifest_object) = manifest.as_object_mut() else {
            return;
        };
        let restore_root = manifest_object
            .entry("remote_store_restores".to_string())
            .or_insert_with(|| serde_json::json!({ "accepted": [] }));
        if !restore_root.is_object() {
            *restore_root = serde_json::json!({ "accepted": [] });
        }
        let Some(restore_object) = restore_root.as_object_mut() else {
            return;
        };
        let accepted = restore_object
            .entry("accepted".to_string())
            .or_insert_with(|| serde_json::json!([]));
        if !accepted.is_array() {
            *accepted = serde_json::json!([]);
        }
        if let Some(accepted_array) = accepted.as_array_mut() {
            accepted_array.push(serde_json::json!({
                "indices": indices,
                "resolved_indices": resolved_indices,
                "wait_for_completion": wait_for_completion,
                "restore_all_shards": restore_all_shards
            }));
        }
        drop(manifest);
        self.persist_shared_runtime_state_to_disk();
    }

    fn resolve_remote_store_restore_indices(&self, selectors: &[String]) -> Vec<String> {
        let created = self
            .created_indices_state
            .lock()
            .expect("created indices state lock poisoned")
            .clone();
        let mut resolved = Vec::new();
        for selector in selectors {
            for index in &created {
                if (selector == index || wildcard_match(selector, index))
                    && !resolved.contains(index)
                {
                    resolved.push(index.clone());
                }
            }
        }
        resolved
    }

    fn handle_wlm_stats_route(
        &self,
        node_id: Option<&str>,
        workload_group: Option<&str>,
    ) -> RestResponse {
        let runtime_node_id = self.info.name.as_str();
        let selected = match node_id {
            None | Some("_all") | Some("_local") => Some(runtime_node_id.to_string()),
            Some(candidate)
                if candidate == runtime_node_id || candidate == self.info.name.as_str() =>
            {
                Some(runtime_node_id.to_string())
            }
            Some(_) => None,
        };
        let workload_group_id = workload_group.unwrap_or("_all");
        let workload_group_stats = self.wlm_workload_group_stats_for_selector(workload_group_id);
        let cluster_name = self
            .cluster_view
            .as_ref()
            .map(|view| view.cluster_name.as_str())
            .filter(|name| !name.is_empty())
            .unwrap_or("steelsearch-dev");
        let mut body = serde_json::Map::new();
        body.insert("cluster_name".to_string(), serde_json::json!(cluster_name));
        body.insert(
            "_nodes".to_string(),
            serde_json::json!({
                "total": if selected.is_some() { 1 } else { 0 },
                "successful": if selected.is_some() && workload_group_stats.is_some() { 1 } else { 0 },
                "failed": if selected.is_some() && workload_group_stats.is_none() { 1 } else { 0 }
            }),
        );
        if let (Some(selected_node_id), Some(workload_groups)) =
            (selected.clone(), workload_group_stats)
        {
            body.insert(
                selected_node_id.clone(),
                serde_json::json!({ "workload_groups": workload_groups }),
            );
        } else if selected.is_some() {
            body.insert(
                "failures".to_string(),
                serde_json::json!([
                    {
                        "type": "resource_not_found_exception",
                        "reason": format!("WorkloadGroup with id {workload_group_id} does not exist")
                    }
                ]),
            );
        }
        RestResponse::json(200, Value::Object(body))
    }

    fn handle_wlm_workload_group_get_route(&self, name: Option<&str>) -> RestResponse {
        let groups = self
            .wlm_workload_groups_state
            .lock()
            .expect("wlm workload groups lock poisoned");
        let selected = match name {
            Some(name) => {
                let Some(group) = groups.get(name) else {
                    return RestResponse::opensearch_error(
                        404,
                        "resource_not_found_exception",
                        format!("No WorkloadGroup exists with the provided name: {name}"),
                    );
                };
                vec![group.to_opensearch_json()]
            }
            None => groups
                .values()
                .map(WlmWorkloadGroupState::to_opensearch_json)
                .collect(),
        };
        RestResponse::json(200, serde_json::json!({ "workload_groups": selected }))
    }

    fn handle_wlm_workload_group_create_route(&self, request: &RestRequest) -> RestResponse {
        if let Some(response) = self.reject_wlm_mutation_when_disabled("create WorkloadGroup") {
            return response;
        }
        let mutation = match parse_wlm_workload_group_mutation(&request.body, true) {
            Ok(mutation) => mutation,
            Err(response) => return response,
        };
        let Some(name) = mutation.name else {
            return wlm_illegal_argument_response(
                "WorkloadGroup.name shouldn't be null, empty or more than 50 chars long",
            );
        };
        let Some(resource_limits) = mutation.resource_limits else {
            return wlm_illegal_argument_response(
                "WorkloadGroup.resourceLimits should at least have 1 resource limit",
            );
        };
        if let Some(response) = self.validate_wlm_total_resource_usage(&name, &resource_limits) {
            return response;
        }
        let mut groups = self
            .wlm_workload_groups_state
            .lock()
            .expect("wlm workload groups lock poisoned");
        if groups.contains_key(&name) {
            return wlm_illegal_argument_response(format!(
                "WorkloadGroup with name {name} already exists. Not creating a new one."
            ));
        }
        let mut next_id = self
            .next_wlm_workload_group_id
            .lock()
            .expect("next wlm workload group id lock poisoned");
        *next_id += 1;
        let group = WlmWorkloadGroupState {
            id: format!("steel-wlm-workload-group-{next_id}"),
            name: name.clone(),
            resiliency_mode: mutation
                .resiliency_mode
                .unwrap_or_else(|| "enforced".to_string()),
            resource_limits,
            search_settings: mutation
                .search_settings
                .unwrap_or_else(|| serde_json::json!({})),
            updated_at: current_time_millis(),
        };
        let body = group.to_opensearch_json();
        groups.insert(name, group);
        RestResponse::json(200, body)
    }

    fn handle_wlm_workload_group_update_route(
        &self,
        request: &RestRequest,
        name: &str,
    ) -> RestResponse {
        if let Some(response) = self.reject_wlm_mutation_when_disabled("update WorkloadGroup") {
            return response;
        }
        let mutation = match parse_wlm_workload_group_mutation(&request.body, false) {
            Ok(mutation) => mutation,
            Err(response) => return response,
        };
        if let Some(resource_limits) = mutation.resource_limits.as_ref() {
            if let Some(response) = self.validate_wlm_total_resource_usage(name, resource_limits) {
                return response;
            }
        }
        let mut groups = self
            .wlm_workload_groups_state
            .lock()
            .expect("wlm workload groups lock poisoned");
        let Some(group) = groups.get_mut(name) else {
            return RestResponse::opensearch_error(
                404,
                "resource_not_found_exception",
                format!("No WorkloadGroup exists with the provided name: {name}"),
            );
        };
        if let Some(resiliency_mode) = mutation.resiliency_mode {
            group.resiliency_mode = resiliency_mode;
        }
        if let Some(resource_limits) = mutation.resource_limits {
            for (resource, value) in resource_limits {
                group.resource_limits.insert(resource, value);
            }
        }
        if let Some(search_settings) = mutation.search_settings {
            group.search_settings = search_settings;
        }
        group.updated_at = current_time_millis();
        RestResponse::json(200, group.to_opensearch_json())
    }

    fn handle_wlm_workload_group_delete_route(&self, name: &str) -> RestResponse {
        if let Some(response) = self.reject_wlm_mutation_when_disabled("delete WorkloadGroup") {
            return response;
        }
        let mut groups = self
            .wlm_workload_groups_state
            .lock()
            .expect("wlm workload groups lock poisoned");
        if groups.remove(name).is_none() {
            return RestResponse::opensearch_error(
                404,
                "resource_not_found_exception",
                format!("No WorkloadGroup exists with the provided name: {name}"),
            );
        }
        RestResponse::json(200, serde_json::json!({ "acknowledged": true }))
    }

    fn reject_wlm_mutation_when_disabled(&self, operation: &str) -> Option<RestResponse> {
        if self
            .cluster_setting_string("wlm.workload_group.mode")
            .as_deref()
            == Some("enabled")
        {
            return None;
        }
        Some(RestResponse::opensearch_error(
            500,
            "illegal_state_exception",
            format!(
                "Cannot {operation} because workload management mode is disabled or monitor_only.To enable this feature, set [wlm.workload_group.mode] to 'enabled' in cluster settings."
            ),
        ))
    }

    fn cluster_setting_string(&self, key: &str) -> Option<String> {
        let state = self
            .cluster_settings_state
            .lock()
            .expect("cluster settings state lock poisoned");
        state
            .get("transient")
            .and_then(Value::as_object)
            .and_then(|section| section.get(key))
            .or_else(|| {
                state
                    .get("persistent")
                    .and_then(Value::as_object)
                    .and_then(|section| section.get(key))
            })
            .and_then(Value::as_str)
            .map(ToOwned::to_owned)
    }

    fn validate_wlm_total_resource_usage(
        &self,
        name: &str,
        resource_limits: &BTreeMap<String, f64>,
    ) -> Option<RestResponse> {
        let groups = self
            .wlm_workload_groups_state
            .lock()
            .expect("wlm workload groups lock poisoned");
        for resource in resource_limits.keys() {
            let total = groups
                .values()
                .filter(|group| group.name != name)
                .filter_map(|group| group.resource_limits.get(resource))
                .fold(
                    *resource_limits.get(resource).unwrap_or(&0.0),
                    |acc, value| acc + value,
                );
            if total > 1.0 {
                return Some(wlm_illegal_argument_response(format!(
                    "Total resource allocation for {resource} will go above the max limit of 1.0."
                )));
            }
        }
        None
    }

    fn wlm_workload_group_stats_for_selector(
        &self,
        workload_group_id: &str,
    ) -> Option<BTreeMap<String, Value>> {
        let groups = self
            .wlm_workload_groups_state
            .lock()
            .expect("wlm workload groups lock poisoned");
        let mut stats = BTreeMap::new();
        if workload_group_id == "_all" || workload_group_id == "DEFAULT_WORKLOAD_GROUP" {
            stats.insert(
                "DEFAULT_WORKLOAD_GROUP".to_string(),
                wlm_empty_workload_group_stats_holder_json(),
            );
        }
        for group in groups.values() {
            if workload_group_id == "_all" || workload_group_id == group.id {
                stats.insert(
                    group.id.clone(),
                    wlm_empty_workload_group_stats_holder_json(),
                );
            }
        }
        if stats.is_empty() {
            None
        } else {
            Some(stats)
        }
    }

    fn handle_script_context_route(&self) -> RestResponse {
        let response = OpenSearchGetScriptContextResponseWire::default();
        let contexts = response
            .contexts
            .iter()
            .map(|context| {
                let mut methods = Vec::with_capacity(1 + context.getters.len());
                methods.push(script_context_method_json(&context.execute));
                methods.extend(context.getters.iter().map(script_context_method_json));
                serde_json::json!({
                    "name": context.name.clone(),
                    "methods": methods
                })
            })
            .collect::<Vec<_>>();
        RestResponse::json(200, serde_json::json!({ "contexts": contexts }))
    }

    fn handle_script_language_route(&self) -> RestResponse {
        let response = OpenSearchGetScriptLanguageResponseWire::default();
        let language_contexts = response
            .language_contexts
            .iter()
            .map(|(language, contexts)| {
                serde_json::json!({
                    "language": language.clone(),
                    "contexts": contexts.clone()
                })
            })
            .collect::<Vec<_>>();
        RestResponse::json(
            200,
            serde_json::json!({
                "types_allowed": response.types_allowed.clone(),
                "language_contexts": language_contexts
            }),
        )
    }

    fn handle_stored_script_get_route(
        &self,
        script_id: &str,
        request: &RestRequest,
    ) -> RestResponse {
        if let Some(response) = validate_stored_script_query_params(request) {
            return response;
        }
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let script = manifest["stored_scripts"]
            .as_object()
            .and_then(|scripts| scripts.get(script_id))
            .cloned();
        RestResponse::json(
            200,
            match script {
                Some(script) => serde_json::json!({
                    "_id": script_id,
                    "found": true,
                    "script": script
                }),
                None => serde_json::json!({
                    "_id": script_id,
                    "found": false
                }),
            },
        )
    }

    fn handle_stored_script_put_route(
        &self,
        script_id: &str,
        request: &RestRequest,
    ) -> RestResponse {
        if let Some(response) = validate_stored_script_query_params(request) {
            return response;
        }
        let body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        let script = body.get("script").cloned().unwrap_or(Value::Null);
        let mut manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let object = manifest
            .as_object_mut()
            .expect("metadata manifest should be object");
        let stored_scripts = object
            .entry("stored_scripts".to_string())
            .or_insert_with(|| Value::Object(serde_json::Map::new()));
        stored_scripts
            .as_object_mut()
            .expect("stored scripts should be object")
            .insert(script_id.to_string(), script);
        drop(manifest);
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(200, serde_json::json!({ "acknowledged": true }))
    }

    fn handle_stored_script_put_with_context_route(
        &self,
        script_id: &str,
        context: &str,
        request: &RestRequest,
    ) -> RestResponse {
        const ALLOWED_CONTEXTS: &[&str] =
            &["filter", "ingest", "score", "search", "template", "update"];
        if !ALLOWED_CONTEXTS.contains(&context) {
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "root_cause": [{
                            "type": "illegal_argument_exception",
                            "reason": format!("unknown script context [{context}]")
                        }],
                        "type": "illegal_argument_exception",
                        "reason": format!("unknown script context [{context}]")
                    },
                    "status": 400
                }),
            );
        }
        self.handle_stored_script_put_route(script_id, request)
    }

    fn handle_stored_script_delete_route(
        &self,
        script_id: &str,
        request: &RestRequest,
    ) -> RestResponse {
        if let Some(response) = validate_stored_script_query_params(request) {
            return response;
        }
        let removed = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned")["stored_scripts"]
            .as_object_mut()
            .and_then(|scripts| scripts.remove(script_id));
        if removed.is_none() {
            return RestResponse::json(
                404,
                serde_json::json!({
                    "error": {
                        "root_cause": [{
                            "type": "resource_not_found_exception",
                            "reason": format!("stored script [{script_id}] does not exist and cannot be deleted")
                        }],
                        "type": "resource_not_found_exception",
                        "reason": format!("stored script [{script_id}] does not exist and cannot be deleted")
                    },
                    "status": 404
                }),
            );
        }
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(200, serde_json::json!({ "acknowledged": true }))
    }

    fn handle_search_shards_route(
        &self,
        target: Option<&str>,
        request: &RestRequest,
    ) -> RestResponse {
        for field in ["ignore_unavailable", "allow_no_indices", "local"] {
            if let Some(response) = validate_opensearch_named_boolean_query_param(
                field,
                request.query_params.get(field),
            ) {
                return response;
            }
        }
        if let Some(response) = validate_index_expand_wildcards_query_param(request) {
            return response;
        }
        let requested_target = target.unwrap_or("_all");
        let ignore_unavailable =
            query_param_is_true(request.query_params.get("ignore_unavailable"));
        let allow_no_indices = ignore_unavailable
            || query_param_is_true(request.query_params.get("allow_no_indices"))
            || requested_target == "_all"
            || requested_target.contains('*')
            || requested_target.contains('?');
        let expand_wildcards = request
            .query_params
            .get("expand_wildcards")
            .map(String::as_str)
            .unwrap_or("open");
        let selected_indices = match self.resolve_search_targets(
            requested_target,
            ignore_unavailable,
            allow_no_indices,
            expand_wildcards,
        ) {
            Ok(indices) => indices,
            Err(response) => return response,
        };
        RestResponse::json(200, self.search_shards_body(selected_indices))
    }

    fn search_shards_body(&self, mut selected_indices: Vec<String>) -> Value {
        selected_indices.sort();
        let created_indices = self
            .created_indices_state
            .lock()
            .expect("created indices state lock poisoned")
            .clone();
        selected_indices.retain(|index| created_indices.contains(index));

        let default_node = DevelopmentClusterNode {
            node_id: self.info.name.clone(),
            node_name: self.info.name.clone(),
            http_address: Some("127.0.0.1:9200".to_string()),
            transport_address: "127.0.0.1:9300".to_string(),
            roles: vec!["cluster_manager".to_string(), "data".to_string()],
            local: true,
        };
        let view = self.cluster_view.clone().unwrap_or_default();
        let local_node = view
            .nodes
            .iter()
            .find(|candidate| candidate.local)
            .cloned()
            .or_else(|| view.nodes.first().cloned())
            .unwrap_or(default_node);

        let mut nodes = serde_json::Map::new();
        nodes.insert(
            local_node.node_id.clone(),
            serde_json::json!({
                "name": local_node.node_name,
                "ephemeral_id": format!("{}-ephemeral", local_node.node_id),
                "transport_address": local_node.transport_address,
                "attributes": {
                    "testattr": "test",
                    "shard_indexing_pressure_enabled": "true"
                }
            }),
        );

        let mut indices = serde_json::Map::new();
        let mut shards = Vec::new();
        for index in selected_indices {
            indices.insert(index.clone(), serde_json::json!({}));
            shards.push(Value::Array(vec![serde_json::json!({
                "state": "STARTED",
                "primary": true,
                "node": local_node.node_id,
                "relocating_node": Value::Null,
                "shard": 0,
                "index": index,
                "allocation_id": {
                    "id": format!("alloc-{index}-0")
                }
            })]));
        }

        serde_json::json!({
            "nodes": nodes,
            "indices": indices,
            "shards": shards
        })
    }

    fn cluster_stats_body(&self) -> Value {
        let view = self.cluster_view.clone().unwrap_or_default();
        let index_count = self
            .created_indices_state
            .lock()
            .expect("created indices state lock poisoned")
            .len() as u64;
        let node_count = view.nodes.len() as u64;
        let shard_total = index_count.saturating_mul(2);
        let primary_total = index_count;
        let unique_versions = view
            .nodes
            .iter()
            .map(|_| "3.7.0")
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        serde_json::json!({
            "cluster_uuid": if view.cluster_uuid.is_empty() {
                "_na_".to_string()
            } else {
                view.cluster_uuid.clone()
            },
            "cluster_name": if view.cluster_name.is_empty() {
                self.info.name.clone()
            } else {
                view.cluster_name.clone()
            },
            "timestamp": 1,
            "status": if node_count <= 1 { "yellow" } else { "green" },
            "indices": {
                "count": index_count,
                "docs": {
                    "count": 0
                },
                "shards": {
                    "total": shard_total,
                    "primaries": primary_total,
                    "replication": if primary_total == 0 {
                        0.0
                    } else {
                        1.0
                    }
                },
                "store": {
                    "size_in_bytes": 0
                },
                "fielddata": {
                    "memory_size_in_bytes": 0
                },
                "query_cache": {
                    "memory_size_in_bytes": 0
                },
                "completion": {
                    "size_in_bytes": 0
                },
                "segments": {
                    "count": 0
                }
            },
            "nodes": {
                "count": {
                    "total": node_count,
                    "data": node_count,
                    "cluster_manager_only": 0
                },
                "versions": unique_versions,
                "os": {
                    "available_processors": 1,
                    "allocated_processors": 1
                },
                "jvm": {
                    "max_uptime_in_millis": 0,
                    "versions": [{
                        "version": "21",
                        "vm_name": "OpenJDK 64-Bit Server VM",
                        "vm_vendor": "OpenJDK"
                    }]
                }
            },
            "fs": {
                "total_in_bytes": 0,
                "free_in_bytes": 0,
                "available_in_bytes": 0
            }
        })
    }

    fn cluster_stats_variant_path_supported(&self, path: &str) -> bool {
        let Some(remainder) = path.strip_prefix("/_cluster/stats/") else {
            return false;
        };
        let segments = remainder
            .split('/')
            .filter(|segment| !segment.is_empty())
            .collect::<Vec<_>>();
        match segments.as_slice() {
            ["nodes", node_id] => !node_id.is_empty(),
            [metric, "nodes", node_id] => !metric.is_empty() && !node_id.is_empty(),
            [metric, index_metric, "nodes", node_id] => {
                !metric.is_empty() && !index_metric.is_empty() && !node_id.is_empty()
            }
            _ => false,
        }
    }

    fn handle_nodes_hot_threads_route(
        &self,
        request: &RestRequest,
        requested_node: Option<&str>,
    ) -> RestResponse {
        let threads = match parse_hot_threads_int_query_param(request, "threads", 3) {
            Ok(value) => value,
            Err(response) => return response,
        };
        let snapshots = match parse_hot_threads_int_query_param(request, "snapshots", 10) {
            Ok(value) => value,
            Err(response) => return response,
        };
        if let Some(response) =
            validate_opensearch_boolean_query_param(request.query_params.get("ignore_idle_threads"))
        {
            return response;
        }
        let ignore_idle_threads = request
            .query_params
            .get("ignore_idle_threads")
            .map(|raw| query_param_is_true(Some(raw)))
            .unwrap_or(true);
        let hot_threads_type = request
            .query_params
            .get("type")
            .map(String::as_str)
            .unwrap_or("cpu");
        if !matches!(hot_threads_type, "cpu" | "wait" | "block") {
            return RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                format!("type not supported [{hot_threads_type}]"),
            );
        }
        let interval = request
            .query_params
            .get("interval")
            .map(String::as_str)
            .unwrap_or("500ms");
        if parse_time_value_millis(interval).is_none() {
            return RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                format!(
                    "failed to parse setting [interval] with value [{interval}] as a time value: unit is missing or unrecognized"
                ),
            );
        }
        let cluster_name = self
            .cluster_view
            .as_ref()
            .map(|view| view.cluster_name.as_str())
            .unwrap_or("steelsearch-dev");
        let node_name = requested_node
            .filter(|node| !node.is_empty() && *node != "_all")
            .unwrap_or(self.info.name.as_str());
        let body = format!(
            "::: {node_name}\nHot threads at 2026-05-01T00:00:00Z, interval={interval}, busiestThreads={threads}, ignoreIdleThreads={ignore_idle_threads}:\n   0.0% (0ms out of 500ms) {hot_threads_type} usage by thread '{cluster_name}[{node_name}][generic][T#1]'\n    1/{snapshots} snapshots sharing following 1 elements\n      java.base@21/java.lang.Thread.sleep(Native Method)\n"
        );
        RestResponse::text(200, body)
    }

    fn handle_nodes_reload_secure_settings_route(
        &self,
        requested_node: Option<&str>,
        request: &RestRequest,
    ) -> RestResponse {
        if let Some(response) = validate_tasks_time_query_params(request, &["timeout"]) {
            return response;
        }
        let cluster_name = self
            .cluster_view
            .as_ref()
            .map(|view| view.cluster_name.clone())
            .filter(|name| !name.is_empty())
            .unwrap_or_else(|| self.info.name.clone());
        let selector = requested_node
            .filter(|node| !node.is_empty())
            .unwrap_or("_all");
        let all_nodes = self.nodes_info_body()["nodes"]
            .as_object()
            .cloned()
            .unwrap_or_default();
        let selected_nodes = all_nodes
            .into_iter()
            .filter(|(node_id, node)| {
                if matches!(selector, "_all" | "_local" | "*") {
                    return true;
                }
                let node_name = node.get("name").and_then(Value::as_str).unwrap_or_default();
                node_id == selector
                    || node_name == selector
                    || matches_index_selector(selector, node_id)
                    || matches_index_selector(selector, node_name)
            })
            .map(|(node_id, node)| {
                let node_name = node
                    .get("name")
                    .cloned()
                    .unwrap_or_else(|| Value::String(node_id.clone()));
                (
                    node_id,
                    serde_json::json!({
                        "name": node_name
                    }),
                )
            })
            .collect::<serde_json::Map<String, Value>>();
        let total = selected_nodes.len();
        RestResponse::json(
            200,
            serde_json::json!({
                "_nodes": {
                    "total": total,
                    "successful": total,
                    "failed": 0
                },
                "cluster_name": cluster_name,
                "nodes": selected_nodes
            }),
        )
    }

    fn nodes_stats_variant_path_supported(&self, path: &str) -> bool {
        let Some(remainder) = path.strip_prefix("/_nodes/") else {
            return false;
        };
        let segments = remainder
            .split('/')
            .filter(|segment| !segment.is_empty())
            .collect::<Vec<_>>();
        match segments.as_slice() {
            ["stats", metric] => !metric.is_empty(),
            ["stats", metric, index_metric] => !metric.is_empty() && !index_metric.is_empty(),
            [node_id, "stats"] => !node_id.is_empty(),
            [node_id, "stats", metric] => !node_id.is_empty() && !metric.is_empty(),
            [node_id, "stats", metric, index_metric] => {
                !node_id.is_empty() && !metric.is_empty() && !index_metric.is_empty()
            }
            _ => false,
        }
    }

    fn nodes_usage_variant_path_supported(&self, path: &str) -> bool {
        let Some(remainder) = path.strip_prefix("/_nodes/") else {
            return false;
        };
        let segments = remainder
            .split('/')
            .filter(|segment| !segment.is_empty())
            .collect::<Vec<_>>();
        match segments.as_slice() {
            ["usage"] => true,
            ["usage", metric] => !metric.is_empty(),
            [node_id, "usage"] => !node_id.is_empty(),
            [node_id, "usage", metric] => !node_id.is_empty() && !metric.is_empty(),
            _ => false,
        }
    }

    fn nodes_info_variant_path_supported(&self, path: &str) -> bool {
        let Some(remainder) = path.strip_prefix("/_nodes/") else {
            return false;
        };
        let segments = remainder
            .split('/')
            .filter(|segment| !segment.is_empty())
            .collect::<Vec<_>>();
        match segments.as_slice() {
            [node_id] => !node_id.is_empty(),
            [node_id, metric] => {
                !node_id.is_empty()
                    && !metric.is_empty()
                    && *metric != "stats"
                    && *metric != "usage"
            }
            [node_id, "info", metric] => !node_id.is_empty() && !metric.is_empty(),
            _ => false,
        }
    }

    fn index_stats_variant_path_supported(&self, path: &str) -> bool {
        let Some(metric) = path.strip_prefix("/_stats/") else {
            return false;
        };
        !metric.is_empty() && !metric.contains('/')
    }

    fn index_stats_body(&self) -> Value {
        let created_indices = self
            .created_indices_state
            .lock()
            .expect("created indices state lock poisoned")
            .clone();
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let created_indices = created_indices
            .into_iter()
            .filter(|index| !index_metadata_is_hidden(&manifest["indices"][index]))
            .collect::<Vec<_>>();
        drop(manifest);
        let created_index_count = created_indices.len();
        let pit_open_contexts_by_index = self.pit_open_context_counts_by_index();
        let total_pit_open_contexts = created_indices
            .iter()
            .map(|index| pit_open_contexts_by_index.get(index).copied().unwrap_or(0))
            .sum::<u64>();
        let pit_total_contexts_by_index = self
            .pit_total_contexts_by_index
            .lock()
            .expect("pit total contexts lock poisoned")
            .clone();
        let pit_time_millis_by_index = self
            .pit_time_millis_by_index
            .lock()
            .expect("pit time millis lock poisoned")
            .clone();
        let total_pit_contexts = created_indices
            .iter()
            .map(|index| pit_total_contexts_by_index.get(index).copied().unwrap_or(0))
            .sum::<u64>();
        let total_pit_time_millis = created_indices
            .iter()
            .map(|index| pit_time_millis_by_index.get(index).copied().unwrap_or(0))
            .sum::<u64>();
        let mut indices = serde_json::Map::new();
        for index in created_indices {
            let pit_open_contexts = pit_open_contexts_by_index
                .get(&index)
                .copied()
                .unwrap_or_default();
            let pit_total_contexts = pit_total_contexts_by_index
                .get(&index)
                .copied()
                .unwrap_or_default();
            let pit_time_millis = pit_time_millis_by_index
                .get(&index)
                .copied()
                .unwrap_or_default();
            indices.insert(
                index,
                serde_json::json!({
                    "primaries": {
                        "docs": { "count": 0 },
                        "search": search_stats_body(
                            pit_open_contexts,
                            pit_open_contexts,
                            pit_total_contexts,
                            pit_time_millis
                        )
                    },
                    "total": {
                        "docs": { "count": 0 },
                        "search": search_stats_body(
                            pit_open_contexts,
                            pit_open_contexts,
                            pit_total_contexts,
                            pit_time_millis
                        )
                    }
                }),
            );
        }
        serde_json::json!({
            "_shards": {
                "total": created_index_count,
                "successful": created_index_count,
                "failed": 0
            },
            "_all": {
                "primaries": {
                    "docs": {
                        "count": 0
                    },
                    "search": search_stats_body(
                        total_pit_open_contexts,
                        total_pit_open_contexts,
                        total_pit_contexts,
                        total_pit_time_millis
                    )
                },
                "total": {
                    "docs": {
                        "count": 0
                    },
                    "search": search_stats_body(
                        total_pit_open_contexts,
                        total_pit_open_contexts,
                        total_pit_contexts,
                        total_pit_time_millis
                    )
                }
            },
            "indices": indices
        })
    }

    fn pit_open_context_counts_by_index(&self) -> BTreeMap<String, u64> {
        let now_millis = current_epoch_millis();
        let mut contexts = self
            .pit_contexts
            .lock()
            .expect("pit contexts lock poisoned");
        let expired_contexts = drain_expired_pit_contexts(&mut contexts, now_millis);
        drop(contexts);
        self.record_pit_context_time_millis(&expired_contexts, now_millis);
        let contexts = self
            .pit_contexts
            .lock()
            .expect("pit contexts lock poisoned");
        let mut counts = BTreeMap::new();
        for context in contexts.values() {
            for index in &context.indices {
                let shard_contexts = self.index_primary_shard_count(index).max(1) as u64;
                *counts.entry(index.clone()).or_insert(0) += shard_contexts;
            }
        }
        counts
    }

    fn record_pit_open_context_totals(&self, indices: &[String]) {
        let mut totals = self
            .pit_total_contexts_by_index
            .lock()
            .expect("pit total contexts lock poisoned");
        for index in indices {
            let shard_contexts = self.index_primary_shard_count(index).max(1) as u64;
            *totals.entry(index.clone()).or_insert(0) += shard_contexts;
        }
    }

    fn record_pit_context_time_millis(&self, contexts: &[PitContext], now_millis: u128) {
        record_pit_context_time_millis_with_lookup(
            &self.pit_time_millis_by_index,
            contexts,
            now_millis,
            |index| self.index_primary_shard_count(index),
        );
    }

    fn handle_index_stats_route(
        &self,
        target: Option<&str>,
        request: &RestRequest,
    ) -> RestResponse {
        let body = self.index_stats_body();
        let (all_matched, open_matched) =
            match self.resolve_open_index_state_targets(target, request) {
                Ok(matched) => matched,
                Err(response) => return response,
            };

        let filtered_indices = body["indices"]
            .as_object()
            .cloned()
            .unwrap_or_default()
            .into_iter()
            .filter(|(index, _)| open_matched.contains(index))
            .collect::<serde_json::Map<String, Value>>();
        let total = self.index_state_read_total_shards(&all_matched, &open_matched);
        let successful = filtered_indices.len();

        RestResponse::json(
            200,
            stats_route_registration::invoke_index_stats_live_route(&serde_json::json!({
                "_shards": {
                    "total": total,
                    "successful": successful,
                    "failed": 0
                },
                "_all": body["_all"].clone(),
                "indices": filtered_indices
            })),
        )
    }

    fn handle_analyze_route(&self, target: Option<&str>, request: &RestRequest) -> RestResponse {
        if let Some(target) = target {
            if !self.index_or_alias_exists(target) {
                return index_not_found_response(target);
            }
        }
        let (text, analyzer) = if request.method == RestMethod::Get {
            let Some(text) = request.query_params.get("text") else {
                return action_request_validation_error(vec!["text is missing"]);
            };
            (
                decode_url_component(text),
                request.query_params.get("analyzer").cloned(),
            )
        } else {
            let body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
            let text = match body.get("text") {
                Some(Value::String(text)) => text.clone(),
                Some(Value::Array(values)) => values
                    .iter()
                    .filter_map(Value::as_str)
                    .collect::<Vec<_>>()
                    .join(" "),
                _ => return action_request_validation_error(vec!["text is missing"]),
            };
            let analyzer = body
                .get("analyzer")
                .and_then(Value::as_str)
                .map(ToOwned::to_owned);
            (text, analyzer)
        };

        let mut offset = 0usize;
        let token_stream = if analyzer
            .as_deref()
            .is_some_and(|value| value.eq_ignore_ascii_case("keyword"))
        {
            if text.is_empty() {
                Vec::new()
            } else {
                vec![text.clone()]
            }
        } else {
            tokenize_search_text(&text)
        };
        let tokens = token_stream
            .into_iter()
            .enumerate()
            .map(|(position, token)| {
                let start_offset = text[offset..]
                    .to_ascii_lowercase()
                    .find(&token)
                    .map(|delta| offset + delta)
                    .unwrap_or(offset);
                let end_offset = start_offset + token.len();
                offset = end_offset;
                serde_json::json!({
                    "token": token,
                    "start_offset": start_offset,
                    "end_offset": end_offset,
                    "type": "word",
                    "position": position
                })
            })
            .collect::<Vec<_>>();

        RestResponse::json(200, serde_json::json!({ "tokens": tokens }))
    }

    fn handle_flush_route(&self, target: Option<&str>, request: &RestRequest) -> RestResponse {
        let _thread_pool = match self.enter_runtime_thread_pool("maintenance", 1000) {
            Ok(execution) => execution,
            Err(response) => return response,
        };
        let (total, successful) = match self.maintenance_shard_counts(target, request) {
            Ok(counts) => counts,
            Err(response) => return response,
        };
        RestResponse::json(
            200,
            serde_json::json!({
                "_shards": {
                    "total": total,
                    "successful": successful,
                    "failed": 0
                }
            }),
        )
    }

