    fn handle_knn_model_search_route(&self, request: &RestRequest) -> RestResponse {
        let body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        if request.query_params.contains_key("index") {
            return RestResponse::opensearch_error(
                400,
                "illegal_argument_exception",
                "request contains an unrecognized parameter: [ index ]",
            );
        }
        let size_limit = match request.query_params.get("size") {
            Some(raw_size) => match raw_size.parse::<usize>() {
                Ok(size) if (1..=1000).contains(&size) => Some(size),
                _ => {
                    return RestResponse::opensearch_error(
                        400,
                        "illegal_argument_exception",
                        "size must be between 1 and 1000 inclusive",
                    );
                }
            },
            None => body
                .get("size")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok()),
        };
        let filter_model_id = body
            .get("query")
            .and_then(Value::as_object)
            .and_then(|query| query.get("term"))
            .and_then(Value::as_object)
            .and_then(|term| term.get("model_id"))
            .and_then(Value::as_str);
        let state = self
            .knn_operational_state
            .lock()
            .expect("knn operational state lock poisoned");
        let models = state
            .as_ref()
            .map(|current| current.trained_models.values().cloned().collect::<Vec<_>>())
            .unwrap_or_default();
        let mut hits: Vec<Value> = models
            .into_iter()
            .filter(|model| {
                filter_model_id
                    .map(|value| value == model.model_id)
                    .unwrap_or(true)
            })
            .map(|model| {
                serde_json::json!({
                    "_id": model.model_id,
                    "_source": {
                        "training_index": model.training_index,
                        "dimension": model.dimension,
                        "description": model.description,
                        "method": model.method,
                        "state": model.state,
                        "task_id": model.task_id,
                        "transport_action": model.transport_action
                    }
                })
            })
            .collect();
        let total = hits.len();
        if let Some(size_limit) = size_limit {
            hits.truncate(size_limit);
        }
        RestResponse::json(
            200,
            serde_json::json!({
                "hits": {
                    "total": {
                        "value": total,
                        "relation": "eq"
                    },
                    "hits": hits
                }
            }),
        )
    }

    fn handle_ml_model_register_route(&self, request: &RestRequest) -> RestResponse {
        let body = serde_json::from_slice::<Value>(&request.body).unwrap_or(Value::Null);
        let name = body
            .get("name")
            .and_then(Value::as_str)
            .unwrap_or("bounded-ml-model")
            .to_string();
        let function_name = body
            .get("function_name")
            .and_then(Value::as_str)
            .unwrap_or("text_embedding")
            .to_string();
        let dimension = body.get("dimension").and_then(Value::as_u64).unwrap_or(3);
        let mut next = self
            .next_ml_model_id
            .lock()
            .expect("next ml model id lock poisoned");
        *next += 1;
        let model_id = format!("ml-model-{}", *next);
        drop(next);
        let model = MlModelState {
            model_id: model_id.clone(),
            name,
            function_name,
            dimension,
            deployed: false,
            last_task_id: String::new(),
            last_task_state: "REGISTERED".to_string(),
        };
        let mut next_task = self
            .next_ml_task_id
            .lock()
            .expect("next ml task id lock poisoned");
        *next_task += 1;
        let task_id = format!("ml-task-{}", *next_task);
        drop(next_task);
        let mut persisted_model = model.clone();
        persisted_model.last_task_id = task_id.clone();
        self.ml_models_state
            .lock()
            .expect("ml models state lock poisoned")
            .insert(model_id.clone(), persisted_model);
        self.ml_tasks_state
            .lock()
            .expect("ml tasks state lock poisoned")
            .insert(
                task_id.clone(),
                MlTaskState {
                    task_id: task_id.clone(),
                    model_id: model_id.clone(),
                    task_type: "REGISTER_MODEL".to_string(),
                    state: "COMPLETED".to_string(),
                },
            );
        self.persist_shared_runtime_state_to_disk();
        RestResponse::json(
            200,
            serde_json::json!({
                "model_id": model_id,
                "task_id": task_id,
                "status": "CREATED",
                "name": model.name,
                "function_name": model.function_name,
                "model_state": "registered",
                "task_state": "COMPLETED"
            }),
        )
    }

