    fn handle_cat_nodes_route(&self, request: &RestRequest) -> RestResponse {
        if let Some(response) = validate_cat_cluster_manager_timeout_query_params(request) {
            return response;
        }
        let nodes = self
            .cluster_view
            .as_ref()
            .map(|view| view.nodes.clone())
            .unwrap_or_else(|| {
                vec![DevelopmentClusterNode {
                    node_id: self.info.name.clone(),
                    node_name: self.info.name.clone(),
                    http_address: Some("127.0.0.1:9200".to_string()),
                    transport_address: "127.0.0.1:9300".to_string(),
                    roles: vec!["cluster_manager".to_string(), "data".to_string()],
                    local: true,
                }]
            });
        let local_search_open_contexts = self.search_open_context_count_for_stats();
        let local_pit_current_contexts = self
            .pit_open_context_counts_by_index()
            .values()
            .copied()
            .sum::<u64>();
        let local_pit_total_contexts = self
            .pit_total_contexts_by_index
            .lock()
            .expect("pit total contexts lock poisoned")
            .values()
            .copied()
            .sum::<u64>();
        let local_pit_time_millis = self
            .pit_time_millis_by_index
            .lock()
            .expect("pit time millis lock poisoned")
            .values()
            .copied()
            .sum::<u64>();
        let mut rows = Vec::new();
        for node in nodes {
            let (ip, port) = node
                .transport_address
                .rsplit_once(':')
                .map(|(host, value)| (host.to_string(), value.to_string()))
                .unwrap_or_else(|| ("127.0.0.1".to_string(), "9300".to_string()));
            let role_summary = if node.roles.iter().any(|role| role == "cluster_manager") {
                "dim"
            } else if node.roles.iter().any(|role| role == "data") {
                "di"
            } else {
                "-"
            };
            let (search_open_contexts, pit_current, pit_total, pit_time_millis) = if node.local {
                (
                    local_search_open_contexts,
                    local_pit_current_contexts,
                    local_pit_total_contexts,
                    local_pit_time_millis,
                )
            } else {
                (0, 0, 0, 0)
            };
            rows.push(serde_json::json!({
                "id": node.node_id,
                "pid": "1",
                "ip": ip,
                "port": port,
                "http_address": node.http_address.unwrap_or("-".to_string()),
                "version": self.info.version.to_string(),
                "type": "tar",
                "build": "-",
                "jdk": "-",
                "heap.current": "0b",
                "heap.max": "0b",
                "heap.percent": "0",
                "ram.current": "0b",
                "ram.max": "0b",
                "ram.percent": "0",
                "disk.total": "0b",
                "disk.used": "0b",
                "disk.avail": "0b",
                "disk.used_percent": "0.00",
                "file_desc.current": "0",
                "file_desc.percent": "0",
                "file_desc.max": "0",
                "cpu": "0",
                "load_1m": "0.00",
                "load_5m": "0.00",
                "load_15m": "0.00",
                "uptime": "0s",
                "node.role": role_summary,
                "node.roles": node.roles.join(","),
                "cluster_manager": if node.local { "*" } else { "-" },
                "master": if node.local { "*" } else { "-" },
                "search.open_contexts": search_open_contexts.to_string(),
                "search.point_in_time_current": pit_current.to_string(),
                "search.point_in_time_time": format_time_value_millis(pit_time_millis),
                "search.point_in_time_total": pit_total.to_string(),
                "name": node.node_name,
            }));
        }
        rows.sort_by(|left, right| {
            left["name"]
                .as_str()
                .unwrap_or_default()
                .cmp(right["name"].as_str().unwrap_or_default())
        });
        if request
            .query_params
            .get("format")
            .is_some_and(|value| value == "json")
        {
            let display_columns = cat_nodes_display_columns(request.query_params.get("h"));
            let selected_rows = rows
                .iter()
                .map(|row| {
                    let mut object = serde_json::Map::new();
                    for (column, display) in &display_columns {
                        object.insert(display.clone(), row[*column].clone());
                    }
                    Value::Object(object)
                })
                .collect::<Vec<_>>();
            return RestResponse::json(200, Value::Array(selected_rows));
        }
        let verbose = request
            .query_params
            .get("v")
            .is_some_and(|value| value == "true");
        let display_columns = cat_nodes_display_columns(request.query_params.get("h"));
        let mut lines = Vec::new();
        if verbose {
            lines.push(
                display_columns
                    .iter()
                    .map(|(_, display)| display.as_str())
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        for row in &rows {
            lines.push(
                display_columns
                    .iter()
                    .map(|(column, _)| row[*column].as_str().unwrap_or(""))
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        RestResponse::text(200, lines.join("\n") + "\n")
    }

