    fn handle_segments_route(&self, target: Option<&str>, request: &RestRequest) -> RestResponse {
        let mut indices = serde_json::Map::new();
        let (all_matched, open_matched) =
            match self.resolve_open_index_state_targets(target, request) {
                Ok(matched) => matched,
                Err(response) => return response,
            };
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let matched_indices: Vec<String> = open_matched
            .into_iter()
            .filter(|index| !index_metadata_is_hidden(&manifest["indices"][index]))
            .collect();
        drop(manifest);
        for index in &matched_indices {
            let docs = self.index_lucene_document_count(&index);
            let segment_size = self.index_segment_size_bytes(&index, docs);
            indices.insert(
                index.clone(),
                serde_json::json!({
                    "shards": {
                        "0": [
                            {
                                "routing": {
                                    "primary": true,
                                    "state": "STARTED"
                                },
                                "num_committed_segments": 0,
                                "num_search_segments": 1,
                                "segments": {
                                    "_0": {
                                        "generation": 0,
                                        "num_docs": docs,
                                        "deleted_docs": 0,
                                        "size_in_bytes": segment_size,
                                        "memory_in_bytes": 0,
                                        "committed": false,
                                        "search": true,
                                        "version": "10.4.0",
                                        "compound": true
                                    }
                                }
                            }
                        ]
                    }
                }),
            );
        }
        RestResponse::json(
            200,
            serde_json::json!({
                "_shards": {
                    "total": self.index_state_read_total_shards(&all_matched, &matched_indices),
                    "successful": indices.len(),
                    "failed": 0
                },
                "indices": indices
            }),
        )
    }

    fn handle_cat_pit_segments_route(
        &self,
        request: &RestRequest,
        include_all: bool,
    ) -> RestResponse {
        if let Some(response) =
            cat_pit_segments_unrecognized_query_param_response(request, include_all)
        {
            return response;
        }
        let pit_ids = if include_all {
            Vec::new()
        } else {
            if request.query_params.contains_key("source")
                && request
                    .query_params
                    .get("source_content_type")
                    .is_some_and(|source_content_type| source_content_type == "json")
            {
                return delete_pit_illegal_argument("invalid Content-Type header [json]");
            }
            let body = match pit_body_or_source_param(request) {
                Ok(body) => body,
                Err(response) => return response,
            };
            match parse_pit_segments_ids(&body) {
                Ok(ids) => ids,
                Err(response) => return response,
            }
        };
        let mut seen_pit_ids = BTreeSet::new();
        let pit_ids = pit_ids
            .into_iter()
            .filter(|pit_id| seen_pit_ids.insert(pit_id.clone()))
            .collect::<Vec<_>>();
        let mut contexts = self
            .pit_contexts
            .lock()
            .expect("pit contexts lock poisoned");
        let now_millis = current_epoch_millis();
        let expired_contexts = drain_expired_pit_contexts(&mut contexts, now_millis);
        drop(contexts);
        self.record_pit_context_time_millis(&expired_contexts, now_millis);
        let contexts = self
            .pit_contexts
            .lock()
            .expect("pit contexts lock poisoned");
        let pit_ids = if include_all {
            contexts.keys().cloned().collect::<Vec<_>>()
        } else {
            pit_ids
        };
        for pit_id in &pit_ids {
            if !pit_search_id_has_local_shape(pit_id) {
                return delete_pit_invalid_id_response(pit_id);
            }
            if !contexts.contains_key(pit_id) {
                return search_phase_missing_pit_context_response(pit_id);
            }
        }
        let mut rows = Vec::new();
        for pit_id in pit_ids {
            let Some(context) = contexts.get(&pit_id) else {
                continue;
            };
            for index in &context.indices {
                let docs = self.pit_lucene_document_count(index, &context.documents);
                rows.push(serde_json::json!({
                    "index": index,
                    "shard": "0",
                    "prirep": "p",
                    "ip": "127.0.0.1",
                    "id": self.info.name.clone(),
                    "segment": "_0",
                    "generation": "0",
                    "docs.count": docs.to_string(),
                    "docs.deleted": "0",
                    "size": "0b",
                    "size.memory": "0",
                    "committed": "true",
                    "searchable": "true",
                    "version": "0",
                    "compound": "false"
                }));
            }
        }
        rows.sort_by(|left, right| {
            left["index"]
                .as_str()
                .unwrap_or_default()
                .cmp(right["index"].as_str().unwrap_or_default())
                .then_with(|| {
                    left["segment"]
                        .as_str()
                        .unwrap_or_default()
                        .cmp(right["segment"].as_str().unwrap_or_default())
                })
        });
        if request
            .query_params
            .get("format")
            .is_some_and(|value| value == "json")
        {
            let display_columns = cat_pit_segments_display_columns(request.query_params.get("h"));
            let selected_rows = rows
                .iter()
                .map(|row| {
                    let mut object = serde_json::Map::new();
                    for (column, display) in &display_columns {
                        object.insert(display.clone(), row[*column].clone());
                    }
                    Value::Object(object)
                })
                .collect();
            return RestResponse::json(200, Value::Array(selected_rows));
        }
        let verbose = request
            .query_params
            .get("v")
            .is_some_and(|value| value == "true");
        let display_columns = cat_pit_segments_display_columns(request.query_params.get("h"));
        let mut lines = Vec::new();
        if verbose {
            lines.push(
                display_columns
                    .iter()
                    .map(|(_, display)| display.as_str())
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        for row in &rows {
            lines.push(
                display_columns
                    .iter()
                    .map(|(column, _)| row[*column].as_str().unwrap_or(""))
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        RestResponse::text(200, lines.join("\n") + "\n")
    }

