    fn handle_cat_templates_route(
        &self,
        request: &RestRequest,
        target: Option<&str>,
    ) -> RestResponse {
        if let Some(response) = validate_cat_cluster_manager_timeout_query_params(request) {
            return response;
        }
        let manifest = self
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        let mut rows = Vec::new();
        if let Some(templates) = manifest["templates"]["legacy_index_templates"].as_object() {
            for (name, template) in templates {
                if target
                    .map(|pattern| wildcard_match(pattern, name))
                    .unwrap_or(true)
                {
                    let patterns = template["index_patterns"]
                        .as_array()
                        .map(|patterns| {
                            patterns
                                .iter()
                                .filter_map(Value::as_str)
                                .collect::<Vec<_>>()
                                .join(", ")
                        })
                        .unwrap_or_default();
                    rows.push(serde_json::json!({
                        "name": name,
                        "index_patterns": format!("[{patterns}]"),
                        "order": template.get("order").and_then(Value::as_u64).unwrap_or(0).to_string(),
                        "version": template.get("version").and_then(Value::as_u64).map(|v| v.to_string()).unwrap_or_default(),
                        "composed_of": ""
                    }));
                }
            }
        }
        if let Some(templates) = manifest["templates"]["index_templates"].as_object() {
            for (name, template) in templates {
                if target
                    .map(|pattern| wildcard_match(pattern, name))
                    .unwrap_or(true)
                {
                    let index_template = &template["index_template"];
                    let patterns = index_template["index_patterns"]
                        .as_array()
                        .map(|patterns| {
                            patterns
                                .iter()
                                .filter_map(Value::as_str)
                                .collect::<Vec<_>>()
                                .join(", ")
                        })
                        .unwrap_or_default();
                    let composed_of = index_template["composed_of"]
                        .as_array()
                        .map(|items| {
                            items
                                .iter()
                                .filter_map(Value::as_str)
                                .collect::<Vec<_>>()
                                .join(", ")
                        })
                        .unwrap_or_default();
                    rows.push(serde_json::json!({
                        "name": name,
                        "index_patterns": format!("[{patterns}]"),
                        "order": index_template.get("priority").and_then(Value::as_u64).unwrap_or(0).to_string(),
                        "version": index_template.get("version").and_then(Value::as_u64).map(|v| v.to_string()).unwrap_or_default(),
                        "composed_of": format!("[{composed_of}]")
                    }));
                }
            }
        }
        drop(manifest);
        rows.sort_by(|left, right| {
            left["name"]
                .as_str()
                .unwrap_or_default()
                .cmp(right["name"].as_str().unwrap_or_default())
        });
        if request
            .query_params
            .get("format")
            .is_some_and(|value| value == "json")
        {
            let display_columns = cat_templates_display_columns(request.query_params.get("h"));
            let selected_rows = rows
                .iter()
                .map(|row| {
                    let mut object = serde_json::Map::new();
                    for (column, display) in &display_columns {
                        object.insert(display.clone(), row[*column].clone());
                    }
                    Value::Object(object)
                })
                .collect::<Vec<_>>();
            return RestResponse::json(200, Value::Array(selected_rows));
        }
        let verbose = request
            .query_params
            .get("v")
            .is_some_and(|value| value == "true");
        let display_columns = cat_templates_display_columns(request.query_params.get("h"));
        let mut lines = Vec::new();
        if verbose {
            lines.push(
                display_columns
                    .iter()
                    .map(|(_, display)| display.as_str())
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        for row in &rows {
            lines.push(
                display_columns
                    .iter()
                    .map(|(column, _)| row[*column].as_str().unwrap_or(""))
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        RestResponse::text(200, lines.join("\n") + "\n")
    }

    fn handle_cat_thread_pool_route(
        &self,
        request: &RestRequest,
        target: Option<&str>,
    ) -> RestResponse {
        if let Some(response) = validate_cat_cluster_manager_timeout_query_params(request) {
            return response;
        }
        let default_node = DevelopmentClusterNode {
            node_id: "steelsearch-dev-node".to_string(),
            node_name: self.info.name.clone(),
            http_address: Some("127.0.0.1:9200".to_string()),
            transport_address: "127.0.0.1:9300".to_string(),
            roles: vec!["cluster_manager".to_string(), "data".to_string()],
            local: true,
        };
        let view = self.cluster_view.clone().unwrap_or_default();
        let nodes = if view.nodes.is_empty() {
            vec![default_node]
        } else {
            view.nodes.clone()
        };
        let local_node_id = if view.local_node_id.is_empty() {
            nodes
                .iter()
                .find(|node| node.local)
                .map(|node| node.node_id.clone())
                .unwrap_or_else(|| nodes[0].node_id.clone())
        } else {
            view.local_node_id.clone()
        };
        let local_counters = BTreeMap::from([
            (
                "cluster_manager",
                self.runtime_thread_pool_counters("cluster_manager"),
            ),
            (
                "maintenance",
                self.runtime_thread_pool_counters("maintenance"),
            ),
            ("snapshot", self.runtime_thread_pool_counters("snapshot")),
            ("search", self.runtime_thread_pool_counters("search")),
            (
                "task_submission",
                self.runtime_thread_pool_counters("task_submission"),
            ),
            ("write", self.runtime_thread_pool_counters("write")),
        ]);
        let zero_counters = RuntimeThreadPoolCounters::default();
        let mut rows = Vec::new();
        for node in nodes {
            let node_id = node.node_id.clone();
            let node_name = node.node_name.clone();
            let is_local = node.local || node_id == local_node_id;
            let (host, port) = node
                .transport_address
                .rsplit_once(':')
                .map(|(host, port)| (host.to_string(), port.to_string()))
                .unwrap_or_else(|| (node.transport_address.clone(), "0".to_string()));
            let (management_active, management_queue) =
                self.task_queue_runtime_counts_for_node(&node_id);
            for (name, pool_type, queue_size) in [
                ("cluster_manager", "fixed", "1000"),
                ("maintenance", "fixed", "1000"),
                ("management", "scaling", "1000"),
                ("remote_transport", "fixed", "1000"),
                ("search", "fixed", "1000"),
                ("snapshot", "fixed", "1000"),
                ("task_submission", "fixed", "1000"),
                ("write", "fixed", "10000"),
            ] {
                let remote_transport_counters;
                let management_counters;
                let counters = if name == "management" {
                    management_counters = RuntimeThreadPoolCounters {
                        active: management_active,
                        queue: management_queue,
                        rejected: 0,
                        completed: 0,
                    };
                    &management_counters
                } else if name == "remote_transport" {
                    remote_transport_counters =
                        self.remote_transport_thread_pool_counters(&node_id);
                    &remote_transport_counters
                } else if is_local {
                    local_counters.get(name).unwrap_or(&zero_counters)
                } else {
                    &zero_counters
                };
                rows.push(serde_json::json!({
                    "node_name": node_name,
                    "node_id": node_id,
                    "ephemeral_node_id": format!("{}-ephemeral", node_id),
                    "pid": "0",
                    "host": host,
                    "ip": host,
                    "port": port,
                    "name": name,
                    "type": pool_type,
                    "active": counters.active.to_string(),
                    "pool_size": "1",
                    "queue": counters.queue.to_string(),
                    "queue_size": queue_size,
                    "rejected": counters.rejected.to_string(),
                    "largest": "1",
                    "completed": counters.completed.to_string(),
                    "total_wait_time": "0ms",
                    "core": if name == "management" { "1" } else { "" },
                    "max": if name == "management" { "1" } else { "" },
                    "size": "1",
                    "keep_alive": if name == "management" { "5m" } else { "" },
                    "parallelism": ""
                }));
            }
        }
        if let Some(patterns) = target {
            rows.retain(|row| {
                wildcard_match(patterns, row["name"].as_str().unwrap_or_default())
                    || patterns.split(',').any(|pattern| {
                        wildcard_match(pattern.trim(), row["name"].as_str().unwrap_or_default())
                    })
            });
        }
        if request
            .query_params
            .get("format")
            .is_some_and(|value| value == "json")
        {
            let display_columns = cat_thread_pool_display_columns(request.query_params.get("h"));
            let selected_rows = rows
                .iter()
                .map(|row| {
                    let mut object = serde_json::Map::new();
                    for (column, display) in &display_columns {
                        object.insert(display.clone(), row[*column].clone());
                    }
                    Value::Object(object)
                })
                .collect();
            return RestResponse::json(200, Value::Array(selected_rows));
        }
        let verbose = request
            .query_params
            .get("v")
            .is_some_and(|value| value == "true");
        let display_columns = cat_thread_pool_display_columns(request.query_params.get("h"));
        let mut lines = Vec::new();
        if verbose {
            lines.push(
                display_columns
                    .iter()
                    .map(|(_, display)| display.as_str())
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        for row in &rows {
            lines.push(
                display_columns
                    .iter()
                    .map(|(column, _)| row[*column].as_str().unwrap_or(""))
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        RestResponse::text(200, lines.join("\n") + "\n")
    }

    fn handle_cat_shards_route(&self, request: &RestRequest, target: Option<&str>) -> RestResponse {
        if let Some(response) = validate_cat_cluster_manager_timeout_query_params(request) {
            return response;
        }
        let mut rows = Vec::new();
        let indices: Vec<String> = self
            .created_indices_state
            .lock()
            .expect("created indices state lock poisoned")
            .iter()
            .filter(|index| {
                target
                    .map(|pattern| wildcard_match(pattern, index))
                    .unwrap_or(true)
            })
            .cloned()
            .collect();
        let pit_open_contexts_by_index = self.pit_open_context_counts_by_index();
        let pit_total_contexts_by_index = self
            .pit_total_contexts_by_index
            .lock()
            .expect("pit total contexts lock poisoned")
            .clone();
        let pit_time_millis_by_index = self
            .pit_time_millis_by_index
            .lock()
            .expect("pit time millis lock poisoned")
            .clone();
        for index in indices {
            let docs = self.index_lucene_document_count(&index);
            let store_size = self.index_store_size_bytes(&index, docs);
            let pit_current = pit_open_contexts_by_index
                .get(&index)
                .copied()
                .unwrap_or_default();
            let pit_total = pit_total_contexts_by_index
                .get(&index)
                .copied()
                .unwrap_or_default();
            let pit_time_millis = pit_time_millis_by_index
                .get(&index)
                .copied()
                .unwrap_or_default();
            rows.push(serde_json::json!({
                "index": &index,
                "shard": "0",
                "prirep": "p",
                "state": "STARTED",
                "docs": docs.to_string(),
                "store": format_cat_byte_size(store_size),
                "ip": "0.0.0.0",
                "id": self.info.name.clone(),
                "node": self.info.name.clone(),
                "search.open_contexts": pit_current.to_string(),
                "search.point_in_time_current": pit_current.to_string(),
                "search.point_in_time_time": format_time_value_millis(pit_time_millis),
                "search.point_in_time_total": pit_total.to_string(),
            }));
            for _ in 0..self.index_replica_count(&index) {
                rows.push(serde_json::json!({
                    "index": &index,
                    "shard": "0",
                    "prirep": "r",
                    "state": "UNASSIGNED",
                    "docs": "0",
                    "store": "0b",
                    "ip": "",
                    "id": "",
                    "node": "",
                    "search.open_contexts": "0",
                    "search.point_in_time_current": "0",
                    "search.point_in_time_time": "0s",
                    "search.point_in_time_total": "0",
                }));
            }
        }
        rows.sort_by(|left, right| {
            left["index"]
                .as_str()
                .unwrap_or_default()
                .cmp(right["index"].as_str().unwrap_or_default())
                .then(
                    left["prirep"]
                        .as_str()
                        .unwrap_or_default()
                        .cmp(right["prirep"].as_str().unwrap_or_default()),
                )
        });
        if request
            .query_params
            .get("format")
            .is_some_and(|value| value == "json")
        {
            let display_columns = cat_shards_display_columns(request.query_params.get("h"));
            let selected_rows = rows
                .iter()
                .map(|row| {
                    let mut object = serde_json::Map::new();
                    for (column, display) in &display_columns {
                        object.insert(display.clone(), row[*column].clone());
                    }
                    Value::Object(object)
                })
                .collect();
            return RestResponse::json(200, Value::Array(selected_rows));
        }
        let verbose = request
            .query_params
            .get("v")
            .is_some_and(|value| value == "true");
        let display_columns = cat_shards_display_columns(request.query_params.get("h"));
        let mut lines = Vec::new();
        if verbose {
            lines.push(
                display_columns
                    .iter()
                    .map(|(_, display)| display.as_str())
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        for row in &rows {
            lines.push(
                display_columns
                    .iter()
                    .map(|(column, _)| row[*column].as_str().unwrap_or(""))
                    .collect::<Vec<_>>()
                    .join(" "),
            );
        }
        RestResponse::text(200, lines.join("\n") + "\n")
    }

