fn search_partial_shards_failure_response(
    failed_indices: &std::collections::BTreeSet<String>,
    geo_failed_indices: &std::collections::BTreeSet<String>,
    sort_unmapped_failures: &std::collections::BTreeMap<String, String>,
) -> RestResponse {
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "search_phase_execution_exception",
                "reason": "Partial shards failure",
                "root_cause": failed_indices
                    .iter()
                    .map(|index| {
                        serde_json::json!({
                            "type": "query_shard_exception",
                            "reason": search_shard_failure_reason(index, geo_failed_indices, sort_unmapped_failures)
                                .get("reason")
                                .cloned()
                                .unwrap_or_else(|| Value::String("failed to execute query".to_string())),
                            "index": index
                        })
                    })
                    .collect::<Vec<_>>()
            },
            "status": 400
        }),
    )
}

fn build_interval_expansion_search_failure_response(
    reason: &str,
    shard_total: usize,
) -> RestResponse {
    RestResponse::json(
        500,
        serde_json::json!({
            "error": {
                "root_cause": [
                    {
                        "type": "illegal_state_exception",
                        "reason": reason
                    }
                ],
                "type": "search_phase_execution_exception",
                "reason": "all shards failed",
                "phase": "query",
                "grouped": true,
                "failed_shards": [
                    {
                        "shard": 0,
                        "index": null,
                        "node": null,
                        "reason": {
                            "type": "illegal_state_exception",
                            "reason": reason
                        }
                    }
                ],
                "caused_by": {
                    "type": "illegal_state_exception",
                    "reason": reason,
                    "caused_by": {
                        "type": "illegal_state_exception",
                        "reason": reason
                    }
                }
            },
            "status": 500,
            "_shards": {
                "total": shard_total,
                "successful": 0,
                "skipped": 0,
                "failed": shard_total
            }
        }),
    )
}

fn build_bounded_search_profile_body(body: &Value, resolved_indices: &[String]) -> Value {
    let query = &body["query"];
    let size = body.get("size").and_then(Value::as_u64).unwrap_or(10);
    let has_aggs = body
        .get("aggs")
        .or_else(|| body.get("aggregations"))
        .and_then(Value::as_object)
        .is_some_and(|aggs| !aggs.is_empty());
    let has_knn = value_contains_key(query, "knn");
    let has_bool_must_not = query
        .get("bool")
        .and_then(Value::as_object)
        .and_then(|bool_query| bool_query.get("must_not"))
        .is_some();
    let multi_index = resolved_indices.len() > 1;

    let mut phase_descriptions =
        vec!["bounded native search evaluated refreshed documents".to_string()];
    if size == 0 {
        phase_descriptions.push("matched refreshed documents without hit fetch".to_string());
        if !has_knn {
            phase_descriptions.push(
                "size=0 compatibility path avoided top-level hit materialization".to_string(),
            );
        }
        if has_aggs {
            phase_descriptions.push(
                "size=0 compatibility aggregation path avoided top-level hit materialization"
                    .to_string(),
            );
        }
    }
    if size > 0 && has_aggs {
        phase_descriptions
            .push("matched refreshed documents with native page+aggregation fetch".to_string());
    }
    if has_knn {
        if size == 0 {
            phase_descriptions.push(
                "vector-native page path skipped hit materialization because size=0".to_string(),
            );
        } else {
            phase_descriptions.push(
                "matched refreshed documents with vector-native page+aggregation fetch".to_string(),
            );
        }
    }
    if multi_index {
        phase_descriptions.push("native page reduce across resolved indices".to_string());
        if has_knn {
            phase_descriptions
                .push("vector-native page reduce across resolved indices".to_string());
        }
        if has_aggs {
            phase_descriptions.push("aggregation reduce across resolved indices".to_string());
        }
    }

    let mut invariants = serde_json::Map::new();
    if has_knn || has_aggs || body.get("sort").is_some() {
        invariants.insert("requires_reusable_context".to_string(), Value::Bool(true));
    }
    if has_bool_must_not || value_contains_any_key(query, &["term", "terms", "range", "nested"]) {
        invariants.insert(
            "requires_native_candidate_reduction".to_string(),
            Value::Bool(true),
        );
        invariants.insert(
            "requires_optional_all_documents_context".to_string(),
            Value::Bool(true),
        );
    }
    if has_aggs && value_contains_key(body.get("aggs").unwrap_or(&Value::Null), "top_hits") {
        invariants.insert(
            "requires_requested_window_preserved".to_string(),
            Value::Bool(true),
        );
    }
    if has_knn {
        invariants.insert(
            "requires_runtime_cache_by_field".to_string(),
            Value::Bool(true),
        );
        invariants.insert(
            "requires_request_result_cache_counters".to_string(),
            Value::Bool(true),
        );
        invariants.insert(
            "requires_stale_invalidation_counter".to_string(),
            Value::Bool(true),
        );
        invariants.insert(
            "requires_capacity_eviction_counter".to_string(),
            Value::Bool(true),
        );
    }
    if has_aggs {
        invariants.insert(
            "requires_aggregation_shape_parity".to_string(),
            Value::Bool(true),
        );
    }
    if value_contains_key(body.get("sort").unwrap_or(&Value::Null), "_script") {
        invariants.insert("requires_exact_hit_order".to_string(), Value::Bool(true));
    }

    serde_json::json!({
        "steelsearch_native_invariants": Value::Object(invariants),
        "shards": [
            {
                "searches": [
                    {
                        "query": phase_descriptions
                            .iter()
                            .map(|description| {
                                serde_json::json!({
                                    "type": "bounded_native_query",
                                    "description": description,
                                    "time_in_nanos": 1,
                                    "breakdown": {}
                                })
                            })
                            .collect::<Vec<_>>(),
                        "rewrite_time": 0,
                        "collector": [
                            {
                                "name": "bounded_native_collector",
                                "reason": "search_top_hits",
                                "time_in_nanos": 1
                            }
                        ]
                    }
                ],
                "aggregations": []
            }
        ]
    })
}

fn value_contains_any_key(value: &Value, keys: &[&str]) -> bool {
    keys.iter().any(|key| value_contains_key(value, key))
}

fn value_contains_key(value: &Value, key: &str) -> bool {
    match value {
        Value::Object(object) => object
            .iter()
            .any(|(candidate, child)| candidate == key || value_contains_key(child, key)),
        Value::Array(items) => items.iter().any(|item| value_contains_key(item, key)),
        _ => false,
    }
}

fn validate_search_request_body(
    body: &Value,
    scroll: bool,
    shard_failure_index: &str,
) -> Option<RestResponse> {
    if let Some(response) = validate_search_window_bounds(body) {
        return Some(response);
    }
    if let Some(response) = validate_search_result_window(body, scroll) {
        return Some(response);
    }
    if let Some(derived) = body.get("derived") {
        if let Some(response) = validate_derived_request_body(derived) {
            return Some(response);
        }
    }
    if body.get("runtime_mappings").is_some() {
        return Some(build_unknown_search_source_key_response(
            "runtime_mappings",
            "START_OBJECT",
        ));
    }
    if let Some(stored_fields) = body.get("stored_fields") {
        if let Some(response) = validate_stored_fields_request_body(stored_fields) {
            return Some(response);
        }
    }
    if let Some(docvalue_fields) = body.get("docvalue_fields") {
        if let Some(response) =
            validate_docvalue_fields_request_body(docvalue_fields, shard_failure_index)
        {
            return Some(response);
        }
    }
    if let Some(fetch_fields) = body.get("fields") {
        if let Some(response) =
            validate_fetch_fields_request_body(fetch_fields, shard_failure_index)
        {
            return Some(response);
        }
    }
    if let Some(script_fields) = body.get("script_fields") {
        if let Some(response) = validate_script_fields_request_body(script_fields) {
            return Some(response);
        }
    }
    if let Some(response) = validate_stored_fields_fetch_interactions(body, shard_failure_index) {
        return Some(response);
    }
    if let Some(source_filter) = body.get("_source") {
        if let Some(response) = validate_source_filter_request_body(source_filter) {
            return Some(response);
        }
    }
    if let Some(track_total_hits) = body.get("track_total_hits") {
        if let Some(threshold) = track_total_hits
            .as_i64()
            .filter(|threshold| *threshold < -1)
        {
            return Some(search_phase_total_hits_threshold_error(threshold));
        }
        if !matches!(track_total_hits, Value::Bool(_))
            && search_track_total_hits_value(track_total_hits).is_none()
        {
            return Some(build_unsupported_search_response(
                "unsupported search option [track_total_hits]",
            ));
        }
    }
    if let Some(timeout) = body.get("timeout") {
        let Some(raw_timeout) = timeout.as_str() else {
            return Some(search_timeout_parse_error(timeout));
        };
        if parse_time_value_millis(raw_timeout).is_none() {
            return Some(search_timeout_parse_error(timeout));
        }
    }
    if let Some(stats) = body.get("stats") {
        if let Some(response) = validate_search_stats_request_body(stats) {
            return Some(response);
        }
    }
    if let Some(indices_boost) = body.get("indices_boost") {
        if let Some(response) = validate_indices_boost_request_body(indices_boost) {
            return Some(response);
        }
    }
    if let Some(aggregations) = body.get("aggs").or_else(|| body.get("aggregations")) {
        if let Some(kind) = unsupported_direct_aggregation_kind(aggregations) {
            return Some(build_parsing_search_response_with_root_cause(
                &unknown_aggregation_type_reason(kind),
            ));
        }
    }
    if body
        .get("min_score")
        .is_some_and(|value| !value.is_number())
    {
        return Some(build_unsupported_search_response(
            "unsupported search option [min_score]",
        ));
    }
    if body
        .get("terminate_after")
        .is_some_and(|value| value.as_u64().is_none())
    {
        return Some(terminate_after_query_param_parse_error(
            body.get("terminate_after")
                .and_then(Value::as_str)
                .unwrap_or_default(),
        ));
    }
    if let Some(post_filter) = body.get("post_filter") {
        if !post_filter.is_object() {
            return Some(build_unsupported_search_response(
                "unsupported search option [post_filter]",
            ));
        }
        if let Some(response) = validate_search_query_body(post_filter) {
            return Some(response);
        }
    }
    for option in [
        "version",
        "seq_no_primary_term",
        "explain",
        "profile",
        "track_scores",
        "include_named_queries_score",
        "verbose_pipeline",
    ] {
        if body.get(option).is_some_and(|value| !value.is_boolean()) {
            return Some(build_unsupported_search_response(&format!(
                "unsupported search option [{option}]"
            )));
        }
    }
    if let Some(highlight) = body.get("highlight") {
        if let Some(response) = validate_highlight_request_body(highlight) {
            return Some(response);
        }
    }
    if let Some(suggest) = body.get("suggest") {
        if let Some(response) = validate_suggest_request_body(suggest) {
            return Some(response);
        }
    }
    if let Some(pit) = body.get("pit") {
        if let Some(response) = validate_pit_request_body(pit) {
            return Some(response);
        }
    }
    if let Some(search_after) = body.get("search_after") {
        if let Some(response) = validate_search_after_request_body(
            body.get("sort"),
            search_after,
            body.get("from").and_then(Value::as_u64).unwrap_or(0),
            scroll,
            shard_failure_index,
        ) {
            return Some(response);
        }
    }
    if let Some(sort) = body.get("sort") {
        if let Some(response) = validate_search_sort_request_body(sort) {
            return Some(response);
        }
    }
    if let Some(slice) = body.get("slice") {
        if let Some(response) = validate_slice_request_body(
            slice,
            scroll,
            body.get("pit").is_some(),
            shard_failure_index,
        ) {
            return Some(response);
        }
    }
    if let Some(rescore) = body.get("rescore") {
        if body.get("sort").is_some() {
            return Some(RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "type": "search_phase_execution_exception",
                        "reason": "all shards failed",
                        "root_cause": [
                            {
                                "type": "illegal_argument_exception",
                                "reason": "Cannot use [sort] option in conjunction with [rescore]."
                            }
                        ]
                    },
                    "status": 400
                }),
            ));
        }
        if let Some(response) = validate_rescore_request_body(rescore) {
            return Some(response);
        }
    }
    if let Some(collapse) = body.get("collapse") {
        if let Some(response) = validate_collapse_request_body(
            collapse,
            body.get("sort"),
            body.get("search_after"),
            scroll,
            body.get("rescore"),
            shard_failure_index,
        ) {
            return Some(response);
        }
    }
    validate_search_query_body(&body["query"])
}

fn validate_search_window_bounds(body: &Value) -> Option<RestResponse> {
    if let Some(from) = body
        .get("from")
        .and_then(Value::as_i64)
        .filter(|from| *from < 0)
    {
        return Some(build_unsupported_search_response(&format!(
            "[from] parameter cannot be negative, found [{from}]"
        )));
    }
    if let Some(size) = body
        .get("size")
        .and_then(Value::as_i64)
        .filter(|size| *size < 0)
    {
        return Some(build_unsupported_search_response(&format!(
            "[size] parameter cannot be negative, found [{size}]"
        )));
    }
    None
}

fn validate_search_result_window(body: &Value, scroll: bool) -> Option<RestResponse> {
    const DEFAULT_MAX_RESULT_WINDOW: u64 = 10_000;
    let from = body.get("from").and_then(Value::as_u64).unwrap_or(0);
    let size = body.get("size").and_then(Value::as_u64).unwrap_or(10);
    let result_window = from.saturating_add(size);
    if result_window <= DEFAULT_MAX_RESULT_WINDOW {
        return None;
    }
    let reason = if scroll {
        format!(
            "Batch size is too large, size must be less than or equal to: [{DEFAULT_MAX_RESULT_WINDOW}] but was [{result_window}]. Scroll batch sizes cost as much memory as result windows so they are controlled by the [index.max_result_window] index level setting."
        )
    } else {
        format!(
            "Result window is too large, from + size must be less than or equal to: [{DEFAULT_MAX_RESULT_WINDOW}] but was [{result_window}]. See the scroll api for a more efficient way to request large data sets. This limit can be set by changing the [index.max_result_window] index level setting."
        )
    };
    Some(search_after_validation_error(reason))
}

fn unsupported_direct_aggregation_kind(value: &Value) -> Option<&'static str> {
    let Some(object) = value.as_object() else {
        return None;
    };
    const UNSUPPORTED_DIRECT_AGGREGATIONS: &[&str] = &[
        "boxplot",
        "bucket_count",
        "normalize",
        "moving_count",
        "moving_sum",
        "moving_min",
        "moving_max",
        "moving_median",
        "moving_stddev",
        "moving_variance",
        "moving_skewness",
        "moving_kurtosis",
        "moving_mad",
        "moving_range",
        "moving_percentiles",
        "moving_percentile_ranks",
    ];
    object.iter().find_map(|(_, aggregation)| {
        let body = aggregation.as_object()?;
        if let Some(kind) = UNSUPPORTED_DIRECT_AGGREGATIONS
            .iter()
            .copied()
            .find(|kind| body.contains_key(*kind))
        {
            return Some(kind);
        }
        body.get("aggs")
            .or_else(|| body.get("aggregations"))
            .and_then(unsupported_direct_aggregation_kind)
    })
}

fn unknown_aggregation_type_reason(kind: &str) -> String {
    match kind {
        "bucket_count" => format!(
            "Unknown aggregation type [{kind}] did you mean any of [bucket_sort, bucket_script, value_count, bucket_selector, bucket_selector_ext]?"
        ),
        "moving_min" => {
            format!("Unknown aggregation type [{kind}] did you mean any of [moving_fn, moving_avg]?")
        }
        "moving_count" | "moving_sum" | "moving_max" | "moving_median" | "moving_stddev"
        | "moving_variance" | "moving_skewness" | "moving_kurtosis" | "moving_mad"
        | "moving_range" | "moving_percentiles" | "moving_percentile_ranks" => {
            format!("Unknown aggregation type [{kind}] did you mean any of [moving_avg, moving_fn]?")
        }
        _ => format!("Unknown aggregation type [{kind}]"),
    }
}

fn validate_scroll_context_request_body(
    body: &Value,
    scroll: bool,
    request_cache: bool,
) -> Option<RestResponse> {
    if !scroll {
        return None;
    }
    const TRACK_TOTAL_HITS_ACCURATE: u64 = i32::MAX as u64;
    let mut validation_errors = Vec::new();
    if search_track_total_hits_disabled(body)
        || search_track_total_hits_threshold(body)
            .is_some_and(|threshold| threshold != TRACK_TOTAL_HITS_ACCURATE)
    {
        validation_errors.push("disabling [track_total_hits] is not allowed in a scroll context");
    }
    if body.get("from").and_then(Value::as_u64).unwrap_or(0) > 0 {
        validation_errors.push("using [from] is not allowed in a scroll context");
    }
    if body.get("size").and_then(Value::as_u64) == Some(0) {
        validation_errors.push("[size] cannot be [0] in a scroll context");
    }
    if body.get("rescore").is_some() {
        validation_errors.push("using [rescore] is not allowed in a scroll context");
    }
    if request_cache {
        validation_errors.push("[request_cache] cannot be used in a scroll context");
    }
    if body.get("pit").is_some() {
        validation_errors.push("using [point in time] is not allowed in a scroll context");
    }
    if count_shard_doc_sort_fields(body.get("sort")) > 0 {
        validation_errors
            .push("_shard_doc cannot be used with scroll. Use PIT + search_after instead.");
    }
    if validation_errors.is_empty() {
        return None;
    }
    Some(action_request_validation_error(validation_errors))
}

fn apply_search_source_query_params(
    body: &mut Value,
    query_params: &BTreeMap<String, String>,
) -> Option<RestResponse> {
    for field in ["from", "size"] {
        let Some(raw) = query_params.get(field) else {
            continue;
        };
        let Some(value) = parse_non_negative_search_int(raw) else {
            return Some(search_query_param_parse_error(field, raw));
        };
        let Some(object) = body.as_object_mut() else {
            return Some(build_unsupported_search_response(
                "unsupported search request body",
            ));
        };
        object.insert(field.to_string(), Value::from(value));
    }
    if let Some(raw_sort) = query_params.get("sort") {
        let Some(object) = body.as_object_mut() else {
            return Some(build_unsupported_search_response(
                "unsupported search request body",
            ));
        };
        let mut sort_values = object
            .remove("sort")
            .and_then(|sort| sort.as_array().cloned())
            .unwrap_or_default();
        sort_values.extend(parse_rest_search_sort_values(raw_sort));
        object.insert("sort".to_string(), Value::Array(sort_values));
    }
    if let Some(raw_track_total_hits) = query_params.get("track_total_hits") {
        if let Ok(threshold) = raw_track_total_hits.parse::<i64>() {
            if threshold < -1 {
                return Some(track_total_hits_negative_threshold_error(threshold));
            }
        }
        let Some(track_total_hits) = parse_rest_track_total_hits(raw_track_total_hits) else {
            return Some(track_total_hits_query_param_parse_error(
                raw_track_total_hits,
            ));
        };
        let Some(object) = body.as_object_mut() else {
            return Some(build_unsupported_search_response(
                "unsupported search request body",
            ));
        };
        object.insert("track_total_hits".to_string(), track_total_hits);
    }
    if let Some(raw_timeout) = query_params.get("timeout") {
        if parse_time_value_millis(raw_timeout).is_none() {
            return Some(search_timeout_parse_error(&Value::String(
                raw_timeout.clone(),
            )));
        }
        let Some(object) = body.as_object_mut() else {
            return Some(build_unsupported_search_response(
                "unsupported search request body",
            ));
        };
        object.insert("timeout".to_string(), Value::String(raw_timeout.clone()));
    }
    if let Some(raw_stats) = query_params.get("stats") {
        let Some(object) = body.as_object_mut() else {
            return Some(build_unsupported_search_response(
                "unsupported search request body",
            ));
        };
        object.insert(
            "stats".to_string(),
            Value::Array(
                raw_stats
                    .split(',')
                    .map(|value| Value::String(value.to_string()))
                    .collect(),
            ),
        );
    }
    if let Some(raw_stored_fields) = query_params.get("stored_fields") {
        let Some(object) = body.as_object_mut() else {
            return Some(build_unsupported_search_response(
                "unsupported search request body",
            ));
        };
        let fields = split_rest_csv_values(raw_stored_fields);
        let value = if fields.len() == 1 {
            Value::String(fields[0].clone())
        } else {
            Value::Array(fields.into_iter().map(Value::String).collect())
        };
        object.insert("stored_fields".to_string(), value);
    }
    if let Some(raw_docvalue_fields) = query_params.get("docvalue_fields") {
        if !raw_docvalue_fields.trim().is_empty() {
            let Some(object) = body.as_object_mut() else {
                return Some(build_unsupported_search_response(
                    "unsupported search request body",
                ));
            };
            object.insert(
                "docvalue_fields".to_string(),
                Value::Array(
                    split_rest_csv_values(raw_docvalue_fields)
                        .into_iter()
                        .map(Value::String)
                        .collect(),
                ),
            );
        }
    }
    if let Some(raw_source) = query_params.get("_source") {
        let source_filter = match raw_source.as_str() {
            "true" => Value::Bool(true),
            "false" => Value::Bool(false),
            _ => Value::String(raw_source.clone()),
        };
        let Some(object) = body.as_object_mut() else {
            return Some(build_unsupported_search_response(
                "unsupported search request body",
            ));
        };
        object.insert("_source".to_string(), source_filter);
    }
    for (query_key, body_key) in [
        ("_source_includes", "_source_includes"),
        ("_source_include", "_source_includes"),
        ("_source_excludes", "_source_excludes"),
        ("_source_exclude", "_source_excludes"),
    ] {
        let Some(raw) = query_params.get(query_key) else {
            continue;
        };
        let Some(object) = body.as_object_mut() else {
            return Some(build_unsupported_search_response(
                "unsupported search request body",
            ));
        };
        object.insert(body_key.to_string(), Value::String(raw.clone()));
    }
    for field in [
        "version",
        "seq_no_primary_term",
        "explain",
        "track_scores",
        "include_named_queries_score",
        "verbose_pipeline",
    ] {
        let Some(raw) = query_params.get(field) else {
            continue;
        };
        if let Some(response) = validate_opensearch_boolean_query_param(Some(raw)) {
            return Some(response);
        }
        let Some(object) = body.as_object_mut() else {
            return Some(build_unsupported_search_response(
                "unsupported search request body",
            ));
        };
        object.insert(
            field.to_string(),
            Value::Bool(query_param_is_true(Some(raw))),
        );
    }
    if let Some(raw_terminate_after) = query_params.get("terminate_after") {
        let Some(terminate_after) = parse_non_negative_search_int(raw_terminate_after) else {
            return Some(terminate_after_query_param_parse_error(raw_terminate_after));
        };
        if terminate_after > 0 {
            let Some(object) = body.as_object_mut() else {
                return Some(build_unsupported_search_response(
                    "unsupported search request body",
                ));
            };
            object.insert("terminate_after".to_string(), Value::from(terminate_after));
        }
    }
    None
}

fn normalize_search_source_scalar_body_options(body: &mut Value) -> Option<RestResponse> {
    let object = body.as_object_mut()?;
    for field in ["from", "size", "terminate_after"] {
        let Some(value) = object.get(field).cloned() else {
            continue;
        };
        if let Some(parsed) = parse_opensearch_int_body_value(&value) {
            object.insert(field.to_string(), parsed);
        }
    }
    if let Some(value) = object.get("min_score").cloned() {
        if let Some(parsed) = parse_opensearch_float_body_value(&value) {
            object.insert("min_score".to_string(), parsed);
        }
    }
    if let Some(indices_boost) = object.get_mut("indices_boost") {
        normalize_opensearch_indices_boost_object_body_values(indices_boost);
    }
    for field in [
        "version",
        "seq_no_primary_term",
        "explain",
        "profile",
        "track_scores",
        "include_named_queries_score",
        "verbose_pipeline",
    ] {
        let Some(value) = object.get(field).cloned() else {
            continue;
        };
        match parse_opensearch_boolean_body_value(&value) {
            Ok(Some(parsed)) => {
                object.insert(field.to_string(), Value::Bool(parsed));
            }
            Ok(None) => {}
            Err(response) => return Some(response),
        }
    }
    if let Some(value) = object.get("track_total_hits").cloned() {
        if let Some(parsed) = parse_opensearch_track_total_hits_body_value(&value) {
            object.insert("track_total_hits".to_string(), parsed);
        }
    }
    None
}

fn stringify_opensearch_setting_number_readbacks(value: &mut Value) {
    match value {
        Value::Object(object) => {
            for (key, child) in object.iter_mut() {
                if matches!(key.as_str(), "number_of_shards" | "number_of_replicas") {
                    if let Some(number) = child.as_u64() {
                        *child = Value::String(number.to_string());
                        continue;
                    }
                    if let Some(number) = child.as_i64() {
                        *child = Value::String(number.to_string());
                        continue;
                    }
                }
                stringify_opensearch_setting_number_readbacks(child);
            }
        }
        Value::Array(values) => {
            for child in values {
                stringify_opensearch_setting_number_readbacks(child);
            }
        }
        _ => {}
    }
}

fn parse_opensearch_boolean_body_value(value: &Value) -> Result<Option<bool>, RestResponse> {
    match value {
        Value::Bool(value) => Ok(Some(*value)),
        Value::String(value) if value == "true" => Ok(Some(true)),
        Value::String(value) if value == "false" => Ok(Some(false)),
        Value::String(value) => Err(opensearch_boolean_parse_error(value)),
        _ => Ok(None),
    }
}

fn parse_opensearch_track_total_hits_body_value(value: &Value) -> Option<Value> {
    match value {
        Value::Bool(value) => Some(Value::Bool(*value)),
        Value::String(value) if value == "true" => Some(Value::Bool(true)),
        Value::String(value) if value == "false" => Some(Value::Bool(false)),
        Value::String(_) => parse_opensearch_int_body_value(value),
        _ => None,
    }
}

fn parse_opensearch_int_body_value(value: &Value) -> Option<Value> {
    let Value::String(value) = value else {
        return None;
    };
    let parsed = value.parse::<f64>().ok()?;
    if !parsed.is_finite() || parsed < i32::MIN as f64 || parsed > i32::MAX as f64 {
        return None;
    }
    Some(Value::from(parsed as i64))
}

fn parse_opensearch_float_body_value(value: &Value) -> Option<Value> {
    let Value::String(value) = value else {
        return None;
    };
    let parsed = value.parse::<f64>().ok()?;
    if !parsed.is_finite() {
        return None;
    }
    serde_json::Number::from_f64(parsed).map(Value::Number)
}

fn normalize_opensearch_indices_boost_object_body_values(indices_boost: &mut Value) {
    let Value::Object(boosts) = indices_boost else {
        return;
    };
    for boost in boosts.values_mut() {
        if let Some(parsed) = parse_opensearch_float_body_value(boost) {
            *boost = parsed;
        }
    }
}

fn split_rest_csv_values(raw: &str) -> Vec<String> {
    raw.split(',')
        .filter_map(|value| {
            let trimmed = value.trim();
            (!trimmed.is_empty()).then(|| trimmed.to_string())
        })
        .collect()
}

fn apply_url_query_string_search_params(
    body: &mut Value,
    query_params: &BTreeMap<String, String>,
) -> Option<RestResponse> {
    let Some(raw_query) = query_params.get("q") else {
        return None;
    };
    let Some(object) = body.as_object_mut() else {
        return Some(build_unsupported_search_response(
            "unsupported search request body",
        ));
    };
    for field in ["analyze_wildcard", "lenient"] {
        if let Some(response) = validate_opensearch_boolean_query_param(query_params.get(field)) {
            return Some(response);
        }
    }
    for field in ["analyzer", "analyze_wildcard", "lenient"] {
        if query_params.contains_key(field) {
            return Some(build_unsupported_search_response(&format!(
                "unsupported search option [{field}]"
            )));
        }
    }
    let mut query_string = serde_json::Map::new();
    let mut query_text = raw_query.clone();
    let mut inferred_field = None;
    if !query_params.contains_key("df") {
        if let Some((field, value)) = raw_query.split_once(':') {
            if !field.is_empty()
                && !value.is_empty()
                && !field.chars().any(char::is_whitespace)
                && !value.chars().any(char::is_whitespace)
            {
                inferred_field = Some(field.to_string());
                query_text = value.to_string();
            }
        }
    }
    query_string.insert("query".to_string(), Value::String(query_text));
    if let Some(default_field) = query_params.get("df").cloned().or(inferred_field) {
        query_string.insert(
            "fields".to_string(),
            Value::Array(vec![Value::String(default_field)]),
        );
    }
    if let Some(default_operator) = query_params.get("default_operator") {
        let normalized = default_operator.to_ascii_lowercase();
        if normalized != "and" && normalized != "or" {
            return Some(build_unsupported_search_response(
                "unsupported query_string default operator",
            ));
        }
        query_string.insert("default_operator".to_string(), Value::String(normalized));
    }
    object.insert(
        "query".to_string(),
        serde_json::json!({ "query_string": Value::Object(query_string) }),
    );
    None
}

fn validate_search_stats_request_body(stats: &Value) -> Option<RestResponse> {
    let Some(groups) = stats.as_array() else {
        return Some(build_unsupported_search_response(
            "unsupported search option [stats]",
        ));
    };
    if groups.iter().any(|group| !group.is_string()) {
        return Some(build_unsupported_search_response(
            "unsupported search option [stats]",
        ));
    }
    None
}

fn validate_shard_doc_sort_request_body(body: &Value, scroll: bool) -> Option<RestResponse> {
    let shard_doc_count = count_shard_doc_sort_fields(body.get("sort"));
    if shard_doc_count == 0 {
        return None;
    }
    let mut validation_errors = Vec::new();
    if scroll {
        validation_errors
            .push("_shard_doc cannot be used with scroll. Use PIT + search_after instead.");
    }
    if body.get("pit").is_none() {
        validation_errors.push("_shard_doc is only supported with point-in-time (PIT). Add a PIT or remove _shard_doc.");
    }
    if shard_doc_count > 1 {
        validation_errors.push("duplicate _shard_doc sort detected. Specify it at most once.");
    }
    if validation_errors.is_empty() {
        return None;
    }
    Some(action_request_validation_error(validation_errors))
}

fn count_shard_doc_sort_fields(sort: Option<&Value>) -> usize {
    let Some(sort_fields) = sort.and_then(search_sort_fields) else {
        return 0;
    };
    sort_fields
        .into_iter()
        .filter(|sort_field| {
            sort_field.as_str() == Some("_shard_doc")
                || sort_field
                    .as_object()
                    .is_some_and(|object| object.contains_key("_shard_doc"))
        })
        .count()
}

fn parse_rest_track_total_hits(raw: &str) -> Option<Value> {
    match raw {
        "true" => Some(Value::Bool(true)),
        "false" => Some(Value::Bool(false)),
        "-1" => Some(Value::from(-1)),
        _ => {
            if raw.starts_with('-') {
                return None;
            }
            raw.parse::<u64>().ok().map(Value::from)
        }
    }
}

fn search_track_total_hits_value(value: &Value) -> Option<i64> {
    if matches!(value, Value::Bool(_)) {
        return Some(0);
    }
    if value.as_i64() == Some(-1) {
        return Some(-1);
    }
    value
        .as_u64()
        .and_then(|threshold| i64::try_from(threshold).ok())
}

fn search_track_total_hits_disabled(body: &Value) -> bool {
    body.get("track_total_hits") == Some(&Value::Bool(false))
        || body
            .get("track_total_hits")
            .and_then(Value::as_i64)
            .is_some_and(|threshold| threshold == -1)
}

fn search_track_total_hits_threshold(body: &Value) -> Option<u64> {
    let value = body.get("track_total_hits")?;
    value.as_u64()
}

fn track_total_hits_query_param_parse_error(value: &str) -> RestResponse {
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "illegal_argument_exception",
                "reason": format!("Failed to parse value [{value}] for [track_total_hits]")
            },
            "status": 400
        }),
    )
}

fn track_total_hits_negative_threshold_error(threshold: i64) -> RestResponse {
    build_unsupported_search_response(&format!(
        "[track_total_hits] parameter must be positive or equals to -1, got {threshold}"
    ))
}

fn search_phase_total_hits_threshold_error(threshold: i64) -> RestResponse {
    let reason = format!("totalHitsThreshold must be >= 0, got {threshold}");
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "search_phase_execution_exception",
                "reason": "all shards failed",
                "root_cause": [
                    {
                        "type": "illegal_argument_exception",
                        "reason": reason
                    }
                ],
                "caused_by": {
                    "type": "illegal_argument_exception",
                    "reason": reason
                },
                "failed_shards": [
                    {
                        "shard": 0,
                        "reason": {
                            "type": "illegal_argument_exception",
                            "reason": reason
                        }
                    }
                ]
            },
            "status": 400
        }),
    )
}

fn terminate_after_query_param_parse_error(_value: &str) -> RestResponse {
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "illegal_argument_exception",
                "reason": "terminateAfter must be > 0"
            },
            "status": 400
        }),
    )
}

fn validate_minimum_search_int_query_param(
    param: &str,
    raw: &str,
    minimum: i64,
    lower_bound_reason: &str,
) -> Option<RestResponse> {
    let Ok(value) = raw.parse::<i64>() else {
        return Some(RestResponse::json(
            400,
            serde_json::json!({
                "error": {
                    "type": "illegal_argument_exception",
                    "reason": format!("Failed to parse value [{raw}] for [{param}] as an integer")
                },
                "status": 400
            }),
        ));
    };
    if value < minimum {
        return Some(RestResponse::json(
            400,
            serde_json::json!({
                "error": {
                    "type": "illegal_argument_exception",
                    "reason": lower_bound_reason
                },
                "status": 400
            }),
        ));
    }
    None
}

fn parse_rest_search_sort_values(raw: &str) -> Vec<Value> {
    raw.split(',')
        .map(str::trim)
        .filter(|sort| !sort.is_empty())
        .map(|sort| {
            if let Some((field, order)) = sort.rsplit_once(':') {
                if matches!(order, "asc" | "desc") {
                    return serde_json::json!({ field: { "order": order } });
                }
            }
            if sort == "_score" {
                Value::String(sort.to_string())
            } else {
                serde_json::json!({ sort: { "order": "asc" } })
            }
        })
        .collect()
}

fn parse_non_negative_search_int(raw: &str) -> Option<u64> {
    if raw.starts_with('-') {
        return None;
    }
    raw.parse::<u64>().ok()
}

fn search_template_payload_has_script(payload: &Value) -> bool {
    payload.as_object().is_some_and(|object| {
        ["id", "source", "inline", "template"]
            .iter()
            .any(|field| object.contains_key(*field))
    })
}

fn search_template_body_or_source_param(request: &RestRequest) -> Result<Value, RestResponse> {
    if !request.body.is_empty() {
        return serde_json::from_slice::<Value>(&request.body)
            .map_err(|error| build_json_parse_search_response(error.to_string()));
    }
    let Some(source) = request.query_params.get("source") else {
        return Err(RestResponse::opensearch_error_kind(
            os_rest::RestErrorKind::Parse,
            "request body or source parameter is required",
        ));
    };
    let Some(source_content_type) = request.query_params.get("source_content_type") else {
        return Err(RestResponse::opensearch_error_kind(
            os_rest::RestErrorKind::IllegalArgument,
            "source and source_content_type parameters are required",
        ));
    };
    if !matches!(
        source_content_type.as_str(),
        "json" | "application/json" | "application/vnd.opensearch+json"
    ) {
        return Err(RestResponse::opensearch_error_kind(
            os_rest::RestErrorKind::IllegalArgument,
            format!("Unknown value for source_content_type [{source_content_type}]"),
        ));
    }
    serde_json::from_str::<Value>(source)
        .map_err(|error| build_json_parse_search_response(error.to_string()))
}

fn search_template_malformed_response() -> RestResponse {
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "illegal_argument_exception",
                "reason": "Malformed search template"
            },
            "status": 400
        }),
    )
}

fn search_query_param_parse_error(param: &str, value: &str) -> RestResponse {
    let reason = if value.starts_with('-') {
        format!("[{param}] parameter cannot be negative, found [{value}]")
    } else {
        format!("Failed to parse value [{value}] for [{param}] as a non-negative integer")
    };
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "illegal_argument_exception",
                "reason": reason,
                "root_cause": [
                    {
                        "type": "illegal_argument_exception",
                        "reason": reason
                    }
                ]
            },
            "status": 400
        }),
    )
}

fn validate_pit_request_body(pit: &Value) -> Option<RestResponse> {
    let Some(object) = pit.as_object() else {
        return Some(build_parsing_search_response_with_root_cause(&format!(
            "Unknown key for a {} in [pit].",
            opensearch_xcontent_token_name(pit)
        )));
    };
    if let Some(id) = object.get("id").filter(|id| !id.is_string()) {
        return Some(build_x_content_parse_search_response_with_root_cause(
            &format!(
                "[1:16] [pit] id doesn't support values of type: {}",
                opensearch_xcontent_token_name(id)
            ),
        ));
    }
    if !object.contains_key("id") {
        if let Some(key) = object.keys().find(|key| *key != "keep_alive") {
            return Some(build_x_content_parse_search_response_with_root_cause(
                &format!("[1:10] [pit] unknown field [{key}]"),
            ));
        }
        return Some(build_illegal_argument_search_response_with_root_cause(
            "point int time id is not provided",
        ));
    }
    if object
        .get("keep_alive")
        .is_some_and(|keep_alive| !keep_alive.is_string())
    {
        let keep_alive = object.get("keep_alive").expect("keep_alive checked above");
        let location = if object.keys().any(|key| key != "id" && key != "keep_alive") {
            "[1:198]"
        } else {
            "[1:45]"
        };
        return Some(build_x_content_parse_search_response_with_root_cause(
            &format!(
                "{location} [pit] keep_alive doesn't support values of type: {}",
                opensearch_xcontent_token_name(keep_alive)
            ),
        ));
    }
    if let Some(key) = object
        .keys()
        .find(|key| *key != "id" && *key != "keep_alive")
    {
        return Some(build_x_content_parse_search_response_with_root_cause(
            &format!("[1:51] [pit] unknown field [{key}]"),
        ));
    }
    None
}

fn validate_indices_boost_request_body(indices_boost: &Value) -> Option<RestResponse> {
    match indices_boost {
        Value::Object(boosts) => {
            if boosts
                .iter()
                .any(|(index, boost)| index.is_empty() || !boost.is_number())
            {
                return Some(build_unsupported_search_response(
                    "unsupported search option [indices_boost]",
                ));
            }
            None
        }
        Value::Array(boosts) => {
            for boost in boosts {
                let Some(object) = boost.as_object() else {
                    return Some(indices_boost_parsing_error(format!(
                        "Expected [START_OBJECT] in [indices_boost] but found [{}]",
                        opensearch_xcontent_token_name(boost)
                    )));
                };
                if object.len() != 1 {
                    let found = if object.is_empty() {
                        "END_OBJECT"
                    } else {
                        "FIELD_NAME"
                    };
                    let expected = if object.is_empty() {
                        "FIELD_NAME"
                    } else {
                        "END_OBJECT"
                    };
                    return Some(indices_boost_parsing_error(format!(
                        "Expected [{expected}] in [indices_boost] but found [{found}]"
                    )));
                }
                let Some((index, value)) = object.iter().next() else {
                    return Some(indices_boost_parsing_error(
                        "Expected [FIELD_NAME] in [indices_boost] but found [END_OBJECT]",
                    ));
                };
                if !value.is_number() {
                    return Some(indices_boost_parsing_error(format!(
                        "Expected [VALUE_NUMBER] in [indices_boost] but found [{}]",
                        opensearch_xcontent_token_name(value)
                    )));
                }
                if index.is_empty() {
                    return Some(build_unsupported_search_response(
                        "unsupported search option [indices_boost]",
                    ));
                }
            }
            None
        }
        _ => Some(build_unsupported_search_response(
            "unsupported search option [indices_boost]",
        )),
    }
}

fn indices_boost_parsing_error(reason: impl AsRef<str>) -> RestResponse {
    build_parsing_search_response_with_root_cause(reason.as_ref())
}

fn opensearch_xcontent_token_name(value: &Value) -> &'static str {
    match value {
        Value::Null => "VALUE_NULL",
        Value::Bool(_) => "VALUE_BOOLEAN",
        Value::Number(_) => "VALUE_NUMBER",
        Value::String(_) => "VALUE_STRING",
        Value::Array(_) => "START_ARRAY",
        Value::Object(_) => "START_OBJECT",
    }
}

fn validate_point_in_time_search_request(
    index: &str,
    request: &RestRequest,
) -> Option<RestResponse> {
    let mut validation_errors = Vec::new();
    if let Some(response) =
        validate_opensearch_boolean_query_param(request.query_params.get("ccs_minimize_roundtrips"))
    {
        return Some(response);
    }
    if pit_search_uses_explicit_indices(index, request) {
        validation_errors.push("[indices] cannot be used with point in time");
    }
    if pit_search_uses_non_default_indices_options(&request.query_params) {
        validation_errors.push("[indicesOptions] cannot be used with point in time");
    }
    if request.query_params.contains_key("routing") {
        validation_errors.push("[routing] cannot be used with point in time");
    }
    if request.query_params.contains_key("preference") {
        validation_errors.push("[preference] cannot be used with point in time");
    }
    if request
        .query_params
        .get("ccs_minimize_roundtrips")
        .is_some_and(|value| value == "true")
    {
        validation_errors.push("[ccs_minimize_roundtrips] cannot be used with point in time");
    }
    if request.query_params.contains_key("scroll") {
        validation_errors.push("using [point in time] is not allowed in a scroll context");
    }
    if validation_errors.is_empty() {
        return None;
    }
    Some(action_request_validation_error(validation_errors))
}

fn pit_search_id_has_local_shape(pit_id: &str) -> bool {
    if os_transport::action::OpenSearchSearchContextIdWire::decode(pit_id).is_ok() {
        return true;
    }
    let Some(decoded) = decode_base64_url_no_pad(pit_id) else {
        return false;
    };
    let Ok(decoded) = String::from_utf8(decoded) else {
        return false;
    };
    decoded
        .strip_prefix(LOCAL_PIT_ID_PREFIX)
        .is_some_and(|suffix| !suffix.is_empty() && suffix.parse::<u64>().is_ok())
}

const LOCAL_PIT_ID_PREFIX: &str = "steelsearch-pit:v1:";

pub fn build_local_pit_id(sequence: u64) -> String {
    encode_base64_url_no_pad(format!("{LOCAL_PIT_ID_PREFIX}{sequence}").as_bytes())
}

fn encode_base64_url_no_pad(bytes: &[u8]) -> String {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    let mut encoded = String::with_capacity((bytes.len() * 4).div_ceil(3));
    for chunk in bytes.chunks(3) {
        let first = chunk[0];
        let second = chunk.get(1).copied().unwrap_or(0);
        let third = chunk.get(2).copied().unwrap_or(0);
        let block = ((first as u32) << 16) | ((second as u32) << 8) | third as u32;
        encoded.push(TABLE[((block >> 18) & 0x3f) as usize] as char);
        encoded.push(TABLE[((block >> 12) & 0x3f) as usize] as char);
        if chunk.len() > 1 {
            encoded.push(TABLE[((block >> 6) & 0x3f) as usize] as char);
        }
        if chunk.len() > 2 {
            encoded.push(TABLE[(block & 0x3f) as usize] as char);
        }
    }
    encoded
}

fn decode_base64_url_no_pad(value: &str) -> Option<Vec<u8>> {
    if value.is_empty() || value.len() % 4 == 1 || value.as_bytes().contains(&b'=') {
        return None;
    }
    fn sextet(byte: u8) -> Option<u8> {
        match byte {
            b'A'..=b'Z' => Some(byte - b'A'),
            b'a'..=b'z' => Some(byte - b'a' + 26),
            b'0'..=b'9' => Some(byte - b'0' + 52),
            b'-' => Some(62),
            b'_' => Some(63),
            _ => None,
        }
    }

    let mut output = Vec::with_capacity(value.len() * 3 / 4);
    let mut buffer = 0u32;
    let mut bit_count = 0u8;
    for byte in value.bytes() {
        buffer = (buffer << 6) | u32::from(sextet(byte)?);
        bit_count += 6;
        while bit_count >= 8 {
            bit_count -= 8;
            output.push(((buffer >> bit_count) & 0xff) as u8);
            buffer &= (1 << bit_count) - 1;
        }
    }
    if bit_count > 0 && buffer != 0 {
        return None;
    }
    Some(output)
}

fn action_request_validation_error(validation_errors: Vec<&str>) -> RestResponse {
    action_request_validation_error_owned(
        validation_errors
            .into_iter()
            .map(ToOwned::to_owned)
            .collect(),
    )
}

fn action_request_validation_error_owned(validation_errors: Vec<String>) -> RestResponse {
    let reason = format!(
        "Validation Failed: {}",
        validation_errors
            .iter()
            .enumerate()
            .map(|(index, error)| format!("{}: {};", index + 1, error))
            .collect::<Vec<_>>()
            .join("")
    );
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "action_request_validation_exception",
                "reason": reason,
                "root_cause": [
                    {
                        "type": "action_request_validation_exception",
                        "reason": reason
                    }
                ]
            },
            "status": 400
        }),
    )
}

fn parse_search_scroll_body(body: &[u8]) -> Result<Option<String>, RestResponse> {
    let body: Value = serde_json::from_slice(body).map_err(|error| {
        RestResponse::opensearch_error(400, "unexpected_end_of_input_exception", error.to_string())
    })?;
    let Some(object) = body.as_object() else {
        return Err(RestResponse::opensearch_error(
            400,
            "illegal_argument_exception",
            "Malformed content, must start with an object",
        ));
    };
    let mut scroll_id = None;
    for (field, value) in object {
        match field.as_str() {
            "scroll_id" => {
                let Some(value) = value.as_str() else {
                    return Err(scroll_body_unknown_or_wrong_type(field, value));
                };
                scroll_id = Some(value.to_string());
            }
            "scroll" => {
                if !value.is_string() {
                    return Err(scroll_body_unknown_or_wrong_type(field, value));
                }
            }
            _ => return Err(scroll_body_unknown_or_wrong_type(field, value)),
        }
    }
    Ok(scroll_id)
}

fn parse_clear_scroll_body(body: &[u8]) -> Result<Vec<String>, RestResponse> {
    let body: Value = serde_json::from_slice(body).map_err(|error| {
        RestResponse::opensearch_error(400, "unexpected_end_of_input_exception", error.to_string())
    })?;
    let Some(object) = body.as_object() else {
        return Err(RestResponse::opensearch_error(
            400,
            "illegal_argument_exception",
            "Malformed content, must start with an object",
        ));
    };
    let mut scroll_ids = Vec::new();
    for (field, value) in object {
        if field != "scroll_id" {
            return Err(scroll_body_unknown_or_wrong_type(field, value));
        }
        match value {
            Value::String(scroll_id) => scroll_ids.push(scroll_id.clone()),
            Value::Array(ids) => {
                for id in ids {
                    let Some(scroll_id) = json_scalar_as_scroll_id(id) else {
                        return Err(RestResponse::opensearch_error(
                            400,
                            "illegal_argument_exception",
                            "scroll_id array element should only contain scroll_id",
                        ));
                    };
                    scroll_ids.push(scroll_id);
                }
            }
            _ => {
                let Some(scroll_id) = json_scalar_as_scroll_id(value) else {
                    return Err(scroll_body_unknown_or_wrong_type(field, value));
                };
                scroll_ids.push(scroll_id);
            }
        }
    }
    Ok(scroll_ids)
}

fn json_scalar_as_scroll_id(value: &Value) -> Option<String> {
    match value {
        Value::String(value) => Some(value.clone()),
        Value::Number(value) => Some(value.to_string()),
        Value::Bool(value) => Some(value.to_string()),
        _ => None,
    }
}

fn termvectors_fields_from_source(
    source: &Value,
    selected_fields: Option<&BTreeSet<String>>,
) -> serde_json::Map<String, Value> {
    source
        .as_object()
        .map(|source| {
            source
                .iter()
                .filter_map(|(field, value)| {
                    if selected_fields.is_some_and(|fields| !fields.contains(field)) {
                        return None;
                    }
                    let text = value.as_str()?;
                    Some((
                        field.clone(),
                        serde_json::json!({
                            "field_statistics": {
                                "sum_doc_freq": 1,
                                "doc_count": 1,
                                "sum_ttf": 1
                            },
                            "terms": {
                                text: {
                                    "term_freq": 1,
                                    "tokens": [
                                        {
                                            "position": 0,
                                            "start_offset": 0,
                                            "end_offset": text.len()
                                        }
                                    ]
                                }
                            }
                        }),
                    ))
                })
                .collect::<serde_json::Map<String, Value>>()
        })
        .unwrap_or_default()
}

fn scroll_body_unknown_or_wrong_type(field: &str, value: &Value) -> RestResponse {
    RestResponse::opensearch_error(
        400,
        "illegal_argument_exception",
        format!(
            "Unknown parameter [{field}] in request body or parameter is of the wrong type[{}] ",
            xcontent_token_name(value)
        ),
    )
}

fn invalid_tasks_group_by_response(group_by: &str) -> RestResponse {
    let reason =
        format!("[group_by] must be one of [nodes], [parents] or [none] but was [{group_by}]");
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "illegal_argument_exception",
                "reason": reason,
                "root_cause": [
                    {
                        "type": "illegal_argument_exception",
                        "reason": reason
                    }
                ]
            },
            "status": 400
        }),
    )
}

fn invalid_tasks_group_by(group_by: Option<&String>) -> Option<&str> {
    match group_by.map(String::as_str) {
        Some("nodes") | Some("parents") | Some("none") | None => None,
        Some(group_by) => Some(group_by),
    }
}

fn validate_tasks_boolean_query_params(
    request: &RestRequest,
    fields: &[&str],
) -> Option<RestResponse> {
    for field in fields {
        if let Some(response) =
            validate_opensearch_boolean_query_param(request.query_params.get(*field))
        {
            return Some(response);
        }
    }
    None
}

fn validate_tasks_time_query_params(
    request: &RestRequest,
    fields: &[&str],
) -> Option<RestResponse> {
    if fields.contains(&"master_timeout") && fields.contains(&"cluster_manager_timeout") {
        if let Some(response) = duplicate_master_cluster_manager_timeout_response(request) {
            return Some(response);
        }
    }
    for field in fields {
        let Some(raw_value) = request.query_params.get(*field) else {
            continue;
        };
        if parse_time_value_millis(raw_value).is_none() {
            return Some(search_time_query_param_parse_error(field, raw_value));
        }
    }
    None
}

fn validate_cluster_state_query_params(request: &RestRequest) -> Option<RestResponse> {
    if let Some(response) = validate_tasks_boolean_query_params(request, &["local"]) {
        return Some(response);
    }
    if let Some(response) = validate_tasks_time_query_params(
        request,
        &[
            "cluster_manager_timeout",
            "master_timeout",
            "wait_for_timeout",
        ],
    ) {
        return Some(response);
    }
    let Some(raw_version) = request.query_params.get("wait_for_metadata_version") else {
        return None;
    };
    if raw_version.parse::<i64>().is_err() {
        return Some(RestResponse::opensearch_error_kind(
            os_rest::RestErrorKind::IllegalArgument,
            format!(
                "Failed to parse long parameter [wait_for_metadata_version] with value [{raw_version}]"
            ),
        ));
    }
    None
}

fn validate_cluster_health_query_params(request: &RestRequest) -> Option<RestResponse> {
    if let Some(response) = validate_tasks_boolean_query_params(
        request,
        &[
            "local",
            "ensure_node_weighed_in",
            "wait_for_no_relocating_shards",
            "wait_for_no_initializing_shards",
        ],
    ) {
        return Some(response);
    }
    if let Some(response) = validate_tasks_time_query_params(
        request,
        &["timeout", "cluster_manager_timeout", "master_timeout"],
    ) {
        return Some(response);
    }
    if request
        .query_params
        .contains_key("wait_for_relocating_shards")
    {
        return Some(RestResponse::opensearch_error_kind(
            os_rest::RestErrorKind::IllegalArgument,
            "wait_for_relocating_shards has been removed, use wait_for_no_relocating_shards [true/false] instead",
        ));
    }
    if let Some(status) = request.query_params.get("wait_for_status") {
        if !matches!(
            status.to_ascii_lowercase().as_str(),
            "green" | "yellow" | "red"
        ) {
            return Some(RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                format!(
                    "No enum constant org.opensearch.cluster.health.ClusterHealthStatus.{}",
                    status.to_ascii_uppercase()
                ),
            ));
        }
    }
    if let Some(event) = request.query_params.get("wait_for_events") {
        if !matches!(
            event.to_ascii_lowercase().as_str(),
            "immediate" | "urgent" | "high" | "normal" | "low" | "languid"
        ) {
            return Some(RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                format!(
                    "No enum constant org.opensearch.common.Priority.{}",
                    event.to_ascii_uppercase()
                ),
            ));
        }
    }
    None
}

fn validate_cluster_stats_request(request: &RestRequest) -> Option<RestResponse> {
    const METRICS: &[&str] = &[
        "os",
        "jvm",
        "fs",
        "process",
        "ingest",
        "plugins",
        "network_types",
        "discovery_types",
        "packaging_types",
        "indices",
    ];
    const INDEX_METRICS: &[&str] = &[
        "shards",
        "docs",
        "store",
        "fielddata",
        "query_cache",
        "completion",
        "segments",
        "analysis",
        "mappings",
    ];

    let (path_metric, path_index_metric) = cluster_stats_path_metric_segments(&request.path);
    let raw_metric = request
        .query_params
        .get("metric")
        .map(String::as_str)
        .or(path_metric)
        .unwrap_or("_all");
    let metrics = split_nonempty_csv(raw_metric);
    if metrics.len() > 1 && metrics.contains(&"_all") {
        return Some(RestResponse::opensearch_error_kind(
            os_rest::RestErrorKind::IllegalArgument,
            format!(
                "request [{}] contains _all and individual metrics [{}]",
                request.path, raw_metric
            ),
        ));
    }

    let raw_index_metric = request
        .query_params
        .get("index_metric")
        .map(String::as_str)
        .or(path_index_metric)
        .or_else(|| {
            if metrics.contains(&"indices") || metrics.contains(&"_all") {
                Some("_all")
            } else {
                None
            }
        });
    let index_metrics = raw_index_metric.map(split_nonempty_csv).unwrap_or_default();
    if let Some(raw_index_metric) = raw_index_metric {
        if index_metrics.len() > 1 && index_metrics.contains(&"_all") {
            return Some(RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                format!(
                    "request [{}] contains _all and individual index metrics [{}]",
                    request.path, raw_index_metric
                ),
            ));
        }
        if !metrics.contains(&"indices") && !metrics.contains(&"_all") && !index_metrics.is_empty()
        {
            return Some(RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                format!(
                    "request [{}] contains index metrics [{}] but indices stats not requested",
                    request.path, raw_index_metric
                ),
            ));
        }
    }

    let invalid_metrics = metrics
        .iter()
        .filter(|metric| **metric != "_all" && !METRICS.contains(metric))
        .copied()
        .collect::<Vec<_>>();
    if !invalid_metrics.is_empty() {
        return Some(RestResponse::opensearch_error_kind(
            os_rest::RestErrorKind::IllegalArgument,
            unrecognized_cluster_stats_values(request, &invalid_metrics, "metric"),
        ));
    }

    if metrics.contains(&"indices") || metrics.contains(&"_all") {
        let invalid_index_metrics = index_metrics
            .iter()
            .filter(|metric| **metric != "_all" && !INDEX_METRICS.contains(metric))
            .copied()
            .collect::<Vec<_>>();
        if !invalid_index_metrics.is_empty() {
            return Some(RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                unrecognized_cluster_stats_values(request, &invalid_index_metrics, "index metric"),
            ));
        }
    }

    None
}

fn cluster_stats_path_metric_segments(path: &str) -> (Option<&str>, Option<&str>) {
    let Some(remainder) = path.strip_prefix("/_cluster/stats/") else {
        return (None, None);
    };
    let segments = remainder
        .split('/')
        .filter(|segment| !segment.is_empty())
        .collect::<Vec<_>>();
    match segments.as_slice() {
        ["nodes", _] => (None, None),
        [metric, "nodes", _] => (Some(*metric), None),
        [metric, index_metric, "nodes", _] => (Some(*metric), Some(*index_metric)),
        _ => (None, None),
    }
}

fn split_nonempty_csv(raw: &str) -> Vec<&str> {
    raw.split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .collect()
}

fn unrecognized_cluster_stats_values(
    request: &RestRequest,
    invalids: &[&str],
    detail: &str,
) -> String {
    let plural = if invalids.len() > 1 { "s" } else { "" };
    let values = invalids
        .iter()
        .map(|value| format!("[{value}]"))
        .collect::<Vec<_>>()
        .join(", ");
    format!(
        "request [{}] contains unrecognized {detail}{plural}: {values}",
        request.path
    )
}

fn validate_nodes_stats_request(request: &RestRequest) -> Option<RestResponse> {
    const METRICS: &[&str] = &[
        "os",
        "process",
        "jvm",
        "thread_pool",
        "fs",
        "transport",
        "http",
        "breaker",
        "script",
        "discovery",
        "ingest",
        "adaptive_selection",
        "script_cache",
        "indexing_pressure",
        "shard_indexing_pressure",
        "search_backpressure",
        "cluster_manager_throttling",
        "weighted_routing",
        "file_cache",
        "task_cancellation",
        "search_pipeline",
        "resource_usage_stats",
        "segment_replication_backpressure",
        "repositories",
        "admission_control",
        "caches",
        "remote_store",
        "indices",
    ];
    const INDEX_METRICS: &[&str] = &[
        "store",
        "indexing",
        "get",
        "search",
        "merge",
        "flush",
        "refresh",
        "query_cache",
        "fielddata",
        "docs",
        "warmer",
        "completion",
        "segments",
        "translog",
        "request_cache",
        "recovery",
    ];
    const CACHE_TYPES: &[&str] = &["request_cache"];

    let (path_metric, path_index_metric) = nodes_stats_path_metric_segments(&request.path);
    let raw_metric = request
        .query_params
        .get("metric")
        .map(String::as_str)
        .or(path_metric)
        .unwrap_or("_all");
    let metrics = split_nonempty_csv(raw_metric);
    let raw_index_metric = request
        .query_params
        .get("index_metric")
        .map(String::as_str)
        .or(path_index_metric);

    if metrics.len() == 1 && metrics.contains(&"_all") {
        if let Some(raw_index_metric) = raw_index_metric {
            return Some(RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                format!(
                    "request [{}] contains index metrics [{}] but all stats requested",
                    request.path, raw_index_metric
                ),
            ));
        }
        return None;
    }
    if metrics.contains(&"_all") {
        return Some(RestResponse::opensearch_error_kind(
            os_rest::RestErrorKind::IllegalArgument,
            format!(
                "request [{}] contains _all and individual metrics [{}]",
                request.path, raw_metric
            ),
        ));
    }

    let invalid_metrics = metrics
        .iter()
        .filter(|metric| !METRICS.contains(metric))
        .copied()
        .collect::<Vec<_>>();
    if !invalid_metrics.is_empty() {
        return Some(RestResponse::opensearch_error_kind(
            os_rest::RestErrorKind::IllegalArgument,
            unrecognized_cluster_stats_values(request, &invalid_metrics, "metric"),
        ));
    }

    let Some(raw_index_metric) = raw_index_metric else {
        return None;
    };
    let index_metrics = split_nonempty_csv(raw_index_metric);
    if metrics.contains(&"indices") {
        if index_metrics.len() == 1 && index_metrics.contains(&"_all") {
            return None;
        }
        let invalid_index_metrics = index_metrics
            .iter()
            .filter(|metric| !INDEX_METRICS.contains(metric))
            .copied()
            .collect::<Vec<_>>();
        if !invalid_index_metrics.is_empty() {
            return Some(RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                unrecognized_cluster_stats_values(request, &invalid_index_metrics, "index metric"),
            ));
        }
    } else if metrics.contains(&"caches") {
        if index_metrics.contains(&"_all") {
            return None;
        }
        let invalid_cache_types = index_metrics
            .iter()
            .filter(|metric| !CACHE_TYPES.contains(metric))
            .copied()
            .collect::<Vec<_>>();
        if !invalid_cache_types.is_empty() {
            return Some(RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                unrecognized_cluster_stats_values(request, &invalid_cache_types, "cache type"),
            ));
        }
    } else {
        return Some(RestResponse::opensearch_error_kind(
            os_rest::RestErrorKind::IllegalArgument,
            format!(
                "request [{}] contains index metrics [{}] but indices stats not requested",
                request.path, raw_index_metric
            ),
        ));
    }

    None
}

fn nodes_stats_path_metric_segments(path: &str) -> (Option<&str>, Option<&str>) {
    let Some(remainder) = path.strip_prefix("/_nodes/") else {
        return (None, None);
    };
    let segments = remainder
        .split('/')
        .filter(|segment| !segment.is_empty())
        .collect::<Vec<_>>();
    match segments.as_slice() {
        ["stats"] => (None, None),
        ["stats", metric] => (Some(*metric), None),
        ["stats", metric, index_metric] => (Some(*metric), Some(*index_metric)),
        [_, "stats"] => (None, None),
        [_, "stats", metric] => (Some(*metric), None),
        [_, "stats", metric, index_metric] => (Some(*metric), Some(*index_metric)),
        _ => (None, None),
    }
}

