fn parse_nodes_info_path(path: &str) -> Option<(String, BTreeSet<String>)> {
    if path == "/_nodes" {
        return Some((
            "_all".to_string(),
            nodes_info_all_metrics()
                .iter()
                .map(|metric| (*metric).to_string())
                .collect(),
        ));
    }
    let remainder = path.strip_prefix("/_nodes/")?;
    let segments = remainder
        .split('/')
        .filter(|segment| !segment.is_empty())
        .collect::<Vec<_>>();
    match segments.as_slice() {
        [node_or_metrics] => {
            let tokens = split_nonempty_csv(node_or_metrics);
            let is_metrics_only = !tokens.is_empty()
                && tokens
                    .iter()
                    .all(|token| nodes_info_all_metrics().contains(token));
            if is_metrics_only {
                Some((
                    "_all".to_string(),
                    tokens.into_iter().map(str::to_string).collect(),
                ))
            } else {
                Some((
                    (*node_or_metrics).to_string(),
                    nodes_info_all_metrics()
                        .iter()
                        .map(|metric| (*metric).to_string())
                        .collect(),
                ))
            }
        }
        [node_id, metrics] => Some((
            (*node_id).to_string(),
            nodes_info_requested_metrics(metrics),
        )),
        [node_id, "info", metrics] => Some((
            (*node_id).to_string(),
            nodes_info_requested_metrics(metrics),
        )),
        _ => None,
    }
}

fn nodes_info_requested_metrics(raw_metrics: &str) -> BTreeSet<String> {
    let metrics = split_nonempty_csv(raw_metrics);
    if metrics.len() == 1 && metrics.contains(&"_all") {
        return nodes_info_all_metrics()
            .iter()
            .map(|metric| (*metric).to_string())
            .collect();
    }
    metrics
        .into_iter()
        .filter(|metric| nodes_info_all_metrics().contains(metric))
        .map(str::to_string)
        .collect()
}

fn node_matches_nodes_info_selector(
    view: &DevelopmentClusterView,
    node: &DevelopmentClusterNode,
    selector: &str,
) -> bool {
    if selector == "_all" || selector == "*" {
        return true;
    }
    if selector == "_local" {
        return node.local
            || (!view.local_node_id.is_empty() && node.node_id == view.local_node_id);
    }
    selector.split(',').any(|pattern| {
        wildcard_match(pattern, &node.node_id)
            || wildcard_match(pattern, &node.node_name)
            || wildcard_match(pattern, &node.transport_address)
    })
}

fn parse_nodes_usage_path(path: &str) -> Option<(String, BTreeSet<String>)> {
    let remainder = path.strip_prefix("/_nodes/")?;
    let segments = remainder
        .split('/')
        .filter(|segment| !segment.is_empty())
        .collect::<Vec<_>>();
    match segments.as_slice() {
        ["usage"] => Some(("_all".to_string(), BTreeSet::from(["_all".to_string()]))),
        ["usage", metric] => Some((
            "_all".to_string(),
            split_nonempty_csv(metric)
                .into_iter()
                .map(str::to_string)
                .collect(),
        )),
        [node_id, "usage"] => Some(((*node_id).to_string(), BTreeSet::from(["_all".to_string()]))),
        [node_id, "usage", metric] => Some((
            (*node_id).to_string(),
            split_nonempty_csv(metric)
                .into_iter()
                .map(str::to_string)
                .collect(),
        )),
        _ => None,
    }
}

fn parse_nodes_hot_threads_path(path: &str) -> Option<Option<&str>> {
    match path {
        "/_nodes/hot_threads"
        | "/_nodes/hotthreads"
        | "/_cluster/nodes/hot_threads"
        | "/_cluster/nodes/hotthreads" => return Some(None),
        _ => {}
    }
    for (prefix, suffix) in [
        ("/_nodes/", "/hot_threads"),
        ("/_nodes/", "/hotthreads"),
        ("/_cluster/nodes/", "/hot_threads"),
        ("/_cluster/nodes/", "/hotthreads"),
    ] {
        if let Some(node_id) = path
            .strip_prefix(prefix)
            .and_then(|remainder| remainder.strip_suffix(suffix))
            .filter(|node_id| !node_id.is_empty() && !node_id.contains('/'))
        {
            return Some(Some(node_id));
        }
    }
    None
}

fn parse_hot_threads_int_query_param(
    request: &RestRequest,
    param: &str,
    default_value: i64,
) -> Result<i64, RestResponse> {
    let Some(raw) = request.query_params.get(param).map(String::as_str) else {
        return Ok(default_value);
    };
    raw.parse::<i64>().map_err(|_| {
        RestResponse::opensearch_error_kind(
            os_rest::RestErrorKind::IllegalArgument,
            format!("Failed to parse value [{raw}] for [{param}] as an integer"),
        )
    })
}

fn nodes_usage_raw_metric(path: &str) -> Option<&str> {
    let remainder = path.strip_prefix("/_nodes/")?;
    let segments = remainder
        .split('/')
        .filter(|segment| !segment.is_empty())
        .collect::<Vec<_>>();
    match segments.as_slice() {
        ["usage", metric] | [_, "usage", metric] => Some(*metric),
        _ => None,
    }
}

fn validate_doc_write_occ_query_params(
    request: &RestRequest,
) -> Option<(Option<i64>, Option<i64>)> {
    let raw_seq_no = request.query_params.get("if_seq_no");
    let raw_primary_term = request.query_params.get("if_primary_term");
    match (raw_seq_no, raw_primary_term) {
        (None, None) => Some((None, None)),
        (Some(seq_no), Some(primary_term)) => Some((
            Some(seq_no.parse::<i64>().ok()?),
            Some(primary_term.parse::<i64>().ok()?),
        )),
        _ => None,
    }
}

fn doc_write_occ_query_params_error(request: &RestRequest) -> RestResponse {
    let raw_seq_no = request.query_params.get("if_seq_no");
    let raw_primary_term = request.query_params.get("if_primary_term");
    if let Some(seq_no) = raw_seq_no {
        if seq_no.parse::<i64>().is_err() {
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "type": "illegal_argument_exception",
                        "reason": format!("Failed to parse value [{seq_no}] for [if_seq_no] as a long")
                    },
                    "status": 400
                }),
            );
        }
    }
    if let Some(primary_term) = raw_primary_term {
        if primary_term.parse::<i64>().is_err() {
            return RestResponse::json(
                400,
                serde_json::json!({
                    "error": {
                        "type": "illegal_argument_exception",
                        "reason": format!("Failed to parse value [{primary_term}] for [if_primary_term] as a long")
                    },
                    "status": 400
                }),
            );
        }
    }
    match (raw_seq_no, raw_primary_term) {
        (Some(_), None) => {
            action_request_validation_error(vec!["ifSeqNo is set, but primary term is [0]"])
        }
        (None, Some(primary_term)) => action_request_validation_error_owned(vec![format!(
            "ifSeqNo is unassigned, but primary term is [{primary_term}]"
        )]),
        _ => action_request_validation_error(vec![
            "if_seq_no and if_primary_term must be specified together",
        ]),
    }
}

fn require_alias_not_alias_reason(target: &str) -> String {
    format!("[require_alias] request flag is [true] and [{target}] is not an alias")
}

fn index_not_found_response(index: &str) -> RestResponse {
    let reason = format!("no such index [{index}]");
    RestResponse::json(
        404,
        serde_json::json!({
            "error": {
                "type": "index_not_found_exception",
                "reason": reason,
                "index": index,
                "index_uuid": "_na_",
                "resource.id": index,
                "resource.type": "index_or_alias",
                "root_cause": [
                    {
                        "type": "index_not_found_exception",
                        "reason": reason,
                        "index": index,
                        "index_uuid": "_na_",
                        "resource.id": index,
                        "resource.type": "index_or_alias"
                    }
                ]
            },
            "status": 404
        }),
    )
}

fn pit_search_uses_explicit_indices(index: &str, request: &RestRequest) -> bool {
    index != "_all" || request.path != "/_search"
}

fn pit_search_uses_non_default_indices_options(query_params: &BTreeMap<String, String>) -> bool {
    query_params.contains_key("ignore_unavailable")
        || query_params.contains_key("allow_no_indices")
        || query_params.contains_key("expand_wildcards")
        || query_params.contains_key("ignore_throttled")
}

fn validate_opensearch_boolean_query_param(raw: Option<&String>) -> Option<RestResponse> {
    let Some(value) = raw.map(String::as_str) else {
        return None;
    };
    if value.trim().is_empty() || value == "true" || value == "false" {
        return None;
    }
    Some(opensearch_boolean_parse_error(value))
}

fn opensearch_boolean_parse_error(value: &str) -> RestResponse {
    let reason = format!("Failed to parse value [{value}] as only [true] or [false] are allowed.");
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "illegal_argument_exception",
                "reason": reason,
                "root_cause": [
                    {
                        "type": "illegal_argument_exception",
                        "reason": reason
                    }
                ]
            },
            "status": 400
        }),
    )
}

fn parse_routing_values(routing: &str) -> Vec<String> {
    routing
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .collect()
}

fn parse_delete_pit_ids(body: &Value) -> Result<Vec<String>, RestResponse> {
    parse_pit_ids_with_messages(
        body,
        "pit_id element should only contain pit_id",
        "pit_id array element should only contain pit_id",
    )
}

fn parse_pit_segments_ids(body: &Value) -> Result<Vec<String>, RestResponse> {
    parse_pit_ids_with_messages(
        body,
        "pit_id element should only contain PIT identifier",
        "pit_id array element should only contain PIT identifier",
    )
}

fn parse_pit_ids_with_messages(
    body: &Value,
    scalar_error: &str,
    array_error: &str,
) -> Result<Vec<String>, RestResponse> {
    if body.is_null() {
        return Err(delete_pit_validation_error("no pit ids specified"));
    }
    let Some(object) = body.as_object() else {
        return Err(delete_pit_illegal_argument(
            "Malformed content, must start with an object",
        ));
    };
    if let Some((key, value)) = object.iter().find(|(key, _)| key.as_str() != "pit_id") {
        return Err(delete_pit_illegal_argument(format!(
            "Unknown parameter [{key}] in request body or parameter is of the wrong type[{}] ",
            xcontent_token_name(value)
        )));
    }
    let Some(pit_id) = object.get("pit_id") else {
        return Err(delete_pit_validation_error("no pit ids specified"));
    };
    let ids = if let Some(id_array) = pit_id.as_array() {
        let mut ids = Vec::new();
        for id in id_array {
            if id.is_number() {
                return Err(delete_pit_invalid_id_response(&id.to_string()));
            }
            if id.is_boolean() {
                return Err(delete_pit_invalid_eof_id_response(&id.to_string()));
            }
            let Some(id) = pit_id_value_as_text(id) else {
                return Err(delete_pit_illegal_argument(array_error));
            };
            if id.is_empty() {
                return Err(delete_pit_invalid_eof_id_response(&id));
            }
            ids.push(id);
        }
        ids
    } else if pit_id.is_number() {
        return Err(delete_pit_invalid_id_response(&pit_id.to_string()));
    } else if pit_id.is_boolean() {
        return Err(delete_pit_invalid_eof_id_response(&pit_id.to_string()));
    } else if let Some(id) = pit_id_value_as_text(pit_id) {
        if id.is_empty() {
            return Err(delete_pit_invalid_eof_id_response(&id));
        }
        vec![id]
    } else {
        return Err(delete_pit_illegal_argument(scalar_error));
    };
    if ids.is_empty() {
        return Err(delete_pit_validation_error("no pit ids specified"));
    }
    Ok(ids)
}

fn pit_id_value_as_text(value: &Value) -> Option<String> {
    match value {
        Value::String(value) => Some(value.clone()),
        Value::Number(value) => Some(value.to_string()),
        Value::Bool(value) => Some(value.to_string()),
        Value::Null | Value::Array(_) | Value::Object(_) => None,
    }
}

fn xcontent_token_name(value: &Value) -> &'static str {
    match value {
        Value::Object(_) => "START_OBJECT",
        Value::Array(_) => "START_ARRAY",
        Value::String(_) => "VALUE_STRING",
        Value::Number(_) => "VALUE_NUMBER",
        Value::Bool(_) => "VALUE_BOOLEAN",
        Value::Null => "VALUE_NULL",
    }
}

fn delete_pit_illegal_argument(reason: impl Into<String>) -> RestResponse {
    let reason = reason.into();
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "illegal_argument_exception",
                "reason": reason,
                "root_cause": [
                    {
                        "type": "illegal_argument_exception",
                        "reason": reason
                    }
                ]
            },
            "status": 400
        }),
    )
}

