fn validate_rescore_request_body(rescore: &Value) -> Option<RestResponse> {
    const DEFAULT_MAX_RESCORE_WINDOW: u64 = 10_000;
    let Some(object) = rescore.as_object() else {
        return Some(build_unsupported_search_response(
            "unsupported search option [rescore]",
        ));
    };
    if object
        .keys()
        .any(|key| key != "window_size" && key != "query")
    {
        return Some(build_unsupported_search_response(
            "unsupported search option [rescore]",
        ));
    }
    if object.get("window_size").and_then(Value::as_u64).is_none() {
        return Some(build_unsupported_search_response(
            "unsupported search option [rescore]",
        ));
    }
    if let Some(window_size) = object.get("window_size").and_then(Value::as_u64) {
        if window_size > DEFAULT_MAX_RESCORE_WINDOW {
            return Some(search_after_validation_error(format!(
                "Rescore window [{window_size}] is too large. It must be less than [{DEFAULT_MAX_RESCORE_WINDOW}]. This prevents allocating massive heaps for storing the results to be rescored. This limit can be set by changing the [index.max_rescore_window] index level setting."
            )));
        }
    }
    if let Some(query) = object.get("query").and_then(Value::as_object) {
        if query.keys().any(|key| {
            key != "rescore_query"
                && key != "query_weight"
                && key != "rescore_query_weight"
                && key != "score_mode"
        }) {
            return Some(build_unsupported_search_response(
                "unsupported search option [rescore]",
            ));
        }
        if let Some(rescore_query) = query.get("rescore_query") {
            if let Some(response) = validate_search_query_body(rescore_query) {
                return Some(response);
            }
        }
    }
    None
}

fn validate_collapse_request_body(
    collapse: &Value,
    sort: Option<&Value>,
    search_after: Option<&Value>,
    scroll: bool,
    rescore: Option<&Value>,
    shard_failure_index: &str,
) -> Option<RestResponse> {
    let Some(object) = collapse.as_object() else {
        return Some(build_unsupported_search_response(
            "unsupported search option [collapse]",
        ));
    };
    let Some(collapse_field) = object.get("field").and_then(Value::as_str) else {
        return Some(build_unsupported_search_response(
            "unsupported search option [collapse]",
        ));
    };
    if object.keys().any(|key| {
        !matches!(
            key.as_str(),
            "field" | "inner_hits" | "max_concurrent_group_searches"
        )
    }) {
        return Some(build_unsupported_search_response(
            "unsupported search option [collapse]",
        ));
    }
    if let Some(inner_hits) = object.get("inner_hits") {
        if !collapse_inner_hits_body_is_supported(inner_hits) {
            return Some(build_unsupported_search_response(
                "unsupported search option [collapse]",
            ));
        }
    }
    if object
        .get("max_concurrent_group_searches")
        .is_some_and(|value| value.as_u64().is_none())
    {
        return Some(build_unsupported_search_response(
            "unsupported search option [collapse]",
        ));
    }
    if scroll {
        return Some(search_after_phase_execution_error(
            "cannot use `collapse` in a scroll context",
            shard_failure_index,
        ));
    }
    if search_after.is_some() {
        let sort_fields = sort.and_then(search_sort_fields).unwrap_or_default();
        if sort_fields.len() != 1
            || sort_fields
                .first()
                .and_then(sort_field_name)
                .map_or(true, |field| field != collapse_field)
        {
            return Some(search_after_phase_execution_error(
                "collapse field and sort field must be the same when use `collapse` in conjunction with `search_after`",
                shard_failure_index,
            ));
        }
    }
    if rescore.is_some() {
        return Some(search_after_phase_execution_error(
            "cannot use `collapse` in conjunction with `rescore`",
            shard_failure_index,
        ));
    }
    None
}

fn collapse_inner_hits_body_is_supported(inner_hits: &Value) -> bool {
    let Some(object) = inner_hits.as_object() else {
        return false;
    };
    if object.keys().any(|key| {
        !matches!(
            key.as_str(),
            "name" | "from" | "size" | "sort" | "_source" | "version" | "seq_no_primary_term"
        )
    }) {
        return false;
    }
    if object.get("name").is_some_and(|value| !value.is_string()) {
        return false;
    }
    if object
        .get("from")
        .is_some_and(|value| value.as_u64().is_none())
    {
        return false;
    }
    if object
        .get("size")
        .is_some_and(|value| value.as_u64().is_none())
    {
        return false;
    }
    if object
        .get("sort")
        .is_some_and(|sort| search_sort_fields(sort).is_none())
    {
        return false;
    }
    true
}

fn validate_derived_request_body(derived: &Value) -> Option<RestResponse> {
    validate_request_scoped_field_definitions(
        derived,
        "derived",
        &[
            "type",
            "script",
            "properties",
            "prefilter_field",
            "format",
            "ignore_malformed",
        ],
    )
}

fn validate_request_scoped_field_definitions(
    definitions: &Value,
    option: &str,
    allowed_keys: &[&str],
) -> Option<RestResponse> {
    let unsupported =
        || build_unsupported_search_response(&format!("unsupported search option [{option}]"));
    let Some(mappings) = definitions.as_object() else {
        return Some(unsupported());
    };
    for definition in mappings.values() {
        let Some(definition_object) = definition.as_object() else {
            return Some(unsupported());
        };
        if definition_object
            .keys()
            .any(|key| !allowed_keys.iter().any(|allowed| allowed == key))
        {
            return Some(unsupported());
        }
        if definition_object
            .get("type")
            .and_then(Value::as_str)
            .is_none()
        {
            return Some(unsupported());
        }
        if definition_object
            .get("properties")
            .is_some_and(|value| !value.is_object())
        {
            return Some(unsupported());
        }
        if definition_object
            .get("prefilter_field")
            .is_some_and(|value| !value.is_string())
        {
            return Some(unsupported());
        }
        if definition_object
            .get("format")
            .is_some_and(|value| !value.is_string())
        {
            return Some(unsupported());
        }
        if definition_object
            .get("ignore_malformed")
            .is_some_and(|value| !value.is_boolean())
        {
            return Some(unsupported());
        }
        let Some(source) = request_scoped_field_script_source(definition_object) else {
            return Some(unsupported());
        };
        if parse_runtime_mapping_script_source(source).is_none() {
            return Some(unsupported());
        }
    }
    None
}

fn validate_stored_fields_request_body(stored_fields: &Value) -> Option<RestResponse> {
    match stored_fields {
        Value::String(field) if !field.is_empty() => None,
        Value::Array(fields) => {
            if fields.iter().any(|field| field.as_str().is_none()) {
                return Some(build_unsupported_search_response(
                    "unsupported search option [stored_fields]",
                ));
            }
            if fields
                .iter()
                .filter_map(Value::as_str)
                .any(|field| field == "_none_")
                && !(fields.len() == 1 && fields.first().and_then(Value::as_str) == Some("_none_"))
            {
                return Some(stored_fields_illegal_argument(
                    "cannot combine _none_ with other fields",
                ));
            }
            None
        }
        _ => Some(build_unsupported_search_response(
            "unsupported search option [stored_fields]",
        )),
    }
}

fn validate_stored_fields_fetch_interactions(
    body: &Value,
    shard_failure_index: &str,
) -> Option<RestResponse> {
    if !stored_fields_fetch_disabled(body.get("stored_fields")) {
        return None;
    }
    if body.get("fields").is_some() {
        return Some(search_after_phase_execution_error(
            "[stored_fields] cannot be disabled when using the [fields] option",
            shard_failure_index,
        ));
    }
    if source_fetch_explicitly_requested(body) {
        return Some(search_after_phase_execution_error(
            "[stored_fields] cannot be disabled if [_source] is requested",
            shard_failure_index,
        ));
    }
    None
}

