fn validate_match_query_shape(
    query_name: &str,
    query: &serde_json::Map<String, Value>,
    supported_options: &[&str],
) -> Option<RestResponse> {
    let Some((_, spec)) = query.iter().next() else {
        return Some(build_unsupported_search_response(&format!(
            "unsupported {query_name} query shape"
        )));
    };
    if query.len() != 1 {
        return Some(build_unsupported_search_response(&format!(
            "unsupported {query_name} query shape"
        )));
    }
    if let Some(options) = spec.as_object() {
        for key in options.keys() {
            if !supported_options.contains(&key.as_str()) {
                return Some(build_parsing_search_response_with_root_cause(&format!(
                    "[{query_name}] query does not support [{key}]"
                )));
            }
        }
        if options.get("query").and_then(Value::as_str).is_none() {
            return Some(build_unsupported_search_response(&format!(
                "unsupported {query_name} query shape"
            )));
        }
    } else if !spec.is_string() {
        return Some(build_unsupported_search_response(&format!(
            "unsupported {query_name} query shape"
        )));
    }
    None
}

fn validate_multi_match_query_shape(
    query: &serde_json::Map<String, Value>,
) -> Option<RestResponse> {
    for key in query.keys() {
        if !MULTI_MATCH_QUERY_OPTIONS.contains(&key.as_str()) {
            return Some(build_parsing_search_response_with_root_cause(&format!(
                "[multi_match] query does not support [{key}]"
            )));
        }
    }
    let zero_terms_all = query
        .get("zero_terms_query")
        .and_then(Value::as_str)
        .is_some_and(|value| value.eq_ignore_ascii_case("all"));
    if query
        .get("query")
        .and_then(Value::as_str)
        .map(str::is_empty)
        .unwrap_or(true)
        && !zero_terms_all
    {
        return Some(build_unsupported_search_response(
            "unsupported multi_match query shape",
        ));
    }
    if let Some(fields) = query.get("fields") {
        let valid = fields.as_str().is_some_and(|value| !value.is_empty())
            || fields.as_array().is_some_and(|items| {
                !items.is_empty()
                    && items
                        .iter()
                        .all(|value| value.as_str().is_some_and(|field| !field.is_empty()))
            });
        if !valid {
            return Some(build_parsing_search_response_with_root_cause(
                "[multi_match] query does not support [fields]",
            ));
        }
    }
    None
}

fn validate_terms_query_shape(query: &serde_json::Map<String, Value>) -> Option<RestResponse> {
    let mut field_count = 0usize;
    let mut values = None;
    for (key, value) in query {
        match key.as_str() {
            "boost" => {
                if !value
                    .as_f64()
                    .is_some_and(|number| number.is_finite() && number >= 0.0)
                {
                    return Some(build_unsupported_search_response("unsupported terms boost"));
                }
            }
            "_name" => {
                if !value.is_string() {
                    return Some(build_unsupported_search_response("unsupported terms _name"));
                }
            }
            "value_type" => {
                if !value
                    .as_str()
                    .is_some_and(|value| value.eq_ignore_ascii_case("default"))
                {
                    return Some(build_unsupported_search_response(
                        "unsupported terms value_type",
                    ));
                }
            }
            _ => {
                field_count += 1;
                values = Some(value);
            }
        }
    }
    let Some(values) = values else {
        return Some(build_parsing_search_response_with_root_cause(
            "[terms] query requires a field name, followed by array of terms or a document lookup specification",
        ));
    };
    if field_count != 1 {
        return Some(build_parsing_search_response_with_root_cause(
            "[terms] query does not support multiple fields",
        ));
    }
    let Some(values) = values.as_array() else {
        return Some(build_unsupported_search_response(
            "unsupported terms query shape",
        ));
    };
    if values.iter().any(Value::is_null) {
        return Some(build_parsing_search_response_with_root_cause(
            "No value specified for terms query",
        ));
    }
    None
}

fn validate_dis_max_query_shape(query: &serde_json::Map<String, Value>) -> Option<RestResponse> {
    for key in query.keys() {
        if !matches!(key.as_str(), "queries" | "tie_breaker" | "boost" | "_name") {
            return Some(build_parsing_search_response_with_root_cause(&format!(
                "[dis_max] query does not support [{key}]"
            )));
        }
    }
    if query
        .get("tie_breaker")
        .is_some_and(|value| value.as_f64().is_none())
    {
        return Some(build_parsing_search_response_with_root_cause(
            "[dis_max] query does not support [tie_breaker]",
        ));
    }
    if query
        .get("boost")
        .is_some_and(|value| value.as_f64().is_none())
    {
        return Some(build_parsing_search_response_with_root_cause(
            "[dis_max] query does not support [boost]",
        ));
    }
    if query.get("_name").is_some_and(|value| !value.is_string()) {
        return Some(build_parsing_search_response_with_root_cause(
            "[dis_max] query does not support [_name]",
        ));
    }
    None
}

fn validate_ids_query_shape(query: &serde_json::Map<String, Value>) -> Option<RestResponse> {
    for key in query.keys() {
        if !matches!(key.as_str(), "values" | "boost" | "_name") {
            return Some(build_parsing_search_response_with_root_cause(&format!(
                "[1:41] [ids] unknown field [{key}]"
            )));
        }
    }
    if let Some(values) = query.get("values") {
        if !values
            .as_array()
            .is_some_and(|items| items.iter().all(Value::is_string))
        {
            return Some(build_parsing_search_response_with_root_cause(
                "[ids] failed to parse field [values]",
            ));
        }
    }
    if query
        .get("boost")
        .is_some_and(|value| value.as_f64().is_none())
    {
        return Some(build_parsing_search_response_with_root_cause(
            "[ids] failed to parse field [boost]",
        ));
    }
    if query.get("_name").is_some_and(|value| !value.is_string()) {
        return Some(build_parsing_search_response_with_root_cause(
            "[ids] failed to parse field [_name]",
        ));
    }
    None
}

fn split_document_key(key: &str) -> Option<(&str, &str, &str)> {
    let mut parts = key.splitn(3, ':');
    Some((parts.next()?, parts.next()?, parts.next()?))
}

fn next_seq_no_by_index_from_documents(documents: &DocumentMap) -> BTreeMap<String, u64> {
    let mut next_by_index: BTreeMap<String, u64> = BTreeMap::new();
    for (key, document) in documents {
        let Some((index, _, _)) = split_document_key(key) else {
            continue;
        };
        let next = document.seq_no.saturating_add(1).max(0) as u64;
        next_by_index
            .entry(index.to_string())
            .and_modify(|current| *current = (*current).max(next))
            .or_insert(next);
    }
    next_by_index
}

fn current_epoch_millis() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .expect("system time before unix epoch")
        .as_millis()
}

fn initial_auto_id_sequence() -> u32 {
    (current_time_millis() as u32) & 0x00ff_ffff
}

fn encode_opensearch_auto_id(sequence_id: u32, timestamp: u64, node_name: &str) -> String {
    let sequence_id = sequence_id & 0x00ff_ffff;
    let address = auto_id_node_address_bytes(node_name);
    let mut uuid_bytes = [0_u8; 15];
    let mut i = 0;
    uuid_bytes[i] = sequence_id as u8;
    i += 1;
    uuid_bytes[i] = (sequence_id >> 16) as u8;
    i += 1;
    uuid_bytes[i] = (timestamp >> 16) as u8;
    i += 1;
    uuid_bytes[i] = (timestamp >> 24) as u8;
    i += 1;
    uuid_bytes[i] = (timestamp >> 32) as u8;
    i += 1;
    uuid_bytes[i] = (timestamp >> 40) as u8;
    i += 1;
    uuid_bytes[i..i + address.len()].copy_from_slice(&address);
    i += address.len();
    uuid_bytes[i] = (timestamp >> 8) as u8;
    i += 1;
    uuid_bytes[i] = (sequence_id >> 8) as u8;
    i += 1;
    uuid_bytes[i] = timestamp as u8;

    base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(uuid_bytes)
}

fn auto_id_node_address_bytes(node_name: &str) -> [u8; 6] {
    let digest = Sha256::digest(node_name.as_bytes());
    [
        digest[0], digest[1], digest[2], digest[3], digest[4], digest[5],
    ]
}

fn parse_time_value_millis(value: &str) -> Option<u64> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return None;
    }
    let units = [
        ("micros", 1_u64, 1_000_u64),
        ("nanos", 1_u64, 1_000_000_u64),
        ("ms", 1_u64, 1_u64),
        ("s", 1_000_u64, 1_u64),
        ("m", 60_000_u64, 1_u64),
        ("h", 3_600_000_u64, 1_u64),
        ("d", 86_400_000_u64, 1_u64),
    ];
    let (number, multiplier, divisor) =
        units.iter().find_map(|(suffix, multiplier, divisor)| {
            trimmed
                .strip_suffix(suffix)
                .map(|number| (number, *multiplier, *divisor))
        })?;
    let amount = number.parse::<i128>().ok()?;
    if amount <= 0 {
        return Some(0);
    }
    u64::try_from(amount)
        .ok()
        .and_then(|amount| amount.checked_mul(multiplier))
        .map(|millis| millis / divisor)
}

fn keep_alive_parse_error_reason(value: &str) -> String {
    if time_value_has_fractional_number(value) {
        format!("failed to parse [{value}], fractional time values are not supported")
    } else {
        format!(
            "failed to parse setting [keep_alive] with value [{value}] as a time value: unit is missing or unrecognized"
        )
    }
}

fn time_value_has_fractional_number(value: &str) -> bool {
    let trimmed = value.trim();
    let units = ["micros", "nanos", "ms", "s", "m", "h", "d"];
    units
        .iter()
        .find_map(|suffix| trimmed.strip_suffix(suffix))
        .is_some_and(|number| number.contains('.'))
}

fn validate_pit_keep_alive_limit(keep_alive_millis: u64) -> Option<RestResponse> {
    if keep_alive_millis <= DEFAULT_MAX_PIT_KEEP_ALIVE_MILLIS {
        return None;
    }
    let reason = pit_keep_alive_limit_reason(keep_alive_millis);
    Some(RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "illegal_argument_exception",
                "reason": reason,
                "root_cause": [
                    {
                        "type": "illegal_argument_exception",
                        "reason": reason
                    }
                ]
            },
            "status": 400
        }),
    ))
}

fn pit_search_keep_alive_limit_response(
    keep_alive_millis: u64,
    index_name: Option<String>,
) -> RestResponse {
    let reason = pit_keep_alive_limit_reason(keep_alive_millis);
    let mut failed_shard = serde_json::json!({
        "shard": 0,
        "reason": {
            "type": "illegal_argument_exception",
            "reason": reason
        }
    });
    if let (Value::Object(object), Some(index_name)) = (&mut failed_shard, index_name) {
        object.insert("index".to_string(), Value::String(index_name));
    }
    RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "search_phase_execution_exception",
                "reason": "all shards failed",
                "root_cause": [
                    {
                        "type": "illegal_argument_exception",
                        "reason": reason
                    }
                ],
                "caused_by": {
                    "type": "illegal_argument_exception",
                    "reason": reason,
                    "caused_by": {
                        "type": "illegal_argument_exception",
                        "reason": reason
                    }
                },
                "failed_shards": [failed_shard]
            },
            "status": 400
        }),
    )
}

fn pit_keep_alive_limit_reason(keep_alive_millis: u64) -> String {
    format!(
        "Keep alive for request ({}) is too large. It must be less than ({}). This limit can be set by changing the [point_in_time.max_keep_alive] cluster level setting.",
        format_time_value_millis(keep_alive_millis),
        format_time_value_millis(DEFAULT_MAX_PIT_KEEP_ALIVE_MILLIS)
    )
}

fn normalize_pit_keep_alive_millis(keep_alive_millis: u64) -> u64 {
    if keep_alive_millis == 0 {
        DEFAULT_PIT_NON_POSITIVE_KEEP_ALIVE_MILLIS
    } else {
        keep_alive_millis
    }
}

fn pit_expires_at_millis(now_millis: u128, keep_alive_millis: u64) -> u128 {
    now_millis + u128::from(keep_alive_millis.max(DEFAULT_PIT_EXPIRY_REAPER_GRACE_MILLIS))
}

fn drain_expired_pit_contexts(
    contexts: &mut BTreeMap<String, PitContext>,
    now_millis: u128,
) -> Vec<PitContext> {
    let expired_ids = contexts
        .iter()
        .filter_map(|(id, context)| {
            if context.expires_at_millis <= now_millis {
                Some(id.clone())
            } else {
                None
            }
        })
        .collect::<Vec<_>>();
    expired_ids
        .into_iter()
        .filter_map(|id| contexts.remove(&id))
        .collect()
}

fn index_primary_shard_count_from_manifest(
    metadata_manifest_state: &Arc<Mutex<Value>>,
    index: &str,
) -> usize {
    let manifest = metadata_manifest_state
        .lock()
        .expect("metadata manifest state lock poisoned");
    primary_shard_count_from_index_metadata(&manifest["indices"][index])
}

fn primary_shard_count_from_index_metadata(index_metadata: &Value) -> usize {
    let settings = &index_metadata["settings"];
    settings["index"]["number_of_shards"]
        .as_str()
        .or_else(|| settings["number_of_shards"].as_str())
        .and_then(|value| value.parse::<usize>().ok())
        .or_else(|| {
            settings["index"]["number_of_shards"]
                .as_u64()
                .or_else(|| settings["number_of_shards"].as_u64())
                .map(|value| value as usize)
        })
        .unwrap_or(1)
}

fn index_resize_body_sets_number_of_shards(body: &Value) -> bool {
    let settings = &body["settings"];
    settings["index"]["number_of_shards"].is_string()
        || settings["index"]["number_of_shards"].is_number()
        || settings["number_of_shards"].is_string()
        || settings["number_of_shards"].is_number()
        || settings["index.number_of_shards"].is_string()
        || settings["index.number_of_shards"].is_number()
}

fn index_remote_store_enabled_from_metadata(index_metadata: &Value) -> bool {
    let settings = &index_metadata["settings"];
    settings["index"]["remote_store"]["enabled"]
        .as_bool()
        .or_else(|| settings["index"]["remote_store.enabled"].as_bool())
        .or_else(|| settings["index.remote_store.enabled"].as_bool())
        .or_else(|| parse_boolish(settings["index"]["remote_store"]["enabled"].as_str()))
        .or_else(|| parse_boolish(settings["index"]["remote_store.enabled"].as_str()))
        .or_else(|| parse_boolish(settings["index.remote_store.enabled"].as_str()))
        .unwrap_or(false)
}

fn index_search_only_enabled_from_metadata(index_metadata: &Value) -> bool {
    let settings = &index_metadata["settings"];
    settings["index"]["blocks"]["search_only"]
        .as_bool()
        .or_else(|| settings["index"]["blocks.search_only"].as_bool())
        .or_else(|| settings["index.blocks.search_only"].as_bool())
        .or_else(|| index_metadata["blocks"]["search_only"].as_bool())
        .or_else(|| parse_boolish(settings["index"]["blocks"]["search_only"].as_str()))
        .or_else(|| parse_boolish(settings["index"]["blocks.search_only"].as_str()))
        .or_else(|| parse_boolish(settings["index.blocks.search_only"].as_str()))
        .unwrap_or(false)
}

fn parse_boolish(value: Option<&str>) -> Option<bool> {
    match value? {
        "true" => Some(true),
        "false" => Some(false),
        _ => None,
    }
}

fn replica_count_from_index_metadata(index_metadata: &Value) -> usize {
    let settings = &index_metadata["settings"];
    settings["index"]["number_of_replicas"]
        .as_str()
        .or_else(|| settings["number_of_replicas"].as_str())
        .and_then(|value| value.parse::<usize>().ok())
        .or_else(|| {
            settings["index"]["number_of_replicas"]
                .as_u64()
                .or_else(|| settings["number_of_replicas"].as_u64())
                .map(|value| value as usize)
        })
        .unwrap_or(0)
}

fn record_pit_context_time_millis_with_lookup<F>(
    pit_time_millis_by_index: &Arc<Mutex<BTreeMap<String, u64>>>,
    contexts: &[PitContext],
    now_millis: u128,
    shard_count_for_index: F,
) where
    F: Fn(&str) -> usize,
{
    if contexts.is_empty() {
        return;
    }
    let mut totals = pit_time_millis_by_index
        .lock()
        .expect("pit time millis lock poisoned");
    for context in contexts {
        let elapsed_millis = now_millis
            .saturating_sub(context.creation_time_millis)
            .min(u128::from(u64::MAX)) as u64;
        for index in &context.indices {
            let shard_contexts = shard_count_for_index(index).max(1) as u64;
            let elapsed = elapsed_millis.saturating_mul(shard_contexts);
            let entry = totals.entry(index.clone()).or_insert(0);
            *entry = entry.saturating_add(elapsed);
        }
    }
}

