fn extract_snapshot_restore_unknown_parameter(body: &Value) -> Option<&'static str> {
    let object = body.as_object()?;
    for candidate in ["stale", "corrupt", "incompatible"] {
        if object.get(candidate).and_then(Value::as_bool) == Some(true) {
            return Some(candidate);
        }
    }
    None
}

fn apply_snapshot_restore_rename(
    source_index: &str,
    rename_pattern: Option<&str>,
    rename_replacement: Option<&str>,
) -> String {
    match (rename_pattern, rename_replacement) {
        (Some("(.+)"), Some(replacement)) => replacement.replace("$1", source_index),
        (Some(pattern), Some(replacement)) if pattern.contains("(.+)") => {
            let Some((prefix, suffix)) = pattern.split_once("(.+)") else {
                return source_index.to_string();
            };
            if source_index.starts_with(prefix) && source_index.ends_with(suffix) {
                let capture_end = source_index.len().saturating_sub(suffix.len());
                if prefix.len() <= capture_end {
                    return replacement.replace("$1", &source_index[prefix.len()..capture_end]);
                }
            }
            source_index.to_string()
        }
        (Some(pattern), Some(replacement)) if pattern == source_index => replacement.to_string(),
        _ => source_index.to_string(),
    }
}

fn evaluate_search_query(
    record: &StoredDocument,
    doc_id: &str,
    query: &Value,
) -> Option<(bool, f64)> {
    evaluate_search_query_source(&record.source, doc_id, query)
}

fn evaluate_search_query_source(
    source: &Value,
    doc_id: &str,
    query: &Value,
) -> Option<(bool, f64)> {
    evaluate_search_query_source_with_mappings(source, doc_id, query, &Value::Null)
}

fn evaluate_search_query_source_with_mappings(
    source: &Value,
    doc_id: &str,
    query: &Value,
    mappings: &Value,
) -> Option<(bool, f64)> {
    if query.is_null() || query.as_object().is_some_and(|object| object.is_empty()) {
        return Some((true, 1.0));
    }
    if query.get("match_all").is_some() {
        return Some((true, direct_named_query_boost(query)));
    }
    if query.get("match_none").is_some() {
        return Some((false, 0.0));
    }
    if let Some(term) = query.get("term").and_then(Value::as_object) {
        let (field, expected) = term.iter().next()?;
        let (expected, case_insensitive) = extract_term_query_value(expected)?;
        let matched = value_matches_term(
            lookup_query_field_value(source, field),
            expected,
            lookup_query_field_mapping_type(mappings, field),
            case_insensitive,
        );
        return Some((
            matched,
            if matched {
                direct_named_query_boost(query)
            } else {
                0.0
            },
        ));
    }
    if let Some(terms) = query.get("terms").and_then(Value::as_object) {
        let (field, expected) = extract_terms_query_field_values(terms)?;
        let matched = value_matches_terms(
            lookup_query_field_value(source, field),
            expected,
            lookup_query_field_mapping_type(mappings, field),
        );
        return Some((
            matched,
            if matched {
                direct_named_query_boost(query)
            } else {
                0.0
            },
        ));
    }
    if let Some(match_query) = query.get("match").and_then(Value::as_object) {
        let (field, expected) = match_query.iter().next()?;
        let query_text = extract_match_query_value(expected).unwrap_or_default();
        let boost = direct_named_query_boost(query);
        if query_text.trim().is_empty() && extract_zero_terms_query_all(expected) {
            return Some((true, boost));
        }
        let haystacks = lookup_query_field_value(source, field)
            .map(collect_string_leaf_values)
            .unwrap_or_default();
        if let Some(fuzzy_options) = extract_match_query_fuzzy_options(expected, query_text) {
            let matched = value_matches_match_fuzzy(
                &haystacks,
                query_text,
                fuzzy_options.fuzziness,
                fuzzy_options.prefix_length,
                fuzzy_options.transpositions,
                extract_match_query_operator(expected),
                extract_match_minimum_should_match(expected),
            );
            return Some((matched, if matched { boost } else { 0.0 }));
        }
        let (matched, score) = evaluate_text_query_strings(
            &haystacks,
            query_text,
            extract_match_query_operator(expected),
            false,
            extract_match_minimum_should_match(expected),
        );
        return Some((matched, if matched { score * boost } else { 0.0 }));
    }
    if let Some(multi_match) = query.get("multi_match").and_then(Value::as_object) {
        let expected = multi_match
            .get("query")
            .and_then(Value::as_str)
            .unwrap_or_default();
        if expected.trim().is_empty()
            && extract_zero_terms_query_all(&Value::Object(multi_match.clone()))
        {
            return Some((true, 1.0));
        }
        let fields = extract_multi_match_fields(multi_match.get("fields"));
        let field_refs = fields.iter().map(String::as_str).collect::<Vec<_>>();
        let haystacks = collect_searchable_field_values(source, Some(field_refs.as_slice()));
        let slop = extract_match_phrase_slop(&Value::Object(multi_match.clone()));
        let (matched, score) = match multi_match.get("type").and_then(Value::as_str) {
            Some("phrase") => {
                let matched = haystacks.iter().any(|haystack| {
                    value_matches_phrase_with_analyzer(
                        Some(&Value::String(haystack.clone())),
                        expected,
                        false,
                        slop,
                        multi_match.get("analyzer").and_then(Value::as_str),
                    )
                });
                (matched, if matched { 1.0 } else { 0.0 })
            }
            Some("phrase_prefix") => {
                let matched = haystacks.iter().any(|haystack| {
                    value_matches_phrase_with_analyzer(
                        Some(&Value::String(haystack.clone())),
                        expected,
                        true,
                        slop,
                        multi_match.get("analyzer").and_then(Value::as_str),
                    )
                });
                (matched, if matched { 1.0 } else { 0.0 })
            }
            Some("bool_prefix") => {
                let matched = value_matches_multi_match_bool_prefix(
                    &haystacks,
                    expected,
                    multi_match
                        .get("operator")
                        .and_then(Value::as_str)
                        .unwrap_or("or"),
                    multi_match.get("minimum_should_match"),
                );
                (matched, if matched { 1.0 } else { 0.0 })
            }
            Some("cross_fields") => evaluate_text_query_strings(
                &haystacks,
                expected,
                multi_match
                    .get("operator")
                    .and_then(Value::as_str)
                    .unwrap_or("or"),
                false,
                multi_match.get("minimum_should_match"),
            ),
            _ => {
                let operator = multi_match
                    .get("operator")
                    .and_then(Value::as_str)
                    .unwrap_or("or");
                if let Some(fuzzy_options) =
                    extract_match_query_fuzzy_options(&Value::Object(multi_match.clone()), expected)
                {
                    let matched = value_matches_match_fuzzy(
                        &haystacks,
                        expected,
                        fuzzy_options.fuzziness,
                        fuzzy_options.prefix_length,
                        fuzzy_options.transpositions,
                        operator,
                        multi_match.get("minimum_should_match"),
                    );
                    (matched, if matched { 1.0 } else { 0.0 })
                } else {
                    evaluate_text_query_strings(
                        &haystacks,
                        expected,
                        operator,
                        false,
                        multi_match.get("minimum_should_match"),
                    )
                }
            }
        };
        return Some((matched, score));
    }
    if let Some(match_phrase) = query.get("match_phrase").and_then(Value::as_object) {
        let (field, expected) = match_phrase.iter().next()?;
        let query_text = extract_match_query_value(expected).unwrap_or_default();
        let boost = direct_named_query_boost(query);
        if query_text.trim().is_empty() && extract_zero_terms_query_all(expected) {
            return Some((true, boost));
        }
        let matched = value_matches_phrase_with_analyzer(
            lookup_query_field_value(source, field),
            query_text,
            false,
            extract_match_phrase_slop(expected),
            extract_match_query_analyzer(expected),
        );
        return Some((matched, if matched { boost } else { 0.0 }));
    }
    if let Some(match_phrase_prefix) = query.get("match_phrase_prefix").and_then(Value::as_object) {
        let (field, expected) = match_phrase_prefix.iter().next()?;
        let query_text = extract_match_query_value(expected).unwrap_or_default();
        let boost = direct_named_query_boost(query);
        if query_text.trim().is_empty() && extract_zero_terms_query_all(expected) {
            return Some((true, boost));
        }
        let matched = value_matches_phrase_with_analyzer(
            lookup_query_field_value(source, field),
            query_text,
            true,
            extract_match_phrase_slop(expected),
            extract_match_query_analyzer(expected),
        );
        return Some((matched, if matched { boost } else { 0.0 }));
    }
    if let Some(match_bool_prefix) = query.get("match_bool_prefix").and_then(Value::as_object) {
        let (field, expected) = match_bool_prefix.iter().next()?;
        let expected_value = extract_match_query_value(expected)?;
        let haystacks = lookup_query_field_value(source, field)
            .map(collect_string_leaf_values)
            .unwrap_or_default();
        let matched = value_matches_multi_match_bool_prefix(
            &haystacks,
            expected_value,
            extract_match_query_operator(expected),
            extract_match_minimum_should_match(expected),
        );
        return Some((
            matched,
            if matched {
                direct_named_query_boost(query)
            } else {
                0.0
            },
        ));
    }
    if let Some(combined_fields) = query.get("combined_fields").and_then(Value::as_object) {
        let query_text = combined_fields.get("query").and_then(Value::as_str)?;
        let fields = combined_fields
            .get("fields")
            .and_then(Value::as_array)?
            .iter()
            .filter_map(Value::as_str)
            .collect::<Vec<_>>();
        let haystacks = collect_searchable_field_values(source, Some(fields.as_slice()));
        let (matched, score) =
            evaluate_text_query_strings(&haystacks, query_text, "and", false, None);
        return Some((matched, score));
    }
    if let Some(dis_max) = query.get("dis_max").and_then(Value::as_object) {
        let queries = dis_max.get("queries").and_then(Value::as_array)?;
        let mut best_score: f64 = 0.0;
        let mut matched = false;
        for clause in queries {
            let (clause_matched, clause_score) =
                evaluate_search_query_source_with_mappings(source, doc_id, clause, mappings)?;
            if clause_matched {
                matched = true;
                best_score = best_score.max(clause_score);
            }
        }
        return Some((matched, if matched { best_score.max(1.0) } else { 0.0 }));
    }
    if let Some(boosting) = query.get("boosting").and_then(Value::as_object) {
        let positive = boosting.get("positive")?;
        let negative = boosting.get("negative")?;
        let negative_boost = boosting
            .get("negative_boost")
            .and_then(Value::as_f64)
            .unwrap_or(0.2);
        let (positive_matched, positive_score) =
            evaluate_search_query_source_with_mappings(source, doc_id, positive, mappings)?;
        if !positive_matched {
            return Some((false, 0.0));
        }
        let (negative_matched, _) =
            evaluate_search_query_source_with_mappings(source, doc_id, negative, mappings)?;
        let boost = boosting
            .get("boost")
            .and_then(finite_number_value)
            .unwrap_or(1.0);
        let score = if negative_matched {
            positive_score.max(1.0) * negative_boost
        } else {
            positive_score.max(1.0)
        };
        let score = score * boost;
        return Some((true, score));
    }
    if let Some(ids_query) = query.get("ids").and_then(Value::as_object) {
        let matched = ids_query
            .get("values")
            .and_then(Value::as_array)
            .is_some_and(|values| {
                values
                    .iter()
                    .filter_map(Value::as_str)
                    .any(|candidate| candidate == doc_id)
            });
        return Some((
            matched,
            if matched {
                direct_named_query_boost(query)
            } else {
                0.0
            },
        ));
    }
    if let Some(query_string) = query.get("query_string").and_then(Value::as_object) {
        return Some(evaluate_text_query_spec(source, query_string, false));
    }
    if let Some(simple_query_string) = query.get("simple_query_string").and_then(Value::as_object) {
        return Some(evaluate_text_query_spec(source, simple_query_string, true));
    }
    if let Some(wildcard_query) = query.get("wildcard").and_then(Value::as_object) {
        let (field, expected) = wildcard_query.iter().next()?;
        let (expected_value, case_insensitive) =
            extract_string_query_value_and_case_insensitive(expected)?;
        let matched = value_matches_wildcard(
            lookup_query_field_value(source, field),
            expected_value,
            case_insensitive,
        );
        return Some((
            matched,
            if matched {
                direct_named_query_boost(query)
            } else {
                0.0
            },
        ));
    }
    if let Some(prefix_query) = query.get("prefix").and_then(Value::as_object) {
        let (field, expected) = prefix_query.iter().next()?;
        let (expected_value, case_insensitive) =
            extract_string_query_value_and_case_insensitive(expected)?;
        let matched = value_matches_prefix(
            lookup_query_field_value(source, field),
            expected_value,
            case_insensitive,
        );
        return Some((
            matched,
            if matched {
                direct_named_query_boost(query)
            } else {
                0.0
            },
        ));
    }
    if let Some(regexp_query) = query.get("regexp").and_then(Value::as_object) {
        let (field, expected) = regexp_query.iter().next()?;
        let (expected_value, case_insensitive) =
            extract_string_query_value_and_case_insensitive(expected)?;
        let matched = value_matches_regexp(
            lookup_query_field_value(source, field),
            expected_value,
            case_insensitive,
        );
        return Some((
            matched,
            if matched {
                direct_named_query_boost(query)
            } else {
                0.0
            },
        ));
    }
    if let Some(fuzzy_query) = query.get("fuzzy").and_then(Value::as_object) {
        let (field, expected) = fuzzy_query.iter().next()?;
        let (expected_value, fuzzy_options) = extract_fuzzy_query_value(expected)?;
        let matched = value_matches_fuzzy(
            lookup_query_field_value(source, field),
            expected_value,
            fuzzy_options.fuzziness,
            fuzzy_options.prefix_length,
            fuzzy_options.transpositions,
        );
        return Some((
            matched,
            if matched {
                direct_named_query_boost(query)
            } else {
                0.0
            },
        ));
    }
    if let Some(exists_query) = query.get("exists").and_then(Value::as_object) {
        let field = exists_query.get("field").and_then(Value::as_str)?;
        let matched = lookup_query_field_value(source, field).is_some_and(|value| !value.is_null());
        return Some((
            matched,
            if matched {
                direct_named_query_boost(query)
            } else {
                0.0
            },
        ));
    }
    if let Some(terms_set_query) = query.get("terms_set").and_then(Value::as_object) {
        let (field, expected) = terms_set_query.iter().next()?;
        let (matched, score) = value_matches_terms_set(source, field, expected)?;
        return Some((matched, score));
    }
    if let Some(rank_feature) = query.get("rank_feature").and_then(Value::as_object) {
        let field = rank_feature.get("field").and_then(Value::as_str)?;
        let score =
            rank_feature_score(lookup_query_field_value(source, field), Some(rank_feature))?;
        return Some((score > 0.0, score));
    }
    if let Some(neural_sparse) = query.get("neural_sparse").and_then(Value::as_object) {
        let (field, spec) = neural_sparse.iter().next()?;
        let spec_object = spec.as_object()?;
        let query_tokens = spec_object.get("query_tokens").and_then(Value::as_object)?;
        let score =
            neural_sparse_query_score(lookup_query_field_value(source, field), query_tokens);
        return Some((score > 0.0, score));
    }
    if let Some(distance_feature) = query.get("distance_feature").and_then(Value::as_object) {
        let field = distance_feature.get("field").and_then(Value::as_str)?;
        let origin = distance_feature.get("origin")?;
        let pivot = distance_feature.get("pivot")?;
        let matched =
            value_matches_distance_feature(lookup_query_field_value(source, field), origin, pivot);
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(constant_score) = query.get("constant_score").and_then(Value::as_object) {
        let inner_query = constant_score
            .get("filter")
            .or_else(|| constant_score.get("query"))?;
        let (matched, _) =
            evaluate_search_query_source_with_mappings(source, doc_id, inner_query, mappings)?;
        let boost = constant_score
            .get("boost")
            .and_then(finite_number_value)
            .unwrap_or(1.0);
        return Some((matched, if matched { boost } else { 0.0 }));
    }
    if query.get("wrapper").is_some() {
        let inner_query = decode_wrapper_query(query).ok()?;
        return evaluate_search_query_source_with_mappings(source, doc_id, &inner_query, mappings);
    }
    if let Some(function_score) = query.get("function_score").and_then(Value::as_object) {
        let inner_query = function_score.get("query")?;
        let (matched, inner_score) =
            evaluate_search_query_source_with_mappings(source, doc_id, inner_query, mappings)?;
        if !matched {
            return Some((false, 0.0));
        }
        let function_value =
            evaluate_function_score_value(source, doc_id, function_score, mappings)?;
        let max_boost = function_score
            .get("max_boost")
            .and_then(finite_number_value)
            .unwrap_or(f64::MAX);
        let function_value = function_value.min(max_boost);
        let boost_mode = function_score
            .get("boost_mode")
            .and_then(Value::as_str)
            .unwrap_or("multiply");
        let score = combine_function_boost_score(inner_score, function_value, boost_mode);
        if function_score
            .get("min_score")
            .and_then(finite_number_value)
            .is_some_and(|min_score| score < min_score)
        {
            return Some((false, 0.0));
        }
        return Some((true, score.max(0.0)));
    }
    if let Some(script_score) = query.get("script_score").and_then(Value::as_object) {
        let inner_query = script_score.get("query")?;
        let (matched, _) =
            evaluate_search_query_source_with_mappings(source, doc_id, inner_query, mappings)?;
        if !matched {
            return Some((false, 0.0));
        }
        let score = script_score
            .get("script")
            .and_then(Value::as_object)
            .and_then(|script| script.get("source"))
            .and_then(Value::as_str)
            .and_then(|value| value.parse::<f64>().ok())
            .unwrap_or(1.0);
        let boost = script_score
            .get("boost")
            .and_then(finite_number_value)
            .unwrap_or(1.0);
        let score = score * boost;
        if script_score
            .get("min_score")
            .and_then(finite_number_value)
            .is_some_and(|min_score| score < min_score)
        {
            return Some((false, 0.0));
        }
        return Some((true, score.max(0.0)));
    }
    if let Some(script_query) = query.get("script").and_then(Value::as_object) {
        let matched = script_query
            .get("script")
            .is_some_and(|script| matches_script_filter_query(source, script));
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(span_term) = query.get("span_term").and_then(Value::as_object) {
        return evaluate_span_query(source, span_term)
            .map(|matched| (matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(span_or) = query.get("span_or").and_then(Value::as_object) {
        let matched = evaluate_span_or_query(source, span_or)?;
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(span_first) = query.get("span_first").and_then(Value::as_object) {
        let matched = evaluate_span_first_query(source, span_first)?;
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(span_not) = query.get("span_not").and_then(Value::as_object) {
        let matched = evaluate_span_not_query(source, span_not)?;
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(span_containing) = query.get("span_containing").and_then(Value::as_object) {
        let matched = evaluate_span_containing_query(source, span_containing)?;
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(span_within) = query.get("span_within").and_then(Value::as_object) {
        let matched = evaluate_span_containing_query(source, span_within)?;
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(span_near) = query.get("span_near").and_then(Value::as_object) {
        let matched = evaluate_span_near_query(source, span_near)?;
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(span_multi) = query.get("span_multi").and_then(Value::as_object) {
        let matched = evaluate_span_multi_query(source, span_multi)?;
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(field_masking_span) = field_masking_span_query_object(query) {
        let matched = evaluate_field_masking_span_query(source, field_masking_span)?;
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(more_like_this) = query.get("more_like_this").and_then(Value::as_object) {
        let like = more_like_this
            .get("like")
            .and_then(Value::as_str)
            .unwrap_or_default();
        let fields = more_like_this
            .get("fields")
            .and_then(Value::as_array)?
            .iter()
            .filter_map(Value::as_str)
            .collect::<Vec<_>>();
        let mut best_score: f64 = 0.0;
        for field in fields {
            best_score = best_score.max(score_match_query(
                lookup_query_field_value(source, field),
                like,
            ));
        }
        return Some((best_score > 0.0, best_score));
    }
    if let Some(intervals_query) = query.get("intervals").and_then(Value::as_object) {
        let (field, spec) = intervals_query.iter().next()?;
        let matched = evaluate_intervals_query(source, field, spec)?;
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(nested_query) = query.get("nested").and_then(Value::as_object) {
        let path = nested_query.get("path").and_then(Value::as_str)?;
        let inner_query = nested_query.get("query")?;
        let candidates = source.get(path)?.as_array()?;
        let mut scores = Vec::new();
        for candidate in candidates {
            let (inner_matched, inner_score) = evaluate_search_query_source_with_mappings(
                candidate,
                doc_id,
                inner_query,
                mappings,
            )?;
            if inner_matched {
                scores.push(inner_score);
            }
        }
        let matched = !scores.is_empty();
        let score_mode = nested_query
            .get("score_mode")
            .and_then(Value::as_str)
            .unwrap_or("avg");
        return Some((
            matched,
            if matched {
                combine_nested_scores(&scores, score_mode)
            } else {
                0.0
            },
        ));
    }
    if let Some(geo_distance_query) = query.get("geo_distance").and_then(Value::as_object) {
        let distance = geo_distance_query.get("distance")?;
        let max_distance_meters =
            parse_distance_meters_with_unit(distance, geo_distance_query.get("unit"))?;
        let (field, point) = geo_distance_query.iter().find(|(key, _)| {
            !matches!(
                key.as_str(),
                "distance"
                    | "unit"
                    | "distance_type"
                    | "validation_method"
                    | "ignore_unmapped"
                    | "boost"
                    | "_name"
            )
        })?;
        let candidate_point =
            lookup_query_field_value(source, field).and_then(parse_geo_point_value)?;
        let query_point = parse_geo_point_value(point)?;
        let distance_meters = haversine_distance_meters(candidate_point, query_point);
        let matched = distance_meters <= max_distance_meters;
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(geo_bounding_box_query) = query.get("geo_bounding_box").and_then(Value::as_object) {
        let (field, box_spec) = geo_bounding_box_query.iter().find(|(key, _)| {
            !matches!(
                key.as_str(),
                "ignore_unmapped" | "validation_method" | "type" | "_name" | "boost"
            )
        })?;
        let box_object = box_spec.as_object()?;
        let (top_left, bottom_right) = parse_geo_bounding_box_corners(box_object)?;
        let candidate_point =
            lookup_query_field_value(source, field).and_then(parse_geo_point_value)?;
        let matched = geo_point_in_bounding_box(candidate_point, top_left, bottom_right);
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(geo_polygon_query) = query.get("geo_polygon").and_then(Value::as_object) {
        let (field, polygon_spec) = geo_polygon_query.iter().find(|(key, _)| {
            !matches!(
                key.as_str(),
                "ignore_unmapped" | "validation_method" | "_name" | "boost"
            )
        })?;
        let points = polygon_spec
            .as_object()?
            .get("points")?
            .as_array()?
            .iter()
            .map(parse_geo_point_value)
            .collect::<Option<Vec<_>>>()?;
        let candidate_point =
            lookup_query_field_value(source, field).and_then(parse_geo_point_value)?;
        let matched = geo_point_in_polygon(candidate_point, &points);
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(geo_shape_query) = query.get("geo_shape").and_then(Value::as_object) {
        let (field, shape_spec) = geo_shape_query
            .iter()
            .find(|(key, _)| !matches!(key.as_str(), "ignore_unmapped" | "_name" | "boost"))?;
        let shape_object = shape_spec.as_object()?;
        let candidate_point =
            lookup_query_field_value(source, field).and_then(geo_shape_field_point_value)?;
        let relation = shape_object
            .get("relation")
            .and_then(Value::as_str)
            .map(str::to_ascii_lowercase)
            .unwrap_or_else(|| "intersects".to_string());
        let query_shape = shape_object.get("shape")?;
        let matched = match relation.as_str() {
            "intersects" | "within" => geo_shape_contains_point(query_shape, candidate_point),
            "disjoint" => !geo_shape_contains_point(query_shape, candidate_point),
            "contains" => {
                geo_shape_point_value(query_shape).is_some_and(|point| point == candidate_point)
            }
            _ => false,
        };
        return Some((matched, if matched { 1.0 } else { 0.0 }));
    }
    if let Some(bool_query) = query.get("bool").and_then(Value::as_object) {
        let mut total_score = 0.0;
        let mut has_scoring_clause = false;
        let mut has_filter_clause = false;
        let mut bool_matched_without_score = false;
        for clause in bool_query_clauses(bool_query, "must") {
            let (matched, score) =
                evaluate_search_query_source_with_mappings(source, doc_id, clause, mappings)?;
            if !matched {
                return Some((false, 0.0));
            }
            total_score += score;
            has_scoring_clause = true;
        }
        let filters = bool_query_clauses(bool_query, "filter");
        if !filters.is_empty() {
            has_filter_clause = true;
            let matched = filters.iter().all(|clause| {
                evaluate_search_query_source_with_mappings(source, doc_id, clause, mappings)
                    .map(|(matched, _)| matched)
                    .unwrap_or(false)
            });
            if !matched {
                return Some((false, 0.0));
            }
            bool_matched_without_score = true;
        }
        for clause in bool_query_clauses(bool_query, "must_not") {
            let (matched, _) =
                evaluate_search_query_source_with_mappings(source, doc_id, clause, mappings)?;
            if matched {
                return Some((false, 0.0));
            }
            bool_matched_without_score = true;
        }
        let shoulds = bool_query_clauses(bool_query, "should");
        if !shoulds.is_empty() {
            let mut matched_should = 0usize;
            for clause in &shoulds {
                let (matched, score) =
                    evaluate_search_query_source_with_mappings(source, doc_id, clause, mappings)?;
                if matched {
                    matched_should += 1;
                    total_score += score;
                    has_scoring_clause = true;
                }
            }
            let has_required_positive_clause =
                bool_query.get("must").is_some() || has_filter_clause;
            let required = bool_query
                .get("minimum_should_match")
                .and_then(|value| bool_minimum_should_match_value(value, shoulds.len()))
                .map(|value| {
                    if value == 0
                        && shoulds
                            .iter()
                            .any(|clause| value_contains_vector_query(clause))
                    {
                        0
                    } else if !has_required_positive_clause {
                        value.max(1)
                    } else {
                        value
                    }
                })
                .unwrap_or_else(|| if has_required_positive_clause { 0 } else { 1 });
            if matched_should < required {
                return Some((false, 0.0));
            }
            if matched_should == 0 && required == 0 {
                bool_matched_without_score = true;
            }
        }
        if has_scoring_clause {
            return Some((true, total_score.max(1.0)));
        }
        if has_filter_clause || bool_matched_without_score {
            return Some((true, 1.0));
        }
    }
    if let Some(knn_query) = query.get("knn").and_then(Value::as_object) {
        let (field, spec) = knn_query.iter().next()?;
        let spec_object = spec.as_object()?;
        if let Some(filter) = spec_object.get("filter") {
            let (matched, _) =
                evaluate_search_query_source_with_mappings(source, doc_id, filter, mappings)?;
            if !matched {
                return Some((false, 0.0));
            }
        }
        let vector = spec_object.get("vector")?.as_array()?;
        let score = score_knn_query(lookup_query_field_value(source, field), vector);
        if score <= f64::MIN / 2.0 {
            return Some((false, 0.0));
        }
        if let Some(min_score) = spec_object.get("min_score").and_then(Value::as_f64) {
            if score < min_score {
                return Some((false, 0.0));
            }
        }
        if let Some(max_distance) = spec_object.get("max_distance").and_then(Value::as_f64) {
            if score < max_distance {
                return Some((false, 0.0));
            }
        }
        return Some((true, score));
    }
    if let Some(hybrid_query) = query.get("hybrid").and_then(Value::as_object) {
        let clauses = hybrid_query.get("queries").and_then(Value::as_array)?;
        let mut total_score = 0.0;
        let mut matched = false;
        for clause in clauses {
            let (clause_matched, clause_score) =
                evaluate_search_query_source_with_mappings(source, doc_id, clause, mappings)?;
            if clause_matched {
                matched = true;
                total_score += clause_score;
            }
        }
        return Some((matched, if matched { total_score.max(1.0) } else { 0.0 }));
    }
    if let Some(range_query) = query.get("range").and_then(Value::as_object) {
        let (field, bounds) = range_query.iter().next()?;
        let matched = value_matches_range(lookup_query_field_value(source, field), bounds);
        return Some((
            matched,
            if matched {
                direct_named_query_boost(query)
            } else {
                0.0
            },
        ));
    }
    Some((false, 0.0))
}

fn collect_matched_named_queries(
    source: &Value,
    doc_id: &str,
    body: &Value,
    mappings: &Value,
) -> Vec<(String, f64)> {
    let mut matched = Vec::new();
    collect_matched_named_queries_from_query(
        source,
        doc_id,
        &body["query"],
        mappings,
        &mut matched,
    );
    for rescore_query in search_rescore_queries(body.get("rescore")) {
        collect_matched_named_queries_from_query(
            source,
            doc_id,
            rescore_query,
            mappings,
            &mut matched,
        );
    }
    matched
}

fn collect_matched_named_queries_from_query(
    source: &Value,
    doc_id: &str,
    query: &Value,
    mappings: &Value,
    matched: &mut Vec<(String, f64)>,
) {
    if let Some(name) = direct_named_query_name(query) {
        if let Some((true, score)) =
            evaluate_search_query_source_with_mappings(source, doc_id, query, mappings)
        {
            matched.push((name.to_string(), score * direct_named_query_boost(query)));
        }
    }
    for child in child_named_query_candidates(query) {
        collect_matched_named_queries_from_query(source, doc_id, child, mappings, matched);
    }
}

fn render_matched_named_queries(matched: &[(String, f64)], body: &Value) -> Value {
    if body.get("include_named_queries_score") == Some(&Value::Bool(true)) {
        let mut object = serde_json::Map::new();
        for (name, score) in matched {
            object.insert(name.clone(), Value::from(*score));
        }
        Value::Object(object)
    } else {
        let mut names = matched
            .iter()
            .map(|(name, _)| name.clone())
            .collect::<Vec<_>>();
        names.sort();
        Value::Array(names.into_iter().map(Value::String).collect())
    }
}

fn direct_named_query_name(query: &Value) -> Option<&str> {
    let object = query.as_object()?;
    for query_type in NAMED_QUERY_TYPES {
        let Some(spec) = object.get(*query_type) else {
            continue;
        };
        if let Some(name) = spec.get("_name").and_then(Value::as_str) {
            return Some(name);
        }
        if let Some(name) = field_query_inner_option(spec, "_name").and_then(Value::as_str) {
            return Some(name);
        }
    }
    None
}

fn direct_named_query_boost(query: &Value) -> f64 {
    let Some(object) = query.as_object() else {
        return 1.0;
    };
    for query_type in NAMED_QUERY_TYPES {
        let Some(spec) = object.get(*query_type) else {
            continue;
        };
        if let Some(boost) = spec.get("boost").and_then(Value::as_f64) {
            return boost;
        }
        if let Some(boost) = field_query_inner_option(spec, "boost").and_then(Value::as_f64) {
            return boost;
        }
    }
    1.0
}

fn field_query_inner_option<'a>(spec: &'a Value, option: &str) -> Option<&'a Value> {
    spec.as_object()?.iter().find_map(|(key, value)| {
        if key.starts_with('_') || matches!(key.as_str(), "boost" | "value_type") {
            return None;
        }
        value.as_object()?.get(option)
    })
}

fn child_named_query_candidates(query: &Value) -> Vec<&Value> {
    if let Some(bool_query) = query.get("bool").and_then(Value::as_object) {
        return ["must", "filter", "should", "must_not"]
            .into_iter()
            .flat_map(|field| bool_query_clauses(bool_query, field))
            .collect();
    }
    if let Some(dis_max) = query.get("dis_max").and_then(Value::as_object) {
        return dis_max
            .get("queries")
            .and_then(Value::as_array)
            .map(|queries| queries.iter().collect())
            .unwrap_or_default();
    }
    if let Some(boosting) = query.get("boosting").and_then(Value::as_object) {
        return ["positive", "negative"]
            .into_iter()
            .filter_map(|field| boosting.get(field))
            .collect();
    }
    if let Some(constant_score) = query.get("constant_score").and_then(Value::as_object) {
        return ["filter", "query"]
            .into_iter()
            .filter_map(|field| constant_score.get(field))
            .collect();
    }
    if let Some(function_score) = query.get("function_score").and_then(Value::as_object) {
        return function_score.get("query").into_iter().collect();
    }
    if let Some(script_score) = query.get("script_score").and_then(Value::as_object) {
        return script_score.get("query").into_iter().collect();
    }
    if let Some(nested) = query.get("nested").and_then(Value::as_object) {
        return nested.get("query").into_iter().collect();
    }
    if let Some(knn) = query.get("knn").and_then(Value::as_object) {
        return knn.values().filter_map(|spec| spec.get("filter")).collect();
    }
    if let Some(hybrid) = query.get("hybrid").and_then(Value::as_object) {
        return hybrid
            .get("queries")
            .and_then(Value::as_array)
            .map(|queries| queries.iter().collect())
            .unwrap_or_default();
    }
    Vec::new()
}

fn search_rescore_queries(rescore: Option<&Value>) -> Vec<&Value> {
    let Some(rescore) = rescore else {
        return Vec::new();
    };
    let specs = rescore
        .as_array()
        .map(|values| values.iter().collect::<Vec<_>>())
        .unwrap_or_else(|| vec![rescore]);
    specs
        .into_iter()
        .filter_map(|spec| {
            spec.get("query")
                .and_then(|query| query.get("rescore_query"))
        })
        .collect()
}

const NAMED_QUERY_TYPES: &[&str] = &[
    "bool",
    "boosting",
    "combined_fields",
    "constant_score",
    "dis_max",
    "distance_feature",
    "exists",
    "function_score",
    "fuzzy",
    "geo_bounding_box",
    "geo_distance",
    "geo_polygon",
    "geo_shape",
    "hybrid",
    "ids",
    "intervals",
    "knn",
    "match",
    "match_all",
    "match_bool_prefix",
    "match_none",
    "match_phrase",
    "match_phrase_prefix",
    "more_like_this",
    "multi_match",
    "nested",
    "prefix",
    "query_string",
    "range",
    "rank_feature",
    "regexp",
    "script",
    "script_score",
    "simple_query_string",
    "term",
    "terms",
    "terms_set",
    "wildcard",
    "wrapper",
];

fn value_matches_term(
    candidate: Option<&Value>,
    expected: &Value,
    field_type: Option<&str>,
    case_insensitive: bool,
) -> bool {
    match (candidate, expected) {
        (Some(Value::Array(values)), expected) => values
            .iter()
            .any(|value| value_matches_term(Some(value), expected, field_type, case_insensitive)),
        (Some(Value::String(left)), Value::String(right)) => {
            let lowered_right = right.to_ascii_lowercase();
            if matches!(
                field_type,
                Some("keyword") | Some("constant_keyword") | Some("wildcard")
            ) {
                if case_insensitive {
                    left.to_ascii_lowercase() == lowered_right
                } else {
                    left == right
                }
            } else {
                tokenize_search_text(left)
                    .into_iter()
                    .any(|token| token == lowered_right)
            }
        }
        (Some(Value::Number(left)), Value::Number(right)) => left == right,
        (Some(left), right) => left == right,
        _ => false,
    }
}

fn value_matches_terms(
    candidate: Option<&Value>,
    expected: &Value,
    field_type: Option<&str>,
) -> bool {
    let Some(expected_values) = expected.as_array() else {
        return false;
    };
    expected_values
        .iter()
        .any(|expected| value_matches_term(candidate, expected, field_type, false))
}

fn decode_wrapper_query(query: &Value) -> Result<Value, ()> {
    let encoded = query
        .get("wrapper")
        .and_then(Value::as_object)
        .and_then(|wrapper| wrapper.get("query"))
        .and_then(Value::as_str)
        .ok_or(())?;
    let decoded = decode_base64_standard(encoded).ok_or(())?;
    serde_json::from_slice::<Value>(&decoded).map_err(|_| ())
}

fn lookup_query_field_mapping_type<'a>(mappings: &'a Value, field: &str) -> Option<&'a str> {
    let mut current = mappings.get("properties")?;
    let mut segments = field.split('.').peekable();
    while let Some(segment) = segments.next() {
        let field_mapping = current.get(segment)?;
        if segments.peek().is_none() {
            return field_mapping.get("type").and_then(Value::as_str);
        }
        current = field_mapping.get("properties")?;
    }
    None
}

fn tokenize_search_text(input: &str) -> Vec<String> {
    input
        .split(|character: char| !character.is_ascii_alphanumeric())
        .map(|token| token.to_ascii_lowercase())
        .filter(|token| !token.is_empty())
        .collect()
}

fn build_highlight_response_body(
    source: &Value,
    query: &Value,
    highlight: &Value,
) -> Option<Value> {
    let highlight_object = highlight.as_object()?;
    let fields = highlight_object.get("fields")?.as_object()?;
    let pre_tag = highlight_object
        .get("pre_tags")
        .and_then(Value::as_array)
        .and_then(|tags| tags.first())
        .and_then(Value::as_str)
        .unwrap_or("<em>");
    let post_tag = highlight_object
        .get("post_tags")
        .and_then(Value::as_array)
        .and_then(|tags| tags.first())
        .and_then(Value::as_str)
        .unwrap_or("</em>");
    let default_no_match_size = highlight_object
        .get("no_match_size")
        .and_then(Value::as_u64)
        .and_then(|value| usize::try_from(value).ok())
        .unwrap_or(0);
    let mut highlighted_fields = serde_json::Map::new();
    for (field, field_options) in fields {
        let Some(original_text) = lookup_query_field_value(source, field).and_then(Value::as_str)
        else {
            continue;
        };
        let no_match_size = field_options
            .get("no_match_size")
            .and_then(Value::as_u64)
            .and_then(|value| usize::try_from(value).ok())
            .unwrap_or(default_no_match_size);
        let terms = collect_highlight_terms(query, field);
        if terms.is_empty() {
            if let Some(snippet) = render_no_match_highlight_text(original_text, no_match_size) {
                highlighted_fields.insert(field.clone(), serde_json::json!([snippet]));
            }
            continue;
        }
        let rendered = render_highlight_text(original_text, &terms, pre_tag, post_tag);
        if rendered != original_text {
            highlighted_fields.insert(field.clone(), serde_json::json!([rendered]));
        } else if let Some(snippet) = render_no_match_highlight_text(original_text, no_match_size) {
            highlighted_fields.insert(field.clone(), serde_json::json!([snippet]));
        }
    }
    if highlighted_fields.is_empty() {
        None
    } else {
        Some(Value::Object(highlighted_fields))
    }
}

fn render_no_match_highlight_text(input: &str, no_match_size: usize) -> Option<String> {
    if no_match_size == 0 || input.is_empty() {
        return None;
    }
    let mut end = 0;
    for (index, ch) in input.char_indices() {
        if index >= no_match_size && ch.is_whitespace() {
            break;
        }
        end = index + ch.len_utf8();
    }
    if end == 0 {
        end = input.len().min(no_match_size);
    }
    Some(input[..end].trim_end().to_string())
}

fn collect_highlight_terms(query: &Value, field: &str) -> Vec<String> {
    let mut terms = Vec::new();
    if let Some(term_query) = query.get("term").and_then(Value::as_object) {
        if let Some((query_field, expected)) = term_query.iter().next() {
            if query_field == field {
                if let Some((value, _)) =
                    extract_term_query_value(expected).and_then(|(value, case_insensitive)| {
                        value.as_str().map(|text| (text, case_insensitive))
                    })
                {
                    terms.extend(tokenize_search_text(value));
                }
            }
        }
    }
    for query_name in ["match", "match_phrase", "match_phrase_prefix"] {
        if let Some(match_query) = query.get(query_name).and_then(Value::as_object) {
            if let Some((query_field, value)) = match_query.iter().next() {
                if query_field == field {
                    if let Some(text) = extract_string_query_value(value) {
                        terms.extend(tokenize_search_text(text));
                    }
                }
            }
        }
    }
    if let Some(multi_match) = query.get("multi_match").and_then(Value::as_object) {
        let query_text = multi_match
            .get("query")
            .and_then(Value::as_str)
            .unwrap_or_default();
        let fields = extract_multi_match_fields(multi_match.get("fields"));
        if fields.is_empty() || fields.iter().any(|candidate| candidate == field) {
            terms.extend(tokenize_search_text(query_text));
        }
    }
    for query_name in ["query_string", "simple_query_string"] {
        if let Some(spec) = query.get(query_name).and_then(Value::as_object) {
            let query_text = spec
                .get("query")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let fields = spec
                .get("fields")
                .and_then(Value::as_array)
                .map(|items| items.iter().filter_map(Value::as_str).collect::<Vec<_>>())
                .unwrap_or_default();
            if fields.is_empty() || fields.iter().any(|candidate| *candidate == field) {
                terms.extend(tokenize_search_text(query_text));
            }
        }
    }
    if let Some(bool_query) = query.get("bool").and_then(Value::as_object) {
        for branch in ["must", "filter"] {
            if let Some(clauses) = bool_query.get(branch).and_then(Value::as_array) {
                for clause in clauses {
                    terms.extend(collect_highlight_terms(clause, field));
                }
            }
        }
    }
    if let Some(dis_max) = query.get("dis_max").and_then(Value::as_object) {
        if let Some(clauses) = dis_max.get("queries").and_then(Value::as_array) {
            for clause in clauses {
                terms.extend(collect_highlight_terms(clause, field));
            }
        }
    }
    let mut unique = BTreeSet::new();
    terms.retain(|term| unique.insert(term.clone()));
    terms
}

fn render_highlight_text(input: &str, terms: &[String], pre_tag: &str, post_tag: &str) -> String {
    let lowered_terms = terms
        .iter()
        .map(|term| term.to_ascii_lowercase())
        .collect::<BTreeSet<_>>();
    let mut rendered = String::new();
    let mut current = String::new();
    for ch in input.chars() {
        if ch.is_ascii_alphanumeric() {
            current.push(ch);
            continue;
        }
        if !current.is_empty() {
            let lowered = current.to_ascii_lowercase();
            if lowered_terms.contains(&lowered) {
                rendered.push_str(pre_tag);
                rendered.push_str(&current);
                rendered.push_str(post_tag);
            } else {
                rendered.push_str(&current);
            }
            current.clear();
        }
        rendered.push(ch);
    }
    if !current.is_empty() {
        let lowered = current.to_ascii_lowercase();
        if lowered_terms.contains(&lowered) {
            rendered.push_str(pre_tag);
            rendered.push_str(&current);
            rendered.push_str(post_tag);
        } else {
            rendered.push_str(&current);
        }
    }
    rendered
}

fn build_suggest_response_body(
    suggest: &Value,
    resolved_indices: &[String],
    docs: &DocumentMap,
) -> Value {
    let mut suggest_body = serde_json::Map::new();
    let Some(suggest_object) = suggest.as_object() else {
        return Value::Object(suggest_body);
    };
    for (name, entry) in suggest_object {
        let Some(entry_object) = entry.as_object() else {
            continue;
        };
        if let Some(term) = entry_object.get("term").and_then(Value::as_object) {
            let text = entry_object
                .get("text")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let field = term
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let size = term.get("size").and_then(Value::as_u64).unwrap_or(3) as usize;
            let candidates = collect_term_suggest_candidates(docs, resolved_indices, field);
            let options = build_term_suggest_options(text, &candidates, size);
            suggest_body.insert(
                name.clone(),
                serde_json::json!([{
                    "text": text,
                    "offset": 0,
                    "length": text.chars().count(),
                    "options": options
                }]),
            );
            continue;
        }
        if let Some(completion) = entry_object.get("completion").and_then(Value::as_object) {
            let prefix = entry_object
                .get("prefix")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let field = completion
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let size = completion.get("size").and_then(Value::as_u64).unwrap_or(5) as usize;
            let candidates = collect_completion_suggest_candidates(docs, resolved_indices, field);
            let options = build_completion_suggest_options(prefix, &candidates, size);
            suggest_body.insert(
                name.clone(),
                serde_json::json!([{
                    "text": prefix,
                    "offset": 0,
                    "length": prefix.chars().count(),
                    "options": options
                }]),
            );
            continue;
        }
        if let Some(phrase) = entry_object.get("phrase").and_then(Value::as_object) {
            let text = entry_object
                .get("text")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let field = phrase
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let candidates = collect_term_suggest_candidates(docs, resolved_indices, field);
            let options = build_phrase_suggest_options(text, &candidates);
            suggest_body.insert(
                name.clone(),
                serde_json::json!([{
                    "text": text,
                    "offset": 0,
                    "length": text.chars().count(),
                    "options": options
                }]),
            );
        }
    }
    Value::Object(suggest_body)
}

fn collect_term_suggest_candidates(
    docs: &DocumentMap,
    resolved_indices: &[String],
    field: &str,
) -> BTreeMap<String, u64> {
    let mut frequencies = BTreeMap::new();
    for (key, record) in docs {
        let Some((doc_index, _, _)) = split_document_key(key) else {
            continue;
        };
        if !resolved_indices
            .iter()
            .any(|candidate| candidate == doc_index)
        {
            continue;
        }
        let Some(value) = lookup_query_field_value(&record.source, field).and_then(Value::as_str)
        else {
            continue;
        };
        let normalized_value = value.trim().to_ascii_lowercase();
        if !normalized_value.is_empty() {
            *frequencies.entry(normalized_value).or_insert(0) += 1;
        }
        for token in tokenize_search_text(value) {
            *frequencies.entry(token).or_insert(0) += 1;
        }
    }
    frequencies
}

fn build_term_suggest_options(
    text: &str,
    candidates: &BTreeMap<String, u64>,
    size: usize,
) -> Vec<Value> {
    let lowered = text.to_ascii_lowercase();
    let mut ranked = candidates
        .iter()
        .filter_map(|(candidate, frequency)| {
            if candidate == &lowered {
                return None;
            }
            let distance = levenshtein_distance(candidate, &lowered);
            if distance > 2 {
                return None;
            }
            Some((candidate.clone(), *frequency, distance))
        })
        .collect::<Vec<_>>();
    ranked.sort_by(|left, right| {
        left.2
            .cmp(&right.2)
            .then_with(|| right.1.cmp(&left.1))
            .then_with(|| left.0.cmp(&right.0))
    });
    ranked
        .into_iter()
        .take(size)
        .map(|(candidate, frequency, distance)| {
            serde_json::json!({
                "text": candidate,
                "score": 1.0 / (distance.max(1) as f64),
                "freq": frequency
            })
        })
        .collect()
}

fn collect_completion_suggest_candidates(
    docs: &DocumentMap,
    resolved_indices: &[String],
    field: &str,
) -> BTreeMap<String, u64> {
    let mut frequencies = BTreeMap::new();
    for (key, record) in docs {
        let Some((doc_index, _, _)) = split_document_key(key) else {
            continue;
        };
        if !resolved_indices
            .iter()
            .any(|candidate| candidate == doc_index)
        {
            continue;
        }
        let Some(value) = lookup_query_field_value(&record.source, field) else {
            continue;
        };
        match value {
            Value::String(text) => {
                *frequencies.entry(text.to_ascii_lowercase()).or_insert(0) += 1;
            }
            Value::Array(items) => {
                for item in items.iter().filter_map(Value::as_str) {
                    *frequencies.entry(item.to_ascii_lowercase()).or_insert(0) += 1;
                }
            }
            _ => {}
        }
    }
    frequencies
}

fn build_completion_suggest_options(
    prefix: &str,
    candidates: &BTreeMap<String, u64>,
    size: usize,
) -> Vec<Value> {
    let lowered_prefix = prefix.to_ascii_lowercase();
    let mut ranked = candidates
        .iter()
        .filter(|(candidate, _)| candidate.starts_with(&lowered_prefix))
        .map(|(candidate, frequency)| (candidate.clone(), *frequency))
        .collect::<Vec<_>>();
    ranked.sort_by(|left, right| right.1.cmp(&left.1).then_with(|| left.0.cmp(&right.0)));
    let mut options = Vec::new();
    for (candidate, frequency) in ranked {
        for _ in 0..frequency {
            options.push(serde_json::json!({
                "text": candidate,
                "_score": 1.0
            }));
            if options.len() >= size {
                return options;
            }
        }
    }
    options
}

fn build_phrase_suggest_options(text: &str, candidates: &BTreeMap<String, u64>) -> Vec<Value> {
    let mut corrected_tokens = Vec::new();
    let mut changed = false;
    for token in tokenize_search_text(text) {
        if candidates.contains_key(&token) {
            corrected_tokens.push(token);
            continue;
        }
        if token.chars().count() < 3 {
            corrected_tokens.push(token);
            continue;
        }
        let mut ranked = candidates
            .iter()
            .map(|(candidate, frequency)| {
                (
                    candidate.clone(),
                    *frequency,
                    levenshtein_distance(candidate, &token),
                )
            })
            .filter(|(_, _, distance)| *distance <= 2)
            .collect::<Vec<_>>();
        ranked.sort_by(|left, right| {
            left.2
                .cmp(&right.2)
                .then_with(|| right.1.cmp(&left.1))
                .then_with(|| left.0.cmp(&right.0))
        });
        if let Some((candidate, _, _)) = ranked.into_iter().next() {
            corrected_tokens.push(candidate);
            changed = true;
        } else {
            corrected_tokens.push(token);
        }
    }
    if !changed || corrected_tokens.is_empty() {
        return Vec::new();
    }
    vec![serde_json::json!({
        "text": corrected_tokens.join(" "),
        "score": 1.0
    })]
}

fn score_match_query(candidate: Option<&Value>, expected: &str) -> f64 {
    let Some(candidate_text) = candidate.and_then(Value::as_str) else {
        return 0.0;
    };
    let haystack_tokens = candidate_text
        .split(|ch: char| !ch.is_alphanumeric())
        .filter(|token| !token.is_empty())
        .map(|token| token.to_ascii_lowercase())
        .collect::<Vec<_>>();
    let mut score = 0.0;
    for token in expected
        .split_whitespace()
        .map(|token| token.to_ascii_lowercase())
        .filter(|token| !token.is_empty())
    {
        if haystack_tokens.iter().any(|candidate| candidate == &token) {
            score += 1.0;
        }
    }
    score
}

fn evaluate_text_query_spec(
    source: &Value,
    query_spec: &serde_json::Map<String, Value>,
    simple_syntax: bool,
) -> (bool, f64) {
    let query_text = query_spec
        .get("query")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let default_operator = query_spec
        .get("default_operator")
        .and_then(Value::as_str)
        .unwrap_or("or");
    let fields = query_spec
        .get("fields")
        .and_then(Value::as_array)
        .map(|items| items.iter().filter_map(Value::as_str).collect::<Vec<_>>());
    let haystacks = collect_searchable_field_values(source, fields.as_deref());
    let minimum_should_match = query_spec.get("minimum_should_match");
    evaluate_text_query_strings(
        &haystacks,
        query_text,
        default_operator,
        simple_syntax,
        minimum_should_match,
    )
}

fn collect_searchable_field_values(source: &Value, fields: Option<&[&str]>) -> Vec<String> {
    let Some(source_object) = source.as_object() else {
        return Vec::new();
    };
    if let Some(fields) = fields {
        return fields
            .iter()
            .filter_map(|field| lookup_query_field_value(source, field))
            .flat_map(collect_string_leaf_values)
            .collect();
    }
    source_object
        .values()
        .flat_map(collect_string_leaf_values)
        .collect()
}

fn collect_string_leaf_values(value: &Value) -> Vec<String> {
    match value {
        Value::String(text) => vec![text.to_string()],
        Value::Array(items) => items.iter().flat_map(collect_string_leaf_values).collect(),
        Value::Object(object) => object
            .values()
            .flat_map(collect_string_leaf_values)
            .collect(),
        _ => Vec::new(),
    }
}

fn evaluate_text_query_strings(
    haystacks: &[String],
    query_text: &str,
    default_operator: &str,
    simple_syntax: bool,
    minimum_should_match: Option<&Value>,
) -> (bool, f64) {
    let explicit_or = if simple_syntax && query_text.contains('|') {
        Some(
            query_text
                .split('|')
                .map(str::trim)
                .filter(|part| !part.is_empty())
                .map(str::to_string)
                .collect::<Vec<_>>(),
        )
    } else if query_text.contains(" OR ") {
        Some(
            query_text
                .split(" OR ")
                .map(str::trim)
                .filter(|part| !part.is_empty())
                .map(str::to_string)
                .collect::<Vec<_>>(),
        )
    } else {
        None
    };
    if let Some(disjuncts) = explicit_or {
        let mut best_score: f64 = 0.0;
        let mut matched = false;
        for disjunct in disjuncts {
            let (disjunct_matched, disjunct_score) =
                evaluate_text_conjunction(haystacks, &split_query_terms(&disjunct));
            if disjunct_matched {
                matched = true;
                best_score = best_score.max(disjunct_score);
            }
        }
        return (matched, if matched { best_score.max(1.0) } else { 0.0 });
    }
    if query_text.contains(" AND ") || default_operator == "and" {
        return evaluate_text_conjunction(haystacks, &split_query_terms(query_text));
    }
    let terms = split_query_terms(query_text);
    let required = minimum_should_match
        .and_then(|value| bool_minimum_should_match_value(value, terms.len()))
        .unwrap_or(1);
    if required == 0 {
        return (true, 1.0);
    }
    let mut best_score: f64 = 0.0;
    let mut matched_terms = 0usize;
    for term in terms {
        let term_score = score_text_query_term(haystacks, &term);
        if term_score > 0.0 {
            matched_terms += 1;
            best_score = best_score.max(term_score);
        }
    }
    let matched = matched_terms >= required;
    (matched, if matched { best_score.max(1.0) } else { 0.0 })
}

fn split_query_terms(query_text: &str) -> Vec<String> {
    let mut terms = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut chars = query_text.chars().peekable();
    while let Some(ch) = chars.next() {
        match ch {
            '"' => {
                in_quotes = !in_quotes;
            }
            ' ' if !in_quotes => {
                if !current.is_empty() {
                    if current != "AND" && current != "OR" {
                        terms.push(std::mem::take(&mut current));
                    } else {
                        current.clear();
                    }
                }
                while chars.peek().is_some_and(|next| *next == ' ') {
                    chars.next();
                }
            }
            _ => current.push(ch),
        }
    }
    if !current.is_empty() && current != "AND" && current != "OR" {
        terms.push(current);
    }
    terms
}

fn evaluate_text_conjunction(haystacks: &[String], terms: &[String]) -> (bool, f64) {
    if terms.is_empty() {
        return (true, 1.0);
    }
    let mut score = 0.0;
    for term in terms {
        let term_score = score_text_query_term(haystacks, term);
        if term_score == 0.0 {
            return (false, 0.0);
        }
        score += term_score;
    }
    (true, score.max(1.0))
}

fn value_matches_match_bool_prefix(haystacks: &[String], query_text: &str) -> bool {
    let terms = split_query_terms(query_text);
    let Some((last, required)) = terms.split_last() else {
        return true;
    };
    if required
        .iter()
        .any(|term| score_text_query_term(haystacks, term) > 0.0)
    {
        return true;
    }
    let prefix = last.to_ascii_lowercase();
    haystacks.iter().any(|haystack| {
        haystack
            .split(|ch: char| !ch.is_alphanumeric())
            .filter(|token| !token.is_empty())
            .any(|token| token.to_ascii_lowercase().starts_with(&prefix))
    })
}

fn value_matches_multi_match_bool_prefix(
    haystacks: &[String],
    query_text: &str,
    operator: &str,
    minimum_should_match: Option<&Value>,
) -> bool {
    let terms = split_query_terms(query_text);
    let Some((last, exact_terms)) = terms.split_last() else {
        return true;
    };
    let matched_exact = exact_terms
        .iter()
        .filter(|term| score_text_query_term(haystacks, term) > 0.0)
        .count();
    let prefix = last.to_ascii_lowercase();
    let matched_prefix = usize::from(haystacks.iter().any(|haystack| {
        haystack
            .split(|ch: char| !ch.is_alphanumeric())
            .filter(|token| !token.is_empty())
            .any(|token| token.to_ascii_lowercase().starts_with(&prefix))
    }));
    let matched = matched_exact + matched_prefix;
    let required = minimum_should_match
        .and_then(|value| bool_minimum_should_match_value(value, terms.len()))
        .unwrap_or_else(|| {
            if operator.eq_ignore_ascii_case("and") {
                terms.len()
            } else {
                1
            }
        });
    matched >= required
}

fn value_matches_match_fuzzy(
    haystacks: &[String],
    query_text: &str,
    fuzziness: usize,
    prefix_length: usize,
    transpositions: bool,
    operator: &str,
    minimum_should_match: Option<&Value>,
) -> bool {
    let terms = split_query_terms(query_text);
    if terms.is_empty() {
        return false;
    }
    let matched = terms
        .iter()
        .filter(|term| {
            haystack_tokens_match_fuzzy(haystacks, term, fuzziness, prefix_length, transpositions)
        })
        .count();
    let required = minimum_should_match
        .and_then(|value| bool_minimum_should_match_value(value, terms.len()))
        .unwrap_or_else(|| {
            if operator.eq_ignore_ascii_case("and") {
                terms.len()
            } else {
                1
            }
        });
    matched >= required
}

fn haystack_tokens_match_fuzzy(
    haystacks: &[String],
    term: &str,
    fuzziness: usize,
    prefix_length: usize,
    transpositions: bool,
) -> bool {
    let expected = term.to_ascii_lowercase();
    haystacks.iter().any(|haystack| {
        tokenize_search_text(haystack).into_iter().any(|token| {
            fuzzy_token_matches(&token, &expected, fuzziness, prefix_length, transpositions)
        })
    })
}

fn score_text_query_term(haystacks: &[String], term: &str) -> f64 {
    let phrase = term.trim_matches('"');
    let is_phrase = term.contains(' ') || term.starts_with('"') || term.ends_with('"');
    let mut best_score: f64 = 0.0;
    for haystack in haystacks {
        let candidate = Value::String(haystack.clone());
        let score = if is_phrase {
            if value_matches_phrase(Some(&candidate), phrase, false, 0) {
                phrase.split_whitespace().count().max(1) as f64
            } else {
                0.0
            }
        } else {
            score_match_query(Some(&candidate), phrase)
        };
        best_score = best_score.max(score);
    }
    best_score
}

fn lookup_query_field_value<'a>(source: &'a Value, field: &str) -> Option<&'a Value> {
    if let Some(value) = source.get(field) {
        return Some(value);
    }
    let mut current = source;
    let mut traversed = false;
    let mut traversal_failed = false;
    for segment in field.split('.') {
        match current.get(segment) {
            Some(next) => {
                current = next;
                traversed = true;
            }
            None => {
                traversal_failed = true;
                break;
            }
        }
    }
    if traversed && !traversal_failed {
        return Some(current);
    }
    field.rsplit('.').next().and_then(|last| source.get(last))
}

fn evaluate_function_score_value(
    source: &Value,
    doc_id: &str,
    function_score: &serde_json::Map<String, Value>,
    mappings: &Value,
) -> Option<f64> {
    let mut values = Vec::new();
    if let Some(weight) = function_score.get("weight").and_then(finite_number_value) {
        values.push(weight);
    }
    if let Some(value) = function_score
        .get("field_value_factor")
        .and_then(|spec| evaluate_field_value_factor_score(source, spec))
    {
        values.push(value);
    }
    if let Some(random_score) = function_score.get("random_score") {
        values.push(evaluate_random_score(doc_id, random_score));
    }
    for decay_kind in ["gauss", "linear", "exp"] {
        if let Some(decay_score) = function_score
            .get(decay_kind)
            .and_then(|spec| evaluate_decay_score(source, decay_kind, spec))
        {
            values.push(decay_score);
        }
    }
    if let Some(functions) = function_score.get("functions").and_then(Value::as_array) {
        for function in functions {
            let Some(function) = function.as_object() else {
                continue;
            };
            if let Some(filter) = function.get("filter") {
                let (matched, _) =
                    evaluate_search_query_source_with_mappings(source, doc_id, filter, mappings)?;
                if !matched {
                    continue;
                }
            }
            if let Some(value) = evaluate_function_score_function(source, doc_id, function) {
                values.push(value);
            }
        }
    }
    if values.is_empty() {
        return Some(1.0);
    }
    let score_mode = function_score
        .get("score_mode")
        .and_then(Value::as_str)
        .unwrap_or("multiply");
    Some(combine_function_score_values(&values, score_mode))
}

fn evaluate_function_score_function(
    source: &Value,
    doc_id: &str,
    function: &serde_json::Map<String, Value>,
) -> Option<f64> {
    let mut value = function
        .get("weight")
        .and_then(finite_number_value)
        .unwrap_or(1.0);
    if let Some(field_score) = function
        .get("field_value_factor")
        .and_then(|spec| evaluate_field_value_factor_score(source, spec))
    {
        value *= field_score;
    }
    if let Some(random_score) = function.get("random_score") {
        value *= evaluate_random_score(doc_id, random_score);
    }
    for decay_kind in ["gauss", "linear", "exp"] {
        if let Some(decay_score) = function
            .get(decay_kind)
            .and_then(|spec| evaluate_decay_score(source, decay_kind, spec))
        {
            value *= decay_score;
        }
    }
    Some(value)
}

fn evaluate_field_value_factor_score(source: &Value, spec: &Value) -> Option<f64> {
    let spec = spec.as_object()?;
    let field = spec.get("field").and_then(Value::as_str)?;
    let factor = spec.get("factor").and_then(Value::as_f64).unwrap_or(1.0);
    let value = lookup_query_field_value(source, field)
        .and_then(numeric_score_value)
        .or_else(|| spec.get("missing").and_then(Value::as_f64))
        .unwrap_or(1.0);
    Some(value * factor)
}

fn numeric_score_value(value: &Value) -> Option<f64> {
    if let Some(number) = value.as_f64() {
        return Some(number);
    }
    value
        .as_array()
        .and_then(|values| values.iter().find_map(Value::as_f64))
}

fn evaluate_random_score(doc_id: &str, spec: &Value) -> f64 {
    let seed = spec
        .as_object()
        .and_then(|object| object.get("seed"))
        .map(canonical_random_seed)
        .unwrap_or_default();
    let hash = fnv1a64(&[doc_id.as_bytes(), seed.as_bytes()]);
    (hash as f64 / u64::MAX as f64).max(f64::MIN_POSITIVE)
}

fn evaluate_decay_score(source: &Value, decay_kind: &str, spec: &Value) -> Option<f64> {
    let object = spec.as_object()?;
    let mode = object
        .get("multi_value_mode")
        .and_then(Value::as_str)
        .unwrap_or("min");
    let (field, config) = object
        .iter()
        .find(|(key, _)| key.as_str() != "multi_value_mode")?;
    let config = config.as_object()?;
    let origin = config.get("origin").and_then(Value::as_f64)?;
    let scale = config.get("scale").and_then(Value::as_f64)?;
    if scale <= 0.0 {
        return None;
    }
    let offset = config
        .get("offset")
        .and_then(Value::as_f64)
        .unwrap_or(0.0)
        .max(0.0);
    let decay = config.get("decay").and_then(Value::as_f64).unwrap_or(0.5);
    if !(0.0..1.0).contains(&decay) {
        return None;
    }
    let field_values = numeric_score_values(lookup_query_field_value(source, field)?);
    let value = combine_numeric_values(&field_values, mode)?;
    let distance = (value - origin).abs();
    let distance = (distance - offset).max(0.0);
    let score = match decay_kind {
        "linear" => {
            let processed_scale = scale / (1.0 - decay);
            ((processed_scale - distance) / processed_scale).max(0.0)
        }
        "exp" => ((decay.ln() / scale) * distance).exp(),
        _ => (decay.ln() * (distance / scale).powi(2)).exp(),
    };
    Some(score)
}

fn numeric_score_values(value: &Value) -> Vec<f64> {
    if let Some(number) = value.as_f64() {
        return vec![number];
    }
    value
        .as_array()
        .map(|values| values.iter().filter_map(Value::as_f64).collect())
        .unwrap_or_default()
}

fn combine_numeric_values(values: &[f64], mode: &str) -> Option<f64> {
    if values.is_empty() {
        return None;
    }
    Some(match mode {
        "max" => values.iter().copied().fold(f64::MIN, f64::max),
        "avg" => values.iter().sum::<f64>() / values.len() as f64,
        "sum" => values.iter().sum(),
        _ => values.iter().copied().fold(f64::MAX, f64::min),
    })
}

fn canonical_random_seed(value: &Value) -> String {
    value
        .as_str()
        .map(str::to_string)
        .unwrap_or_else(|| value.to_string())
}

fn fnv1a64(parts: &[&[u8]]) -> u64 {
    let mut hash = 0xcbf29ce484222325u64;
    for part in parts {
        for byte in *part {
            hash ^= u64::from(*byte);
            hash = hash.wrapping_mul(0x100000001b3);
        }
        hash ^= 0xff;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    hash
}

fn combine_function_score_values(values: &[f64], score_mode: &str) -> f64 {
    match score_mode {
        "sum" => values.iter().sum(),
        "avg" => values.iter().sum::<f64>() / values.len() as f64,
        "max" => values.iter().copied().fold(f64::MIN, f64::max),
        "min" => values.iter().copied().fold(f64::MAX, f64::min),
        "first" => values.first().copied().unwrap_or(1.0),
        _ => values.iter().product(),
    }
}

fn combine_function_boost_score(query_score: f64, function_score: f64, boost_mode: &str) -> f64 {
    match boost_mode {
        "replace" => function_score,
        "sum" => query_score + function_score,
        "avg" => (query_score + function_score) / 2.0,
        "min" => query_score.min(function_score),
        "max" => query_score.max(function_score),
        _ => query_score * function_score,
    }
}

fn script_filter_source(script: &Value) -> Option<&str> {
    if let Some(source) = script.as_str() {
        return Some(source);
    }
    script
        .as_object()
        .and_then(|object| object.get("source"))
        .and_then(Value::as_str)
}

fn script_filter_source_is_supported(source: &str) -> bool {
    let source = source.trim();
    source == "true"
        || source == "false"
        || ["==", "!=", ">=", "<=", ">", "<"].iter().any(|operator| {
            source.split_once(operator).is_some_and(|(left, right)| {
                script_field_operand(left.trim()).is_some()
                    && parse_script_literal(right.trim()).is_some()
            })
        })
}

fn matches_script_filter_query(source: &Value, script: &Value) -> bool {
    let Some(script_source) = script_filter_source(script).map(str::trim) else {
        return false;
    };
    match script_source {
        "true" => return true,
        "false" => return false,
        _ => {}
    }

    for operator in ["==", "!=", ">=", "<=", ">", "<"] {
        let Some((left, right)) = script_source.split_once(operator) else {
            continue;
        };
        let Some(field) = script_field_operand(left.trim()) else {
            return false;
        };
        let Some(expected) = parse_script_literal(right.trim()) else {
            return false;
        };
        return lookup_query_field_value(source, field)
            .is_some_and(|actual| script_value_matches(actual, operator, &expected));
    }
    false
}

fn script_field_operand(operand: &str) -> Option<&str> {
    let operand = operand.strip_suffix(".value").unwrap_or(operand);
    script_bracket_operand(operand, "doc")
        .or_else(|| script_bracket_operand(operand, "params._source"))
}

fn script_bracket_operand<'a>(operand: &'a str, prefix: &str) -> Option<&'a str> {
    let rest = operand.strip_prefix(prefix)?.trim_start();
    let rest = rest.strip_prefix('[')?.trim_start();
    let quote = rest.chars().next()?;
    if quote != '\'' && quote != '"' {
        return None;
    }
    let rest = &rest[quote.len_utf8()..];
    let end = rest.find(quote)?;
    let field = &rest[..end];
    let tail = rest[end + quote.len_utf8()..].trim_start();
    if tail == "]" && !field.is_empty() {
        Some(field)
    } else {
        None
    }
}

fn parse_script_literal(value: &str) -> Option<Value> {
    let value = value.trim();
    if value.len() >= 2
        && ((value.starts_with('\'') && value.ends_with('\''))
            || (value.starts_with('"') && value.ends_with('"')))
    {
        return Some(Value::String(value[1..value.len() - 1].to_string()));
    }
    match value {
        "true" => return Some(Value::Bool(true)),
        "false" => return Some(Value::Bool(false)),
        "null" => return Some(Value::Null),
        _ => {}
    }
    value
        .parse::<f64>()
        .ok()
        .and_then(serde_json::Number::from_f64)
        .map(Value::Number)
}

fn script_value_matches(actual: &Value, operator: &str, expected: &Value) -> bool {
    if let Value::Array(items) = actual {
        return items
            .iter()
            .any(|item| script_value_matches(item, operator, expected));
    }

    match operator {
        "==" => compare_script_values(actual, expected).is_some_and(|ordering| ordering.is_eq()),
        "!=" => compare_script_values(actual, expected).is_some_and(|ordering| !ordering.is_eq()),
        ">" => compare_script_values(actual, expected).is_some_and(|ordering| ordering.is_gt()),
        ">=" => compare_script_values(actual, expected).is_some_and(|ordering| ordering.is_ge()),
        "<" => compare_script_values(actual, expected).is_some_and(|ordering| ordering.is_lt()),
        "<=" => compare_script_values(actual, expected).is_some_and(|ordering| ordering.is_le()),
        _ => false,
    }
}

fn compare_script_values(left: &Value, right: &Value) -> Option<std::cmp::Ordering> {
    match (left, right) {
        (Value::Number(left), Value::Number(right)) => left
            .as_f64()
            .zip(right.as_f64())
            .and_then(|(left, right)| left.partial_cmp(&right)),
        (Value::Bool(left), Value::Bool(right)) => Some(left.cmp(right)),
        (Value::String(left), Value::String(right)) => Some(left.cmp(right)),
        _ => None,
    }
}

fn extract_string_query_value(value: &Value) -> Option<&str> {
    if let Some(object) = value.as_object() {
        return object.get("value").and_then(Value::as_str);
    }
    value.as_str()
}

fn extract_term_query_value(value: &Value) -> Option<(&Value, bool)> {
    if let Some(object) = value.as_object() {
        return Some((
            object.get("value").or_else(|| object.get("term"))?,
            object
                .get("case_insensitive")
                .and_then(Value::as_bool)
                .unwrap_or(false),
        ));
    }
    Some((value, false))
}

fn extract_terms_query_field_values(
    terms: &serde_json::Map<String, Value>,
) -> Option<(&str, &Value)> {
    terms
        .iter()
        .find(|(key, _)| !matches!(key.as_str(), "boost" | "_name" | "value_type"))
        .map(|(field, value)| (field.as_str(), value))
}

fn extract_string_query_value_and_case_insensitive(value: &Value) -> Option<(&str, bool)> {
    if let Some(object) = value.as_object() {
        return Some((
            object
                .get("value")
                .or_else(|| object.get("wildcard"))
                .and_then(Value::as_str)?,
            object
                .get("case_insensitive")
                .and_then(Value::as_bool)
                .unwrap_or(false),
        ));
    }
    value.as_str().map(|text| (text, false))
}

fn extract_match_query_value(value: &Value) -> Option<&str> {
    if let Some(object) = value.as_object() {
        return object.get("query").and_then(Value::as_str);
    }
    value.as_str()
}

fn extract_match_query_operator(value: &Value) -> &str {
    value
        .as_object()
        .and_then(|object| object.get("operator"))
        .and_then(Value::as_str)
        .unwrap_or("or")
}

fn extract_match_query_analyzer(value: &Value) -> Option<&str> {
    value
        .as_object()
        .and_then(|object| object.get("analyzer"))
        .and_then(Value::as_str)
}

fn extract_match_minimum_should_match(value: &Value) -> Option<&Value> {
    value
        .as_object()
        .and_then(|object| object.get("minimum_should_match"))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct MatchFuzzyOptions {
    fuzziness: usize,
    prefix_length: usize,
    transpositions: bool,
}

fn extract_match_query_fuzzy_options(value: &Value, query_text: &str) -> Option<MatchFuzzyOptions> {
    let fuzziness = extract_match_query_fuzziness(value, query_text)?;
    let object = value.as_object()?;
    let prefix_length = object
        .get("prefix_length")
        .and_then(Value::as_u64)
        .map(|value| value as usize)
        .unwrap_or(0);
    let transpositions = object
        .get("fuzzy_transpositions")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    Some(MatchFuzzyOptions {
        fuzziness,
        prefix_length,
        transpositions,
    })
}

fn extract_match_query_fuzziness(value: &Value, query_text: &str) -> Option<usize> {
    let object = value.as_object()?;
    match object.get("fuzziness") {
        Some(Value::String(mode)) if mode.eq_ignore_ascii_case("AUTO") => {
            Some(auto_fuzziness(query_text))
        }
        Some(Value::String(value)) => value.parse::<usize>().ok(),
        Some(value) => value.as_u64().map(|value| value as usize),
        None => None,
    }
}

fn extract_zero_terms_query_all(value: &Value) -> bool {
    value
        .as_object()
        .and_then(|object| object.get("zero_terms_query"))
        .and_then(Value::as_str)
        .is_some_and(|value| value.eq_ignore_ascii_case("all"))
}

fn extract_multi_match_fields(value: Option<&Value>) -> Vec<String> {
    fn normalize(field: &str) -> String {
        field
            .split_once('^')
            .map_or(field, |(name, _)| name)
            .to_string()
    }

    match value {
        Some(Value::String(field)) => vec![normalize(field)],
        Some(Value::Array(fields)) => fields
            .iter()
            .filter_map(Value::as_str)
            .map(normalize)
            .collect(),
        _ => Vec::new(),
    }
}

fn extract_fuzzy_query_value(value: &Value) -> Option<(&str, MatchFuzzyOptions)> {
    if let Some(object) = value.as_object() {
        let query_value = object
            .get("value")
            .or_else(|| object.get("term"))
            .and_then(Value::as_str)?;
        let fuzziness = match object.get("fuzziness") {
            Some(Value::String(mode)) if mode.eq_ignore_ascii_case("AUTO") => {
                auto_fuzziness(query_value)
            }
            Some(Value::String(value)) => value.parse::<usize>().ok()?,
            Some(value) => value.as_u64()? as usize,
            None => auto_fuzziness(query_value),
        };
        let prefix_length = object
            .get("prefix_length")
            .and_then(Value::as_u64)
            .map(|value| value as usize)
            .unwrap_or(0);
        let transpositions = object
            .get("transpositions")
            .and_then(Value::as_bool)
            .unwrap_or(true);
        return Some((
            query_value,
            MatchFuzzyOptions {
                fuzziness,
                prefix_length,
                transpositions,
            },
        ));
    }
    let query_value = value.as_str()?;
    Some((
        query_value,
        MatchFuzzyOptions {
            fuzziness: auto_fuzziness(query_value),
            prefix_length: 0,
            transpositions: true,
        },
    ))
}

fn auto_fuzziness(query_value: &str) -> usize {
    match query_value.chars().count() {
        0..=2 => 0,
        3..=5 => 1,
        _ => 2,
    }
}

fn value_matches_phrase(
    candidate: Option<&Value>,
    expected: &str,
    prefix_last_token: bool,
    slop: usize,
) -> bool {
    value_matches_phrase_with_analyzer(candidate, expected, prefix_last_token, slop, None)
}

fn value_matches_phrase_with_analyzer(
    candidate: Option<&Value>,
    expected: &str,
    prefix_last_token: bool,
    slop: usize,
    analyzer: Option<&str>,
) -> bool {
    if analyzer.is_some_and(|value| value.eq_ignore_ascii_case("keyword")) {
        return value_matches_keyword_analyzed_phrase(candidate, expected, prefix_last_token);
    }
    let Some(candidate_text) = candidate.and_then(Value::as_str) else {
        return false;
    };
    let candidate_tokens = tokenize_search_text(candidate_text);
    let expected_tokens = tokenize_search_text(expected);
    if expected_tokens.is_empty() || candidate_tokens.len() < expected_tokens.len() {
        return false;
    }
    if prefix_last_token {
        return phrase_prefix_tokens_match_with_slop(&candidate_tokens, &expected_tokens, slop);
    }
    phrase_tokens_match_with_slop(&candidate_tokens, &expected_tokens, slop)
}

fn value_matches_keyword_analyzed_phrase(
    candidate: Option<&Value>,
    expected: &str,
    prefix_last_token: bool,
) -> bool {
    let Some(candidate_text) = candidate.and_then(Value::as_str) else {
        return false;
    };
    let expected = expected.to_ascii_lowercase();
    if expected.is_empty() {
        return false;
    }
    tokenize_search_text(candidate_text)
        .into_iter()
        .any(|token| {
            if prefix_last_token {
                token.starts_with(&expected)
            } else {
                token == expected
            }
        })
}

fn extract_match_phrase_slop(value: &Value) -> usize {
    value
        .as_object()
        .and_then(|object| object.get("slop"))
        .and_then(Value::as_u64)
        .and_then(|slop| usize::try_from(slop).ok())
        .unwrap_or(0)
}

fn phrase_tokens_match_with_slop(
    candidate_tokens: &[String],
    expected_tokens: &[String],
    slop: usize,
) -> bool {
    if slop == 0 {
        return candidate_tokens
            .windows(expected_tokens.len())
            .any(|window| window == expected_tokens);
    }

    fn visit(
        candidate_tokens: &[String],
        expected_tokens: &[String],
        candidate_start: usize,
        expected_index: usize,
        previous_position: Option<usize>,
        used_slop: usize,
        slop: usize,
    ) -> bool {
        if expected_index == expected_tokens.len() {
            return true;
        }
        for position in candidate_start..candidate_tokens.len() {
            if candidate_tokens[position] != expected_tokens[expected_index] {
                continue;
            }
            let extra_gap = previous_position
                .map(|previous| position.saturating_sub(previous + 1))
                .unwrap_or(0);
            let next_slop = used_slop.saturating_add(extra_gap);
            if next_slop > slop {
                continue;
            }
            if visit(
                candidate_tokens,
                expected_tokens,
                position + 1,
                expected_index + 1,
                Some(position),
                next_slop,
                slop,
            ) {
                return true;
            }
        }
        false
    }

    visit(candidate_tokens, expected_tokens, 0, 0, None, 0, slop)
}

fn phrase_prefix_tokens_match_with_slop(
    candidate_tokens: &[String],
    expected_tokens: &[String],
    slop: usize,
) -> bool {
    if slop == 0 {
        return candidate_tokens
            .windows(expected_tokens.len())
            .any(|window| phrase_prefix_window_matches(window, expected_tokens));
    }

    fn visit(
        candidate_tokens: &[String],
        expected_tokens: &[String],
        candidate_start: usize,
        expected_index: usize,
        previous_position: Option<usize>,
        used_slop: usize,
        slop: usize,
    ) -> bool {
        if expected_index == expected_tokens.len() {
            return true;
        }
        for position in candidate_start..candidate_tokens.len() {
            let is_last = expected_index + 1 == expected_tokens.len();
            let token_matches = if is_last {
                candidate_tokens[position].starts_with(&expected_tokens[expected_index])
            } else {
                candidate_tokens[position] == expected_tokens[expected_index]
            };
            if !token_matches {
                continue;
            }
            let extra_gap = previous_position
                .map(|previous| position.saturating_sub(previous + 1))
                .unwrap_or(0);
            let next_slop = used_slop.saturating_add(extra_gap);
            if next_slop > slop {
                continue;
            }
            if visit(
                candidate_tokens,
                expected_tokens,
                position + 1,
                expected_index + 1,
                Some(position),
                next_slop,
                slop,
            ) {
                return true;
            }
        }
        false
    }

    visit(candidate_tokens, expected_tokens, 0, 0, None, 0, slop)
}

fn phrase_prefix_window_matches(window: &[String], expected_tokens: &[String]) -> bool {
    window.iter().enumerate().all(|(index, candidate_token)| {
        let expected_token = &expected_tokens[index];
        if index + 1 == expected_tokens.len() {
            candidate_token.starts_with(expected_token)
        } else {
            candidate_token == expected_token
        }
    })
}

fn value_matches_wildcard(
    candidate: Option<&Value>,
    expected: &str,
    case_insensitive: bool,
) -> bool {
    let Some(candidate_text) = candidate.and_then(Value::as_str) else {
        return false;
    };
    if case_insensitive {
        wildcard_match(
            &expected.to_ascii_lowercase(),
            &candidate_text.to_ascii_lowercase(),
        )
    } else {
        wildcard_match(expected, candidate_text)
    }
}

fn value_matches_distance_feature(
    candidate: Option<&Value>,
    origin: &Value,
    pivot: &Value,
) -> bool {
    let pivot_valid = distance_feature_pivot_millis(origin, pivot)
        .or_else(|| distance_feature_numeric_pivot(origin, pivot))
        .is_some_and(|value| value.is_finite() && value > 0.0);
    if !pivot_valid {
        return false;
    }
    match candidate {
        Some(Value::Array(values)) => values
            .iter()
            .any(|value| value_matches_distance_feature(Some(value), origin, pivot)),
        Some(value) => distance_feature_distance(value, origin).is_some(),
        None => false,
    }
}

fn distance_feature_distance(candidate: &Value, origin: &Value) -> Option<f64> {
    if let Some((candidate, origin)) = candidate.as_f64().zip(origin.as_f64()) {
        return Some((candidate - origin).abs());
    }
    let candidate = parse_rfc3339_epoch_millis(candidate)?;
    let origin = parse_rfc3339_epoch_millis(origin)?;
    Some((candidate - origin).abs() as f64)
}

fn distance_feature_numeric_pivot(origin: &Value, pivot: &Value) -> Option<f64> {
    origin
        .as_f64()
        .and_then(|_| pivot.as_f64())
        .filter(|value| value.is_finite() && *value > 0.0)
}

fn distance_feature_pivot_millis(origin: &Value, pivot: &Value) -> Option<f64> {
    parse_rfc3339_epoch_millis(origin)?;
    match pivot {
        Value::Number(number) => number.as_f64(),
        Value::String(text) => parse_distance_feature_time_pivot_millis(text),
        _ => None,
    }
    .filter(|value| value.is_finite() && *value > 0.0)
}

fn parse_rfc3339_epoch_millis(value: &Value) -> Option<i128> {
    let text = value.as_str()?;
    let time = humantime::parse_rfc3339(text).ok()?;
    match time.duration_since(UNIX_EPOCH) {
        Ok(duration) => Some(duration.as_millis() as i128),
        Err(error) => Some(-(error.duration().as_millis() as i128)),
    }
}

fn parse_distance_feature_time_pivot_millis(text: &str) -> Option<f64> {
    let lower = text.trim().to_ascii_lowercase();
    let parse = |suffix: &str, multiplier: f64| {
        lower
            .strip_suffix(suffix)
            .and_then(|value| value.trim().parse::<f64>().ok())
            .map(|value| value * multiplier)
    };
    parse("ms", 1.0)
        .or_else(|| parse("s", 1_000.0))
        .or_else(|| parse("m", 60_000.0))
        .or_else(|| parse("h", 3_600_000.0))
        .or_else(|| parse("d", 86_400_000.0))
        .or_else(|| parse("w", 604_800_000.0))
}

fn value_matches_prefix(candidate: Option<&Value>, expected: &str, case_insensitive: bool) -> bool {
    let Some(candidate_text) = candidate.and_then(Value::as_str) else {
        return false;
    };
    if case_insensitive {
        candidate_text
            .to_ascii_lowercase()
            .starts_with(&expected.to_ascii_lowercase())
    } else {
        candidate_text.starts_with(expected)
    }
}

fn value_matches_regexp(candidate: Option<&Value>, expected: &str, case_insensitive: bool) -> bool {
    let Some(candidate_text) = candidate.and_then(Value::as_str) else {
        return false;
    };
    if case_insensitive {
        bounded_regexp_match(
            expected.to_ascii_lowercase().as_bytes(),
            candidate_text.to_ascii_lowercase().as_bytes(),
        )
    } else {
        bounded_regexp_match(expected.as_bytes(), candidate_text.as_bytes())
    }
}

fn bounded_regexp_match(pattern: &[u8], candidate: &[u8]) -> bool {
    fn recurse(pattern: &[u8], candidate: &[u8]) -> bool {
        if pattern.is_empty() {
            return candidate.is_empty();
        }
        let char_matches =
            !candidate.is_empty() && (pattern[0] == b'.' || pattern[0] == candidate[0]);
        if pattern.len() >= 2 && pattern[1] == b'*' {
            return recurse(&pattern[2..], candidate)
                || (char_matches && recurse(pattern, &candidate[1..]));
        }
        char_matches && recurse(&pattern[1..], &candidate[1..])
    }
    recurse(
        &pattern
            .iter()
            .map(u8::to_ascii_lowercase)
            .collect::<Vec<_>>(),
        candidate,
    )
}

fn value_matches_fuzzy(
    candidate: Option<&Value>,
    expected: &str,
    fuzziness: usize,
    prefix_length: usize,
    transpositions: bool,
) -> bool {
    let Some(candidate_text) = candidate.and_then(Value::as_str) else {
        return false;
    };
    let expected = expected.to_ascii_lowercase();
    tokenize_search_text(candidate_text)
        .into_iter()
        .any(|token| {
            fuzzy_token_matches(&token, &expected, fuzziness, prefix_length, transpositions)
        })
}

fn value_matches_terms_set(source: &Value, field: &str, expected: &Value) -> Option<(bool, f64)> {
    let candidate = lookup_query_field_value(source, field)?;
    let expected_object = expected.as_object()?;
    let terms = expected_object.get("terms")?.as_array()?;
    let minimum = terms_set_minimum_should_match(source, expected_object)?;
    let mut matched_terms = 0usize;
    for term in terms {
        let matched = match candidate {
            Value::Array(values) => values.iter().any(|value| value == term),
            _ => candidate == term,
        };
        if matched {
            matched_terms += 1;
        }
    }
    Some((
        matched_terms >= minimum,
        if matched_terms >= minimum {
            matched_terms.max(1) as f64
        } else {
            0.0
        },
    ))
}

fn rank_feature_score(
    candidate: Option<&Value>,
    rank_feature: Option<&serde_json::Map<String, Value>>,
) -> Option<f64> {
    let feature_value = match candidate? {
        Value::Number(number) => number
            .as_f64()
            .filter(|value| value.is_finite() && *value > 0.0),
        _ => None,
    }?;
    let score = match rank_feature {
        Some(spec) if spec.contains_key("linear") => feature_value,
        Some(spec) if spec.get("log").is_some() => {
            let scaling_factor = spec
                .get("log")
                .and_then(Value::as_object)
                .and_then(|log| log.get("scaling_factor"))
                .and_then(Value::as_f64)?;
            (scaling_factor + feature_value).ln()
        }
        Some(spec) if spec.get("sigmoid").is_some() => {
            let sigmoid = spec.get("sigmoid").and_then(Value::as_object)?;
            let pivot = sigmoid.get("pivot").and_then(Value::as_f64)?;
            let exponent = sigmoid.get("exponent").and_then(Value::as_f64)?;
            let feature_pow = feature_value.powf(exponent);
            let pivot_pow = pivot.powf(exponent);
            feature_pow / (feature_pow + pivot_pow)
        }
        Some(spec) => {
            let pivot = spec
                .get("saturation")
                .and_then(Value::as_object)
                .and_then(|saturation| saturation.get("pivot"))
                .and_then(Value::as_f64)
                .unwrap_or(1.0);
            feature_value / (feature_value + pivot)
        }
        None => feature_value,
    };
    score.is_finite().then_some(score)
}

fn neural_sparse_query_score(
    candidate: Option<&Value>,
    query_tokens: &serde_json::Map<String, Value>,
) -> f64 {
    let Some(candidate_tokens) = candidate.and_then(Value::as_object) else {
        return 0.0;
    };
    query_tokens
        .iter()
        .filter_map(|(token, query_weight)| {
            let query_weight = query_weight.as_f64()?;
            let candidate_weight = candidate_tokens.get(token)?.as_f64()?;
            let contribution = query_weight * candidate_weight;
            contribution.is_finite().then_some(contribution)
        })
        .sum::<f64>()
        .max(0.0)
}

fn valid_rank_feature_log(value: &Value) -> bool {
    let Some(object) = value.as_object() else {
        return false;
    };
    object.keys().all(|key| key == "scaling_factor")
        && object
            .get("scaling_factor")
            .and_then(Value::as_f64)
            .is_some_and(|number| number.is_finite() && number >= 0.0)
}

fn valid_rank_feature_saturation(value: &Value) -> bool {
    let Some(object) = value.as_object() else {
        return false;
    };
    object.keys().all(|key| key == "pivot")
        && object.get("pivot").map_or(true, |pivot| {
            pivot
                .as_f64()
                .is_some_and(|number| number.is_finite() && number >= 0.0)
        })
}

fn valid_rank_feature_sigmoid(value: &Value) -> bool {
    let Some(object) = value.as_object() else {
        return false;
    };
    object.keys().all(|key| key == "pivot" || key == "exponent")
        && object.get("pivot").is_some_and(|pivot| {
            pivot
                .as_f64()
                .is_some_and(|number| number.is_finite() && number >= 0.0)
        })
        && object.get("exponent").is_some_and(|exponent| {
            exponent
                .as_f64()
                .is_some_and(|number| number.is_finite() && number >= 0.0)
        })
}

fn valid_nested_score_mode(value: &Value) -> bool {
    matches!(value.as_str(), Some("none" | "min" | "max" | "avg" | "sum"))
}

fn combine_nested_scores(scores: &[f64], score_mode: &str) -> f64 {
    match score_mode {
        "none" => 0.0,
        "min" => scores
            .iter()
            .copied()
            .fold(f64::INFINITY, f64::min)
            .max(0.0),
        "max" => scores.iter().copied().fold(0.0_f64, f64::max),
        "sum" => scores.iter().sum::<f64>(),
        _ => scores.iter().sum::<f64>() / scores.len() as f64,
    }
}

fn terms_set_minimum_should_match(
    source: &Value,
    expected_object: &serde_json::Map<String, Value>,
) -> Option<usize> {
    if let Some(field) = expected_object
        .get("minimum_should_match_field")
        .and_then(Value::as_str)
    {
        let value = lookup_query_field_value(source, field)?;
        return value
            .as_u64()
            .or_else(|| {
                value
                    .as_i64()
                    .and_then(|value| if value < 0 { Some(0) } else { None })
            })
            .or_else(|| value.as_str().and_then(|value| value.parse::<u64>().ok()))
            .and_then(|value| usize::try_from(value).ok());
    }
    expected_object
        .get("minimum_should_match_script")
        .and_then(Value::as_object)
        .and_then(|script| script.get("source"))
        .and_then(|source| {
            source
                .as_u64()
                .or_else(|| source.as_str().and_then(|value| value.parse::<u64>().ok()))
        })
        .and_then(|value| usize::try_from(value).ok())
}

fn parse_distance_meters_with_unit(value: &Value, unit: Option<&Value>) -> Option<f64> {
    let multiplier = unit.map(distance_unit_multiplier).unwrap_or(Some(1.0))?;
    match value {
        Value::Number(number) => number
            .as_f64()
            .filter(|number| number.is_finite() && *number > 0.0)
            .map(|number| number * multiplier),
        Value::String(raw) => parse_distance_meters_text(raw, Some(multiplier)),
        _ => None,
    }
}

fn parse_distance_meters_text(raw: &str, unit_multiplier: Option<f64>) -> Option<f64> {
    let raw = raw.trim().to_ascii_lowercase();
    if let Some(value) = raw.strip_suffix("km") {
        return value.parse::<f64>().ok().map(|distance| distance * 1000.0);
    }
    if let Some(value) = raw.strip_suffix('m') {
        return value.parse::<f64>().ok();
    }
    raw.parse::<f64>()
        .ok()
        .filter(|number| number.is_finite() && *number > 0.0)
        .map(|number| number * unit_multiplier.unwrap_or(1.0))
}

fn distance_unit_multiplier(value: &Value) -> Option<f64> {
    match value.as_str()?.to_ascii_lowercase().as_str() {
        "m" | "meter" | "meters" => Some(1.0),
        "km" | "kilometer" | "kilometers" => Some(1000.0),
        _ => None,
    }
}

fn parse_geo_point_value(value: &Value) -> Option<(f64, f64)> {
    if let Some(object) = value.as_object() {
        return Some((object.get("lat")?.as_f64()?, object.get("lon")?.as_f64()?));
    }
    if let Some(value) = value.as_str() {
        let (lat, lon) = value.split_once(',')?;
        return Some((lat.trim().parse().ok()?, lon.trim().parse().ok()?));
    }
    let array = value.as_array()?;
    if array.len() != 2 {
        return None;
    }
    Some((array[1].as_f64()?, array[0].as_f64()?))
}

fn parse_geo_bounding_box_corners(
    box_object: &serde_json::Map<String, Value>,
) -> Option<((f64, f64), (f64, f64))> {
    if let Some(corners) = box_object
        .get("top_left")
        .and_then(parse_geo_point_value)
        .zip(
            box_object
                .get("bottom_right")
                .and_then(parse_geo_point_value),
        )
    {
        return Some(corners);
    }
    let (top, right) = box_object
        .get("top_right")
        .and_then(parse_geo_point_value)?;
    let (bottom, left) = box_object
        .get("bottom_left")
        .and_then(parse_geo_point_value)?;
    Some(((top, left), (bottom, right)))
}

fn lucene_geo_encode_latitude(latitude: f64) -> i32 {
    const LAT_DECODE: f64 = 4.190951585769653E-8;
    let latitude = if latitude == 90.0 {
        f64::from_bits(latitude.to_bits() - 1)
    } else {
        latitude
    };
    (latitude / LAT_DECODE).floor() as i32
}

fn lucene_geo_decode_latitude(encoded: i32) -> f64 {
    const LAT_DECODE: f64 = 4.190951585769653E-8;
    (encoded as f64) * LAT_DECODE
}

fn lucene_geo_encode_longitude(longitude: f64) -> i32 {
    const LON_DECODE: f64 = 8.381903171539307E-8;
    let longitude = if longitude == 180.0 {
        f64::from_bits(longitude.to_bits() - 1)
    } else {
        longitude
    };
    (longitude / LON_DECODE).floor() as i32
}

fn lucene_geo_decode_longitude(encoded: i32) -> f64 {
    const LON_DECODE: f64 = 8.381903171539307E-8;
    (encoded as f64) * LON_DECODE
}

fn geo_shape_value_is_supported(value: &Value) -> bool {
    geo_shape_point_value(value).is_some()
        || geo_shape_envelope_value(value).is_some()
        || geo_shape_polygon_value(value).is_some()
}

fn geo_shape_contains_point(shape: &Value, point: (f64, f64)) -> bool {
    if let Some(query_point) = geo_shape_point_value(shape) {
        return query_point == point;
    }
    if let Some((top_left, bottom_right)) = geo_shape_envelope_value(shape) {
        return geo_point_in_bounding_box(point, top_left, bottom_right);
    }
    if let Some(polygon) = geo_shape_polygon_value(shape) {
        return geo_point_in_polygon(point, &polygon);
    }
    false
}

fn geo_shape_field_point_value(value: &Value) -> Option<(f64, f64)> {
    if let Some(point) = parse_geo_point_value(value) {
        return Some(point);
    }
    let object = value.as_object()?;
    if !object
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|shape_type| shape_type.eq_ignore_ascii_case("point"))
    {
        return None;
    }
    parse_geo_point_value(object.get("coordinates")?)
}

fn geo_shape_point_value(shape: &Value) -> Option<(f64, f64)> {
    let object = shape.as_object()?;
    if !object
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|shape_type| shape_type.eq_ignore_ascii_case("point"))
    {
        return None;
    }
    parse_geo_point_value(object.get("coordinates")?)
}

fn geo_shape_envelope_value(shape: &Value) -> Option<((f64, f64), (f64, f64))> {
    let object = shape.as_object()?;
    if !object
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|shape_type| shape_type.eq_ignore_ascii_case("envelope"))
    {
        return None;
    }
    let coordinates = object.get("coordinates")?.as_array()?;
    if coordinates.len() != 2 {
        return None;
    }
    Some((
        parse_geo_point_value(&coordinates[0])?,
        parse_geo_point_value(&coordinates[1])?,
    ))
}

fn geo_shape_polygon_value(shape: &Value) -> Option<Vec<(f64, f64)>> {
    let object = shape.as_object()?;
    if !object
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|shape_type| shape_type.eq_ignore_ascii_case("polygon"))
    {
        return None;
    }
    let rings = object.get("coordinates")?.as_array()?;
    let first_ring = rings.first()?.as_array()?;
    let mut points = first_ring
        .iter()
        .map(parse_geo_point_value)
        .collect::<Option<Vec<_>>>()?;
    let already_closed = points.first() == points.last();
    if points.len() < 3 || (already_closed && points.len() < 4) {
        return None;
    }
    if !already_closed {
        if let Some(first) = points.first().copied() {
            points.push(first);
        }
    }
    Some(points)
}

fn geo_point_in_bounding_box(
    point: (f64, f64),
    top_left: (f64, f64),
    bottom_right: (f64, f64),
) -> bool {
    let lat_min = bottom_right.0.min(top_left.0);
    let lat_max = bottom_right.0.max(top_left.0);
    if point.0 < lat_min || point.0 > lat_max {
        return false;
    }
    let lon = normalize_geo_lon_f64(point.1);
    let left = normalize_geo_lon_f64(top_left.1);
    let right = normalize_geo_lon_f64(bottom_right.1);
    if left <= right {
        lon >= left && lon <= right
    } else {
        lon >= left || lon <= right
    }
}

fn normalize_geo_lon_f64(lon: f64) -> f64 {
    let mut normalized = lon;
    while normalized < -180.0 {
        normalized += 360.0;
    }
    while normalized > 180.0 {
        normalized -= 360.0;
    }
    normalized
}

fn geo_point_in_polygon(point: (f64, f64), polygon: &[(f64, f64)]) -> bool {
    if polygon.len() < 3 {
        return false;
    }
    let (lat, lon) = point;
    let mut inside = false;
    let mut previous = *polygon.last().expect("checked len");
    for &current in polygon {
        if point_on_polygon_segment(lat, lon, previous, current) {
            return true;
        }
        let intersects = ((current.0 > lat) != (previous.0 > lat))
            && (lon
                < (previous.1 - current.1) * (lat - current.0) / (previous.0 - current.0)
                    + current.1);
        if intersects {
            inside = !inside;
        }
        previous = current;
    }
    inside
}

fn point_on_polygon_segment(lat: f64, lon: f64, start: (f64, f64), end: (f64, f64)) -> bool {
    let cross = (lat - start.0) * (end.1 - start.1) - (lon - start.1) * (end.0 - start.0);
    if cross.abs() > 1.0e-9 {
        return false;
    }
    lat >= start.0.min(end.0)
        && lat <= start.0.max(end.0)
        && lon >= start.1.min(end.1)
        && lon <= start.1.max(end.1)
}

fn haversine_distance_meters(left: (f64, f64), right: (f64, f64)) -> f64 {
    let earth_radius_m = 6_371_000.0_f64;
    let (left_lat, left_lon) = (left.0.to_radians(), left.1.to_radians());
    let (right_lat, right_lon) = (right.0.to_radians(), right.1.to_radians());
    let delta_lat = right_lat - left_lat;
    let delta_lon = right_lon - left_lon;
    let a = (delta_lat / 2.0).sin().powi(2)
        + left_lat.cos() * right_lat.cos() * (delta_lon / 2.0).sin().powi(2);
    let c = 2.0 * a.sqrt().atan2((1.0 - a).sqrt());
    earth_radius_m * c
}

fn levenshtein_distance(left: &str, right: &str) -> usize {
    let left_chars = left.chars().collect::<Vec<_>>();
    let right_chars = right.chars().collect::<Vec<_>>();
    let mut prev = (0..=right_chars.len()).collect::<Vec<_>>();
    let mut curr = vec![0; right_chars.len() + 1];
    for (i, left_char) in left_chars.iter().enumerate() {
        curr[0] = i + 1;
        for (j, right_char) in right_chars.iter().enumerate() {
            let cost = usize::from(left_char != right_char);
            curr[j + 1] = (curr[j] + 1).min(prev[j + 1] + 1).min(prev[j] + cost);
        }
        std::mem::swap(&mut prev, &mut curr);
    }
    prev[right_chars.len()]
}

fn fuzzy_token_matches(
    candidate: &str,
    query: &str,
    fuzziness: usize,
    prefix_length: usize,
    transpositions: bool,
) -> bool {
    let candidate_chars = candidate.chars().collect::<Vec<_>>();
    let query_chars = query.chars().collect::<Vec<_>>();
    if prefix_length > candidate_chars.len() || prefix_length > query_chars.len() {
        return false;
    }
    if candidate_chars[..prefix_length] != query_chars[..prefix_length] {
        return false;
    }
    let candidate_suffix = &candidate_chars[prefix_length..];
    let query_suffix = &query_chars[prefix_length..];
    let distance = if transpositions {
        optimal_string_alignment_distance(candidate_suffix, query_suffix)
    } else {
        levenshtein_distance_chars(candidate_suffix, query_suffix)
    };
    distance <= fuzziness
}

fn levenshtein_distance_chars(left: &[char], right: &[char]) -> usize {
    let mut prev = (0..=right.len()).collect::<Vec<_>>();
    let mut curr = vec![0; right.len() + 1];
    for (i, left_char) in left.iter().enumerate() {
        curr[0] = i + 1;
        for (j, right_char) in right.iter().enumerate() {
            let cost = usize::from(left_char != right_char);
            curr[j + 1] = (curr[j] + 1).min(prev[j + 1] + 1).min(prev[j] + cost);
        }
        std::mem::swap(&mut prev, &mut curr);
    }
    prev[right.len()]
}

fn optimal_string_alignment_distance(left: &[char], right: &[char]) -> usize {
    let mut dp = vec![vec![0; right.len() + 1]; left.len() + 1];
    for (i, row) in dp.iter_mut().enumerate() {
        row[0] = i;
    }
    for j in 0..=right.len() {
        dp[0][j] = j;
    }
    for i in 1..=left.len() {
        for j in 1..=right.len() {
            let substitution_cost = usize::from(left[i - 1] != right[j - 1]);
            let mut distance = (dp[i - 1][j] + 1)
                .min(dp[i][j - 1] + 1)
                .min(dp[i - 1][j - 1] + substitution_cost);
            if i > 1 && j > 1 && left[i - 1] == right[j - 2] && left[i - 2] == right[j - 1] {
                distance = distance.min(dp[i - 2][j - 2] + 1);
            }
            dp[i][j] = distance;
        }
    }
    dp[left.len()][right.len()]
}

fn evaluate_span_query(source: &Value, span_term: &serde_json::Map<String, Value>) -> Option<bool> {
    let (field, expected) = span_term.iter().next()?;
    Some(value_matches_term(
        lookup_query_field_value(source, field),
        expected,
        None,
        false,
    ))
}

fn evaluate_span_or_query(
    source: &Value,
    span_or: &serde_json::Map<String, Value>,
) -> Option<bool> {
    let clauses = span_or.get("clauses")?.as_array()?;
    for clause in clauses {
        if evaluate_span_like_clause(source, clause)? {
            return Some(true);
        }
    }
    Some(false)
}

fn evaluate_span_first_query(
    source: &Value,
    span_first: &serde_json::Map<String, Value>,
) -> Option<bool> {
    let end = span_first.get("end")?.as_u64()? as usize;
    if end == 0 {
        return Some(false);
    }
    let match_query = span_first.get("match")?.as_object()?;
    if let Some(span_term) = match_query.get("span_term").and_then(Value::as_object) {
        let (field, expected) = span_term.iter().next()?;
        return Some(span_first_term_matches(
            lookup_query_field_value(source, field)?,
            expected,
            end,
        ));
    }
    if let Some(span_or) = match_query.get("span_or").and_then(Value::as_object) {
        let clauses = span_or.get("clauses")?.as_array()?;
        for clause in clauses {
            if evaluate_span_first_query(
                source,
                &serde_json::Map::from_iter([
                    ("match".to_string(), clause.clone()),
                    ("end".to_string(), Value::from(end as u64)),
                ]),
            )? {
                return Some(true);
            }
        }
        return Some(false);
    }
    if let Some(span_multi) = match_query.get("span_multi").and_then(Value::as_object) {
        let (field, terms) = extract_span_multi_terms(source, span_multi)?;
        let tokens = tokenize_search_text(lookup_query_field_value(source, &field)?.as_str()?);
        return Some(
            tokens
                .iter()
                .take(end)
                .any(|token| terms.iter().any(|term| term == token)),
        );
    }
    None
}

fn span_first_term_matches(field_value: &Value, expected: &Value, end: usize) -> bool {
    match (field_value, expected) {
        (Value::Array(items), expected) => items
            .iter()
            .any(|item| span_first_term_matches(item, expected, end)),
        (Value::String(field_text), Value::String(term_text)) => {
            let expected = term_text.to_ascii_lowercase();
            tokenize_search_text(field_text)
                .iter()
                .take(end)
                .any(|token| token == &expected)
        }
        _ => value_matches_term(Some(field_value), expected, None, false),
    }
}

fn evaluate_span_not_query(
    source: &Value,
    span_not: &serde_json::Map<String, Value>,
) -> Option<bool> {
    let include = span_not.get("include")?;
    let exclude = span_not.get("exclude")?;
    let (pre, post) = span_not_distance_window(span_not);
    let include_ranges = span_query_position_ranges(source, include)?;
    if include_ranges.ranges.is_empty() {
        return Some(false);
    }
    let Some(exclude_ranges) = span_query_position_ranges(source, exclude) else {
        return Some(true);
    };
    if include_ranges.field != exclude_ranges.field {
        return Some(true);
    }
    Some(include_ranges.ranges.iter().any(|include_range| {
        !exclude_ranges.ranges.iter().any(|exclude_range| {
            span_ranges_overlap_with_window(include_range, exclude_range, pre, post)
        })
    }))
}

fn span_not_distance_window(span_not: &serde_json::Map<String, Value>) -> (usize, usize) {
    if let Some(distance) = span_not.get("dist").and_then(Value::as_u64) {
        let distance = distance as usize;
        return (distance, distance);
    }
    (
        span_not.get("pre").and_then(Value::as_u64).unwrap_or(0) as usize,
        span_not.get("post").and_then(Value::as_u64).unwrap_or(0) as usize,
    )
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct RuntimeSpanRanges {
    field: String,
    ranges: Vec<(usize, usize)>,
}

fn span_ranges_overlap_with_window(
    include: &(usize, usize),
    exclude: &(usize, usize),
    pre: usize,
    post: usize,
) -> bool {
    let include_start = include.0.saturating_sub(pre);
    let include_end = include.1.saturating_add(post);
    exclude.0 <= include_end && exclude.1 >= include_start
}

fn evaluate_span_containing_query(
    source: &Value,
    span_containing: &serde_json::Map<String, Value>,
) -> Option<bool> {
    let big = span_containing.get("big")?;
    let little = span_containing.get("little")?;
    let big_ranges = span_query_position_ranges(source, big)?;
    let little_ranges = span_query_position_ranges(source, little)?;
    if big_ranges.field != little_ranges.field {
        return Some(false);
    }
    Some(little_ranges.ranges.iter().any(|little_range| {
        big_ranges
            .ranges
            .iter()
            .any(|big_range| span_range_contains(big_range, little_range))
    }))
}

fn span_range_contains(big: &(usize, usize), little: &(usize, usize)) -> bool {
    big.0 <= little.0 && big.1 >= little.1
}

fn span_query_position_ranges(source: &Value, query: &Value) -> Option<RuntimeSpanRanges> {
    let object = query.as_object()?;
    if let Some(span_term) = object.get("span_term").and_then(Value::as_object) {
        let (field, expected) = span_term.iter().next()?;
        let token = expected.as_str()?.to_ascii_lowercase();
        let tokens = tokenize_search_text(lookup_query_field_value(source, field)?.as_str()?);
        let ranges = tokens
            .iter()
            .enumerate()
            .filter_map(|(index, candidate)| (candidate == &token).then_some((index, index)))
            .collect::<Vec<_>>();
        return Some(RuntimeSpanRanges {
            field: field.clone(),
            ranges,
        });
    }
    if let Some(span_first) = object.get("span_first").and_then(Value::as_object) {
        let match_query = span_first.get("match")?;
        let end = span_first.get("end")?.as_u64()? as usize;
        let mut ranges = span_query_position_ranges(source, match_query)?;
        ranges.ranges.retain(|(_, range_end)| *range_end < end);
        return Some(ranges);
    }
    if let Some(span_or) = object.get("span_or").and_then(Value::as_object) {
        let clauses = span_or.get("clauses")?.as_array()?;
        let mut output: Option<RuntimeSpanRanges> = None;
        for clause in clauses {
            let ranges = span_query_position_ranges(source, clause)?;
            match output.as_mut() {
                Some(existing) if existing.field == ranges.field => {
                    existing.ranges.extend(ranges.ranges);
                }
                Some(_) => return None,
                None => output = Some(ranges),
            }
        }
        if let Some(existing) = output.as_mut() {
            existing.ranges.sort_unstable();
            existing.ranges.dedup();
        }
        return output;
    }
    if let Some(span_near) = object.get("span_near").and_then(Value::as_object) {
        return span_near_position_ranges(source, span_near);
    }
    if let Some(field_masking_span) = field_masking_span_query_object(query) {
        let mask_field = field_masking_span.get("field")?.as_str()?.to_string();
        let inner = field_masking_span.get("query")?;
        let mut ranges = span_query_position_ranges(source, inner)?;
        ranges.field = mask_field;
        return Some(ranges);
    }
    None
}

fn span_near_position_ranges(
    source: &Value,
    span_near: &serde_json::Map<String, Value>,
) -> Option<RuntimeSpanRanges> {
    let clauses = span_near.get("clauses")?.as_array()?;
    let slop = span_near.get("slop")?.as_u64()? as usize;
    let in_order = span_near.get("in_order")?.as_bool()?;
    if !in_order {
        return None;
    }
    let mut extracted = Vec::new();
    for clause in clauses {
        extracted.push(extract_span_clause(source, clause)?);
    }
    let field = extracted.first()?.0.clone();
    if extracted
        .iter()
        .any(|(candidate_field, _)| *candidate_field != field)
    {
        return Some(RuntimeSpanRanges {
            field,
            ranges: Vec::new(),
        });
    }
    let tokens = tokenize_search_text(lookup_query_field_value(source, &field)?.as_str()?);
    let specs = extracted
        .into_iter()
        .map(|(_, values)| values)
        .collect::<Vec<_>>();
    let Some((first_terms, rest)) = first_span_near_term_clause(&specs) else {
        return Some(RuntimeSpanRanges {
            field,
            ranges: Vec::new(),
        });
    };
    let mut ranges = Vec::new();
    for start_position in 0..tokens.len() {
        if !first_terms
            .iter()
            .any(|term| term == &tokens[start_position])
        {
            continue;
        }
        let mut previous_position = start_position;
        let mut matched = true;
        for spec in rest {
            match spec {
                RuntimeSpanClause::Gap(width) => {
                    previous_position = previous_position.saturating_add(*width);
                    if previous_position >= tokens.len() {
                        matched = false;
                        break;
                    }
                }
                RuntimeSpanClause::Terms(accepted_terms) => {
                    let start = previous_position + 1;
                    let mut matched_position = None;
                    for (index, token) in tokens.iter().enumerate().skip(start) {
                        if accepted_terms.iter().any(|term| term == token) {
                            matched_position = Some(index);
                            break;
                        }
                    }
                    let Some(position) = matched_position else {
                        matched = false;
                        break;
                    };
                    let gap = position.saturating_sub(previous_position + 1);
                    if gap > slop {
                        matched = false;
                        break;
                    }
                    previous_position = position;
                }
            }
        }
        if matched {
            ranges.push((start_position, previous_position));
        }
    }
    Some(RuntimeSpanRanges { field, ranges })
}

fn evaluate_span_near_query(
    source: &Value,
    span_near: &serde_json::Map<String, Value>,
) -> Option<bool> {
    let clauses = span_near.get("clauses")?.as_array()?;
    let slop = span_near.get("slop")?.as_u64()? as usize;
    let in_order = span_near.get("in_order")?.as_bool()?;
    let mut extracted = Vec::new();
    for clause in clauses {
        extracted.push(extract_span_clause(source, clause)?);
    }
    let field = extracted.first()?.0.clone();
    if extracted
        .iter()
        .any(|(candidate_field, _)| *candidate_field != field)
    {
        return Some(false);
    }
    let tokens = tokenize_search_text(lookup_query_field_value(source, &field)?.as_str()?);
    if tokens.is_empty() {
        return Some(false);
    }
    let specs = extracted
        .into_iter()
        .map(|(_, values)| values)
        .collect::<Vec<_>>();
    if in_order {
        let Some((first_terms, rest)) = first_span_near_term_clause(&specs) else {
            return Some(false);
        };
        for start_position in 0..tokens.len() {
            if !first_terms
                .iter()
                .any(|term| term == &tokens[start_position])
            {
                continue;
            }
            let mut previous_position = start_position;
            let mut matched = true;
            for spec in rest {
                match spec {
                    RuntimeSpanClause::Gap(width) => {
                        previous_position = previous_position.saturating_add(*width);
                        if previous_position >= tokens.len() {
                            matched = false;
                            break;
                        }
                    }
                    RuntimeSpanClause::Terms(accepted_terms) => {
                        let start = previous_position + 1;
                        let mut matched_position = None;
                        for (index, token) in tokens.iter().enumerate().skip(start) {
                            if accepted_terms.iter().any(|term| term == token) {
                                matched_position = Some(index);
                                break;
                            }
                        }
                        let Some(position) = matched_position else {
                            matched = false;
                            break;
                        };
                        let gap = position.saturating_sub(previous_position + 1);
                        if gap > slop {
                            matched = false;
                            break;
                        }
                        previous_position = position;
                    }
                }
            }
            if matched {
                return Some(true);
            }
        }
        return Some(false);
    }
    if specs
        .iter()
        .any(|spec| matches!(spec, RuntimeSpanClause::Gap(_)))
    {
        return Some(false);
    }
    for accepted_terms in specs.iter().filter_map(|spec| match spec {
        RuntimeSpanClause::Terms(terms) => Some(terms),
        RuntimeSpanClause::Gap(_) => None,
    }) {
        if !tokens
            .iter()
            .any(|token| accepted_terms.iter().any(|term| term == token))
        {
            return Some(false);
        }
    }
    Some(true)
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum RuntimeSpanClause {
    Terms(Vec<String>),
    Gap(usize),
}

fn first_span_near_term_clause(
    specs: &[RuntimeSpanClause],
) -> Option<(&[String], &[RuntimeSpanClause])> {
    let mut first_index = None;
    for (index, spec) in specs.iter().enumerate() {
        if matches!(spec, RuntimeSpanClause::Terms(_)) {
            first_index = Some(index);
            break;
        }
    }
    let first_index = first_index?;
    let RuntimeSpanClause::Terms(terms) = &specs[first_index] else {
        return None;
    };
    Some((terms.as_slice(), &specs[(first_index + 1)..]))
}

fn evaluate_span_multi_query(
    source: &Value,
    span_multi: &serde_json::Map<String, Value>,
) -> Option<bool> {
    let inner = span_multi.get("match")?;
    if let Some(prefix_query) = inner.get("prefix").and_then(Value::as_object) {
        let (field, expected) = prefix_query.iter().next()?;
        let expected_value = extract_string_query_value(expected)?;
        return Some(value_matches_prefix(
            lookup_query_field_value(source, field),
            expected_value,
            false,
        ));
    }
    None
}

fn evaluate_field_masking_span_query(
    source: &Value,
    field_masking_span: &serde_json::Map<String, Value>,
) -> Option<bool> {
    let inner = field_masking_span.get("query")?;
    let Value::Object(inner_object) = inner else {
        return None;
    };
    if let Some(span_term) = inner_object.get("span_term").and_then(Value::as_object) {
        let (inner_field, expected) = span_term.iter().next()?;
        return Some(value_matches_term(
            lookup_query_field_value(source, inner_field),
            expected,
            None,
            false,
        ));
    }
    None
}

fn field_masking_span_query_object(query: &Value) -> Option<&serde_json::Map<String, Value>> {
    query
        .get("span_field_masking")
        .or_else(|| query.get("field_masking_span"))
        .and_then(Value::as_object)
}

fn evaluate_span_like_clause(source: &Value, clause: &Value) -> Option<bool> {
    let object = clause.as_object()?;
    if let Some(span_term) = object.get("span_term").and_then(Value::as_object) {
        return evaluate_span_query(source, span_term);
    }
    if let Some(span_multi) = object.get("span_multi").and_then(Value::as_object) {
        return evaluate_span_multi_query(source, span_multi);
    }
    if let Some(span_first) = object.get("span_first").and_then(Value::as_object) {
        return evaluate_span_first_query(source, span_first);
    }
    if let Some(span_not) = object.get("span_not").and_then(Value::as_object) {
        return evaluate_span_not_query(source, span_not);
    }
    if let Some(span_containing) = object.get("span_containing").and_then(Value::as_object) {
        return evaluate_span_containing_query(source, span_containing);
    }
    if let Some(span_within) = object.get("span_within").and_then(Value::as_object) {
        return evaluate_span_containing_query(source, span_within);
    }
    if let Some(field_masking_span) = field_masking_span_query_object(clause) {
        return evaluate_field_masking_span_query(source, field_masking_span);
    }
    None
}

fn extract_span_clause(source: &Value, clause: &Value) -> Option<(String, RuntimeSpanClause)> {
    let object = clause.as_object()?;
    if let Some(span_term) = object.get("span_term").and_then(Value::as_object) {
        let (field, expected) = span_term.iter().next()?;
        return Some((
            field.clone(),
            RuntimeSpanClause::Terms(vec![expected.as_str()?.to_ascii_lowercase()]),
        ));
    }
    if let Some(span_gap) = object.get("span_gap").and_then(Value::as_object) {
        let (field, width) = span_gap.iter().next()?;
        return Some((
            field.clone(),
            RuntimeSpanClause::Gap(width.as_u64()? as usize),
        ));
    }
    if let Some(span_multi) = object.get("span_multi").and_then(Value::as_object) {
        let (field, accepted) = extract_span_multi_terms(source, span_multi)?;
        return Some((field.clone(), RuntimeSpanClause::Terms(accepted)));
    }
    None
}

fn extract_span_multi_terms(
    source: &Value,
    span_multi: &serde_json::Map<String, Value>,
) -> Option<(String, Vec<String>)> {
    let inner = span_multi.get("match")?;
    let prefix_query = inner.get("prefix").and_then(Value::as_object)?;
    let (field, expected) = prefix_query.iter().next()?;
    let expected_value = extract_string_query_value(expected)?.to_ascii_lowercase();
    let tokens = tokenize_search_text(lookup_query_field_value(source, field)?.as_str()?);
    let accepted = tokens
        .into_iter()
        .filter(|token| token.starts_with(&expected_value))
        .collect::<Vec<_>>();
    Some((field.clone(), accepted))
}

fn evaluate_intervals_query(source: &Value, query_field: &str, spec: &Value) -> Option<bool> {
    return interval_matching_spans(source, query_field, spec).map(|spans| !spans.is_empty());
}

fn interval_max_expansions_overflow_reason_for_sources(
    query: &Value,
    sources: &[&Value],
) -> Option<String> {
    if query.is_null() {
        return None;
    }
    if let Some(intervals) = query.get("intervals").and_then(Value::as_object) {
        let (field, spec) = intervals.iter().next()?;
        return interval_spec_max_expansions_overflow_reason(field, spec, sources);
    }
    if let Some(bool_query) = query.get("bool").and_then(Value::as_object) {
        for key in ["must", "should", "filter", "must_not"] {
            if let Some(reason) =
                interval_query_value_max_expansions_overflow_reason(bool_query.get(key), sources)
            {
                return Some(reason);
            }
        }
    }
    if let Some(constant_score) = query.get("constant_score").and_then(Value::as_object) {
        if let Some(reason) = interval_query_value_max_expansions_overflow_reason(
            constant_score.get("filter"),
            sources,
        ) {
            return Some(reason);
        }
    }
    if let Some(function_score) = query.get("function_score").and_then(Value::as_object) {
        if let Some(reason) = interval_query_value_max_expansions_overflow_reason(
            function_score.get("query"),
            sources,
        ) {
            return Some(reason);
        }
    }
    if let Some(dis_max) = query.get("dis_max").and_then(Value::as_object) {
        if let Some(reason) =
            interval_query_value_max_expansions_overflow_reason(dis_max.get("queries"), sources)
        {
            return Some(reason);
        }
    }
    if let Some(boosting) = query.get("boosting").and_then(Value::as_object) {
        for key in ["positive", "negative"] {
            if let Some(reason) =
                interval_query_value_max_expansions_overflow_reason(boosting.get(key), sources)
            {
                return Some(reason);
            }
        }
    }
    if let Some(nested) = query.get("nested").and_then(Value::as_object) {
        if let Some(reason) =
            interval_query_value_max_expansions_overflow_reason(nested.get("query"), sources)
        {
            return Some(reason);
        }
    }
    None
}

fn interval_query_value_max_expansions_overflow_reason(
    query_value: Option<&Value>,
    sources: &[&Value],
) -> Option<String> {
    match query_value {
        Some(Value::Array(queries)) => queries
            .iter()
            .find_map(|query| interval_max_expansions_overflow_reason_for_sources(query, sources)),
        Some(query) => interval_max_expansions_overflow_reason_for_sources(query, sources),
        None => None,
    }
}

fn interval_spec_max_expansions_overflow_reason(
    query_field: &str,
    spec: &Value,
    sources: &[&Value],
) -> Option<String> {
    let interval_object = spec.as_object()?;
    if let Some(wildcard_spec) = interval_object.get("wildcard").and_then(Value::as_object) {
        let max_expansions = interval_max_expansions(wildcard_spec)?;
        let pattern = wildcard_spec.get("pattern")?.as_str()?.to_ascii_lowercase();
        let expanded = interval_expanded_terms_for_sources(
            sources,
            query_field,
            wildcard_spec,
            interval_wildcard_candidate_tokens,
            |token| wildcard_match(&pattern, token),
        );
        if expanded.len() > max_expansions {
            return Some(format!(
                "Automaton [{pattern}] expanded to too many terms (limit {max_expansions})"
            ));
        }
    }
    if let Some(regexp_spec) = interval_object.get("regexp").and_then(Value::as_object) {
        let max_expansions = interval_max_expansions(regexp_spec)?;
        let pattern = regexp_spec.get("pattern")?.as_str()?;
        let case_insensitive = regexp_spec
            .get("case_insensitive")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let expanded = interval_expanded_terms_for_sources(
            sources,
            query_field,
            regexp_spec,
            interval_regexp_candidate_tokens,
            |token| interval_regexp_token_matches(pattern, token, case_insensitive),
        );
        if expanded.len() > max_expansions {
            return Some(format!(
                "Automaton [{pattern}] expanded to too many terms (limit {max_expansions})"
            ));
        }
    }
    if let Some(all_of) = interval_object.get("all_of").and_then(Value::as_object) {
        if let Some(reason) =
            interval_composite_max_expansions_overflow_reason(query_field, all_of, sources)
        {
            return Some(reason);
        }
    }
    if let Some(any_of) = interval_object.get("any_of").and_then(Value::as_object) {
        if let Some(reason) =
            interval_composite_max_expansions_overflow_reason(query_field, any_of, sources)
        {
            return Some(reason);
        }
    }
    None
}

fn interval_composite_max_expansions_overflow_reason(
    query_field: &str,
    composite: &serde_json::Map<String, Value>,
    sources: &[&Value],
) -> Option<String> {
    composite
        .get("intervals")
        .and_then(Value::as_array)?
        .iter()
        .find_map(|interval| {
            interval_spec_max_expansions_overflow_reason(query_field, interval, sources)
        })
}

fn interval_expanded_terms_for_sources<F, C>(
    sources: &[&Value],
    query_field: &str,
    spec: &serde_json::Map<String, Value>,
    candidate_tokens: C,
    mut matches: F,
) -> Vec<String>
where
    F: FnMut(&str) -> bool,
    C: Fn(&Value, &str, &serde_json::Map<String, Value>) -> Option<Vec<String>>,
{
    let mut terms = sources
        .iter()
        .filter_map(|source| candidate_tokens(source, query_field, spec))
        .flatten()
        .filter(|token| matches(token))
        .collect::<Vec<_>>();
    terms.sort();
    terms.dedup();
    terms
}

#[derive(Clone, Copy, Debug)]
struct IntervalSpan {
    start: usize,
    end: usize,
}

fn interval_matching_spans(
    source: &Value,
    query_field: &str,
    spec: &Value,
) -> Option<Vec<IntervalSpan>> {
    let interval_object = spec.as_object()?;
    let (mut spans, filter) = if let Some(match_spec) =
        interval_object.get("match").and_then(Value::as_object)
    {
        let tokens = interval_match_candidate_tokens(source, query_field, match_spec)?;
        let query_text = match_spec.get("query")?.as_str()?;
        let (ordered, max_gaps) = interval_ordering_options(match_spec)?;
        let terms = interval_match_query_terms(query_text, match_spec);
        (
            interval_match_spans(&tokens, &terms, ordered, max_gaps),
            match_spec.get("filter"),
        )
    } else if let Some(prefix_spec) = interval_object.get("prefix").and_then(Value::as_object) {
        let tokens = interval_prefix_candidate_tokens(source, query_field, prefix_spec)?;
        let prefix = prefix_spec.get("prefix")?.as_str()?.to_ascii_lowercase();
        (
            token_match_spans(&tokens, |token| token.starts_with(&prefix)),
            prefix_spec.get("filter"),
        )
    } else if let Some(wildcard_spec) = interval_object.get("wildcard").and_then(Value::as_object) {
        let tokens = interval_wildcard_candidate_tokens(source, query_field, wildcard_spec)?;
        let pattern = wildcard_spec.get("pattern")?.as_str()?.to_ascii_lowercase();
        let max_expansions = interval_max_expansions(wildcard_spec);
        (
            token_match_spans_with_expansion_limit(&tokens, max_expansions, |token| {
                wildcard_match(&pattern, token)
            }),
            wildcard_spec.get("filter"),
        )
    } else if let Some(regexp_spec) = interval_object.get("regexp").and_then(Value::as_object) {
        let tokens = interval_regexp_candidate_tokens(source, query_field, regexp_spec)?;
        let pattern = regexp_spec.get("pattern")?.as_str()?;
        let case_insensitive = regexp_spec
            .get("case_insensitive")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let max_expansions = interval_max_expansions(regexp_spec);
        (
            token_match_spans_with_expansion_limit(&tokens, max_expansions, |token| {
                interval_regexp_token_matches(pattern, token, case_insensitive)
            }),
            regexp_spec.get("filter"),
        )
    } else if let Some(fuzzy_spec) = interval_object.get("fuzzy").and_then(Value::as_object) {
        let tokens = interval_fuzzy_candidate_tokens(source, query_field, fuzzy_spec)?;
        let term = fuzzy_spec.get("term")?.as_str()?.to_ascii_lowercase();
        let fuzziness = interval_fuzzy_distance(fuzzy_spec, &term)?;
        let prefix_length = fuzzy_spec
            .get("prefix_length")
            .and_then(Value::as_u64)
            .map(|value| value as usize)
            .unwrap_or(0);
        let transpositions = fuzzy_spec
            .get("transpositions")
            .and_then(Value::as_bool)
            .unwrap_or(true);
        (
            token_match_spans(&tokens, |token| {
                fuzzy_token_matches(token, &term, fuzziness, prefix_length, transpositions)
            }),
            fuzzy_spec.get("filter"),
        )
    } else if let Some(all_of) = interval_object.get("all_of").and_then(Value::as_object) {
        let (ordered, max_gaps) = interval_ordering_options(all_of)?;
        let intervals = all_of.get("intervals")?.as_array()?;
        if !intervals_share_single_effective_field(intervals, query_field) {
            return None;
        }
        let mut span_sets = Vec::new();
        for interval in intervals {
            span_sets.push(interval_matching_spans(source, query_field, interval)?);
        }
        (
            interval_composite_spans(&span_sets, ordered, max_gaps),
            all_of.get("filter"),
        )
    } else if let Some(any_of) = interval_object.get("any_of").and_then(Value::as_object) {
        let mut spans = Vec::new();
        for interval in any_of.get("intervals")?.as_array()? {
            spans.extend(interval_matching_spans(source, query_field, interval)?);
        }
        (spans, any_of.get("filter"))
    } else {
        return None;
    };
    if let Some(filter) = filter {
        spans = apply_interval_filter(source, query_field, spans, filter)?;
    }
    Some(spans)
}

fn interval_match_spans(
    tokens: &[String],
    terms: &[String],
    ordered: bool,
    max_gaps: Option<usize>,
) -> Vec<IntervalSpan> {
    if terms.is_empty() {
        return Vec::new();
    }
    if terms.len() == 1 {
        return token_match_spans(tokens, |token| token == terms[0]);
    }
    let position_sets = terms
        .iter()
        .map(|term| token_match_positions(tokens, |token| token == term))
        .collect::<Vec<_>>();
    interval_position_sets_spans(&position_sets, ordered, max_gaps)
}

fn interval_match_query_terms(
    query_text: &str,
    match_spec: &serde_json::Map<String, Value>,
) -> Vec<String> {
    if match_spec
        .get("analyzer")
        .and_then(Value::as_str)
        .is_some_and(|analyzer| analyzer.eq_ignore_ascii_case("keyword"))
    {
        let term = query_text.to_ascii_lowercase();
        if term.is_empty() {
            return Vec::new();
        }
        return vec![term];
    }
    tokenize_search_text(query_text)
}

fn token_match_spans<F>(tokens: &[String], mut matches: F) -> Vec<IntervalSpan>
where
    F: FnMut(&str) -> bool,
{
    tokens
        .iter()
        .enumerate()
        .filter_map(|(index, token)| {
            matches(token).then_some(IntervalSpan {
                start: index,
                end: index,
            })
        })
        .collect()
}

fn token_match_spans_with_expansion_limit<F>(
    tokens: &[String],
    max_expansions: Option<usize>,
    matches: F,
) -> Vec<IntervalSpan>
where
    F: FnMut(&str) -> bool,
{
    let accepted_terms = interval_expanded_terms(tokens, max_expansions, matches);
    tokens
        .iter()
        .enumerate()
        .filter_map(|(index, token)| {
            accepted_terms.contains(token).then_some(IntervalSpan {
                start: index,
                end: index,
            })
        })
        .collect()
}

fn interval_expanded_terms<F>(
    tokens: &[String],
    max_expansions: Option<usize>,
    mut matches: F,
) -> Vec<String>
where
    F: FnMut(&str) -> bool,
{
    let mut terms = tokens
        .iter()
        .filter(|token| matches(token))
        .cloned()
        .collect::<Vec<_>>();
    terms.sort();
    terms.dedup();
    if let Some(max_expansions) = max_expansions {
        terms.truncate(max_expansions);
    }
    terms
}

fn interval_max_expansions(spec: &serde_json::Map<String, Value>) -> Option<usize> {
    spec.get("max_expansions")
        .and_then(Value::as_u64)
        .and_then(|value| usize::try_from(value).ok())
}

fn interval_position_sets_spans(
    position_sets: &[Vec<usize>],
    ordered: bool,
    max_gaps: Option<usize>,
) -> Vec<IntervalSpan> {
    if position_sets.is_empty() || position_sets.iter().any(Vec::is_empty) {
        return Vec::new();
    }
    if !ordered {
        let start = position_sets
            .iter()
            .filter_map(|positions| positions.iter().min())
            .min()
            .copied();
        let end = position_sets
            .iter()
            .filter_map(|positions| positions.iter().max())
            .max()
            .copied();
        return start
            .zip(end)
            .map(|(start, end)| vec![IntervalSpan { start, end }])
            .unwrap_or_default();
    }
    let mut spans = Vec::new();
    for start in &position_sets[0] {
        let mut previous = *start;
        let mut matched = true;
        for positions in &position_sets[1..] {
            let next = positions.iter().copied().find(|position| {
                *position > previous
                    && max_gaps.map_or(true, |max_gaps| {
                        position.saturating_sub(previous + 1) <= max_gaps
                    })
            });
            let Some(next) = next else {
                matched = false;
                break;
            };
            previous = next;
        }
        if matched {
            spans.push(IntervalSpan {
                start: *start,
                end: previous,
            });
        }
    }
    spans
}

fn interval_composite_spans(
    span_sets: &[Vec<IntervalSpan>],
    ordered: bool,
    max_gaps: Option<usize>,
) -> Vec<IntervalSpan> {
    if span_sets.is_empty() || span_sets.iter().any(Vec::is_empty) {
        return Vec::new();
    }
    if !ordered {
        let start = span_sets
            .iter()
            .filter_map(|spans| spans.iter().map(|span| span.start).min())
            .min();
        let end = span_sets
            .iter()
            .filter_map(|spans| spans.iter().map(|span| span.end).max())
            .max();
        return start
            .zip(end)
            .map(|(start, end)| vec![IntervalSpan { start, end }])
            .unwrap_or_default();
    }
    let mut spans = Vec::new();
    for start_span in &span_sets[0] {
        let mut previous = *start_span;
        let mut matched = true;
        for candidates in &span_sets[1..] {
            let next = candidates.iter().copied().find(|candidate| {
                candidate.start > previous.end
                    && max_gaps.map_or(true, |max_gaps| {
                        candidate.start.saturating_sub(previous.end + 1) <= max_gaps
                    })
            });
            let Some(next) = next else {
                matched = false;
                break;
            };
            previous = next;
        }
        if matched {
            spans.push(IntervalSpan {
                start: start_span.start,
                end: previous.end,
            });
        }
    }
    spans
}

fn apply_interval_filter(
    source: &Value,
    query_field: &str,
    spans: Vec<IntervalSpan>,
    filter: &Value,
) -> Option<Vec<IntervalSpan>> {
    let object = filter.as_object()?;
    let (kind, provider) = object.iter().next()?;
    let filter_spans = interval_matching_spans(source, query_field, provider)?;
    Some(
        spans
            .into_iter()
            .filter(|span| interval_filter_accepts(*span, &filter_spans, kind))
            .collect(),
    )
}

fn interval_filter_accepts(span: IntervalSpan, filters: &[IntervalSpan], kind: &str) -> bool {
    match kind {
        "containing" => filters
            .iter()
            .any(|filter| span.start <= filter.start && span.end >= filter.end),
        "contained_by" => filters
            .iter()
            .any(|filter| filter.start <= span.start && filter.end >= span.end),
        "not_containing" => filters
            .iter()
            .all(|filter| !(span.start <= filter.start && span.end >= filter.end)),
        "not_contained_by" => filters
            .iter()
            .all(|filter| !(filter.start <= span.start && filter.end >= span.end)),
        "overlapping" => filters
            .iter()
            .any(|filter| span.start <= filter.end && filter.start <= span.end),
        "not_overlapping" => filters
            .iter()
            .all(|filter| !(span.start <= filter.end && filter.start <= span.end)),
        "before" => filters.iter().any(|filter| span.end < filter.start),
        "after" => filters.iter().any(|filter| span.start > filter.end),
        _ => false,
    }
}

fn interval_match_candidate_tokens(
    source: &Value,
    query_field: &str,
    match_spec: &serde_json::Map<String, Value>,
) -> Option<Vec<String>> {
    let effective_field = interval_match_effective_field(match_spec, query_field);
    lookup_query_field_value(source, effective_field)
        .and_then(Value::as_str)
        .map(tokenize_search_text)
}

fn interval_prefix_candidate_tokens(
    source: &Value,
    query_field: &str,
    prefix_spec: &serde_json::Map<String, Value>,
) -> Option<Vec<String>> {
    let effective_field = interval_prefix_effective_field(prefix_spec, query_field);
    lookup_query_field_value(source, effective_field)
        .and_then(Value::as_str)
        .map(tokenize_search_text)
}

fn interval_wildcard_candidate_tokens(
    source: &Value,
    query_field: &str,
    wildcard_spec: &serde_json::Map<String, Value>,
) -> Option<Vec<String>> {
    let effective_field = interval_wildcard_effective_field(wildcard_spec, query_field);
    lookup_query_field_value(source, effective_field)
        .and_then(Value::as_str)
        .map(tokenize_search_text)
}

fn interval_regexp_candidate_tokens(
    source: &Value,
    query_field: &str,
    regexp_spec: &serde_json::Map<String, Value>,
) -> Option<Vec<String>> {
    let effective_field = interval_regexp_effective_field(regexp_spec, query_field);
    lookup_query_field_value(source, effective_field)
        .and_then(Value::as_str)
        .map(tokenize_search_text)
}

fn interval_regexp_token_matches(pattern: &str, token: &str, case_insensitive: bool) -> bool {
    let mut builder = regex::RegexBuilder::new(&format!("^(?:{pattern})$"));
    builder.case_insensitive(case_insensitive);
    builder.build().is_ok_and(|regex| regex.is_match(token))
}

fn interval_fuzzy_candidate_tokens(
    source: &Value,
    query_field: &str,
    fuzzy_spec: &serde_json::Map<String, Value>,
) -> Option<Vec<String>> {
    let effective_field = interval_fuzzy_effective_field(fuzzy_spec, query_field);
    lookup_query_field_value(source, effective_field)
        .and_then(Value::as_str)
        .map(tokenize_search_text)
}

fn interval_fuzzy_distance(
    fuzzy_spec: &serde_json::Map<String, Value>,
    term: &str,
) -> Option<usize> {
    match fuzzy_spec.get("fuzziness") {
        Some(Value::String(value)) if value.eq_ignore_ascii_case("AUTO") => {
            Some(auto_fuzziness(term))
        }
        Some(Value::String(value)) => value.parse::<usize>().ok(),
        Some(value) => value.as_u64().map(|value| value as usize),
        None => Some(auto_fuzziness(term)),
    }
}

fn interval_leaf_matching_positions(
    source: &Value,
    query_field: &str,
    interval: &Value,
) -> Option<Vec<usize>> {
    let interval_object = interval.as_object()?;
    if let Some(match_spec) = interval_object.get("match").and_then(Value::as_object) {
        let tokens = interval_match_candidate_tokens(source, query_field, match_spec)?;
        let query_text = match_spec.get("query")?.as_str()?;
        let terms = interval_match_query_terms(query_text, match_spec);
        return Some(token_match_positions(&tokens, |token| {
            terms.iter().any(|term| term == token)
        }));
    }
    if let Some(prefix_spec) = interval_object.get("prefix").and_then(Value::as_object) {
        let tokens = interval_prefix_candidate_tokens(source, query_field, prefix_spec)?;
        let prefix = prefix_spec.get("prefix")?.as_str()?.to_ascii_lowercase();
        return Some(token_match_positions(&tokens, |token| {
            token.starts_with(&prefix)
        }));
    }
    if let Some(wildcard_spec) = interval_object.get("wildcard").and_then(Value::as_object) {
        let tokens = interval_wildcard_candidate_tokens(source, query_field, wildcard_spec)?;
        let pattern = wildcard_spec.get("pattern")?.as_str()?.to_ascii_lowercase();
        return Some(token_match_positions_with_expansion_limit(
            &tokens,
            interval_max_expansions(wildcard_spec),
            |token| wildcard_match(&pattern, token),
        ));
    }
    if let Some(regexp_spec) = interval_object.get("regexp").and_then(Value::as_object) {
        let tokens = interval_regexp_candidate_tokens(source, query_field, regexp_spec)?;
        let pattern = regexp_spec.get("pattern")?.as_str()?;
        let case_insensitive = regexp_spec
            .get("case_insensitive")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        return Some(token_match_positions_with_expansion_limit(
            &tokens,
            interval_max_expansions(regexp_spec),
            |token| interval_regexp_token_matches(pattern, token, case_insensitive),
        ));
    }
    if let Some(fuzzy_spec) = interval_object.get("fuzzy").and_then(Value::as_object) {
        let tokens = interval_fuzzy_candidate_tokens(source, query_field, fuzzy_spec)?;
        let term = fuzzy_spec.get("term")?.as_str()?.to_ascii_lowercase();
        let fuzziness = interval_fuzzy_distance(fuzzy_spec, &term)?;
        let prefix_length = fuzzy_spec
            .get("prefix_length")
            .and_then(Value::as_u64)
            .map(|value| value as usize)
            .unwrap_or(0);
        let transpositions = fuzzy_spec
            .get("transpositions")
            .and_then(Value::as_bool)
            .unwrap_or(true);
        return Some(token_match_positions(&tokens, |token| {
            fuzzy_token_matches(token, &term, fuzziness, prefix_length, transpositions)
        }));
    }
    None
}

fn token_match_positions<F>(tokens: &[String], mut matches: F) -> Vec<usize>
where
    F: FnMut(&str) -> bool,
{
    tokens
        .iter()
        .enumerate()
        .filter_map(|(index, token)| matches(token).then_some(index))
        .collect()
}

fn token_match_positions_with_expansion_limit<F>(
    tokens: &[String],
    max_expansions: Option<usize>,
    matches: F,
) -> Vec<usize>
where
    F: FnMut(&str) -> bool,
{
    let accepted_terms = interval_expanded_terms(tokens, max_expansions, matches);
    tokens
        .iter()
        .enumerate()
        .filter_map(|(index, token)| accepted_terms.contains(token).then_some(index))
        .collect()
}

fn interval_position_sets_match(
    position_sets: &[Vec<usize>],
    ordered: bool,
    max_gaps: Option<usize>,
) -> bool {
    if position_sets.is_empty() || position_sets.iter().any(Vec::is_empty) {
        return false;
    }
    if !ordered {
        return true;
    }
    for start in &position_sets[0] {
        let mut previous = *start;
        let mut matched = true;
        for positions in &position_sets[1..] {
            let next = positions.iter().copied().find(|position| {
                *position > previous
                    && max_gaps.map_or(true, |max_gaps| {
                        position.saturating_sub(previous + 1) <= max_gaps
                    })
            });
            let Some(next) = next else {
                matched = false;
                break;
            };
            previous = next;
        }
        if matched {
            return true;
        }
    }
    false
}

fn interval_ordering_options(
    object: &serde_json::Map<String, Value>,
) -> Option<(bool, Option<usize>)> {
    let ordered = if let Some(ordered) = object.get("ordered") {
        ordered.as_bool()?
    } else if let Some(mode) = object.get("mode").and_then(Value::as_str) {
        mode.eq_ignore_ascii_case("ordered")
    } else {
        false
    };
    let max_gaps = match object.get("max_gaps").and_then(Value::as_i64) {
        Some(-1) | None => None,
        Some(value) if value >= 0 => Some(value as usize),
        _ => return None,
    };
    Some((ordered, max_gaps))
}

fn tokens_match_interval_terms(
    candidate_tokens: &[String],
    expected_terms: &[String],
    ordered: bool,
    max_gaps: Option<usize>,
) -> bool {
    if expected_terms.is_empty() {
        return false;
    }
    if ordered {
        let mut previous_position = None;
        for expected in expected_terms {
            let start = previous_position.map(|position| position + 1).unwrap_or(0);
            let mut matched_position = None;
            for (index, token) in candidate_tokens.iter().enumerate().skip(start) {
                if token == expected {
                    matched_position = Some(index);
                    break;
                }
            }
            let Some(position) = matched_position else {
                return false;
            };
            if let Some(previous) = previous_position {
                let gap = position.saturating_sub(previous + 1);
                if max_gaps.is_some_and(|max_gaps| gap > max_gaps) {
                    return false;
                }
            }
            previous_position = Some(position);
        }
        return true;
    }
    expected_terms
        .iter()
        .all(|expected| candidate_tokens.iter().any(|token| token == expected))
}

fn score_knn_query(candidate: Option<&Value>, expected: &[Value]) -> f64 {
    let Some(candidate_values) = candidate.and_then(Value::as_array) else {
        return f64::MIN;
    };
    if candidate_values.len() != expected.len() {
        return f64::MIN;
    }
    let mut score = 0.0;
    for (left, right) in candidate_values.iter().zip(expected) {
        let Some(left) = left.as_f64() else {
            return f64::MIN;
        };
        let Some(right) = right.as_f64() else {
            return f64::MIN;
        };
        score += left * right;
    }
    score
}

fn value_matches_range(candidate: Option<&Value>, bounds: &Value) -> bool {
    if let Some(candidate_number) = candidate.and_then(Value::as_f64) {
        let gte = bounds.get("gte").and_then(Value::as_f64);
        let gt = bounds.get("gt").and_then(Value::as_f64);
        let lte = bounds.get("lte").and_then(Value::as_f64);
        let lt = bounds.get("lt").and_then(Value::as_f64);
        return gte.map_or(true, |bound| candidate_number >= bound)
            && gt.map_or(true, |bound| candidate_number > bound)
            && lte.map_or(true, |bound| candidate_number <= bound)
            && lt.map_or(true, |bound| candidate_number < bound);
    }
    let Some(candidate_text) = candidate.and_then(Value::as_str) else {
        return false;
    };
    let gte = bounds.get("gte").and_then(Value::as_str);
    let gt = bounds.get("gt").and_then(Value::as_str);
    let lte = bounds.get("lte").and_then(Value::as_str);
    let lt = bounds.get("lt").and_then(Value::as_str);
    gte.map_or(true, |bound| candidate_text >= bound)
        && gt.map_or(true, |bound| candidate_text > bound)
        && lte.map_or(true, |bound| candidate_text <= bound)
        && lt.map_or(true, |bound| candidate_text < bound)
}

fn wildcard_match(pattern: &str, candidate: &str) -> bool {
    if !pattern.contains('*') {
        return pattern == candidate;
    }
    let parts: Vec<&str> = pattern.split('*').collect();
    let mut remainder = candidate;
    let starts_with_wildcard = pattern.starts_with('*');
    let ends_with_wildcard = pattern.ends_with('*');
    for (index, part) in parts.iter().enumerate() {
        if part.is_empty() {
            continue;
        }
        if index == 0 && !starts_with_wildcard {
            if let Some(stripped) = remainder.strip_prefix(part) {
                remainder = stripped;
                continue;
            }
            return false;
        }
        if index == parts.len() - 1 && !ends_with_wildcard {
            return remainder.ends_with(part);
        }
        if let Some(position) = remainder.find(part) {
            remainder = &remainder[position + part.len()..];
        } else {
            return false;
        }
    }
    true
}

const CAT_INDICES_DEFAULT_COLUMNS: &[&str] = &[
    "health",
    "status",
    "index",
    "uuid",
    "pri",
    "rep",
    "docs.count",
    "docs.deleted",
    "store.size",
    "pri.store.size",
];

const CAT_INDICES_ALL_COLUMNS: &[&str] = &[
    "health",
    "status",
    "index",
    "uuid",
    "pri",
    "rep",
    "docs.count",
    "docs.deleted",
    "store.size",
    "pri.store.size",
    "completion.size",
    "pri.completion.size",
    "flush.total",
    "pri.flush.total",
    "flush.total_time",
    "pri.flush.total_time",
    "segments.count",
    "pri.segments.count",
    "segments.memory",
    "pri.segments.memory",
    "search.open_contexts",
    "pri.search.open_contexts",
    "search.point_in_time_current",
    "pri.search.point_in_time_current",
    "search.point_in_time_time",
    "pri.search.point_in_time_time",
    "search.point_in_time_total",
    "pri.search.point_in_time_total",
];

fn cat_indices_column_aliases(column: &str) -> &'static [&'static str] {
    match column {
        "health" => &["h"],
        "status" => &["s"],
        "index" => &["i", "idx"],
        "uuid" => &["id", "uuid"],
        "pri" => &["p", "shards.primary", "shardsPrimary"],
        "rep" => &["r", "shards.replica", "shardsReplica"],
        "docs.count" => &["dc", "docsCount"],
        "docs.deleted" => &["dd", "docsDeleted"],
        "store.size" => &["ss", "storeSize"],
        "completion.size" => &["cs", "completionSize"],
        "flush.total" => &["ft", "flushTotal"],
        "flush.total_time" => &["ftt", "flushTotalTime"],
        "segments.count" => &["sc", "segmentsCount"],
        "segments.memory" => &["sm", "segmentsMemory"],
        "search.open_contexts" => &["so", "searchOpenContexts"],
        "search.point_in_time_current" => &["searchPointInTimeCurrent"],
        "search.point_in_time_time" => &["searchPointInTimeTime"],
        "search.point_in_time_total" => &["searchPointInTimeTotal"],
        _ => &[],
    }
}

fn cat_indices_sibling_column(column: &str) -> Option<&'static str> {
    match column {
        "store.size" => Some("pri.store.size"),
        "completion.size" => Some("pri.completion.size"),
        "flush.total" => Some("pri.flush.total"),
        "flush.total_time" => Some("pri.flush.total_time"),
        "segments.count" => Some("pri.segments.count"),
        "segments.memory" => Some("pri.segments.memory"),
        "search.open_contexts" => Some("pri.search.open_contexts"),
        "search.point_in_time_current" => Some("pri.search.point_in_time_current"),
        "search.point_in_time_time" => Some("pri.search.point_in_time_time"),
        "search.point_in_time_total" => Some("pri.search.point_in_time_total"),
        _ => None,
    }
}

fn cat_indices_resolve_column(column: &str) -> Option<&'static str> {
    CAT_INDICES_ALL_COLUMNS
        .iter()
        .copied()
        .find(|candidate| *candidate == column)
        .or_else(|| {
            CAT_INDICES_ALL_COLUMNS.iter().copied().find(|candidate| {
                cat_indices_column_aliases(candidate)
                    .iter()
                    .any(|alias| *alias == column)
            })
        })
}

fn compare_cat_indices_values(left: &Value, right: &Value) -> std::cmp::Ordering {
    let left_text = left.as_str().unwrap_or_default();
    let right_text = right.as_str().unwrap_or_default();
    match (left_text.parse::<i64>(), right_text.parse::<i64>()) {
        (Ok(left_number), Ok(right_number)) => left_number.cmp(&right_number),
        _ => left_text.cmp(right_text),
    }
}

fn sort_cat_indices_rows(rows: &mut [Value], s_param: Option<&String>) -> Result<(), RestResponse> {
    let ordering = match s_param {
        Some(value) => {
            let mut ordering = Vec::new();
            for raw_column in value
                .split(',')
                .map(str::trim)
                .filter(|value| !value.is_empty())
            {
                let (column_name, reverse) = if let Some(column) = raw_column.strip_suffix(":desc")
                {
                    (column, true)
                } else if let Some(column) = raw_column.strip_suffix(":asc") {
                    (column, false)
                } else {
                    (raw_column, false)
                };
                let Some(column) = cat_indices_resolve_column(column_name) else {
                    return Err(RestResponse::opensearch_error(
                        500,
                        "unsupported_operation_exception",
                        &format!("Unable to sort by unknown sort key `{column_name}`"),
                    ));
                };
                ordering.push((column, reverse));
            }
            ordering
        }
        None => vec![("index", false)],
    };
    rows.sort_by(|left, right| {
        for (column, reverse) in &ordering {
            let comparison = compare_cat_indices_values(&left[*column], &right[*column]);
            if comparison != std::cmp::Ordering::Equal {
                return if *reverse {
                    comparison.reverse()
                } else {
                    comparison
                };
            }
        }
        std::cmp::Ordering::Equal
    });
    Ok(())
}

fn cat_indices_cell_text(row: &Value, column: &str, request: &RestRequest) -> String {
    let value = row[column].as_str().unwrap_or_default();
    if matches!(
        column,
        "store.size"
            | "pri.store.size"
            | "completion.size"
            | "pri.completion.size"
            | "segments.memory"
            | "pri.segments.memory"
    ) && request.query_params.contains_key("bytes")
    {
        return value.trim_end_matches('b').to_string();
    }
    if matches!(column, "store.size" | "pri.store.size") {
        if let Some(bytes) = value.trim_end_matches('b').parse::<usize>().ok() {
            return format_cat_byte_size(bytes);
        }
    }
    if matches!(
        column,
        "flush.total_time"
            | "pri.flush.total_time"
            | "search.point_in_time_time"
            | "pri.search.point_in_time_time"
    ) && request.query_params.contains_key("time")
    {
        if column == "search.point_in_time_time" {
            return row["_search.point_in_time_time_millis"]
                .as_str()
                .unwrap_or_default()
                .to_string();
        }
        if column == "pri.search.point_in_time_time" {
            return row["_pri.search.point_in_time_time_millis"]
                .as_str()
                .unwrap_or_default()
                .to_string();
        }
        return value.trim_end_matches('s').to_string();
    }
    value.to_string()
}

fn format_cat_byte_size(bytes: usize) -> String {
    if bytes < 1024 {
        return format!("{bytes}b");
    }
    let tenths = bytes.saturating_mul(10) / 1024;
    format!("{}.{}kb", tenths / 10, tenths % 10)
}

fn cat_indices_column_right_aligned(column: &str) -> bool {
    matches!(
        column,
        "pri"
            | "rep"
            | "docs.count"
            | "docs.deleted"
            | "store.size"
            | "pri.store.size"
            | "completion.size"
            | "pri.completion.size"
            | "flush.total"
            | "pri.flush.total"
            | "flush.total_time"
            | "pri.flush.total_time"
            | "segments.count"
            | "pri.segments.count"
            | "segments.memory"
            | "pri.segments.memory"
            | "search.open_contexts"
            | "pri.search.open_contexts"
            | "search.point_in_time_current"
            | "pri.search.point_in_time_current"
            | "search.point_in_time_time"
            | "pri.search.point_in_time_time"
            | "search.point_in_time_total"
            | "pri.search.point_in_time_total"
    )
}

fn cat_indices_text_widths(
    display_columns: &[(&'static str, String)],
    rows: &[Value],
    request: &RestRequest,
    verbose: bool,
) -> Vec<usize> {
    display_columns
        .iter()
        .map(|(column, display)| {
            let header_width = if verbose { display.len() } else { 0 };
            rows.iter()
                .map(|row| cat_indices_cell_text(row, column, request).len())
                .fold(header_width, usize::max)
        })
        .collect()
}

fn cat_indices_format_text_cells(
    cells: Vec<String>,
    display_columns: &[(&'static str, String)],
    widths: &[usize],
) -> String {
    let last_index = cells.len().saturating_sub(1);
    let mut output = String::new();
    for (index, value) in cells.iter().enumerate() {
        let column = display_columns[index].0;
        let width = widths.get(index).copied().unwrap_or(value.len());
        let padding = width.saturating_sub(value.len());
        if cat_indices_column_right_aligned(column) {
            output.push_str(&" ".repeat(padding));
            output.push_str(value);
        } else {
            output.push_str(value);
            if index != last_index {
                output.push_str(&" ".repeat(padding));
            }
        }
        if index != last_index {
            output.push(' ');
        }
    }
    output
}

fn cat_indices_display_columns(
    query_params: &BTreeMap<String, String>,
) -> Vec<(&'static str, String)> {
    let h_param = query_params.get("h");
    let Some(h_param) = h_param else {
        return CAT_INDICES_DEFAULT_COLUMNS
            .iter()
            .map(|column| (*column, (*column).to_string()))
            .collect();
    };
    let include_primary_sibling = query_params.get("pri").is_some_and(|value| value == "true");
    let mut selected = Vec::new();
    for requested in h_param
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        if requested.contains('*') {
            for column in CAT_INDICES_ALL_COLUMNS {
                if wildcard_match(requested, column)
                    || cat_indices_column_aliases(column)
                        .iter()
                        .any(|alias| wildcard_match(requested, alias))
                {
                    if !selected.iter().any(|(existing, _)| existing == column) {
                        selected.push((*column, (*column).to_string()));
                        if include_primary_sibling {
                            if let Some(sibling) = cat_indices_sibling_column(column) {
                                selected.push((sibling, format!("pri.{column}")));
                            }
                        }
                    }
                }
            }
            continue;
        }
        if let Some(column) = CAT_INDICES_ALL_COLUMNS
            .iter()
            .copied()
            .find(|column| *column == requested)
        {
            if !selected.iter().any(|(existing, _)| existing == &column) {
                selected.push((column, column.to_string()));
                if include_primary_sibling {
                    if let Some(sibling) = cat_indices_sibling_column(column) {
                        selected.push((sibling, format!("pri.{column}")));
                    }
                }
            }
            continue;
        }
        for column in CAT_INDICES_ALL_COLUMNS {
            if cat_indices_column_aliases(column).contains(&requested) {
                if !selected.iter().any(|(existing, _)| existing == column) {
                    selected.push((*column, requested.to_string()));
                    if include_primary_sibling {
                        if let Some(sibling) = cat_indices_sibling_column(column) {
                            selected.push((sibling, format!("pri.{requested}")));
                        }
                    }
                }
                break;
            }
        }
    }
    selected
}

fn cat_count_display_columns(h_param: Option<&String>) -> Vec<(&'static str, String)> {
    let Some(h_param) = h_param else {
        return vec![
            ("epoch", "epoch".to_string()),
            ("timestamp", "timestamp".to_string()),
            ("count", "count".to_string()),
        ];
    };
    let mut selected = Vec::new();
    for requested in h_param
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        if requested.contains('*') {
            for (column, aliases) in [
                ("epoch", &[][..]),
                ("timestamp", &[][..]),
                ("count", &["dc", "docs.count", "docsCount"][..]),
            ] {
                if wildcard_match(requested, column)
                    || aliases.iter().any(|alias| wildcard_match(requested, alias))
                {
                    if !selected.iter().any(|(existing, _)| existing == &column) {
                        selected.push((column, column.to_string()));
                    }
                }
            }
            continue;
        }
        let column = match requested {
            "epoch" => Some("epoch"),
            "timestamp" => Some("timestamp"),
            "count" => Some("count"),
            "dc" | "docs.count" | "docsCount" => Some("count"),
            "*" => {
                for column in ["epoch", "timestamp", "count"] {
                    if !selected.iter().any(|(existing, _)| existing == &column) {
                        selected.push((column, column.to_string()));
                    }
                }
                None
            }
            _ => None,
        };
        if let Some(column) = column {
            if !selected.iter().any(|(existing, _)| existing == &column) {
                selected.push((column, requested.to_string()));
            }
        }
    }
    selected
}

fn cat_count_resolve_column(column: &str) -> Option<&'static str> {
    match column {
        "epoch" => Some("epoch"),
        "timestamp" => Some("timestamp"),
        "count" | "dc" | "docs.count" | "docsCount" => Some("count"),
        _ => None,
    }
}

fn validate_cat_count_sort(s_param: Option<&String>) -> Result<(), RestResponse> {
    let Some(value) = s_param else {
        return Ok(());
    };
    for raw_column in value
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        let column_name = raw_column
            .strip_suffix(":desc")
            .or_else(|| raw_column.strip_suffix(":asc"))
            .unwrap_or(raw_column);
        if cat_count_resolve_column(column_name).is_none() {
            return Err(RestResponse::opensearch_error(
                500,
                "unsupported_operation_exception",
                &format!("Unable to sort by unknown sort key `{column_name}`"),
            ));
        }
    }
    Ok(())
}

fn cat_count_selected_row(row: &Value, h_param: Option<&String>) -> Value {
    let mut object = serde_json::Map::new();
    for (column, display) in cat_count_display_columns(h_param) {
        object.insert(display, row[column].clone());
    }
    Value::Object(object)
}

