fn parse_search_indices_boosts(indices_boost: Option<&Value>) -> Vec<(String, f64)> {
    match indices_boost {
        Some(Value::Object(boosts)) => boosts
            .iter()
            .filter_map(|(index, boost)| Some((index.clone(), boost.as_f64()?)))
            .collect(),
        Some(Value::Array(boosts)) => boosts
            .iter()
            .filter_map(|boost| {
                let object = boost.as_object()?;
                let (index, value) = object.iter().next()?;
                Some((index.clone(), value.as_f64()?))
            })
            .collect(),
        _ => Vec::new(),
    }
}

fn search_index_boost_for(index: &str, boosts: &[(String, f64)]) -> f64 {
    boosts
        .iter()
        .find_map(|(pattern, boost)| {
            if pattern == index || wildcard_match(pattern, index) {
                Some(*boost)
            } else {
                None
            }
        })
        .unwrap_or(1.0)
}

fn stringify_leaf_scalars(value: &Value) -> Value {
    match value {
        Value::Object(object) => Value::Object(
            object
                .iter()
                .map(|(key, value)| (key.clone(), stringify_leaf_scalars(value)))
                .collect(),
        ),
        Value::Array(values) => Value::Array(values.iter().map(stringify_leaf_scalars).collect()),
        Value::Number(number) => Value::String(number.to_string()),
        Value::Bool(boolean) => Value::String(boolean.to_string()),
        _ => value.clone(),
    }
}

fn merge_object_with_null_reset(base: &mut Value, update: &Value) {
    let Some(base_object) = base.as_object_mut() else {
        *base = update.clone();
        return;
    };
    let Some(update_object) = update.as_object() else {
        *base = update.clone();
        return;
    };
    for (key, value) in update_object {
        if value.is_null() {
            base_object.remove(key);
            continue;
        }
        match base_object.get_mut(key) {
            Some(existing) if existing.is_object() && value.is_object() => {
                merge_object_with_null_reset(existing, value);
            }
            _ => {
                base_object.insert(key.clone(), value.clone());
            }
        }
    }
}

fn build_search_aggregations(
    aggregations: Option<&Value>,
    hits: &[Value],
    global_hits: &[Value],
) -> Result<Option<Value>, RestResponse> {
    let Some(aggregations) = aggregations.and_then(Value::as_object) else {
        return Ok(None);
    };
    let mut result = serde_json::Map::new();
    let mut terms_doc_counts: std::collections::BTreeMap<String, Vec<(String, u64)>> =
        std::collections::BTreeMap::new();
    for (name, aggregation) in aggregations {
        let Some(aggregation_object) = aggregation.as_object() else {
            continue;
        };
        if aggregation_object
            .get("global")
            .and_then(Value::as_object)
            .is_some()
        {
            let mut global_value = serde_json::Map::new();
            global_value.insert(
                "doc_count".to_string(),
                Value::from(global_hits.len() as u64),
            );
            let nested_aggs = aggregation_object
                .get("aggs")
                .or_else(|| aggregation_object.get("aggregations"));
            if let Some(nested) = build_search_aggregations(nested_aggs, global_hits, global_hits)?
            {
                if let Some(nested_object) = nested.as_object() {
                    for (nested_name, nested_value) in nested_object {
                        global_value.insert(nested_name.clone(), nested_value.clone());
                    }
                }
            }
            result.insert(name.clone(), Value::Object(global_value));
            continue;
        }
        if let Some(nested) = aggregation_object.get("nested").and_then(Value::as_object) {
            let path = nested
                .get("path")
                .and_then(Value::as_str)
                .unwrap_or_default();
            if path.is_empty() {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [nested.path]",
                ));
            }
            let nested_hits = collect_nested_child_hits(hits, path);
            let mut nested_value = serde_json::Map::new();
            nested_value.insert(
                "doc_count".to_string(),
                Value::from(nested_hits.len() as u64),
            );
            let nested_aggs = aggregation_object
                .get("aggs")
                .or_else(|| aggregation_object.get("aggregations"));
            if let Some(nested_aggregations) =
                build_search_aggregations(nested_aggs, &nested_hits, &nested_hits)?
            {
                if let Some(nested_object) = nested_aggregations.as_object() {
                    for (nested_name, nested_value_inner) in nested_object {
                        nested_value.insert(nested_name.clone(), nested_value_inner.clone());
                    }
                }
            }
            result.insert(name.clone(), Value::Object(nested_value));
            continue;
        }
        if let Some(reverse_nested) = aggregation_object
            .get("reverse_nested")
            .and_then(Value::as_object)
        {
            if reverse_nested
                .get("path")
                .and_then(Value::as_str)
                .is_some_and(|path| !path.is_empty())
            {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [reverse_nested.path]",
                ));
            }
            let parent_hits = collect_reverse_nested_parent_hits(hits);
            let mut reverse_nested_value = serde_json::Map::new();
            reverse_nested_value.insert(
                "doc_count".to_string(),
                Value::from(parent_hits.len() as u64),
            );
            let nested_aggs = aggregation_object
                .get("aggs")
                .or_else(|| aggregation_object.get("aggregations"));
            if let Some(nested) = build_search_aggregations(nested_aggs, &parent_hits, global_hits)?
            {
                if let Some(nested_object) = nested.as_object() {
                    for (nested_name, nested_value) in nested_object {
                        reverse_nested_value.insert(nested_name.clone(), nested_value.clone());
                    }
                }
            }
            result.insert(name.clone(), Value::Object(reverse_nested_value));
            continue;
        }
        if let Some(sampler) = aggregation_object.get("sampler").and_then(Value::as_object) {
            let shard_size = sampler
                .get("shard_size")
                .and_then(Value::as_u64)
                .unwrap_or(100) as usize;
            let sampled_hits = hits.iter().take(shard_size).cloned().collect::<Vec<_>>();
            let mut sampled_value = serde_json::Map::new();
            sampled_value.insert(
                "doc_count".to_string(),
                Value::from(sampled_hits.len() as u64),
            );
            let nested_aggs = aggregation_object
                .get("aggs")
                .or_else(|| aggregation_object.get("aggregations"));
            if let Some(nested) =
                build_search_aggregations(nested_aggs, &sampled_hits, global_hits)?
            {
                if let Some(nested_object) = nested.as_object() {
                    for (nested_name, nested_value) in nested_object {
                        sampled_value.insert(nested_name.clone(), nested_value.clone());
                    }
                }
            }
            result.insert(name.clone(), Value::Object(sampled_value));
            continue;
        }
        if let Some(diversified_sampler) = aggregation_object
            .get("diversified_sampler")
            .and_then(Value::as_object)
        {
            let field = diversified_sampler
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            if field.is_empty() {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [diversified_sampler.field]",
                ));
            }
            let shard_size = diversified_sampler
                .get("shard_size")
                .and_then(Value::as_u64)
                .unwrap_or(100) as usize;
            let max_docs_per_value = diversified_sampler
                .get("max_docs_per_value")
                .and_then(Value::as_u64)
                .unwrap_or(1);
            let mut value_counts = std::collections::BTreeMap::<String, u64>::new();
            let mut sampled_hits = Vec::new();
            for hit in hits {
                if sampled_hits.len() >= shard_size {
                    break;
                }
                let Some(value) = hit
                    .get("_source")
                    .and_then(|source| lookup_query_field_value(source, field))
                    .filter(|value| !value.is_null())
                else {
                    continue;
                };
                let value_key = aggregation_bucket_sort_key(value);
                let current_count = value_counts.get(&value_key).copied().unwrap_or(0);
                if current_count >= max_docs_per_value {
                    continue;
                }
                value_counts.insert(value_key, current_count + 1);
                sampled_hits.push(hit.clone());
            }
            let mut sampled_value = serde_json::Map::new();
            sampled_value.insert(
                "doc_count".to_string(),
                Value::from(sampled_hits.len() as u64),
            );
            let nested_aggs = aggregation_object
                .get("aggs")
                .or_else(|| aggregation_object.get("aggregations"));
            if let Some(nested) =
                build_search_aggregations(nested_aggs, &sampled_hits, global_hits)?
            {
                if let Some(nested_object) = nested.as_object() {
                    for (nested_name, nested_value) in nested_object {
                        sampled_value.insert(nested_name.clone(), nested_value.clone());
                    }
                }
            }
            result.insert(name.clone(), Value::Object(sampled_value));
            continue;
        }
        if let Some(terms) = aggregation_object.get("terms").and_then(Value::as_object) {
            let field = terms
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            if terms
                .get("include")
                .is_some_and(aggregation_include_filter_is_partition)
                && terms.contains_key("exclude")
            {
                return Err(build_unsupported_search_response(
                    "Cannot specify any excludes when using a partition-based include",
                ));
            }
            let missing = terms
                .get("missing")
                .filter(|value| !value.is_array() && !value.is_object() && !value.is_null());
            let min_doc_count = terms
                .get("min_doc_count")
                .map(|value| {
                    value.as_u64().ok_or_else(|| {
                        build_unsupported_search_response(
                            "unsupported aggregation option [terms.min_doc_count]",
                        )
                    })
                })
                .transpose()?
                .unwrap_or(1);
            let size = terms
                .get("size")
                .map(|value| {
                    value.as_u64().ok_or_else(|| {
                        build_unsupported_search_response(
                            "unsupported aggregation option [terms.size]",
                        )
                    })
                })
                .transpose()?
                .unwrap_or(10) as usize;
            if terms.contains_key("keyed") {
                return Err(build_x_content_parse_search_response_with_root_cause(
                    "[1:67] [terms] unknown field [keyed]",
                ));
            }
            let mut counts = std::collections::BTreeMap::new();
            for hit in hits {
                let key = hit
                    .get("_source")
                    .and_then(|source| lookup_query_field_value(source, field))
                    .filter(|value| !value.is_null())
                    .or(missing);
                if let Some(key_value) = key {
                    if !aggregation_term_is_allowed_by_include_exclude(
                        key_value,
                        terms.get("include"),
                        terms.get("exclude"),
                    )? {
                        continue;
                    }
                    let Some(key) = key_value.as_str() else {
                        continue;
                    };
                    *counts.entry(key.to_string()).or_insert(0_u64) += 1;
                }
            }
            let mut buckets: Vec<(String, u64)> = counts.into_iter().collect();
            buckets.retain(|(_, doc_count)| *doc_count >= min_doc_count);
            let order = terms.get("order").and_then(Value::as_object);
            let order_key = order
                .and_then(|value| value.iter().next())
                .map(|(key, direction)| (key.as_str(), direction.as_str().unwrap_or("desc")));
            match order_key {
                Some(("_count", "asc")) => buckets
                    .sort_by(|left, right| left.1.cmp(&right.1).then_with(|| left.0.cmp(&right.0))),
                Some(("_count", _)) | None => buckets
                    .sort_by(|left, right| right.1.cmp(&left.1).then_with(|| left.0.cmp(&right.0))),
                Some(("_key", "desc")) => buckets.sort_by(|left, right| right.0.cmp(&left.0)),
                Some(("_key", _)) => buckets.sort_by(|left, right| left.0.cmp(&right.0)),
                Some(_) => {
                    return Err(build_unsupported_search_response(
                        "unsupported aggregation option [terms.order]",
                    ))
                }
            }
            let sum_other_doc_count = buckets
                .iter()
                .skip(size)
                .map(|(_, doc_count)| *doc_count)
                .sum::<u64>();
            let nested_aggs = aggregation_object
                .get("aggs")
                .or_else(|| aggregation_object.get("aggregations"));
            let mut bucket_values = buckets
                .into_iter()
                .take(size)
                .map(|(key, doc_count)| serde_json::json!({"key": key, "doc_count": doc_count}))
                .collect::<Vec<_>>();
            apply_terms_bucket_parent_pipeline_transforms(&mut bucket_values, nested_aggs);
            terms_doc_counts.insert(
                name.clone(),
                bucket_values
                    .iter()
                    .filter_map(|bucket| {
                        Some((
                            bucket.get("key")?.as_str()?.to_string(),
                            bucket.get("doc_count")?.as_u64()?,
                        ))
                    })
                    .collect(),
            );
            result.insert(
                name.clone(),
                serde_json::json!({
                    "doc_count_error_upper_bound": 0,
                    "sum_other_doc_count": sum_other_doc_count,
                    "buckets": bucket_values
                }),
            );
            continue;
        }
        if let Some(rare_terms) = aggregation_object
            .get("rare_terms")
            .and_then(Value::as_object)
        {
            let field = rare_terms
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let max_doc_count = rare_terms
                .get("max_doc_count")
                .and_then(Value::as_u64)
                .unwrap_or(1);
            if max_doc_count == 0 || max_doc_count > 100 {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [rare_terms.max_doc_count]",
                ));
            }
            let mut counts = std::collections::BTreeMap::<String, (Value, u64)>::new();
            for hit in hits {
                let Some(key) = hit
                    .get("_source")
                    .and_then(|source| lookup_query_field_value(source, field))
                    .filter(|value| !value.is_null())
                else {
                    continue;
                };
                if !aggregation_term_is_allowed_by_include_exclude(
                    key,
                    rare_terms.get("include"),
                    rare_terms.get("exclude"),
                )? {
                    continue;
                }
                let sort_key = aggregation_bucket_sort_key(key);
                let entry = counts.entry(sort_key).or_insert_with(|| (key.clone(), 0));
                entry.1 += 1;
            }
            let mut buckets = counts
                .into_iter()
                .filter_map(|(_, (key, doc_count))| {
                    (doc_count <= max_doc_count).then_some((key, doc_count))
                })
                .collect::<Vec<_>>();
            buckets.sort_by(|left, right| {
                left.1
                    .cmp(&right.1)
                    .then_with(|| aggregation_bucket_key_cmp(&left.0, &right.0))
            });
            result.insert(
                name.clone(),
                serde_json::json!({
                    "buckets": buckets
                        .into_iter()
                        .map(|(key, doc_count)| serde_json::json!({"key": key, "doc_count": doc_count}))
                        .collect::<Vec<_>>()
                }),
            );
            continue;
        }
        if let Some(multi_terms) = aggregation_object
            .get("multi_terms")
            .and_then(Value::as_object)
        {
            let fields = multi_terms
                .get("terms")
                .and_then(Value::as_array)
                .map(|terms| {
                    terms
                        .iter()
                        .filter_map(|term| {
                            term.get("field")
                                .and_then(Value::as_str)
                                .map(str::to_string)
                        })
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            if fields.is_empty() {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [multi_terms.terms]",
                ));
            }
            let min_doc_count = multi_terms
                .get("min_doc_count")
                .and_then(Value::as_u64)
                .unwrap_or(1);
            let size = multi_terms
                .get("size")
                .and_then(Value::as_u64)
                .unwrap_or(10) as usize;
            let mut counts = std::collections::BTreeMap::<String, (Vec<Value>, u64)>::new();
            for hit in hits {
                let Some(source) = hit.get("_source") else {
                    continue;
                };
                let mut key_values = Vec::new();
                let mut sort_parts = Vec::new();
                for field in &fields {
                    let Some(value) =
                        lookup_query_field_value(source, field).filter(|value| !value.is_null())
                    else {
                        key_values.clear();
                        break;
                    };
                    key_values.push(value.clone());
                    sort_parts.push(aggregation_bucket_sort_key(value));
                }
                if key_values.is_empty() {
                    continue;
                }
                let sort_key = sort_parts.join("\u{1f}");
                let entry = counts.entry(sort_key).or_insert_with(|| (key_values, 0));
                entry.1 += 1;
            }
            let mut buckets = counts
                .into_iter()
                .filter_map(|(_, (key, doc_count))| {
                    (doc_count >= min_doc_count).then_some((key, doc_count))
                })
                .collect::<Vec<_>>();
            let order = multi_terms.get("order").and_then(Value::as_object);
            let order_key = order
                .and_then(|value| value.iter().next())
                .map(|(key, direction)| (key.as_str(), direction.as_str().unwrap_or("desc")));
            match order_key {
                Some(("_count", "asc")) => buckets.sort_by(|left, right| {
                    left.1.cmp(&right.1).then_with(|| {
                        aggregation_multi_terms_sort_key(&left.0)
                            .cmp(&aggregation_multi_terms_sort_key(&right.0))
                    })
                }),
                Some(("_count", _)) | None => buckets.sort_by(|left, right| {
                    right.1.cmp(&left.1).then_with(|| {
                        aggregation_multi_terms_sort_key(&left.0)
                            .cmp(&aggregation_multi_terms_sort_key(&right.0))
                    })
                }),
                Some(("_key", "desc")) => buckets.sort_by(|left, right| {
                    aggregation_multi_terms_sort_key(&right.0)
                        .cmp(&aggregation_multi_terms_sort_key(&left.0))
                }),
                Some(("_key", _)) => buckets.sort_by(|left, right| {
                    aggregation_multi_terms_sort_key(&left.0)
                        .cmp(&aggregation_multi_terms_sort_key(&right.0))
                }),
                Some(_) => {
                    return Err(build_unsupported_search_response(
                        "unsupported aggregation option [multi_terms.order]",
                    ))
                }
            }
            let sum_other_doc_count = buckets
                .iter()
                .skip(size)
                .map(|(_, doc_count)| *doc_count)
                .sum::<u64>();
            result.insert(
                name.clone(),
                serde_json::json!({
                    "buckets": buckets
                        .into_iter()
                        .take(size)
                        .map(|(key, doc_count)| {
                            let key_as_string = aggregation_multi_terms_key_as_string(&key);
                            serde_json::json!({
                                "key": key,
                                "key_as_string": key_as_string,
                                "doc_count": doc_count
                            })
                        })
                        .collect::<Vec<_>>(),
                    "doc_count_error_upper_bound": 0,
                    "sum_other_doc_count": sum_other_doc_count
                }),
            );
            continue;
        }
        if let Some((metric_name, metric_body)) =
            first_supported_metric_aggregation(aggregation_object)
        {
            let field = metric_body
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let missing = metric_body.get("missing").and_then(metric_missing_value);
            let values: Vec<f64> = hits
                .iter()
                .flat_map(|hit| {
                    let values = hit
                        .get("_source")
                        .and_then(|source| lookup_query_field_value(source, field))
                        .map(numeric_values_from_value)
                        .unwrap_or_default();
                    if values.is_empty() {
                        missing.into_iter().collect::<Vec<_>>()
                    } else {
                        values
                    }
                })
                .collect();
            let value = match metric_name {
                "min" => values.iter().copied().reduce(f64::min).unwrap_or(0.0),
                "max" => values.iter().copied().reduce(f64::max).unwrap_or(0.0),
                "sum" => values.iter().sum(),
                "avg" => {
                    if values.is_empty() {
                        0.0
                    } else {
                        values.iter().sum::<f64>() / values.len() as f64
                    }
                }
                "weighted_avg" => {
                    result.insert(
                        name.clone(),
                        serde_json::json!({
                            "value": weighted_avg_aggregation_value(&hits, metric_body)
                                .map(Value::from)
                                .unwrap_or(Value::Null)
                        }),
                    );
                    continue;
                }
                "value_count" => values.len() as f64,
                "stats" => {
                    result.insert(
                        name.clone(),
                        serde_json::json!({
                            "count": values.len(),
                            "min": values.iter().copied().reduce(f64::min).unwrap_or(0.0),
                            "max": values.iter().copied().reduce(f64::max).unwrap_or(0.0),
                            "avg": if values.is_empty() { 0.0 } else { values.iter().sum::<f64>() / values.len() as f64 },
                            "sum": values.iter().sum::<f64>(),
                        }),
                    );
                    continue;
                }
                "extended_stats" => {
                    result.insert(
                        name.clone(),
                        extended_stats_aggregation_value(
                            &values,
                            metric_body
                                .get("sigma")
                                .and_then(metric_missing_value)
                                .unwrap_or(2.0),
                        ),
                    );
                    continue;
                }
                "percentiles" => {
                    result.insert(
                        name.clone(),
                        percentiles_aggregation_value(
                            &values,
                            metric_body
                                .get("percents")
                                .and_then(metric_numeric_array_value)
                                .as_deref(),
                        ),
                    );
                    continue;
                }
                "percentile_ranks" => {
                    result.insert(
                        name.clone(),
                        percentile_ranks_aggregation_value(
                            &values,
                            metric_body
                                .get("values")
                                .and_then(metric_numeric_array_value)
                                .as_deref()
                                .unwrap_or(&[]),
                        ),
                    );
                    continue;
                }
                "median_absolute_deviation" => {
                    if let Some(compression) =
                        metric_body.get("compression").and_then(Value::as_f64)
                    {
                        if compression <= 0.0 {
                            let reason = format!(
                                "[compression] must be greater than 0. Found [{compression}] in [{name}]"
                            );
                            return Err(RestResponse::json(
                                400,
                                serde_json::json!({
                                    "error": {
                                        "type": "illegal_argument_exception",
                                        "reason": reason,
                                        "root_cause": [{
                                            "type": "illegal_argument_exception",
                                            "reason": reason
                                        }]
                                    },
                                    "status": 400
                                }),
                            ));
                        }
                    }
                    result.insert(
                        name.clone(),
                        serde_json::json!({
                            "value": median_absolute_deviation_value(&values)
                                .map(Value::from)
                                .unwrap_or(Value::Null)
                        }),
                    );
                    continue;
                }
                _ => 0.0,
            };
            result.insert(name.clone(), serde_json::json!({ "value": value }));
            continue;
        }
        if let Some(filter) = aggregation_object.get("filter") {
            let doc_count = hits
                .iter()
                .filter(|hit| hit_matches_query(hit, filter))
                .count() as u64;
            result.insert(name.clone(), serde_json::json!({ "doc_count": doc_count }));
            continue;
        }
        if let Some(adjacency_matrix) = aggregation_object
            .get("adjacency_matrix")
            .and_then(Value::as_object)
        {
            let filters = adjacency_matrix
                .get("filters")
                .and_then(Value::as_object)
                .cloned()
                .unwrap_or_default();
            if filters.is_empty() {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [adjacency_matrix.filters]",
                ));
            }
            let separator = adjacency_matrix
                .get("separator")
                .and_then(Value::as_str)
                .unwrap_or("&");
            let show_only_intersecting = adjacency_matrix
                .get("show_only_intersecting")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            let mut filter_entries = filters.into_iter().collect::<Vec<_>>();
            filter_entries.sort_by(|left, right| left.0.cmp(&right.0));
            let mut buckets = Vec::new();
            if !show_only_intersecting {
                for (bucket_name, filter) in &filter_entries {
                    let doc_count = hits
                        .iter()
                        .filter(|hit| hit_matches_query(hit, filter))
                        .count() as u64;
                    if doc_count > 0 {
                        buckets.push(serde_json::json!({
                            "key": bucket_name,
                            "doc_count": doc_count,
                        }));
                    }
                }
            }
            for left_index in 0..filter_entries.len() {
                for right_index in (left_index + 1)..filter_entries.len() {
                    let (left_name, left_filter) = &filter_entries[left_index];
                    let (right_name, right_filter) = &filter_entries[right_index];
                    let doc_count = hits
                        .iter()
                        .filter(|hit| {
                            hit_matches_query(hit, left_filter)
                                && hit_matches_query(hit, right_filter)
                        })
                        .count() as u64;
                    if doc_count > 0 {
                        buckets.push(serde_json::json!({
                            "key": format!("{left_name}{separator}{right_name}"),
                            "doc_count": doc_count,
                        }));
                    }
                }
            }
            result.insert(name.clone(), serde_json::json!({ "buckets": buckets }));
            continue;
        }
        if let Some(filters) = aggregation_object
            .get("filters")
            .and_then(|value| value.get("filters"))
            .and_then(Value::as_object)
        {
            let mut buckets = serde_json::Map::new();
            for (bucket_name, filter) in filters {
                let doc_count = hits
                    .iter()
                    .filter(|hit| hit_matches_query(hit, filter))
                    .count() as u64;
                buckets.insert(
                    bucket_name.clone(),
                    serde_json::json!({ "doc_count": doc_count }),
                );
            }
            result.insert(name.clone(), serde_json::json!({ "buckets": buckets }));
            continue;
        }
        if let Some(missing) = aggregation_object.get("missing").and_then(Value::as_object) {
            let Some(field) = missing.get("field").and_then(Value::as_str) else {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [missing.field]",
                ));
            };
            let doc_count = hits
                .iter()
                .filter(|hit| {
                    extract_source_path_value(hit.get("_source").unwrap_or(&Value::Null), field)
                        .map_or(true, |value| value.is_null())
                })
                .count() as u64;
            result.insert(name.clone(), serde_json::json!({ "doc_count": doc_count }));
            continue;
        }
        if let Some(top_hits) = aggregation_object
            .get("top_hits")
            .and_then(Value::as_object)
        {
            let mut top_rows = hits.to_vec();
            apply_search_sort(&mut top_rows, top_hits.get("sort").unwrap_or(&Value::Null));
            let from = top_hits.get("from").and_then(Value::as_u64).unwrap_or(0) as usize;
            let size = top_hits.get("size").and_then(Value::as_u64).unwrap_or(3) as usize;
            let mut selected: Vec<Value> = top_rows.into_iter().skip(from).take(size).collect();
            apply_top_hits_fields_to_hits(&mut selected, top_hits);
            apply_search_source_projection_to_hits(&mut selected, &Value::Object(top_hits.clone()));
            result.insert(
                name.clone(),
                serde_json::json!({
                    "hits": {
                        "total": { "value": hits.len() },
                        "hits": selected
                    }
                }),
            );
            continue;
        }
        if let Some(composite) = aggregation_object
            .get("composite")
            .and_then(Value::as_object)
        {
            let sources = composite
                .get("sources")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let mut counts = std::collections::BTreeMap::<String, (Value, u64)>::new();
            for hit in hits {
                let mut key_object = serde_json::Map::new();
                for source in &sources {
                    if let Some(source_object) = source.as_object() {
                        for (name, spec) in source_object {
                            let field = spec
                                .get("terms")
                                .and_then(|terms| terms.get("field"))
                                .and_then(Value::as_str)
                                .unwrap_or_default();
                            key_object.insert(
                                name.clone(),
                                hit.get("_source")
                                    .and_then(|source| source.get(field))
                                    .cloned()
                                    .unwrap_or(Value::Null),
                            );
                        }
                    }
                }
                let key_value = Value::Object(key_object.clone());
                let encoded = serde_json::to_string(&key_value).unwrap_or_default();
                let entry = counts.entry(encoded).or_insert((key_value, 0));
                entry.1 += 1;
            }
            let buckets = counts
                .into_values()
                .map(|(key, doc_count)| serde_json::json!({ "key": key, "doc_count": doc_count }))
                .collect::<Vec<_>>();
            result.insert(name.clone(), serde_json::json!({ "buckets": buckets }));
            continue;
        }
        if let Some(date_histogram) = aggregation_object
            .get("date_histogram")
            .and_then(Value::as_object)
        {
            let field = date_histogram
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let interval = date_histogram
                .get("calendar_interval")
                .or_else(|| date_histogram.get("fixed_interval"))
                .and_then(Value::as_str)
                .unwrap_or_default();
            let Some(interval_kind) = date_histogram_interval_kind(interval) else {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation [date_histogram]",
                ));
            };
            let missing = date_histogram.get("missing").and_then(Value::as_str);
            let keyed = date_histogram
                .get("keyed")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            let offset_millis = date_histogram
                .get("offset")
                .and_then(parse_date_histogram_offset_millis)
                .unwrap_or(0);
            let time_zone = date_histogram.get("time_zone").and_then(Value::as_str);
            let Some(time_zone_offset_millis) = date_histogram_time_zone_offset_millis(time_zone)
            else {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [date_histogram.time_zone]",
                ));
            };
            let format = match date_histogram.get("format").and_then(Value::as_str) {
                Some("epoch_millis") => Some("epoch_millis"),
                Some("yyyy-MM-dd HH:mm:ss") => Some("yyyy-MM-dd HH:mm:ss"),
                Some("basic_date_time_no_millis") => Some("basic_date_time_no_millis"),
                Some("date") => Some("date"),
                Some(_) => {
                    return Err(build_unsupported_search_response(
                        "unsupported aggregation option [date_histogram.format]",
                    ));
                }
                None => None,
            };
            let min_doc_count = date_histogram
                .get("min_doc_count")
                .and_then(Value::as_u64)
                .unwrap_or(0);
            let extended_bounds = date_histogram
                .get("extended_bounds")
                .map(parse_fallback_date_histogram_bounds)
                .transpose()?;
            let hard_bounds = date_histogram
                .get("hard_bounds")
                .map(parse_fallback_date_histogram_bounds)
                .transpose()?;
            let mut counts = std::collections::BTreeMap::<i64, (String, u64)>::new();
            for hit in hits {
                let raw = hit
                    .get("_source")
                    .and_then(|source| source.get(field))
                    .and_then(Value::as_str)
                    .or(missing);
                let Some(raw) = raw else { continue };
                let Some((bucket_key, bucket_string)) = date_histogram_bucket_with_offset(
                    raw,
                    interval_kind,
                    offset_millis,
                    time_zone_offset_millis,
                    format,
                ) else {
                    continue;
                };
                if !fallback_date_histogram_bounds_contain(
                    hard_bounds.as_ref(),
                    bucket_key,
                    interval_kind,
                    offset_millis,
                    time_zone_offset_millis,
                    format,
                ) {
                    continue;
                }
                let entry = counts.entry(bucket_key).or_insert((bucket_string, 0));
                entry.1 += 1;
            }
            let buckets = render_date_histogram_bucket_values_from_counts(
                &counts,
                interval_kind,
                offset_millis,
                time_zone_offset_millis,
                format,
                min_doc_count,
                extended_bounds.as_ref(),
                hard_bounds.as_ref(),
            );
            result.insert(
                name.clone(),
                serde_json::json!({ "buckets": render_date_histogram_buckets(buckets, keyed) }),
            );
            continue;
        }
        if let Some(auto_date_histogram) = aggregation_object
            .get("auto_date_histogram")
            .and_then(Value::as_object)
        {
            let field = auto_date_histogram
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let minimum_interval = auto_date_histogram
                .get("minimum_interval")
                .and_then(Value::as_str)
                .unwrap_or("day");
            if !matches!(minimum_interval, "day" | "1d") {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [auto_date_histogram.minimum_interval]",
                ));
            }
            let missing = auto_date_histogram.get("missing").and_then(Value::as_str);
            let time_zone = auto_date_histogram.get("time_zone").and_then(Value::as_str);
            let Some(time_zone_offset_millis) = date_histogram_time_zone_offset_millis(time_zone)
            else {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [auto_date_histogram.time_zone]",
                ));
            };
            let format = match auto_date_histogram.get("format").and_then(Value::as_str) {
                Some("epoch_millis") => Some("epoch_millis"),
                Some("yyyy-MM-dd HH:mm:ss") => Some("yyyy-MM-dd HH:mm:ss"),
                Some("basic_date_time_no_millis") => Some("basic_date_time_no_millis"),
                Some("date") => Some("date"),
                Some(_) => {
                    return Err(build_unsupported_search_response(
                        "unsupported aggregation option [auto_date_histogram.format]",
                    ));
                }
                None => None,
            };
            let mut counts = std::collections::BTreeMap::<i64, (String, u64)>::new();
            for hit in hits {
                let raw = hit
                    .get("_source")
                    .and_then(|source| lookup_query_field_value(source, field))
                    .and_then(Value::as_str)
                    .or(missing);
                let Some(raw) = raw else { continue };
                let Some((bucket_key, bucket_string)) = date_histogram_bucket_with_offset(
                    raw,
                    FallbackDateHistogramInterval::FixedMillis(86_400_000),
                    0,
                    time_zone_offset_millis,
                    format,
                ) else {
                    continue;
                };
                let entry = counts.entry(bucket_key).or_insert((bucket_string, 0));
                entry.1 += 1;
            }
            let buckets = counts
                .into_iter()
                .map(|(key, (key_as_string, doc_count))| {
                    serde_json::json!({
                        "key": key,
                        "key_as_string": key_as_string,
                        "doc_count": doc_count,
                    })
                })
                .collect::<Vec<_>>();
            result.insert(
                name.clone(),
                serde_json::json!({
                    "buckets": buckets,
                    "interval": "1d"
                }),
            );
            continue;
        }
        if let Some(histogram) = aggregation_object
            .get("histogram")
            .and_then(Value::as_object)
        {
            let field = histogram
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let interval = histogram
                .get("interval")
                .and_then(Value::as_f64)
                .unwrap_or(0.0);
            let offset = histogram
                .get("offset")
                .and_then(Value::as_f64)
                .unwrap_or(0.0);
            let missing = histogram.get("missing").and_then(Value::as_f64);
            let min_doc_count = histogram
                .get("min_doc_count")
                .and_then(Value::as_u64)
                .unwrap_or(0);
            let extended_bounds = histogram
                .get("extended_bounds")
                .map(parse_fallback_histogram_bounds)
                .transpose()?;
            let hard_bounds = histogram
                .get("hard_bounds")
                .map(parse_fallback_histogram_bounds)
                .transpose()?;
            let keyed = histogram
                .get("keyed")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            if interval <= 0.0 || !offset.is_finite() {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation [histogram]",
                ));
            }
            let mut counts = std::collections::BTreeMap::<u64, (f64, u64)>::new();
            let mut bucket_hits = std::collections::BTreeMap::<u64, Vec<&Value>>::new();
            for hit in hits {
                let value = hit
                    .get("_source")
                    .and_then(|source| source.get(field))
                    .and_then(Value::as_f64)
                    .or(missing);
                let Some(value) = value else { continue };
                let Some(bucket) =
                    fallback_histogram_bucket_key_with_offset(value, interval, offset)
                else {
                    continue;
                };
                if !fallback_histogram_bounds_contain(hard_bounds.as_ref(), bucket) {
                    continue;
                }
                let bucket_key = bucket.to_bits();
                let entry = counts.entry(bucket_key).or_insert((bucket, 0));
                entry.1 += 1;
                bucket_hits.entry(bucket_key).or_default().push(hit);
            }
            let mut buckets = render_histogram_bucket_values_from_counts(
                &counts,
                interval,
                offset,
                min_doc_count,
                extended_bounds.as_ref(),
                hard_bounds.as_ref(),
            );
            apply_histogram_nested_aggregations(
                &mut buckets,
                aggregation_object
                    .get("aggs")
                    .or_else(|| aggregation_object.get("aggregations")),
                &bucket_hits,
            )?;
            result.insert(
                name.clone(),
                serde_json::json!({ "buckets": render_histogram_buckets(buckets, keyed) }),
            );
            continue;
        }
        if let Some(variable_width_histogram) = aggregation_object
            .get("variable_width_histogram")
            .and_then(Value::as_object)
        {
            let field = variable_width_histogram
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let target_buckets = variable_width_histogram
                .get("buckets")
                .and_then(Value::as_u64)
                .unwrap_or(10) as usize;
            if target_buckets == 0 {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [variable_width_histogram.buckets]",
                ));
            }
            let mut values = hits
                .iter()
                .filter_map(|hit| {
                    hit.get("_source")
                        .and_then(|source| lookup_query_field_value(source, field))
                        .and_then(Value::as_f64)
                })
                .filter(|value| value.is_finite())
                .collect::<Vec<_>>();
            values.sort_by(|left, right| left.total_cmp(right));
            let buckets =
                variable_width_histogram_buckets_from_sorted_values(&values, target_buckets);
            result.insert(name.clone(), serde_json::json!({ "buckets": buckets }));
            continue;
        }
        if let Some(geo_distance) = aggregation_object
            .get("geo_distance")
            .and_then(Value::as_object)
        {
            let field = geo_distance
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let Some(origin) = geo_distance
                .get("origin")
                .or_else(|| geo_distance.get("center"))
                .or_else(|| geo_distance.get("point"))
                .and_then(parse_geo_point_value)
            else {
                return Err(build_unsupported_search_response(
                    "unsupported aggregation option [geo_distance.origin]",
                ));
            };
            let unit_multiplier = geo_distance
                .get("unit")
                .and_then(Value::as_str)
                .and_then(geo_distance_unit_meters)
                .unwrap_or(1.0);
            let ranges = geo_distance
                .get("ranges")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let missing = geo_distance.get("missing").and_then(parse_geo_point_value);
            let mut buckets = Vec::new();
            for bucket in ranges {
                let Some(bucket_object) = bucket.as_object() else {
                    continue;
                };
                let from = bucket_object.get("from").and_then(Value::as_f64);
                let to = bucket_object.get("to").and_then(Value::as_f64);
                let from_meters = from.unwrap_or(0.0) * unit_multiplier;
                let to_meters = to.unwrap_or(f64::INFINITY) * unit_multiplier;
                let key = bucket_object.get("key").cloned().unwrap_or_else(|| {
                    Value::String(default_geo_distance_range_bucket_key(from, to))
                });
                let doc_count = hits
                    .iter()
                    .filter(|hit| {
                        let point = hit
                            .get("_source")
                            .and_then(|source| lookup_query_field_value(source, field))
                            .and_then(parse_geo_point_value)
                            .or(missing);
                        let Some(point) = point else { return false };
                        let distance = haversine_distance_meters(point, origin);
                        distance >= from_meters && distance < to_meters
                    })
                    .count() as u64;
                let mut rendered = serde_json::Map::new();
                rendered.insert("key".to_string(), key);
                rendered.insert("doc_count".to_string(), Value::from(doc_count));
                if let Some(from) = from {
                    rendered.insert("from".to_string(), Value::from(from));
                }
                if let Some(to) = to {
                    rendered.insert("to".to_string(), Value::from(to));
                }
                buckets.push(Value::Object(rendered));
            }
            let buckets_value = render_range_aggregation_buckets(
                buckets,
                geo_distance
                    .get("keyed")
                    .and_then(Value::as_bool)
                    .unwrap_or(false),
            );
            result.insert(
                name.clone(),
                serde_json::json!({ "buckets": buckets_value }),
            );
            continue;
        }
        if let Some(date_range) = aggregation_object
            .get("date_range")
            .and_then(Value::as_object)
        {
            let field = date_range
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let ranges = date_range
                .get("ranges")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let missing = date_range.get("missing").and_then(Value::as_str);
            let mut buckets = Vec::new();
            for bucket in ranges {
                let Some(bucket_object) = bucket.as_object() else {
                    continue;
                };
                let from = bucket_object.get("from").and_then(Value::as_str);
                let to = bucket_object.get("to").and_then(Value::as_str);
                let key = bucket_object
                    .get("key")
                    .cloned()
                    .unwrap_or_else(|| Value::String(default_date_range_bucket_key(from, to)));
                let doc_count = hits
                    .iter()
                    .filter(|hit| {
                        let value = hit
                            .get("_source")
                            .and_then(|source| source.get(field))
                            .and_then(Value::as_str)
                            .or(missing);
                        let Some(value) = value else { return false };
                        from.map_or(true, |bound| value >= bound)
                            && to.map_or(true, |bound| value < bound)
                    })
                    .count() as u64;
                let mut rendered = serde_json::Map::new();
                rendered.insert("key".to_string(), key);
                rendered.insert("doc_count".to_string(), Value::from(doc_count));
                if let Some(from) = from {
                    rendered.insert(
                        "from_as_string".to_string(),
                        Value::String(from.to_string()),
                    );
                }
                if let Some(to) = to {
                    rendered.insert("to_as_string".to_string(), Value::String(to.to_string()));
                }
                buckets.push(Value::Object(rendered));
            }
            let buckets_value = render_range_aggregation_buckets(
                buckets,
                date_range
                    .get("keyed")
                    .and_then(Value::as_bool)
                    .unwrap_or(false),
            );
            result.insert(
                name.clone(),
                serde_json::json!({ "buckets": buckets_value }),
            );
            continue;
        }
        if let Some(ip_range) = aggregation_object
            .get("ip_range")
            .and_then(Value::as_object)
        {
            let field = ip_range
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let ranges = ip_range
                .get("ranges")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let missing = ip_range
                .get("missing")
                .and_then(Value::as_str)
                .and_then(parse_ip_address_to_u128);
            let mut buckets = Vec::new();
            for bucket in ranges {
                let Some(bucket_object) = bucket.as_object() else {
                    continue;
                };
                let mask_range = bucket_object
                    .get("mask")
                    .and_then(Value::as_str)
                    .and_then(ip_cidr_range);
                let from = bucket_object
                    .get("from")
                    .and_then(Value::as_str)
                    .or_else(|| mask_range.as_ref().map(|range| range.0.as_str()));
                let to = bucket_object
                    .get("to")
                    .and_then(Value::as_str)
                    .or_else(|| mask_range.as_ref().map(|range| range.1.as_str()));
                let from_bound = from.and_then(parse_ip_address_to_u128);
                let to_bound = to.and_then(parse_ip_address_to_u128);
                let key = bucket_object
                    .get("key")
                    .cloned()
                    .unwrap_or_else(|| Value::String(default_ip_range_bucket_key(from, to)));
                let doc_count = hits
                    .iter()
                    .filter(|hit| {
                        let value = hit
                            .get("_source")
                            .and_then(|source| source.get(field))
                            .and_then(Value::as_str)
                            .and_then(parse_ip_address_to_u128)
                            .or(missing);
                        let Some(value) = value else { return false };
                        from_bound.map_or(true, |bound| value >= bound)
                            && to_bound.map_or(true, |bound| value < bound)
                    })
                    .count() as u64;
                let mut rendered = serde_json::Map::new();
                rendered.insert("key".to_string(), key);
                rendered.insert("doc_count".to_string(), Value::from(doc_count));
                if let Some(from) = from {
                    rendered.insert("from".to_string(), Value::String(from.to_string()));
                }
                if let Some(to) = to {
                    rendered.insert("to".to_string(), Value::String(to.to_string()));
                }
                buckets.push(Value::Object(rendered));
            }
            let buckets_value = render_range_aggregation_buckets(
                buckets,
                ip_range
                    .get("keyed")
                    .and_then(Value::as_bool)
                    .unwrap_or(false),
            );
            result.insert(
                name.clone(),
                serde_json::json!({ "buckets": buckets_value }),
            );
            continue;
        }
        if let Some(range) = aggregation_object.get("range").and_then(Value::as_object) {
            let field = range
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let ranges = range
                .get("ranges")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let missing = range.get("missing").and_then(Value::as_f64);
            let mut buckets = Vec::new();
            for bucket in ranges {
                let bucket_object = match bucket.as_object() {
                    Some(v) => v,
                    None => continue,
                };
                let from = bucket_object.get("from").and_then(Value::as_f64);
                let to = bucket_object.get("to").and_then(Value::as_f64);
                let key = bucket_object
                    .get("key")
                    .cloned()
                    .unwrap_or_else(|| Value::String(default_range_bucket_key(from, to)));
                let doc_count = hits
                    .iter()
                    .filter(|hit| {
                        let value = hit
                            .get("_source")
                            .and_then(|source| source.get(field))
                            .and_then(Value::as_f64)
                            .or(missing);
                        let Some(value) = value else { return false };
                        from.map_or(true, |bound| value >= bound)
                            && to.map_or(true, |bound| value < bound)
                    })
                    .count() as u64;
                buckets.push(serde_json::json!({ "key": key, "doc_count": doc_count }));
            }
            let buckets_value = render_range_aggregation_buckets(
                buckets,
                range.get("keyed").and_then(Value::as_bool).unwrap_or(false),
            );
            result.insert(
                name.clone(),
                serde_json::json!({ "buckets": buckets_value }),
            );
            continue;
        }
        if let Some(cardinality) = aggregation_object
            .get("cardinality")
            .and_then(Value::as_object)
        {
            let field = cardinality
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let mut seen = std::collections::BTreeSet::new();
            for hit in hits {
                if let Some(value) = hit.get("_source").and_then(|source| source.get(field)) {
                    seen.insert(value.to_string());
                }
            }
            result.insert(name.clone(), serde_json::json!({ "value": seen.len() }));
            continue;
        }
        if let Some(significant_terms) = aggregation_object
            .get("significant_terms")
            .and_then(Value::as_object)
        {
            let field = significant_terms
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let size = significant_terms
                .get("size")
                .and_then(Value::as_u64)
                .unwrap_or(10) as usize;
            let min_doc_count = significant_terms
                .get("min_doc_count")
                .and_then(Value::as_u64)
                .unwrap_or(3);
            let background_filter = significant_terms.get("background_filter");
            let background_hits = if background_filter.is_some() {
                hits.iter()
                    .filter(|hit| {
                        background_filter.is_some_and(|filter| hit_matches_query(hit, filter))
                    })
                    .collect::<Vec<_>>()
            } else {
                hits.iter().collect::<Vec<_>>()
            };
            result.insert(
                name.clone(),
                build_fallback_significant_terms_aggregation(
                    field,
                    size,
                    min_doc_count,
                    significant_terms.get("include"),
                    significant_terms.get("exclude"),
                    hits,
                    &background_hits,
                )?,
            );
            continue;
        }
        if let Some(significant_text) = aggregation_object
            .get("significant_text")
            .and_then(Value::as_object)
        {
            let field = significant_text
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let size = significant_text
                .get("size")
                .and_then(Value::as_u64)
                .unwrap_or(10) as usize;
            let min_doc_count = significant_text
                .get("min_doc_count")
                .and_then(Value::as_u64)
                .unwrap_or(3);
            let background_filter = significant_text.get("background_filter");
            let background_hits = if background_filter.is_some() {
                hits.iter()
                    .filter(|hit| {
                        background_filter.is_some_and(|filter| hit_matches_query(hit, filter))
                    })
                    .collect::<Vec<_>>()
            } else {
                hits.iter().collect::<Vec<_>>()
            };
            result.insert(
                name.clone(),
                build_fallback_significant_text_aggregation(
                    field,
                    size,
                    min_doc_count,
                    hits,
                    &background_hits,
                ),
            );
            continue;
        }
        if let Some(geo_bounds) = aggregation_object
            .get("geo_bounds")
            .and_then(Value::as_object)
        {
            let field = geo_bounds
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let mut min_lat = f64::INFINITY;
            let mut max_lat = f64::NEG_INFINITY;
            let mut min_lon = f64::INFINITY;
            let mut max_lon = f64::NEG_INFINITY;
            for hit in hits {
                let Some(point) = hit.get("_source").and_then(|source| source.get(field)) else {
                    continue;
                };
                let Some(lat) = point.get("lat").and_then(Value::as_f64) else {
                    continue;
                };
                let Some(lon) = point.get("lon").and_then(Value::as_f64) else {
                    continue;
                };
                min_lat = min_lat.min(lat);
                max_lat = max_lat.max(lat);
                min_lon = min_lon.min(lon);
                max_lon = max_lon.max(lon);
            }
            result.insert(
                name.clone(),
                serde_json::json!({
                    "bounds": {
                        "top_left": { "lat": max_lat, "lon": min_lon },
                        "bottom_right": { "lat": min_lat, "lon": max_lon }
                    }
                }),
            );
            continue;
        }
        if let Some(geo_centroid) = aggregation_object
            .get("geo_centroid")
            .and_then(Value::as_object)
        {
            let field = geo_centroid
                .get("field")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let mut lat_sum = 0.0;
            let mut lon_sum = 0.0;
            let mut count = 0_u64;
            for hit in hits {
                let Some(point) = hit
                    .get("_source")
                    .and_then(|source| lookup_query_field_value(source, field))
                    .and_then(parse_geo_point_value)
                else {
                    continue;
                };
                lat_sum += lucene_geo_decode_latitude(lucene_geo_encode_latitude(point.0));
                lon_sum += lucene_geo_decode_longitude(lucene_geo_encode_longitude(point.1));
                count += 1;
            }
            let mut body = serde_json::Map::new();
            if count > 0 {
                body.insert(
                    "location".to_string(),
                    serde_json::json!({
                        "lat": lat_sum / (count as f64),
                        "lon": lon_sum / (count as f64),
                    }),
                );
            }
            body.insert("count".to_string(), Value::from(count));
            result.insert(name.clone(), Value::Object(body));
            continue;
        }
        if let Some((pipeline_kind, pipeline_object)) =
            first_supported_bucket_metric_pipeline_aggregation(aggregation_object)
        {
            let buckets_path = pipeline_object
                .get("buckets_path")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let prefix = buckets_path.split('>').next().unwrap_or_default();
            let counts = terms_doc_counts
                .get(prefix)
                .map(|buckets| {
                    buckets
                        .iter()
                        .map(|(_, count)| *count as f64)
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            if pipeline_kind == "stats_bucket" {
                result.insert(
                    name.clone(),
                    serde_json::json!({
                        "count": counts.len(),
                        "min": counts.iter().copied().reduce(f64::min).unwrap_or(0.0),
                        "max": counts.iter().copied().reduce(f64::max).unwrap_or(0.0),
                        "avg": if counts.is_empty() { 0.0 } else { counts.iter().sum::<f64>() / counts.len() as f64 },
                        "sum": counts.iter().sum::<f64>(),
                    }),
                );
                continue;
            }
            if pipeline_kind == "extended_stats_bucket" {
                result.insert(
                    name.clone(),
                    extended_stats_aggregation_value(
                        &counts,
                        pipeline_object
                            .get("sigma")
                            .and_then(metric_missing_value)
                            .unwrap_or(2.0),
                    ),
                );
                continue;
            }
            if pipeline_kind == "percentiles_bucket" {
                let requested_percentiles = pipeline_object.get("percents").and_then(|value| {
                    value
                        .as_array()
                        .map(|values| values.iter().filter_map(Value::as_f64).collect::<Vec<_>>())
                });
                result.insert(
                    name.clone(),
                    percentiles_aggregation_value(&counts, requested_percentiles.as_deref()),
                );
                continue;
            }
            let value = match pipeline_kind {
                "sum_bucket" => counts.iter().sum::<f64>(),
                "avg_bucket" => {
                    if counts.is_empty() {
                        0.0
                    } else {
                        counts.iter().sum::<f64>() / counts.len() as f64
                    }
                }
                "min_bucket" => counts.iter().copied().reduce(f64::min).unwrap_or(0.0),
                "max_bucket" => counts.iter().copied().reduce(f64::max).unwrap_or(0.0),
                _ => 0.0,
            };
            result.insert(name.clone(), serde_json::json!({ "value": value }));
            continue;
        }
        if let Some(scripted_metric) = aggregation_object
            .get("scripted_metric")
            .and_then(Value::as_object)
        {
            let init_ok = scripted_metric
                .get("init_script")
                .and_then(Value::as_str)
                .map(|script| script == "state.count = 0")
                .unwrap_or(false);
            let map_ok = scripted_metric
                .get("map_script")
                .and_then(Value::as_str)
                .map(|script| script == "state.count += params.inc")
                .unwrap_or(false);
            let combine_ok = scripted_metric
                .get("combine_script")
                .and_then(Value::as_str)
                .map(|script| script == "return state.count")
                .unwrap_or(false);
            let reduce_ok = scripted_metric
                .get("reduce_script")
                .and_then(Value::as_str)
                .map(|script| script == "double sum = 0; for (s in states) { sum += s } return sum")
                .unwrap_or(false);
            if init_ok && map_ok && combine_ok && reduce_ok {
                let increment = scripted_metric
                    .get("params")
                    .and_then(|params| params.get("inc"))
                    .and_then(Value::as_f64)
                    .unwrap_or(1.0);
                result.insert(
                    name.clone(),
                    serde_json::json!({
                        "value": (hits.len() as f64) * increment
                    }),
                );
                continue;
            }
            return Err(build_unsupported_search_response(
                "unsupported aggregation [scripted_metric]",
            ));
        }
    }
    Ok(Some(Value::Object(result)))
}

fn apply_terms_bucket_parent_pipeline_transforms(
    bucket_values: &mut Vec<Value>,
    nested_aggs: Option<&Value>,
) {
    let Some(nested_aggs) = nested_aggs.and_then(Value::as_object) else {
        return;
    };
    for (name, aggregation) in nested_aggs {
        if let Some(script) = aggregation
            .get("bucket_script")
            .and_then(parent_bucket_script_transform)
        {
            apply_parent_bucket_script(bucket_values, name, &script);
        }
    }
    for aggregation in nested_aggs.values() {
        if let Some(selector) = aggregation
            .get("bucket_selector")
            .and_then(parent_bucket_selector_filter)
        {
            bucket_values.retain(|bucket| {
                bucket_selector_bucket_value(bucket, &selector.path)
                    .map(|value| {
                        compare_parent_bucket_selector_value(
                            value,
                            selector.operator,
                            selector.threshold,
                        )
                    })
                    .unwrap_or(false)
            });
        }
        if let Some(sort) = aggregation
            .get("bucket_sort")
            .and_then(parent_bucket_sort_transform)
        {
            apply_parent_bucket_sort(bucket_values, &sort);
        }
    }
}

#[derive(Clone)]
struct ParentBucketSelectorFilter {
    path: String,
    operator: &'static str,
    threshold: f64,
}

fn parent_bucket_selector_filter(selector: &Value) -> Option<ParentBucketSelectorFilter> {
    let selector = selector.as_object()?;
    let (alias, path) = parent_bucket_selector_buckets_path(selector.get("buckets_path")?)?;
    let script = parent_bucket_selector_script_source(selector.get("script")?)?;
    let (operator, threshold) = parse_parent_bucket_selector_script(script, alias)?;
    Some(ParentBucketSelectorFilter {
        path: path.to_string(),
        operator,
        threshold,
    })
}

fn parent_bucket_selector_buckets_path(value: &Value) -> Option<(&str, &str)> {
    if value.as_str().is_some_and(|path| path == "_count") {
        return Some(("_value", "_count"));
    }
    let object = value.as_object()?;
    let (alias, path) = object.iter().next()?;
    Some((alias.as_str(), path.as_str()?))
}

fn parent_bucket_selector_script_source(value: &Value) -> Option<&str> {
    value
        .as_str()
        .or_else(|| value.as_object()?.get("source")?.as_str())
}

fn parse_parent_bucket_selector_script(script: &str, alias: &str) -> Option<(&'static str, f64)> {
    let trimmed = script.trim();
    if alias == "_value" {
        return parse_parent_bucket_selector_script_for_variable(trimmed, "_value");
    }
    parse_parent_bucket_selector_script_for_variable(trimmed, &format!("params.{alias}"))
}

fn parse_parent_bucket_selector_script_for_variable(
    script: &str,
    variable: &str,
) -> Option<(&'static str, f64)> {
    let expression = script.strip_prefix(variable)?.trim_start();
    for (token, operator) in [
        (">=", "gte"),
        ("<=", "lte"),
        ("==", "eq"),
        ("!=", "ne"),
        (">", "gt"),
        ("<", "lt"),
    ] {
        let Some(rest) = expression.strip_prefix(token) else {
            continue;
        };
        let threshold = rest.trim().parse::<f64>().ok()?;
        return Some((operator, threshold));
    }
    None
}

fn bucket_selector_bucket_value(bucket: &Value, path: &str) -> Option<f64> {
    if path == "_count" {
        return bucket.get("doc_count").and_then(Value::as_f64);
    }
    bucket
        .get(path)
        .and_then(|value| value.get("value"))
        .and_then(Value::as_f64)
        .or_else(|| bucket.get(path).and_then(Value::as_f64))
}

fn compare_parent_bucket_selector_value(value: f64, operator: &str, threshold: f64) -> bool {
    match operator {
        "gt" => value > threshold,
        "gte" => value >= threshold,
        "lt" => value < threshold,
        "lte" => value <= threshold,
        "eq" => value == threshold,
        "ne" => value != threshold,
        _ => false,
    }
}

#[derive(Clone)]
struct ParentBucketScriptTransform {
    path: String,
    script: ParentBucketScriptExpression,
}

#[derive(Clone)]
struct ParentBucketScriptExpression {
    alias: String,
    operator: Option<char>,
    operand: Option<f64>,
}

fn parent_bucket_script_transform(bucket_script: &Value) -> Option<ParentBucketScriptTransform> {
    let bucket_script = bucket_script.as_object()?;
    let (alias, path) = parent_bucket_script_buckets_path(bucket_script.get("buckets_path")?)?;
    let source = parent_bucket_selector_script_source(bucket_script.get("script")?)?;
    let script = parse_parent_bucket_script_expression(source, alias)?;
    Some(ParentBucketScriptTransform {
        path: path.to_string(),
        script,
    })
}

fn parent_bucket_script_buckets_path(value: &Value) -> Option<(&str, &str)> {
    if value.as_str().is_some_and(|path| path == "_count") {
        return Some(("_value", "_count"));
    }
    let object = value.as_object()?;
    let (alias, path) = object.iter().next()?;
    Some((alias.as_str(), path.as_str()?))
}

fn parse_parent_bucket_script_expression(
    script: &str,
    alias: &str,
) -> Option<ParentBucketScriptExpression> {
    let variable = if alias == "_value" {
        "_value".to_string()
    } else {
        format!("params.{alias}")
    };
    let rest = script.trim().strip_prefix(&variable)?.trim_start();
    if rest.is_empty() {
        return Some(ParentBucketScriptExpression {
            alias: alias.to_string(),
            operator: None,
            operand: None,
        });
    }
    let mut chars = rest.chars();
    let operator = chars.next()?;
    if !matches!(operator, '+' | '-' | '*' | '/') {
        return None;
    }
    let operand = chars.as_str().trim().parse::<f64>().ok()?;
    Some(ParentBucketScriptExpression {
        alias: alias.to_string(),
        operator: Some(operator),
        operand: Some(operand),
    })
}

fn apply_parent_bucket_script(
    bucket_values: &mut [Value],
    aggregation_name: &str,
    script: &ParentBucketScriptTransform,
) {
    for bucket in bucket_values {
        let Some(input) = bucket_selector_bucket_value(bucket, &script.path) else {
            continue;
        };
        let value = evaluate_parent_bucket_script_expression(input, &script.script);
        if let Some(bucket_object) = bucket.as_object_mut() {
            bucket_object.insert(
                aggregation_name.to_string(),
                serde_json::json!({ "value": value }),
            );
        }
    }
}

fn evaluate_parent_bucket_script_expression(
    input: f64,
    script: &ParentBucketScriptExpression,
) -> f64 {
    let _ = &script.alias;
    match (script.operator, script.operand) {
        (Some('+'), Some(operand)) => input + operand,
        (Some('-'), Some(operand)) => input - operand,
        (Some('*'), Some(operand)) => input * operand,
        (Some('/'), Some(operand)) => input / operand,
        _ => input,
    }
}

#[derive(Clone)]
struct ParentBucketSortTransform {
    sort: Vec<ParentBucketSortSpec>,
    from: usize,
    size: Option<usize>,
}

#[derive(Clone)]
struct ParentBucketSortSpec {
    path: &'static str,
    ascending: bool,
}

fn parent_bucket_sort_transform(bucket_sort: &Value) -> Option<ParentBucketSortTransform> {
    let bucket_sort = bucket_sort.as_object()?;
    let sort = bucket_sort
        .get("sort")
        .and_then(Value::as_array)
        .map(|values| {
            values
                .iter()
                .filter_map(parent_bucket_sort_spec)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let from = bucket_sort.get("from").and_then(Value::as_u64).unwrap_or(0) as usize;
    let size = bucket_sort
        .get("size")
        .and_then(Value::as_u64)
        .map(|value| value as usize);
    Some(ParentBucketSortTransform { sort, from, size })
}

fn parent_bucket_sort_spec(value: &Value) -> Option<ParentBucketSortSpec> {
    let object = value.as_object()?;
    let (field, order_value) = object.iter().next()?;
    let ascending = match order_value {
        Value::String(order) => order != "desc",
        Value::Object(order_object) => order_object
            .get("order")
            .and_then(Value::as_str)
            .map_or(true, |order| order != "desc"),
        _ => true,
    };
    let path = match field.as_str() {
        "_count" => "_count",
        "_key" => "_key",
        _ => return None,
    };
    Some(ParentBucketSortSpec { path, ascending })
}

fn apply_parent_bucket_sort(bucket_values: &mut Vec<Value>, sort: &ParentBucketSortTransform) {
    if !sort.sort.is_empty() {
        bucket_values.sort_by(|left, right| {
            for spec in &sort.sort {
                let ordering = compare_parent_bucket_sort_spec(left, right, spec);
                if ordering != std::cmp::Ordering::Equal {
                    return if spec.ascending {
                        ordering
                    } else {
                        ordering.reverse()
                    };
                }
            }
            std::cmp::Ordering::Equal
        });
    }
    if sort.from > 0 {
        let from = sort.from.min(bucket_values.len());
        bucket_values.drain(0..from);
    }
    if let Some(size) = sort.size {
        bucket_values.truncate(size);
    }
}

fn compare_parent_bucket_sort_spec(
    left: &Value,
    right: &Value,
    spec: &ParentBucketSortSpec,
) -> std::cmp::Ordering {
    match spec.path {
        "_count" => left
            .get("doc_count")
            .and_then(Value::as_u64)
            .cmp(&right.get("doc_count").and_then(Value::as_u64)),
        "_key" => aggregation_bucket_sort_key(left.get("key").unwrap_or(&Value::Null)).cmp(
            &aggregation_bucket_sort_key(right.get("key").unwrap_or(&Value::Null)),
        ),
        _ => std::cmp::Ordering::Equal,
    }
}

fn apply_typed_aggregation_keys(aggregations: &mut Option<Value>, request_aggs: Option<&Value>) {
    let Some(response_aggs) = aggregations.as_mut().and_then(Value::as_object_mut) else {
        return;
    };
    let Some(request_aggs) = request_aggs.and_then(Value::as_object) else {
        return;
    };
    apply_typed_aggregation_keys_to_map(response_aggs, request_aggs);
}

fn apply_typed_aggregation_keys_to_map(
    response_aggs: &mut serde_json::Map<String, Value>,
    request_aggs: &serde_json::Map<String, Value>,
) {
    let mut replacements = Vec::new();
    for (name, request_agg) in request_aggs {
        let Some(response_value) = response_aggs.remove(name) else {
            continue;
        };
        let typed_name =
            typed_aggregation_response_name(name, request_agg).unwrap_or_else(|| name.to_string());
        let response_value = typed_nested_aggregation_value(response_value, request_agg);
        replacements.push((typed_name, response_value));
    }
    for (name, value) in replacements {
        response_aggs.insert(name, value);
    }
}

fn typed_nested_aggregation_value(mut response_value: Value, request_agg: &Value) -> Value {
    let Some(nested_request_aggs) = request_agg.as_object().and_then(|aggregation| {
        aggregation
            .get("aggs")
            .or_else(|| aggregation.get("aggregations"))
    }) else {
        return response_value;
    };
    let Some(response_object) = response_value.as_object_mut() else {
        return response_value;
    };
    if let Some(nested_request_aggs) = nested_request_aggs.as_object() {
        apply_typed_aggregation_keys_to_map(response_object, nested_request_aggs);
        if let Some(buckets) = response_object.get_mut("buckets") {
            match buckets {
                Value::Array(bucket_values) => {
                    for bucket in bucket_values {
                        if let Some(bucket_object) = bucket.as_object_mut() {
                            apply_typed_aggregation_keys_to_map(bucket_object, nested_request_aggs);
                        }
                    }
                }
                Value::Object(bucket_values) => {
                    for bucket in bucket_values.values_mut() {
                        if let Some(bucket_object) = bucket.as_object_mut() {
                            apply_typed_aggregation_keys_to_map(bucket_object, nested_request_aggs);
                        }
                    }
                }
                _ => {}
            }
        }
    }
    response_value
}

fn typed_aggregation_response_name(name: &str, request_agg: &Value) -> Option<String> {
    let aggregation = request_agg.as_object()?;
    let aggregation_type = typed_aggregation_prefix(aggregation)?;
    Some(format!("{aggregation_type}#{name}"))
}

