fn default_range_bucket_key(from: Option<f64>, to: Option<f64>) -> String {
    match (from, to) {
        (Some(from), Some(to)) => format!("{from}-{to}"),
        (Some(from), None) => format!("{from}-*"),
        (None, Some(to)) => format!("*-{to}"),
        (None, None) => "*".to_string(),
    }
}

fn default_date_range_bucket_key(from: Option<&str>, to: Option<&str>) -> String {
    match (from, to) {
        (Some(from), Some(to)) => format!("{from}-{to}"),
        (Some(from), None) => format!("{from}-*"),
        (None, Some(to)) => format!("*-{to}"),
        (None, None) => "*".to_string(),
    }
}

fn default_ip_range_bucket_key(from: Option<&str>, to: Option<&str>) -> String {
    match (from, to) {
        (Some(from), Some(to)) => format!("{from}-{to}"),
        (Some(from), None) => format!("{from}-*"),
        (None, Some(to)) => format!("*-{to}"),
        (None, None) => "*".to_string(),
    }
}

fn default_geo_distance_range_bucket_key(from: Option<f64>, to: Option<f64>) -> String {
    match (from, to) {
        (Some(from), Some(to)) => format!("{from}-{to}"),
        (Some(from), None) => format!("{from}-*"),
        (None, Some(to)) => format!("*-{to}"),
        (None, None) => "*-*".to_string(),
    }
}

fn render_range_aggregation_buckets(buckets: Vec<Value>, keyed: bool) -> Value {
    if !keyed {
        return Value::Array(buckets);
    }
    let mut keyed_buckets = serde_json::Map::new();
    for bucket in buckets {
        let Some(key) = bucket
            .get("key")
            .and_then(Value::as_str)
            .map(ToString::to_string)
        else {
            continue;
        };
        let mut visible_bucket = bucket;
        if let Some(object) = visible_bucket.as_object_mut() {
            object.remove("key");
        }
        keyed_buckets.insert(key, visible_bucket);
    }
    Value::Object(keyed_buckets)
}

fn geo_distance_unit_meters(unit: &str) -> Option<f64> {
    match unit.to_ascii_lowercase().as_str() {
        "m" | "meter" | "meters" => Some(1.0),
        "km" | "kilometer" | "kilometers" => Some(1000.0),
        "mi" | "mile" | "miles" => Some(1609.344),
        _ => None,
    }
}

fn parse_ip_address_to_u128(value: &str) -> Option<u128> {
    match value.parse::<std::net::IpAddr>().ok()? {
        std::net::IpAddr::V4(ip) => Some(u32::from(ip) as u128),
        std::net::IpAddr::V6(ip) => Some(u128::from(ip)),
    }
}

fn ip_cidr_range(mask: &str) -> Option<(String, String)> {
    use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};

    let (address, prefix) = mask.split_once('/')?;
    let prefix = prefix.parse::<u32>().ok()?;
    match address.parse::<IpAddr>().ok()? {
        IpAddr::V4(ip) => {
            if prefix == 0 || prefix > 32 {
                return None;
            }
            let bits = u32::from(ip);
            let network_mask = u32::MAX << (32 - prefix);
            let start = bits & network_mask;
            let end = start.checked_add(1u32 << (32 - prefix))?;
            Some((
                Ipv4Addr::from(start).to_string(),
                Ipv4Addr::from(end).to_string(),
            ))
        }
        IpAddr::V6(ip) => {
            if prefix == 0 || prefix > 128 {
                return None;
            }
            let bits = u128::from(ip);
            let network_mask = u128::MAX << (128 - prefix);
            let start = bits & network_mask;
            let end = start.checked_add(1u128 << (128 - prefix))?;
            Some((
                Ipv6Addr::from(start).to_string(),
                Ipv6Addr::from(end).to_string(),
            ))
        }
    }
}

fn aggregation_bucket_sort_key(value: &Value) -> String {
    match value {
        Value::String(value) => value.clone(),
        other => other.to_string(),
    }
}

fn aggregation_bucket_key_cmp(left: &Value, right: &Value) -> std::cmp::Ordering {
    match (left, right) {
        (Value::Number(left), Value::Number(right)) => {
            let left = left.as_f64().unwrap_or(f64::NAN);
            let right = right.as_f64().unwrap_or(f64::NAN);
            left.partial_cmp(&right)
                .unwrap_or(std::cmp::Ordering::Equal)
        }
        _ => aggregation_bucket_sort_key(left).cmp(&aggregation_bucket_sort_key(right)),
    }
}

fn aggregation_term_is_allowed_by_include_exclude(
    value: &Value,
    include: Option<&Value>,
    exclude: Option<&Value>,
) -> Result<bool, RestResponse> {
    if let Some(include) = include {
        if !aggregation_term_matches_filter(value, include)? {
            return Ok(false);
        }
    }
    if let Some(exclude) = exclude {
        if aggregation_term_matches_filter(value, exclude)? {
            return Ok(false);
        }
    }
    Ok(true)
}

fn aggregation_term_matches_filter(value: &Value, filter: &Value) -> Result<bool, RestResponse> {
    let sort_key = aggregation_bucket_sort_key(value);
    match filter {
        Value::String(pattern) => {
            let anchored_pattern = format!("^(?:{pattern})$");
            let regex = regex::Regex::new(&anchored_pattern).map_err(|_| {
                build_unsupported_search_response(
                    "unsupported aggregation option [include/exclude]",
                )
            })?;
            Ok(regex.is_match(&sort_key))
        }
        Value::Array(values) => Ok(values
            .iter()
            .any(|candidate| sort_key == aggregation_bucket_sort_key(candidate))),
        Value::Object(object) => Ok(aggregation_term_matches_partition(value, object)),
        _ => Ok(false),
    }
}

fn aggregation_term_matches_partition(
    value: &Value,
    object: &serde_json::Map<String, Value>,
) -> bool {
    let Some(partition) = object.get("partition").and_then(Value::as_u64) else {
        return false;
    };
    let Some(num_partitions) = object.get("num_partitions").and_then(Value::as_u64) else {
        return false;
    };
    if num_partitions == 0 || partition >= num_partitions {
        return false;
    }
    let hash = aggregation_term_partition_hash(value);
    hash.rem_euclid(num_partitions as i64) == partition as i64
}

fn aggregation_include_filter_is_partition(value: &Value) -> bool {
    value.as_object().is_some_and(|object| {
        object.contains_key("partition") || object.contains_key("num_partitions")
    })
}

fn aggregation_term_partition_hash(value: &Value) -> i64 {
    match value {
        Value::Number(number) => {
            if let Some(value) = number.as_i64() {
                opensearch_bit_mixer_mix64(value)
            } else if let Some(value) = number.as_u64() {
                opensearch_bit_mixer_mix64(value as i64)
            } else if let Some(value) = number.as_f64() {
                opensearch_bit_mixer_mix64(value.to_bits() as i64)
            } else {
                opensearch_terms_partition_hash(aggregation_bucket_sort_key(value).as_bytes())
            }
        }
        _ => opensearch_terms_partition_hash(aggregation_bucket_sort_key(value).as_bytes()),
    }
}

fn opensearch_terms_partition_hash(value: &[u8]) -> i64 {
    opensearch_murmur3_x86_32(value, 31)
}

fn opensearch_bit_mixer_mix64(value: i64) -> i64 {
    let mut z = value as u64;
    z = (z ^ (z >> 32)).wrapping_mul(0x4cd6_944c_5cc2_0b6d);
    z = (z ^ (z >> 29)).wrapping_mul(0xfc12_c5b1_9d32_59e9);
    (z ^ (z >> 32)) as i64
}

fn aggregation_multi_terms_sort_key(values: &[Value]) -> String {
    values
        .iter()
        .map(aggregation_bucket_sort_key)
        .collect::<Vec<_>>()
        .join("\u{1f}")
}

fn aggregation_multi_terms_key_as_string(values: &[Value]) -> String {
    values
        .iter()
        .map(aggregation_bucket_sort_key)
        .collect::<Vec<_>>()
        .join("|")
}

fn variable_width_histogram_buckets_from_sorted_values(
    values: &[f64],
    target_buckets: usize,
) -> Vec<Value> {
    if values.is_empty() {
        return Vec::new();
    }
    let target_buckets = target_buckets.max(1).min(values.len());
    let mut buckets = Vec::with_capacity(target_buckets);
    let mut start = 0usize;
    for bucket_index in 0..target_buckets {
        let remaining_values = values.len() - start;
        let remaining_buckets = target_buckets - bucket_index;
        let group_len = remaining_values.div_ceil(remaining_buckets);
        let end = (start + group_len).min(values.len());
        let group = &values[start..end];
        let sum = group.iter().sum::<f64>();
        let key = sum / (group.len() as f64);
        buckets.push(serde_json::json!({
            "key": key,
            "min": group.first().copied().unwrap_or(key),
            "max": group.last().copied().unwrap_or(key),
            "doc_count": group.len() as u64,
        }));
        start = end;
    }
    buckets
}

fn fallback_histogram_bucket_key_with_offset(
    value: f64,
    interval: f64,
    offset: f64,
) -> Option<f64> {
    if !interval.is_finite() || interval <= 0.0 || !value.is_finite() || !offset.is_finite() {
        return None;
    }
    Some(((value - offset) / interval).floor() * interval + offset)
}

#[derive(Clone, Copy)]
struct FallbackHistogramBounds {
    min: Option<f64>,
    max: Option<f64>,
}

fn parse_fallback_histogram_bounds(value: &Value) -> Result<FallbackHistogramBounds, RestResponse> {
    let Some(object) = value.as_object() else {
        return Err(build_unsupported_search_response(
            "unsupported aggregation [histogram]",
        ));
    };
    let min = object.get("min").and_then(|value| {
        if value.is_null() {
            None
        } else {
            value.as_f64()
        }
    });
    let max = object.get("max").and_then(|value| {
        if value.is_null() {
            None
        } else {
            value.as_f64()
        }
    });
    if min.is_some_and(|value| !value.is_finite())
        || max.is_some_and(|value| !value.is_finite())
        || matches!((min, max), (Some(min), Some(max)) if max < min)
    {
        return Err(build_unsupported_search_response(
            "unsupported aggregation [histogram]",
        ));
    }
    Ok(FallbackHistogramBounds { min, max })
}

fn collect_nested_child_hits(hits: &[Value], path: &str) -> Vec<Value> {
    let mut nested_hits = Vec::new();
    for hit in hits {
        let Some(source) = hit.get("_source") else {
            continue;
        };
        let Some(value) = lookup_query_field_value(source, path) else {
            continue;
        };
        match value {
            Value::Array(children) => {
                for (index, child) in children.iter().enumerate() {
                    if !child.is_object() {
                        continue;
                    }
                    let parent_id = hit.get("_id").and_then(Value::as_str).unwrap_or_default();
                    nested_hits.push(serde_json::json!({
                        "_id": format!("{parent_id}#{path}#{index}"),
                        "_source": child,
                        "_nested_parent": hit
                    }));
                }
            }
            Value::Object(_) => {
                let parent_id = hit.get("_id").and_then(Value::as_str).unwrap_or_default();
                nested_hits.push(serde_json::json!({
                    "_id": format!("{parent_id}#{path}#0"),
                    "_source": value,
                    "_nested_parent": hit
                }));
            }
            _ => {}
        }
    }
    nested_hits
}

fn collect_reverse_nested_parent_hits(hits: &[Value]) -> Vec<Value> {
    let mut seen = std::collections::BTreeSet::new();
    let mut parents = Vec::new();
    for hit in hits {
        let Some(parent) = hit.get("_nested_parent") else {
            continue;
        };
        let parent_id = parent
            .get("_id")
            .and_then(Value::as_str)
            .unwrap_or_default();
        if seen.insert(parent_id.to_string()) {
            parents.push(parent.clone());
        }
    }
    parents
}

#[derive(Clone, Copy)]
enum FallbackDateHistogramInterval {
    FixedMillis(i64),
    CalendarWeek,
    CalendarMonth,
    CalendarYear,
}

fn date_histogram_bucket_with_offset(
    timestamp: &str,
    interval: FallbackDateHistogramInterval,
    offset_millis: i64,
    time_zone_offset_millis: i64,
    format: Option<&str>,
) -> Option<(i64, String)> {
    let millis = date_histogram_epoch_millis(timestamp)?;
    let bucket_key = date_histogram_bucket_key_with_offset(
        millis,
        interval,
        offset_millis,
        time_zone_offset_millis,
    )?;
    Some((
        bucket_key,
        date_histogram_key_as_string_from_epoch_millis(
            bucket_key,
            time_zone_offset_millis,
            format,
        )?,
    ))
}

fn date_histogram_bucket_key_with_offset(
    epoch_millis: i64,
    interval: FallbackDateHistogramInterval,
    offset_millis: i64,
    time_zone_offset_millis: i64,
) -> Option<i64> {
    let shifted = epoch_millis
        .checked_add(time_zone_offset_millis)?
        .checked_sub(offset_millis)?;
    match interval {
        FallbackDateHistogramInterval::FixedMillis(interval_millis) => {
            if interval_millis <= 0 {
                return None;
            }
            shifted
                .div_euclid(interval_millis)
                .checked_mul(interval_millis)?
                .checked_add(offset_millis)?
                .checked_sub(time_zone_offset_millis)
        }
        FallbackDateHistogramInterval::CalendarMonth => {
            let days = shifted.div_euclid(86_400_000);
            let (year, month, _) = civil_from_days(days)?;
            days_from_civil(year, month, 1)?
                .checked_mul(86_400_000)?
                .checked_add(offset_millis)?
                .checked_sub(time_zone_offset_millis)
        }
        FallbackDateHistogramInterval::CalendarWeek => {
            let days = shifted.div_euclid(86_400_000);
            let weekday_offset = days.checked_add(3)?.rem_euclid(7);
            days.checked_sub(weekday_offset)?
                .checked_mul(86_400_000)?
                .checked_add(offset_millis)?
                .checked_sub(time_zone_offset_millis)
        }
        FallbackDateHistogramInterval::CalendarYear => {
            let days = shifted.div_euclid(86_400_000);
            let (year, _, _) = civil_from_days(days)?;
            days_from_civil(year, 1, 1)?
                .checked_mul(86_400_000)?
                .checked_add(offset_millis)?
                .checked_sub(time_zone_offset_millis)
        }
    }
}

fn next_date_histogram_bucket_key(
    key: i64,
    interval: FallbackDateHistogramInterval,
    offset_millis: i64,
    time_zone_offset_millis: i64,
) -> Option<i64> {
    match interval {
        FallbackDateHistogramInterval::FixedMillis(interval_millis) => {
            key.checked_add(interval_millis)
        }
        FallbackDateHistogramInterval::CalendarMonth => {
            let local_key = key
                .checked_add(time_zone_offset_millis)?
                .checked_sub(offset_millis)?;
            let days = local_key.div_euclid(86_400_000);
            let (year, month, _) = civil_from_days(days)?;
            let (next_year, next_month) = if month == 12 {
                (year.checked_add(1)?, 1)
            } else {
                (year, month + 1)
            };
            days_from_civil(next_year, next_month, 1)?
                .checked_mul(86_400_000)?
                .checked_add(offset_millis)?
                .checked_sub(time_zone_offset_millis)
        }
        FallbackDateHistogramInterval::CalendarWeek => {
            let local_key = key
                .checked_add(time_zone_offset_millis)?
                .checked_sub(offset_millis)?;
            local_key
                .checked_add(7_i64.checked_mul(86_400_000)?)?
                .checked_add(offset_millis)?
                .checked_sub(time_zone_offset_millis)
        }
        FallbackDateHistogramInterval::CalendarYear => {
            let local_key = key
                .checked_add(time_zone_offset_millis)?
                .checked_sub(offset_millis)?;
            let days = local_key.div_euclid(86_400_000);
            let (year, _, _) = civil_from_days(days)?;
            days_from_civil(year.checked_add(1)?, 1, 1)?
                .checked_mul(86_400_000)?
                .checked_add(offset_millis)?
                .checked_sub(time_zone_offset_millis)
        }
    }
}

fn date_histogram_interval_kind(interval: &str) -> Option<FallbackDateHistogramInterval> {
    match interval {
        "minute" | "1m" => Some(FallbackDateHistogramInterval::FixedMillis(60_000)),
        "hour" | "1h" => Some(FallbackDateHistogramInterval::FixedMillis(3_600_000)),
        "day" | "1d" => Some(FallbackDateHistogramInterval::FixedMillis(86_400_000)),
        "week" | "1w" => Some(FallbackDateHistogramInterval::CalendarWeek),
        "month" | "1M" => Some(FallbackDateHistogramInterval::CalendarMonth),
        "year" | "1y" => Some(FallbackDateHistogramInterval::CalendarYear),
        _ => None,
    }
}

fn date_histogram_epoch_millis(timestamp: &str) -> Option<i64> {
    let date = timestamp.get(0..10)?;
    let year: i32 = date.get(0..4)?.parse().ok()?;
    let month: u32 = date.get(5..7)?.parse().ok()?;
    let day: u32 = date.get(8..10)?.parse().ok()?;
    let days = days_from_civil(year, month, day)?;
    let mut millis = days.checked_mul(86_400_000)?;
    let Some(time) = timestamp.get(11..) else {
        return Some(millis);
    };
    let hour: i64 = time.get(0..2)?.parse().ok()?;
    let minute: i64 = time.get(3..5)?.parse().ok()?;
    let second: i64 = time
        .get(6..8)
        .and_then(|value| value.parse().ok())
        .unwrap_or(0);
    millis = millis
        .checked_add(hour.checked_mul(3_600_000)?)?
        .checked_add(minute.checked_mul(60_000)?)?
        .checked_add(second.checked_mul(1_000)?)?;
    Some(millis)
}

fn date_histogram_key_as_string_from_epoch_millis(
    epoch_millis: i64,
    time_zone_offset_millis: i64,
    format: Option<&str>,
) -> Option<String> {
    if format == Some("epoch_millis") {
        return Some(epoch_millis.to_string());
    }
    let zoned_epoch_millis = epoch_millis.checked_add(time_zone_offset_millis)?;
    let days = zoned_epoch_millis.div_euclid(86_400_000);
    let millis_of_day = zoned_epoch_millis.rem_euclid(86_400_000);
    let (year, month, day) = civil_from_days(days)?;
    let hour = millis_of_day / 3_600_000;
    let minute = (millis_of_day % 3_600_000) / 60_000;
    let second = (millis_of_day % 60_000) / 1_000;
    let millis = millis_of_day % 1_000;
    if format == Some("yyyy-MM-dd HH:mm:ss") {
        return Some(format!(
            "{year:04}-{month:02}-{day:02} {hour:02}:{minute:02}:{second:02}"
        ));
    }
    if format == Some("date") {
        return Some(format!("{year:04}-{month:02}-{day:02}"));
    }
    if format == Some("basic_date_time_no_millis") {
        return Some(format!(
            "{year:04}{month:02}{day:02}T{hour:02}{minute:02}{second:02}{}",
            date_histogram_time_zone_suffix(time_zone_offset_millis)
        ));
    }
    let suffix = date_histogram_time_zone_suffix(time_zone_offset_millis);
    Some(format!(
        "{year:04}-{month:02}-{day:02}T{hour:02}:{minute:02}:{second:02}.{millis:03}{suffix}"
    ))
}

fn date_histogram_time_zone_offset_millis(time_zone: Option<&str>) -> Option<i64> {
    let Some(time_zone) = time_zone else {
        return Some(0);
    };
    match time_zone {
        "Z" | "UTC" | "+00:00" | "-00:00" => return Some(0),
        _ => {}
    }
    let bytes = time_zone.as_bytes();
    if bytes.len() != 6 || (bytes[0] != b'+' && bytes[0] != b'-') || bytes[3] != b':' {
        return None;
    }
    let hours: i64 = time_zone.get(1..3)?.parse().ok()?;
    let minutes: i64 = time_zone.get(4..6)?.parse().ok()?;
    if hours > 23 || minutes > 59 {
        return None;
    }
    let millis = hours
        .checked_mul(3_600_000)?
        .checked_add(minutes.checked_mul(60_000)?)?;
    if bytes[0] == b'-' {
        Some(-millis)
    } else {
        Some(millis)
    }
}

fn date_histogram_time_zone_suffix(time_zone_offset_millis: i64) -> String {
    if time_zone_offset_millis == 0 {
        return "Z".to_string();
    }
    let sign = if time_zone_offset_millis < 0 {
        '-'
    } else {
        '+'
    };
    let total_minutes = time_zone_offset_millis.abs() / 60_000;
    let hours = total_minutes / 60;
    let minutes = total_minutes % 60;
    format!("{sign}{hours:02}:{minutes:02}")
}

#[derive(Clone)]
struct FallbackDateHistogramBounds {
    min: Option<String>,
    max: Option<String>,
}

fn parse_fallback_date_histogram_bounds(
    value: &Value,
) -> Result<FallbackDateHistogramBounds, RestResponse> {
    let Some(object) = value.as_object() else {
        return Err(build_unsupported_search_response(
            "unsupported aggregation [date_histogram]",
        ));
    };
    let min = object.get("min").and_then(|value| {
        if value.is_null() {
            None
        } else {
            value.as_str().map(ToString::to_string)
        }
    });
    let max = object.get("max").and_then(|value| {
        if value.is_null() {
            None
        } else {
            value.as_str().map(ToString::to_string)
        }
    });
    Ok(FallbackDateHistogramBounds { min, max })
}

fn civil_from_days(days: i64) -> Option<(i32, u32, u32)> {
    let z = days.checked_add(719_468)?;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = mp + if mp < 10 { 3 } else { -9 };
    let year = y + i64::from(month <= 2);
    Some((
        i32::try_from(year).ok()?,
        u32::try_from(month).ok()?,
        u32::try_from(day).ok()?,
    ))
}

fn parse_date_histogram_offset_millis(value: &Value) -> Option<i64> {
    match value {
        Value::Number(number) => number.as_i64(),
        Value::String(text) => {
            let trimmed = text.trim();
            if trimmed.is_empty() {
                return None;
            }
            let (sign, unsigned) = match trimmed.as_bytes()[0] {
                b'-' => (-1_i64, &trimmed[1..]),
                b'+' => (1_i64, &trimmed[1..]),
                _ => (1_i64, trimmed),
            };
            i64::try_from(parse_time_value_millis(unsigned)?)
                .ok()?
                .checked_mul(sign)
        }
        _ => None,
    }
}

fn render_date_histogram_buckets(buckets: Vec<Value>, keyed: bool) -> Value {
    if !keyed {
        return Value::Array(buckets);
    }
    let mut keyed_buckets = serde_json::Map::new();
    for bucket in buckets {
        let Some(key) = bucket
            .get("key_as_string")
            .and_then(Value::as_str)
            .map(ToString::to_string)
        else {
            continue;
        };
        keyed_buckets.insert(key, bucket);
    }
    Value::Object(keyed_buckets)
}

fn render_date_histogram_bucket_values_from_counts(
    counts: &std::collections::BTreeMap<i64, (String, u64)>,
    interval: FallbackDateHistogramInterval,
    offset_millis: i64,
    time_zone_offset_millis: i64,
    format: Option<&str>,
    min_doc_count: u64,
    extended_bounds: Option<&FallbackDateHistogramBounds>,
    hard_bounds: Option<&FallbackDateHistogramBounds>,
) -> Vec<Value> {
    let mut min_bucket = counts.keys().next().copied();
    let mut max_bucket = counts.keys().next_back().copied();
    if let Some(bounds) = extended_bounds {
        if let Some(bound) = bounds
            .min
            .as_deref()
            .and_then(|min| {
                date_histogram_bucket_with_offset(
                    min,
                    interval,
                    offset_millis,
                    time_zone_offset_millis,
                    format,
                )
            })
            .map(|(key, _)| key)
        {
            min_bucket = Some(min_bucket.map_or(bound, |current| current.min(bound)));
        }
        if let Some(bound) = bounds
            .max
            .as_deref()
            .and_then(|max| {
                date_histogram_bucket_with_offset(
                    max,
                    interval,
                    offset_millis,
                    time_zone_offset_millis,
                    format,
                )
            })
            .map(|(key, _)| key)
        {
            max_bucket = Some(max_bucket.map_or(bound, |current| current.max(bound)));
        }
    }
    let Some(min_bucket) = min_bucket else {
        return Vec::new();
    };
    let Some(max_bucket) = max_bucket else {
        return Vec::new();
    };
    let mut buckets = Vec::new();
    let mut key = min_bucket;
    while key <= max_bucket {
        if !fallback_date_histogram_bounds_contain(
            hard_bounds,
            key,
            interval,
            offset_millis,
            time_zone_offset_millis,
            format,
        ) {
            let Some(next) = next_date_histogram_bucket_key(
                key,
                interval,
                offset_millis,
                time_zone_offset_millis,
            ) else {
                break;
            };
            if next <= key {
                break;
            }
            key = next;
            continue;
        }
        let (key_as_string, doc_count) = counts
            .get(&key)
            .map(|(key_as_string, doc_count)| (key_as_string.clone(), *doc_count))
            .unwrap_or_else(|| {
                (
                    date_histogram_key_as_string_from_epoch_millis(
                        key,
                        time_zone_offset_millis,
                        format,
                    )
                    .unwrap_or_else(|| key.to_string()),
                    0,
                )
            });
        if doc_count < min_doc_count {
            let Some(next) = next_date_histogram_bucket_key(
                key,
                interval,
                offset_millis,
                time_zone_offset_millis,
            ) else {
                break;
            };
            if next <= key {
                break;
            }
            key = next;
            continue;
        }
        buckets.push(serde_json::json!({
            "key": key,
            "key_as_string": key_as_string,
            "doc_count": doc_count,
        }));
        let Some(next) =
            next_date_histogram_bucket_key(key, interval, offset_millis, time_zone_offset_millis)
        else {
            break;
        };
        if next <= key {
            break;
        }
        key = next;
    }
    buckets
}

fn fallback_date_histogram_bounds_contain(
    bounds: Option<&FallbackDateHistogramBounds>,
    key: i64,
    interval: FallbackDateHistogramInterval,
    offset_millis: i64,
    time_zone_offset_millis: i64,
    format: Option<&str>,
) -> bool {
    let Some(bounds) = bounds else {
        return true;
    };
    if let Some(max) = bounds
        .max
        .as_deref()
        .and_then(|max| {
            date_histogram_bucket_with_offset(
                max,
                interval,
                offset_millis,
                time_zone_offset_millis,
                format,
            )
        })
        .map(|(key, _)| key)
    {
        if key > max {
            return false;
        }
    }
    if let Some(min) = bounds
        .min
        .as_deref()
        .and_then(|min| {
            date_histogram_bucket_with_offset(
                min,
                interval,
                offset_millis,
                time_zone_offset_millis,
                format,
            )
        })
        .map(|(key, _)| key)
    {
        if key < min {
            return false;
        }
    }
    true
}

fn render_histogram_buckets(buckets: Vec<Value>, keyed: bool) -> Value {
    if !keyed {
        return Value::Array(buckets);
    }
    let mut keyed_buckets = serde_json::Map::new();
    for bucket in buckets {
        let Some(key) = bucket
            .get("key")
            .and_then(Value::as_f64)
            .map(histogram_key_as_raw_string)
        else {
            continue;
        };
        keyed_buckets.insert(key, bucket);
    }
    Value::Object(keyed_buckets)
}

fn apply_histogram_nested_aggregations(
    buckets: &mut [Value],
    nested_aggs: Option<&Value>,
    bucket_hits: &std::collections::BTreeMap<u64, Vec<&Value>>,
) -> Result<(), RestResponse> {
    let Some(nested_aggs) = nested_aggs.and_then(Value::as_object) else {
        return Ok(());
    };
    let mut metric_series = std::collections::BTreeMap::<String, Vec<Option<f64>>>::new();

    for (name, aggregation) in nested_aggs {
        let Some(aggregation_object) = aggregation.as_object() else {
            continue;
        };
        let Some((metric_kind, metric_body)) =
            histogram_nested_metric_aggregation(aggregation_object)
        else {
            continue;
        };
        let series = buckets
            .iter_mut()
            .map(|bucket| {
                let bucket_key = bucket.get("key").and_then(Value::as_f64)?.to_bits();
                let hits = bucket_hits
                    .get(&bucket_key)
                    .map(Vec::as_slice)
                    .unwrap_or(&[]);
                let value = histogram_nested_metric_value(metric_kind, metric_body, hits);
                if let Some(bucket_object) = bucket.as_object_mut() {
                    bucket_object.insert(
                        name.clone(),
                        serde_json::json!({ "value": value.map(Value::from).unwrap_or(Value::Null) }),
                    );
                }
                value
            })
            .collect::<Vec<_>>();
        metric_series.insert(name.clone(), series);
    }

    for (name, aggregation) in nested_aggs {
        let Some(moving_fn) = aggregation
            .as_object()
            .and_then(|aggregation| aggregation.get("moving_fn"))
            .and_then(Value::as_object)
        else {
            continue;
        };
        let Some(script) = moving_fn
            .get("script")
            .and_then(Value::as_str)
            .and_then(MovingFnScript::from_source)
        else {
            return Err(build_unsupported_search_response(
                "unsupported aggregation option [moving_fn.script]",
            ));
        };
        let buckets_path = moving_fn
            .get("buckets_path")
            .and_then(Value::as_str)
            .unwrap_or_default();
        let window = moving_fn
            .get("window")
            .and_then(Value::as_u64)
            .unwrap_or(5)
            .max(1) as usize;
        let values = metric_series
            .get(buckets_path)
            .cloned()
            .unwrap_or_else(|| vec![None; buckets.len()]);
        for (index, bucket) in buckets.iter_mut().enumerate() {
            let start = (index + 1).saturating_sub(window);
            let window_values = values[start..=index]
                .iter()
                .filter_map(|value| *value)
                .collect::<Vec<_>>();
            let value = script.evaluate(&window_values);
            if let Some(bucket_object) = bucket.as_object_mut() {
                bucket_object.insert(
                    name.clone(),
                    serde_json::json!({ "value": value.map(Value::from).unwrap_or(Value::Null) }),
                );
            }
        }
    }

    Ok(())
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum MovingFnScript {
    UnweightedAvg,
    LinearWeightedAvg,
    Ewma01,
    Holt0101,
    HoltWinters010101Period1Multiplicative,
    StddevUnweightedAvg,
    Sum,
    Min,
    Max,
}

impl MovingFnScript {
    fn from_source(source: &str) -> Option<Self> {
        match source {
            "MovingFunctions.unweightedAvg(values)" => Some(Self::UnweightedAvg),
            "MovingFunctions.linearWeightedAvg(values)" => Some(Self::LinearWeightedAvg),
            "MovingFunctions.ewma(values, 0.1)" => Some(Self::Ewma01),
            "MovingFunctions.holt(values, 0.1, 0.1)" => Some(Self::Holt0101),
            "if (values.length > 1) { MovingFunctions.holtWinters(values, 0.1, 0.1, 0.1, 1, true)}" => {
                Some(Self::HoltWinters010101Period1Multiplicative)
            }
            "MovingFunctions.stdDev(values, MovingFunctions.unweightedAvg(values))" => {
                Some(Self::StddevUnweightedAvg)
            }
            "MovingFunctions.sum(values)" => Some(Self::Sum),
            "MovingFunctions.min(values)" => Some(Self::Min),
            "MovingFunctions.max(values)" => Some(Self::Max),
            _ => None,
        }
    }

    fn evaluate(self, values: &[f64]) -> Option<f64> {
        if values.is_empty() {
            return None;
        }
        match self {
            Self::UnweightedAvg => Some(values.iter().sum::<f64>() / values.len() as f64),
            Self::LinearWeightedAvg => {
                let (weighted_sum, total_weight) = values.iter().enumerate().fold(
                    (0.0, 0.0),
                    |(weighted_sum, total_weight), (index, value)| {
                        let weight = (index + 1) as f64;
                        (weighted_sum + (value * weight), total_weight + weight)
                    },
                );
                Some(weighted_sum / total_weight)
            }
            Self::Ewma01 => Some(moving_ewma(values, 0.1)),
            Self::Holt0101 => Some(moving_holt(values, 0.1, 0.1)),
            Self::HoltWinters010101Period1Multiplicative => {
                if values.len() > 1 {
                    Some(moving_holt_winters(values, 0.1, 0.1, 0.1, 1, true))
                } else {
                    None
                }
            }
            Self::StddevUnweightedAvg => Some(moving_stddev_unweighted_avg(values)),
            Self::Sum => Some(values.iter().sum::<f64>()),
            Self::Min => values.iter().copied().reduce(f64::min),
            Self::Max => values.iter().copied().reduce(f64::max),
        }
    }
}

fn moving_ewma(values: &[f64], alpha: f64) -> f64 {
    values
        .iter()
        .copied()
        .reduce(|avg, value| (value * alpha) + (avg * (1.0 - alpha)))
        .unwrap_or(f64::NAN)
}

fn moving_holt(values: &[f64], alpha: f64, beta: f64) -> f64 {
    let mut s = 0.0;
    let mut last_s = 0.0;
    let mut b = 0.0;
    let mut last_b = 0.0;
    let mut counter = 0usize;

    for value in values.iter().copied().filter(|value| !value.is_nan()) {
        if counter == 0 {
            s = value;
            b = 0.0;
        } else {
            s = (alpha * value) + ((1.0 - alpha) * (last_s + last_b));
            b = (beta * (s - last_s)) + ((1.0 - beta) * last_b);
        }
        counter += 1;
        last_s = s;
        last_b = b;
    }

    if counter == 0 {
        f64::NAN
    } else {
        s
    }
}

fn moving_stddev_unweighted_avg(values: &[f64]) -> f64 {
    let finite_values = values
        .iter()
        .copied()
        .filter(|value| !value.is_nan())
        .collect::<Vec<_>>();
    if finite_values.is_empty() {
        return f64::NAN;
    }
    let avg = finite_values.iter().sum::<f64>() / finite_values.len() as f64;
    let squared_mean = finite_values
        .iter()
        .map(|value| {
            let delta = value - avg;
            delta * delta
        })
        .sum::<f64>()
        / finite_values.len() as f64;
    squared_mean.sqrt()
}

fn moving_holt_winters(
    values: &[f64],
    alpha: f64,
    beta: f64,
    gamma: f64,
    period: usize,
    multiplicative: bool,
) -> f64 {
    if values.len() < period * 2 {
        return f64::NAN;
    }

    let padding = if multiplicative { 0.0000000001 } else { 0.0 };
    let mut vs = vec![0.0; values.len()];
    let mut counter = 0usize;
    for value in values.iter().copied() {
        if !value.is_nan() {
            vs[counter] = value + padding;
            counter += 1;
        }
    }
    if counter == 0 {
        return f64::NAN;
    }

    let mut s = 0.0;
    let mut b = 0.0;
    for index in 0..period {
        s += vs[index];
        b += (vs[index + period] - vs[index]) / period as f64;
    }
    s /= period as f64;
    b /= period as f64;
    let mut last_s = s;
    let mut last_b = 0.0;
    let mut seasonal = vec![0.0; vs.len()];

    if s != 0.0 && s != -0.0 {
        for index in 0..period {
            seasonal[index] = vs[index] / s;
        }
    }

    for index in period..vs.len() {
        if multiplicative {
            s = alpha * (vs[index] / seasonal[index - period]) + (1.0 - alpha) * (last_s + last_b);
        } else {
            s = alpha * (vs[index] - seasonal[index - period]) + (1.0 - alpha) * (last_s + last_b);
        }
        b = beta * (s - last_s) + (1.0 - beta) * last_b;
        if multiplicative {
            seasonal[index] =
                gamma * (vs[index] / (last_s + last_b)) + (1.0 - gamma) * seasonal[index - period];
        } else {
            seasonal[index] =
                gamma * (vs[index] - (last_s - last_b)) + (1.0 - gamma) * seasonal[index - period];
        }
        last_s = s;
        last_b = b;
    }

    let idx = values.len() - period;
    if multiplicative {
        (s + b) * seasonal[idx]
    } else {
        s + b + seasonal[idx]
    }
}

fn histogram_nested_metric_aggregation<'a>(
    aggregation_object: &'a serde_json::Map<String, Value>,
) -> Option<(&'static str, &'a serde_json::Map<String, Value>)> {
    for kind in ["sum", "avg", "min", "max"] {
        if let Some(body) = aggregation_object.get(kind).and_then(Value::as_object) {
            return Some((kind, body));
        }
    }
    None
}

fn histogram_nested_metric_value(
    kind: &str,
    metric_body: &serde_json::Map<String, Value>,
    hits: &[&Value],
) -> Option<f64> {
    let field = metric_body.get("field").and_then(Value::as_str)?;
    let missing = metric_body.get("missing").and_then(metric_missing_value);
    let values = hits
        .iter()
        .filter_map(|hit| {
            hit.get("_source")
                .and_then(|source| lookup_query_field_value(source, field))
                .and_then(metric_missing_value)
                .or(missing)
        })
        .collect::<Vec<_>>();
    match kind {
        "sum" => Some(values.iter().sum::<f64>()),
        "avg" => {
            if values.is_empty() {
                None
            } else {
                Some(values.iter().sum::<f64>() / values.len() as f64)
            }
        }
        "min" => values.iter().copied().reduce(f64::min),
        "max" => values.iter().copied().reduce(f64::max),
        _ => None,
    }
}

fn render_histogram_bucket_values_from_counts(
    counts: &std::collections::BTreeMap<u64, (f64, u64)>,
    interval: f64,
    offset: f64,
    min_doc_count: u64,
    extended_bounds: Option<&FallbackHistogramBounds>,
    hard_bounds: Option<&FallbackHistogramBounds>,
) -> Vec<Value> {
    if counts.is_empty() && extended_bounds.is_none() {
        return Vec::new();
    }
    let count_bucket_indexes = counts
        .values()
        .filter_map(|(key, _)| histogram_bucket_index(*key, interval, offset))
        .collect::<Vec<_>>();
    let mut min_bucket = count_bucket_indexes.iter().copied().min();
    let mut max_bucket = count_bucket_indexes.iter().copied().max();
    if let Some(bounds) = extended_bounds {
        if let Some(bound) = bounds
            .min
            .and_then(|min| fallback_histogram_bucket_key_with_offset(min, interval, offset))
            .and_then(|key| histogram_bucket_index(key, interval, offset))
        {
            min_bucket = Some(min_bucket.map_or(bound, |current| current.min(bound)));
        }
        if let Some(bound) = bounds
            .max
            .and_then(|max| fallback_histogram_bucket_key_with_offset(max, interval, offset))
            .and_then(|key| histogram_bucket_index(key, interval, offset))
        {
            max_bucket = Some(max_bucket.map_or(bound, |current| current.max(bound)));
        }
    }
    let Some(min_bucket) = min_bucket else {
        return Vec::new();
    };
    let Some(max_bucket) = max_bucket else {
        return Vec::new();
    };
    (min_bucket..=max_bucket)
        .filter_map(|bucket| {
            let key = (bucket as f64) * interval + offset;
            if !fallback_histogram_bounds_contain(hard_bounds, key) {
                return None;
            }
            let doc_count = counts
                .get(&key.to_bits())
                .map(|(_, count)| *count)
                .unwrap_or(0);
            if doc_count < min_doc_count {
                return None;
            }
            Some(serde_json::json!({
                "key": key,
                "doc_count": doc_count,
            }))
        })
        .collect()
}

fn fallback_histogram_bounds_contain(bounds: Option<&FallbackHistogramBounds>, value: f64) -> bool {
    if let Some(bounds) = bounds {
        if bounds.max.is_some_and(|max| value > max) {
            return false;
        }
        if bounds.min.is_some_and(|min| value < min) {
            return false;
        }
    }
    true
}

fn histogram_bucket_index(key: f64, interval: f64, offset: f64) -> Option<i64> {
    if !key.is_finite() || !interval.is_finite() || interval <= 0.0 || !offset.is_finite() {
        return None;
    }
    Some(((key - offset) / interval).round() as i64)
}

fn histogram_key_as_raw_string(key: f64) -> String {
    if key.fract() == 0.0 {
        format!("{key:.1}")
    } else {
        key.to_string()
    }
}

fn days_from_civil(year: i32, month: u32, day: u32) -> Option<i64> {
    if !(1..=12).contains(&month) || !(1..=31).contains(&day) {
        return None;
    }
    let year = year - ((month <= 2) as i32);
    let era = if year >= 0 { year } else { year - 399 } / 400;
    let yoe = year - era * 400;
    let month = month as i32;
    let day = day as i32;
    let doy = (153 * (month + if month > 2 { -3 } else { 9 }) + 2) / 5 + day - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    Some((era * 146097 + doe - 719468) as i64)
}

fn first_supported_metric_aggregation<'a>(
    aggregation_object: &'a serde_json::Map<String, Value>,
) -> Option<(&'a str, &'a Value)> {
    for key in [
        "min",
        "max",
        "sum",
        "avg",
        "weighted_avg",
        "value_count",
        "stats",
        "extended_stats",
        "percentiles",
        "percentile_ranks",
        "median_absolute_deviation",
    ] {
        if let Some(value) = aggregation_object.get(key) {
            return Some((key, value));
        }
    }
    None
}

fn first_supported_bucket_metric_pipeline_aggregation<'a>(
    aggregation_object: &'a serde_json::Map<String, Value>,
) -> Option<(&'a str, &'a serde_json::Map<String, Value>)> {
    for key in [
        "sum_bucket",
        "avg_bucket",
        "min_bucket",
        "max_bucket",
        "stats_bucket",
        "extended_stats_bucket",
        "percentiles_bucket",
    ] {
        if let Some(value) = aggregation_object.get(key).and_then(Value::as_object) {
            return Some((key, value));
        }
    }
    None
}

fn extended_stats_aggregation_value(values: &[f64], sigma: f64) -> Value {
    let count = values.len() as u64;
    let sum = values.iter().sum::<f64>();
    let min = values.iter().copied().reduce(f64::min);
    let max = values.iter().copied().reduce(f64::max);
    if count == 0 {
        return serde_json::json!({
            "count": 0,
            "min": Value::Null,
            "max": Value::Null,
            "avg": Value::Null,
            "sum": 0.0,
            "sum_of_squares": 0.0,
            "variance": Value::Null,
            "variance_population": Value::Null,
            "variance_sampling": Value::Null,
            "std_deviation": Value::Null,
            "std_deviation_population": Value::Null,
            "std_deviation_sampling": Value::Null,
            "std_deviation_bounds": {
                "upper": Value::Null,
                "lower": Value::Null,
                "upper_population": Value::Null,
                "lower_population": Value::Null,
                "upper_sampling": Value::Null,
                "lower_sampling": Value::Null
            }
        });
    }
    let avg = sum / (count as f64);
    let sum_of_squares = values.iter().map(|value| value * value).sum::<f64>();
    let variance_population = (sum_of_squares - ((sum * sum) / (count as f64))) / (count as f64);
    let variance_sampling = if count > 1 {
        Some(variance_population * (count as f64) / ((count - 1) as f64))
    } else {
        None
    };
    let std_deviation_population = variance_population.sqrt();
    let std_deviation_sampling = variance_sampling.map(f64::sqrt);
    serde_json::json!({
        "count": count,
        "min": min.map(Value::from).unwrap_or(Value::Null),
        "max": max.map(Value::from).unwrap_or(Value::Null),
        "avg": avg,
        "sum": sum,
        "sum_of_squares": sum_of_squares,
        "variance": variance_population,
        "variance_population": variance_population,
        "variance_sampling": variance_sampling.map(Value::from).unwrap_or(Value::Null),
        "std_deviation": std_deviation_population,
        "std_deviation_population": std_deviation_population,
        "std_deviation_sampling": std_deviation_sampling.map(Value::from).unwrap_or(Value::Null),
        "std_deviation_bounds": {
            "upper": avg + (sigma * std_deviation_population),
            "lower": avg - (sigma * std_deviation_population),
            "upper_population": avg + (sigma * std_deviation_population),
            "lower_population": avg - (sigma * std_deviation_population),
            "upper_sampling": std_deviation_sampling.map(|value| avg + (sigma * value)).map(Value::from).unwrap_or(Value::Null),
            "lower_sampling": std_deviation_sampling.map(|value| avg - (sigma * value)).map(Value::from).unwrap_or(Value::Null)
        }
    })
}

fn percentiles_aggregation_value(values: &[f64], requested_percentiles: Option<&[f64]>) -> Value {
    let percentiles = requested_percentiles
        .filter(|values| !values.is_empty())
        .unwrap_or(&[1.0_f64, 5.0, 25.0, 50.0, 75.0, 95.0, 99.0]);
    serde_json::json!({
        "values": Value::Object(percentiles.iter().map(|percentile| {
            (
                format!("{percentile:.1}"),
                percentile_metric_value(values, *percentile)
                    .map(Value::from)
                    .unwrap_or(Value::Null),
            )
        }).collect::<serde_json::Map<String, Value>>())
    })
}

fn percentile_metric_value(values: &[f64], percentile: f64) -> Option<f64> {
    if values.is_empty() {
        return None;
    }
    let mut sorted = values.to_vec();
    sorted.sort_by(|left, right| left.partial_cmp(right).unwrap_or(std::cmp::Ordering::Equal));
    if percentile <= 0.0 {
        return sorted.first().copied();
    }
    if percentile >= 100.0 {
        return sorted.last().copied();
    }
    let rank = ((percentile / 100.0) * ((sorted.len() + 1) as f64)).ceil() as usize;
    let index = rank.saturating_sub(1).min(sorted.len() - 1);
    sorted.get(index).copied()
}

fn percentile_ranks_aggregation_value(values: &[f64], requested_values: &[f64]) -> Value {
    serde_json::json!({
        "values": Value::Object(requested_values.iter().map(|requested| {
            (
                Value::from(*requested).to_string(),
                percentile_rank_metric_value(values, *requested)
                    .map(Value::from)
                    .unwrap_or(Value::Null),
            )
        }).collect::<serde_json::Map<String, Value>>())
    })
}

fn percentile_rank_metric_value(values: &[f64], requested: f64) -> Option<f64> {
    if values.is_empty() {
        return None;
    }
    let matched = values.iter().filter(|value| **value <= requested).count() as f64;
    Some((matched * 100.0) / (values.len() as f64))
}

fn weighted_avg_aggregation_value(hits: &[Value], metric_body: &Value) -> Option<f64> {
    let value_field = metric_body
        .get("value")
        .and_then(|value| value.get("field"))
        .and_then(Value::as_str)
        .or_else(|| metric_body.get("field").and_then(Value::as_str))?;
    let weight_field = metric_body
        .get("weight")
        .and_then(|value| value.get("field"))
        .and_then(Value::as_str)
        .or_else(|| metric_body.get("weight_field").and_then(Value::as_str))?;
    let mut weighted_sum = 0.0;
    let mut weight_sum = 0.0;
    for hit in hits {
        let Some(source) = hit.get("_source") else {
            continue;
        };
        let values = lookup_query_field_value(source, value_field)
            .map(numeric_values_from_value)
            .unwrap_or_default();
        let weights = lookup_query_field_value(source, weight_field)
            .map(numeric_values_from_value)
            .unwrap_or_default();
        for (value, weight) in values.into_iter().zip(weights) {
            weighted_sum += value * weight;
            weight_sum += weight;
        }
    }
    if weight_sum == 0.0 {
        None
    } else {
        Some(weighted_sum / weight_sum)
    }
}

fn median_absolute_deviation_value(values: &[f64]) -> Option<f64> {
    let median = percentile_metric_value(values, 50.0)?;
    let deviations = values
        .iter()
        .map(|value| (value - median).abs())
        .collect::<Vec<_>>();
    percentile_metric_value(&deviations, 50.0)
}

fn metric_numeric_array_value(value: &Value) -> Option<Vec<f64>> {
    value
        .as_array()
        .map(|values| values.iter().filter_map(metric_missing_value).collect())
}

fn metric_missing_value(value: &Value) -> Option<f64> {
    value
        .as_f64()
        .or_else(|| value.as_str().and_then(|text| text.parse::<f64>().ok()))
}

fn numeric_values_from_value(value: &Value) -> Vec<f64> {
    match value {
        Value::Number(_) => value.as_f64().into_iter().collect(),
        Value::Array(values) => values.iter().filter_map(Value::as_f64).collect(),
        _ => Vec::new(),
    }
}

fn hit_matches_query(hit: &Value, query: &Value) -> bool {
    let record = StoredDocument {
        source: hit.get("_source").cloned().unwrap_or(Value::Null),
        version: 1,
        seq_no: hit
            .get("_seq_no")
            .and_then(Value::as_i64)
            .unwrap_or_default(),
        primary_term: 1,
        routing: None,
        refreshed: true,
    };
    evaluate_search_query(
        &record,
        hit.get("_id").and_then(Value::as_str).unwrap_or_default(),
        query,
    )
    .map(|(matched, _)| matched)
    .unwrap_or(false)
}

fn build_fallback_significant_terms_aggregation(
    field: &str,
    size: usize,
    min_doc_count: u64,
    include: Option<&Value>,
    exclude: Option<&Value>,
    hits: &[Value],
    background_hits: &[&Value],
) -> Result<Value, RestResponse> {
    let mut buckets = std::collections::BTreeMap::<String, (Value, u64)>::new();
    let mut background_counts = std::collections::BTreeMap::<String, u64>::new();
    for hit in background_hits {
        if let Some(value) = hit
            .get("_source")
            .and_then(|source| lookup_query_field_value(source, field))
        {
            for value in fallback_scalar_bucket_values(value) {
                if !aggregation_term_is_allowed_by_include_exclude(&value, include, exclude)? {
                    continue;
                }
                *background_counts
                    .entry(fallback_bucket_sort_key(&value))
                    .or_insert(0) += 1;
            }
        }
    }
    for hit in hits {
        if let Some(value) = hit
            .get("_source")
            .and_then(|source| lookup_query_field_value(source, field))
        {
            for value in fallback_scalar_bucket_values(value) {
                if !aggregation_term_is_allowed_by_include_exclude(&value, include, exclude)? {
                    continue;
                }
                let bucket_key = fallback_bucket_sort_key(&value);
                let (_, count) = buckets.entry(bucket_key).or_insert((value, 0));
                *count += 1;
            }
        }
    }
    let total_doc_count = hits.len() as u64;
    let total_bg_count = background_hits.len() as u64;
    let mut buckets = buckets
        .into_values()
        .filter(|(_, doc_count)| *doc_count >= min_doc_count)
        .map(|(key, doc_count)| {
            let bg_count = background_counts
                .get(&fallback_bucket_sort_key(&key))
                .copied()
                .unwrap_or(doc_count);
            serde_json::json!({
                "key": key,
                "doc_count": doc_count,
                "bg_count": bg_count,
                "score": doc_count as f64
            })
        })
        .collect::<Vec<_>>();
    buckets.sort_by(|left, right| {
        let left_count = left.get("doc_count").and_then(Value::as_u64).unwrap_or(0);
        let right_count = right.get("doc_count").and_then(Value::as_u64).unwrap_or(0);
        right_count.cmp(&left_count).then_with(|| {
            fallback_bucket_sort_key(left.get("key").unwrap_or(&Value::Null)).cmp(
                &fallback_bucket_sort_key(right.get("key").unwrap_or(&Value::Null)),
            )
        })
    });
    buckets.truncate(size);
    Ok(serde_json::json!({
        "doc_count": total_doc_count,
        "bg_count": total_bg_count,
        "buckets": buckets
    }))
}

fn build_fallback_significant_text_aggregation(
    field: &str,
    size: usize,
    min_doc_count: u64,
    hits: &[Value],
    background_hits: &[&Value],
) -> Value {
    let mut buckets = std::collections::BTreeMap::<String, u64>::new();
    let mut background_counts = std::collections::BTreeMap::<String, u64>::new();
    for hit in background_hits {
        if let Some(value) = hit
            .get("_source")
            .and_then(|source| lookup_query_field_value(source, field))
        {
            for token in fallback_text_bucket_tokens(value) {
                *background_counts.entry(token).or_insert(0) += 1;
            }
        }
    }
    for hit in hits {
        if let Some(value) = hit
            .get("_source")
            .and_then(|source| lookup_query_field_value(source, field))
        {
            for token in fallback_text_bucket_tokens(value) {
                *buckets.entry(token).or_insert(0) += 1;
            }
        }
    }
    let total_doc_count = hits.len() as u64;
    let total_bg_count = background_hits.len() as u64;
    let mut buckets = buckets
        .into_iter()
        .filter(|(_, doc_count)| *doc_count >= min_doc_count)
        .map(|(key, doc_count)| {
            let bg_count = background_counts.get(&key).copied().unwrap_or(doc_count);
            serde_json::json!({
                "key": key,
                "doc_count": doc_count,
                "bg_count": bg_count,
                "score": doc_count as f64
            })
        })
        .collect::<Vec<_>>();
    buckets.sort_by(|left, right| {
        let left_count = left.get("doc_count").and_then(Value::as_u64).unwrap_or(0);
        let right_count = right.get("doc_count").and_then(Value::as_u64).unwrap_or(0);
        right_count.cmp(&left_count).then_with(|| {
            left.get("key")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .cmp(right.get("key").and_then(Value::as_str).unwrap_or_default())
        })
    });
    buckets.truncate(size);
    serde_json::json!({
        "doc_count": total_doc_count,
        "bg_count": total_bg_count,
        "buckets": buckets
    })
}

fn fallback_text_bucket_tokens(value: &Value) -> Vec<String> {
    fn visit(value: &Value, values: &mut std::collections::BTreeMap<String, ()>) {
        match value {
            Value::Array(items) => {
                for item in items {
                    visit(item, values);
                }
            }
            Value::String(text) => {
                for token in text
                    .split(|ch: char| !ch.is_ascii_alphanumeric())
                    .filter(|token| !token.is_empty())
                {
                    values.insert(token.to_ascii_lowercase(), ());
                }
            }
            _ => {}
        }
    }
    let mut values = std::collections::BTreeMap::new();
    visit(value, &mut values);
    values.into_keys().collect()
}

fn fallback_scalar_bucket_values(value: &Value) -> Vec<Value> {
    fn visit(value: &Value, values: &mut std::collections::BTreeMap<String, Value>) {
        match value {
            Value::Array(items) => {
                for item in items {
                    visit(item, values);
                }
            }
            Value::String(_) | Value::Bool(_) | Value::Number(_) => {
                values
                    .entry(fallback_bucket_sort_key(value))
                    .or_insert_with(|| value.clone());
            }
            _ => {}
        }
    }
    let mut values = std::collections::BTreeMap::new();
    visit(value, &mut values);
    values.into_values().collect()
}

fn fallback_bucket_sort_key(value: &Value) -> String {
    match value {
        Value::String(value) => format!("s:{value}"),
        Value::Bool(value) => format!("b:{value}"),
        Value::Number(value) => format!("n:{value}"),
        _ => String::new(),
    }
}

fn normalize_alias_metadata_for_readback(metadata: Value) -> Value {
    let mut metadata = metadata;
    if let Some(object) = metadata.as_object_mut() {
        if let Some(routing) = object.remove("routing") {
            object
                .entry("index_routing".to_string())
                .or_insert_with(|| routing.clone());
            object
                .entry("search_routing".to_string())
                .or_insert(routing);
        }
    }
    metadata
}

fn validate_single_alias_mutation_body(body: &Value) -> Option<RestResponse> {
    let Some(object) = body.as_object() else {
        return None;
    };
    for (field, value) in object {
        match field.as_str() {
            "index" | "alias" | "aliases" | "routing" | "indexRouting" | "index-routing"
            | "index_routing" | "searchRouting" | "search-routing" | "search_routing"
            | "is_write_index" | "is_hidden" => {}
            "filter" if value.is_object() => {}
            _ => {
                return Some(RestResponse::opensearch_error(
                    400,
                    "illegal_argument_exception",
                    format!("unknown field [{field}]"),
                ));
            }
        }
    }
    None
}

fn normalize_single_alias_mutation_body(body: Value) -> Value {
    let Value::Object(mut object) = body else {
        return body;
    };
    for (source, target) in [
        ("indexRouting", "index_routing"),
        ("index-routing", "index_routing"),
        ("searchRouting", "search_routing"),
        ("search-routing", "search_routing"),
    ] {
        if let Some(value) = object.remove(source) {
            object.entry(target.to_string()).or_insert(value);
        }
    }
    Value::Object(object)
}

fn extract_alias_named_mutation_targets(body: &Value) -> Vec<String> {
    let mut targets = Vec::new();
    if let Some(index) = body.get("index").and_then(Value::as_str) {
        targets.push(index.to_string());
    }
    if let Some(indices) = body.get("indices") {
        if let Some(index) = indices.as_str() {
            targets.push(index.to_string());
        } else if let Some(array) = indices.as_array() {
            for value in array {
                if let Some(index) = value.as_str() {
                    targets.push(index.to_string());
                }
            }
        }
    }
    targets
}

fn extract_alias_names_from_body(body: &Value) -> Vec<String> {
    let mut aliases = Vec::new();
    if let Some(alias) = body.get("alias").and_then(Value::as_str) {
        aliases.push(alias.to_string());
    }
    if let Some(values) = body.get("aliases") {
        if let Some(alias) = values.as_str() {
            aliases.push(alias.to_string());
        } else if let Some(array) = values.as_array() {
            for value in array {
                if let Some(alias) = value.as_str() {
                    aliases.push(alias.to_string());
                }
            }
        }
    }
    aliases
}

fn parse_index_expand_wildcards(
    expand_wildcards: &str,
) -> Result<(bool, bool, bool), RestResponse> {
    if expand_wildcards.is_empty() {
        return Ok((true, false, false));
    }
    let tokens = expand_wildcards
        .split(',')
        .map(str::trim)
        .collect::<Vec<_>>();
    if tokens.is_empty() {
        return Ok((true, false, false));
    }

    let mut include_open = false;
    let mut include_hidden = false;
    let mut include_closed = false;
    for token in tokens {
        match token {
            "open" => {
                include_open = true;
            }
            "all" => {
                include_open = true;
                include_hidden = true;
                include_closed = true;
            }
            "hidden" => {
                include_hidden = true;
            }
            "closed" => {
                include_closed = true;
            }
            "none" => {
                include_open = false;
                include_hidden = false;
                include_closed = false;
            }
            _ => {
                return Err(RestResponse::opensearch_error_kind(
                    os_rest::RestErrorKind::IllegalArgument,
                    format!("No valid expand wildcard value [{token}]"),
                ));
            }
        }
    }
    Ok((include_open, include_hidden, include_closed))
}

