fn validate_cluster_settings_timeout_params(request: &RestRequest) -> Option<RestResponse> {
    if let Some(response) = duplicate_master_cluster_manager_timeout_response(request) {
        return Some(response);
    }
    for param in ["timeout", "cluster_manager_timeout", "master_timeout"] {
        let Some(raw_value) = request.query_params.get(param) else {
            continue;
        };
        if parse_time_value_millis(raw_value).is_none() {
            return Some(RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                format!(
                    "failed to parse setting [{param}] with value [{raw_value}] as a time value"
                ),
            ));
        }
    }
    None
}

fn validate_settings_get_query_params(request: &RestRequest) -> Option<RestResponse> {
    const ALLOWED_PARAMS: &[&str] = &[
        "allow_no_indices",
        "cluster_manager_timeout",
        "expand_wildcards",
        "flat_settings",
        "human",
        "ignore_throttled",
        "ignore_unavailable",
        "include_defaults",
        "local",
        "master_timeout",
    ];

    let unrecognized = request
        .query_params
        .keys()
        .filter(|key| !ALLOWED_PARAMS.contains(&key.as_str()))
        .collect::<Vec<_>>();
    if let Some(response) = unrecognized_query_param_response_for_keys(request, &unrecognized) {
        return Some(response);
    }

    for field in ["allow_no_indices", "ignore_unavailable"] {
        if let Some(response) =
            validate_opensearch_named_boolean_query_param(field, request.query_params.get(field))
        {
            return Some(response);
        }
    }

    for field in [
        "flat_settings",
        "ignore_throttled",
        "include_defaults",
        "local",
    ] {
        if let Some(response) =
            validate_opensearch_boolean_query_param(request.query_params.get(field))
        {
            return Some(response);
        }
    }

    if let Some(response) = duplicate_master_cluster_manager_timeout_response(request) {
        return Some(response);
    }

    for param in ["cluster_manager_timeout", "master_timeout"] {
        let Some(raw_value) = request.query_params.get(param) else {
            continue;
        };
        if parse_time_value_millis(raw_value).is_none() {
            return Some(RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                format!(
                    "failed to parse setting [{param}] with value [{raw_value}] as a time value"
                ),
            ));
        }
    }

    if let Some(expand_wildcards) = request.query_params.get("expand_wildcards") {
        if let Err(response) = parse_index_expand_wildcards(expand_wildcards) {
            return Some(response);
        }
    }

    None
}

fn validate_alias_get_query_params(request: &RestRequest) -> Option<RestResponse> {
    const ALLOWED_PARAMS: &[&str] = &[
        "allow_no_indices",
        "cluster_manager_timeout",
        "expand_wildcards",
        "ignore_throttled",
        "ignore_unavailable",
        "local",
        "master_timeout",
    ];

    let unrecognized = request
        .query_params
        .keys()
        .filter(|key| !ALLOWED_PARAMS.contains(&key.as_str()))
        .collect::<Vec<_>>();
    if let Some(response) = unrecognized_query_param_response_for_keys(request, &unrecognized) {
        return Some(response);
    }

    for field in ["allow_no_indices", "ignore_unavailable"] {
        if let Some(response) =
            validate_opensearch_named_boolean_query_param(field, request.query_params.get(field))
        {
            return Some(response);
        }
    }

    for field in ["ignore_throttled", "local"] {
        if let Some(response) =
            validate_opensearch_boolean_query_param(request.query_params.get(field))
        {
            return Some(response);
        }
    }

    if let Some(response) = duplicate_master_cluster_manager_timeout_response(request) {
        return Some(response);
    }

    for param in ["cluster_manager_timeout", "master_timeout"] {
        let Some(raw_value) = request.query_params.get(param) else {
            continue;
        };
        if parse_time_value_millis(raw_value).is_none() {
            return Some(RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                format!(
                    "failed to parse setting [{param}] with value [{raw_value}] as a time value"
                ),
            ));
        }
    }

    if let Some(expand_wildcards) = request.query_params.get("expand_wildcards") {
        if let Err(response) = parse_index_expand_wildcards(expand_wildcards) {
            return Some(response);
        }
    }

    None
}

fn validate_alias_mutation_query_params(request: &RestRequest) -> Option<RestResponse> {
    const ALLOWED_PARAMS: &[&str] = &["cluster_manager_timeout", "master_timeout", "timeout"];

    let unrecognized = request
        .query_params
        .keys()
        .filter(|key| !ALLOWED_PARAMS.contains(&key.as_str()))
        .collect::<Vec<_>>();
    if let Some(response) = unrecognized_query_param_response_for_keys(request, &unrecognized) {
        return Some(response);
    }

    if let Some(response) = duplicate_master_cluster_manager_timeout_response(request) {
        return Some(response);
    }

    for param in ALLOWED_PARAMS {
        let Some(raw_value) = request.query_params.get(*param) else {
            continue;
        };
        if parse_time_value_millis(raw_value).is_none() {
            return Some(RestResponse::opensearch_error_kind(
                os_rest::RestErrorKind::IllegalArgument,
                format!(
                    "failed to parse setting [{param}] with value [{raw_value}] as a time value"
                ),
            ));
        }
    }

    None
}

fn merge_cluster_settings_section_flat(base: &Value, patch: &Value) -> Value {
    let mut merged = match base {
        Value::Object(map) => map.clone(),
        _ => serde_json::Map::new(),
    };
    for (key, value) in flatten_cluster_settings_section(patch) {
        if value.is_null() {
            merged.remove(&key);
        } else {
            merged.insert(key, value);
        }
    }
    Value::Object(merged)
}

fn filter_cluster_settings_section(section: &Value, settings_filter: Option<&String>) -> Value {
    let Some(settings_filter) = settings_filter else {
        return section.clone();
    };
    if settings_filter.is_empty() {
        return section.clone();
    }
    let patterns = settings_filter
        .split(',')
        .map(str::trim)
        .filter(|pattern| !pattern.is_empty())
        .collect::<Vec<_>>();
    if patterns.is_empty() {
        return section.clone();
    }
    let mut filtered = match section {
        Value::Object(map) => map.clone(),
        _ => return Value::Object(serde_json::Map::new()),
    };
    filtered.retain(|key, _| {
        !patterns
            .iter()
            .any(|pattern| cluster_setting_filter_pattern_matches(pattern, key))
    });
    Value::Object(filtered)
}

fn cluster_setting_filter_pattern_matches(pattern: &str, key: &str) -> bool {
    if pattern == key {
        return true;
    }
    if !pattern.contains('*') {
        return false;
    }
    let mut remaining = key;
    let anchored_start = !pattern.starts_with('*');
    let anchored_end = !pattern.ends_with('*');
    let parts = pattern.split('*').collect::<Vec<_>>();
    for (index, part) in parts.iter().filter(|part| !part.is_empty()).enumerate() {
        if index == 0 && anchored_start {
            let Some(next) = remaining.strip_prefix(part) else {
                return false;
            };
            remaining = next;
            continue;
        }
        let Some(position) = remaining.find(part) else {
            return false;
        };
        remaining = &remaining[position + part.len()..];
    }
    !anchored_end || parts.last().map_or(true, |part| key.ends_with(part))
}

fn validate_pit_cluster_keep_alive_settings(
    persistent: &Value,
    transient: &Value,
) -> Option<RestResponse> {
    let default_keep_alive = effective_cluster_time_setting_millis(
        persistent,
        transient,
        "search.default_keep_alive",
        300_000,
    )?;
    let max_pit_keep_alive = effective_cluster_time_setting_millis(
        persistent,
        transient,
        "point_in_time.max_keep_alive",
        DEFAULT_MAX_PIT_KEEP_ALIVE_MILLIS,
    )?;
    if default_keep_alive <= max_pit_keep_alive {
        return None;
    }
    let reason = format!(
        "Default keep alive setting for request [search.default_keep_alive] should be smaller than max keep alive for PIT [point_in_time.max_keep_alive], was ({} > {})",
        format_time_value_millis(default_keep_alive),
        format_time_value_millis(max_pit_keep_alive)
    );
    Some(RestResponse::json(
        400,
        serde_json::json!({
            "error": {
                "type": "illegal_argument_exception",
                "reason": reason,
                "root_cause": [
                    {
                        "type": "illegal_argument_exception",
                        "reason": reason
                    }
                ]
            },
            "status": 400
        }),
    ))
}

fn validate_wlm_cluster_mode_setting(
    persistent: &Value,
    transient: &Value,
) -> Option<RestResponse> {
    let value = transient
        .get("wlm.workload_group.mode")
        .or_else(|| persistent.get("wlm.workload_group.mode"))?;
    let Some(mode) = value.as_str() else {
        return Some(wlm_illegal_argument_response(
            "failed to parse setting [wlm.workload_group.mode]",
        ));
    };
    if matches!(mode, "enabled" | "monitor_only" | "disabled") {
        return None;
    }
    Some(wlm_illegal_argument_response(format!(
        "failed to parse setting [wlm.workload_group.mode] with value [{mode}]"
    )))
}

fn effective_cluster_time_setting_millis(
    persistent: &Value,
    transient: &Value,
    key: &str,
    default_millis: u64,
) -> Option<u64> {
    cluster_time_setting_millis(transient, key)
        .or_else(|| cluster_time_setting_millis(persistent, key))
        .or(Some(default_millis))
}

fn cluster_time_setting_millis(section: &Value, key: &str) -> Option<u64> {
    let value = section.get(key)?;
    if value.is_null() {
        return None;
    }
    match value {
        Value::String(raw) => parse_time_value_millis(raw),
        Value::Number(number) => number.as_u64(),
        _ => None,
    }
}

fn render_cluster_settings_section(section: &Value, flat_settings: bool) -> Value {
    if flat_settings {
        return match section {
            Value::Object(map) => Value::Object(map.clone()),
            _ => Value::Object(serde_json::Map::new()),
        };
    }
    expand_dotted_cluster_settings_section(section)
}

fn flatten_cluster_settings_section(section: &Value) -> serde_json::Map<String, Value> {
    let mut flat = serde_json::Map::new();
    flatten_cluster_settings_section_into(None, section, &mut flat);
    flat
}

fn flatten_cluster_settings_section_into(
    prefix: Option<&str>,
    section: &Value,
    flat: &mut serde_json::Map<String, Value>,
) {
    match section {
        Value::Object(map) => {
            for (key, value) in map {
                let next_key = prefix
                    .map(|current| format!("{current}.{key}"))
                    .unwrap_or_else(|| key.clone());
                if value.is_object() {
                    flatten_cluster_settings_section_into(Some(&next_key), value, flat);
                } else {
                    flat.insert(next_key, value.clone());
                }
            }
        }
        Value::Null => {
            if let Some(prefix) = prefix {
                flat.insert(prefix.to_string(), Value::Null);
            }
        }
        _ => {
            if let Some(prefix) = prefix {
                flat.insert(prefix.to_string(), section.clone());
            }
        }
    }
}

fn expand_dotted_cluster_settings_section(section: &Value) -> Value {
    let mut expanded = serde_json::Map::new();
    if let Value::Object(section_map) = section {
        for (key, value) in section_map {
            insert_dotted_cluster_setting_value(&mut expanded, key, value.clone());
        }
    }
    Value::Object(expanded)
}

fn insert_dotted_cluster_setting_value(
    target: &mut serde_json::Map<String, Value>,
    dotted_key: &str,
    value: Value,
) {
    let mut segments = dotted_key.split('.').peekable();
    let mut current = target;
    while let Some(segment) = segments.next() {
        if segments.peek().is_none() {
            current.insert(segment.to_string(), value);
            return;
        }
        let entry = current
            .entry(segment.to_string())
            .or_insert_with(|| Value::Object(serde_json::Map::new()));
        if !entry.is_object() {
            *entry = Value::Object(serde_json::Map::new());
        }
        current = entry
            .as_object_mut()
            .expect("cluster settings nested section must stay object");
    }
}

fn query_param_is_true(raw: Option<&String>) -> bool {
    matches!(raw.map(String::as_str), Some("true") | Some("1"))
}

fn rollover_condition_results(body: &Value, document_count: usize) -> Result<Value, RestResponse> {
    let Some(raw_conditions) = body.get("conditions") else {
        return Ok(serde_json::json!({}));
    };
    let Some(conditions) = raw_conditions.as_object() else {
        return Err(RestResponse::opensearch_error(
            400,
            "x_content_parse_exception",
            "[rollover] failed to parse field [conditions]",
        ));
    };
    for condition in conditions.keys() {
        if condition != "max_docs" {
            return Err(RestResponse::opensearch_error(
                400,
                "x_content_parse_exception",
                format!("[conditions] unknown field [{condition}]"),
            ));
        }
    }
    let Some(max_docs_value) = conditions.get("max_docs") else {
        return Ok(serde_json::json!({}));
    };
    let Some(max_docs) = max_docs_value.as_u64() else {
        return Err(RestResponse::opensearch_error(
            400,
            "illegal_argument_exception",
            "invalid token for [max_docs]",
        ));
    };
    Ok(serde_json::json!({
        format!("[max_docs: {max_docs}]"): (document_count as u64) >= max_docs
    }))
}

fn rollover_conditions_met(condition_results: &Value) -> bool {
    let Some(conditions) = condition_results.as_object() else {
        return true;
    };
    conditions.is_empty()
        || conditions
            .values()
            .any(|value| value.as_bool() == Some(true))
}

