    fn security_env_lock() -> MutexGuard<'static, ()> {
        static SECURITY_ENV_LOCK: std::sync::OnceLock<Mutex<()>> = std::sync::OnceLock::new();
        SECURITY_ENV_LOCK
            .get_or_init(|| Mutex::new(()))
            .lock()
            .expect("security env lock poisoned")
    }

    fn local_pit_id(value: &Value) -> String {
        let pit_id = value.as_str().expect("PIT id should be a string");
        assert!(
            pit_search_id_has_local_shape(pit_id),
            "PIT id should be an OpenSearch-shaped opaque id: {pit_id}"
        );
        assert!(
            pit_id.bytes().all(|byte| byte.is_ascii_alphanumeric()
                || byte == b'-'
                || byte == b'_'
                || byte == b'='),
            "PIT id should use OpenSearch-compatible base64url characters: {pit_id}"
        );
        pit_id.to_string()
    }

    fn assert_search_phase_shard_failure(response: &RestResponse, index: &str, reason: &str) {
        assert_eq!(response.status, 500);
        assert_eq!(
            response.body["error"]["type"],
            "search_phase_execution_exception"
        );
        assert_eq!(response.body["error"]["reason"], "all shards failed");
        assert_eq!(response.body["error"]["phase"], "query");
        assert_eq!(response.body["error"]["grouped"], true);
        assert_eq!(
            response.body["error"]["root_cause"][0]["type"],
            "search_exception"
        );
        assert_eq!(response.body["error"]["root_cause"][0]["reason"], reason);
        assert_eq!(
            response.body["error"]["failed_shards"][0],
            serde_json::json!({
                "shard": 0,
                "index": index,
                "reason": {
                    "type": "search_exception",
                    "reason": reason
                }
            })
        );
    }

    #[test]
    fn search_source_query_params_override_include_named_queries_score_and_verbose_pipeline_body() {
        let mut body = serde_json::json!({
            "query": { "match_all": {} },
            "include_named_queries_score": "maybe",
            "verbose_pipeline": "maybe"
        });
        let mut query_params = BTreeMap::new();
        query_params.insert(
            "include_named_queries_score".to_string(),
            "false".to_string(),
        );
        query_params.insert("verbose_pipeline".to_string(), "true".to_string());

        assert!(apply_search_source_query_params(&mut body, &query_params).is_none());
        assert_eq!(body["include_named_queries_score"], Value::Bool(false));
        assert_eq!(body["verbose_pipeline"], Value::Bool(true));
        assert!(validate_search_request_body(&body, false, "logs-test").is_none());
    }

    #[test]
    fn publication_round_state_accepts_main_rs_gateway_replay_fields() {
        let round = PublicationRoundState {
            state_uuid: "state-9".to_string(),
            version: 9,
            term: 1,
            target_nodes: BTreeSet::from(["node-a".to_string()]),
            acknowledged_nodes: BTreeSet::from(["node-a".to_string()]),
            applied_nodes: BTreeSet::from(["node-a".to_string()]),
            missing_nodes: BTreeSet::new(),
            proposal_transport_failures: BTreeMap::new(),
            acknowledgement_transport_failures: BTreeMap::new(),
            apply_transport_failures: BTreeMap::new(),
            required_quorum: 1,
            committed: true,
        };
        assert_eq!(round.version, 9);
        assert!(round.committed);
        assert!(round.target_nodes.contains("node-a"));
    }

    #[test]
    fn gateway_metadata_state_replays_into_manifest_shape_used_by_main_rs() {
        let mut manifest = serde_json::json!({
            "cluster_uuid": "cluster-uuid",
            "indices": {
                "logs-000001": {}
            },
            "templates": {}
        });
        let metadata_state = PersistedGatewayMetadataState {
            cluster_settings: ClusterSettingsState {
                persistent: BTreeMap::from([(
                    "cluster.routing.allocation.enable".to_string(),
                    serde_json::json!("all"),
                )]),
                transient: BTreeMap::from([(
                    "cluster.info.update.interval".to_string(),
                    serde_json::json!("30s"),
                )]),
            },
            index_aliases: BTreeMap::from([(
                "logs-000001".to_string(),
                serde_json::json!({
                    "logs-write": { "is_write_index": true }
                }),
            )]),
            legacy_index_templates: BTreeMap::new(),
            component_templates: BTreeMap::from([(
                "gateway-component".to_string(),
                serde_json::json!({
                    "template": { "settings": { "index": { "number_of_replicas": 0 } } }
                }),
            )]),
            index_templates: BTreeMap::from([(
                "gateway-template".to_string(),
                serde_json::json!({
                    "index_patterns": ["logs-*"]
                }),
            )]),
        };

        apply_gateway_metadata_state_to_manifest(&mut manifest, &metadata_state);

        assert_eq!(
            manifest["cluster_settings"]["persistent"]["cluster.routing.allocation.enable"],
            "all"
        );
        assert_eq!(
            manifest["cluster_settings"]["transient"]["cluster.info.update.interval"],
            "30s"
        );
        assert_eq!(
            manifest["indices"]["logs-000001"]["aliases"]["logs-write"]["is_write_index"],
            true
        );
        assert!(manifest["templates"]["component_templates"]
            .get("gateway-component")
            .is_some());
        assert!(manifest["templates"]["index_templates"]
            .get("gateway-template")
            .is_some());
    }

