    #[test]
    fn data_stream_named_routes_support_get_put_and_delete() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let template_put = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/_index_template/probe-data-stream-template",
            )
            .with_json_body(serde_json::json!({
                "index_patterns": ["logs-ds-*"],
                "data_stream": {},
                "template": {
                    "settings": {
                        "index": {
                            "number_of_replicas": 0
                        }
                    }
                }
            })),
        );
        assert_eq!(template_put.status, 200);

        let put_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Put,
            "/_data_stream/logs-ds-prod",
        ));
        assert_eq!(put_response.status, 200);
        assert_eq!(put_response.body["acknowledged"], Value::Bool(true));

        let get_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_data_stream/logs-ds-prod",
        ));
        assert_eq!(get_response.status, 200);
        assert_eq!(get_response.body["data_streams"][0]["name"], "logs-ds-prod");
        assert_eq!(get_response.body["data_streams"][0]["status"], "GREEN");
        let backing_index = get_response.body["data_streams"][0]["indices"][0]["index_name"]
            .as_str()
            .expect("data stream backing index");
        let get_backing_index = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            &format!("/{backing_index}"),
        ));
        assert_eq!(get_backing_index.status, 200);
        assert_eq!(
            get_backing_index.body[backing_index]["settings"]["index"]["number_of_replicas"],
            Value::String("0".to_string())
        );

        let stats_response =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_data_stream/_stats"));
        assert_eq!(stats_response.status, 200);
        assert_eq!(stats_response.body["data_stream_count"], Value::from(1));
        assert_eq!(stats_response.body["backing_indices"], Value::from(1));

        let named_stats_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_data_stream/logs-ds-prod/_stats",
        ));
        assert_eq!(named_stats_response.status, 200);
        assert_eq!(
            named_stats_response.body["data_stream_count"],
            Value::from(1)
        );

        let invalid_stats_expand_wildcards = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_data_stream/_stats?expand_wildcards=bogus",
        ));
        assert_eq!(invalid_stats_expand_wildcards.status, 400);
        assert_eq!(
            invalid_stats_expand_wildcards.body["error"]["reason"],
            "No valid expand wildcard value [bogus]"
        );

        let delete_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/_data_stream/logs-ds-prod",
        ));
        assert_eq!(delete_response.status, 200);
        assert_eq!(delete_response.body["acknowledged"], Value::Bool(true));

        let missing_get = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_data_stream/logs-ds-prod",
        ));
        assert_eq!(missing_get.status, 404);

        let stats_after_delete =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_data_stream/_stats"));
        assert_eq!(stats_after_delete.status, 200);
        assert_eq!(stats_after_delete.body["data_stream_count"], Value::from(0));
        assert_eq!(stats_after_delete.body["backing_indices"], Value::from(0));

        let missing_delete = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/_data_stream/logs-ds-prod",
        ));
        assert_eq!(missing_delete.status, 404);
        assert_eq!(
            missing_delete.body["error"]["type"],
            Value::String("resource_not_found_exception".to_string())
        );
    }

    #[test]
    fn data_stream_document_routes_require_create_op_type() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let template_put = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/_index_template/probe-data-stream-template",
            )
            .with_json_body(serde_json::json!({
                "index_patterns": ["logs-ds-*"],
                "data_stream": {}
            })),
        );
        assert_eq!(template_put.status, 200);

        let put_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Put,
            "/_data_stream/logs-ds-prod",
        ));
        assert_eq!(put_response.status, 200);

        let index_write = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-ds-prod/_doc/doc-1?refresh=true")
                .with_json_body(serde_json::json!({
                    "@timestamp": "2024-01-01T00:00:00Z",
                    "message": "stream event"
                })),
        );
        assert_eq!(index_write.status, 400);
        assert_eq!(
            index_write.body["error"]["type"],
            Value::String("illegal_argument_exception".to_string())
        );
        assert!(index_write.body["error"]["reason"]
            .as_str()
            .is_some_and(|reason| reason.contains("only write ops with an op_type of create")));

        let create_write = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-ds-prod/_doc/doc-1?op_type=create&refresh=true",
            )
            .with_json_body(serde_json::json!({
                "@timestamp": "2024-01-01T00:00:01Z",
                "message": "created stream event"
            })),
        );
        assert_eq!(create_write.status, 201);
        assert_eq!(
            create_write.body["result"],
            Value::String("created".to_string())
        );

        let duplicate_create = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-ds-prod/_doc/doc-1?op_type=create")
                .with_json_body(serde_json::json!({
                    "@timestamp": "2024-01-01T00:00:02Z",
                    "message": "duplicate stream event"
                })),
        );
        assert_eq!(duplicate_create.status, 409);
    }

    #[test]
    fn component_template_named_routes_support_get_head_put_post_and_delete() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let put_response = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/_component_template/probe-component-template?cluster_manager_timeout=30s",
            )
            .with_json_body(serde_json::json!({
                "template": {
                    "settings": {
                        "index": {
                            "number_of_replicas": 0
                        }
                    }
                }
            })),
        );
        assert_eq!(put_response.status, 200);
        assert_eq!(put_response.body["acknowledged"], Value::Bool(true));

        let local_get_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_component_template/probe-component-template?local=true&master_timeout=30s",
        ));
        assert_eq!(local_get_response.status, 200);

        let invalid_cluster_manager_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_component_template/probe-component-template?cluster_manager_timeout=soon",
        ));
        assert_eq!(invalid_cluster_manager_timeout.status, 400);
        assert_eq!(
            invalid_cluster_manager_timeout.body["error"]["type"],
            "illegal_argument_exception"
        );
        assert_eq!(
            invalid_cluster_manager_timeout.body["error"]["reason"],
            "failed to parse setting [cluster_manager_timeout] with value [soon] as a time value"
        );

        let duplicate_timeout_alias = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/_component_template/probe-component-template?master_timeout=30s&cluster_manager_timeout=30s",
        ));
        assert_eq!(duplicate_timeout_alias.status, 400);
        assert_eq!(
            duplicate_timeout_alias.body["error"]["type"],
            "parse_exception"
        );
        assert_eq!(
            duplicate_timeout_alias.body["error"]["reason"],
            "Please only use one of the request parameters [master_timeout, cluster_manager_timeout]."
        );

        let unsupported_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Put,
            "/_component_template/probe-component-template?timeout=30s",
        ));
        assert_eq!(unsupported_timeout.status, 400);

        let get_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_component_template/probe-component-template",
        ));
        assert_eq!(get_response.status, 200);
        assert_eq!(
            get_response.body["component_templates"][0]["name"],
            "probe-component-template"
        );

        let head_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Head,
            "/_component_template/probe-component-template",
        ));
        assert_eq!(head_response.status, 200);

        let post_response = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/_component_template/probe-component-template",
            )
            .with_json_body(serde_json::json!({
                "template": {
                    "mappings": {
                        "properties": {
                            "tenant": {
                                "type": "keyword"
                            }
                        }
                    }
                }
            })),
        );
        assert_eq!(post_response.status, 200);
        assert_eq!(post_response.body["acknowledged"], Value::Bool(true));

        let post_readback = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_component_template/probe-component-template",
        ));
        assert_eq!(post_readback.status, 200);
        assert_eq!(
            post_readback.body["component_templates"][0]["component_template"]["template"]
                ["mappings"]["properties"]["tenant"]["type"],
            "keyword"
        );

        let delete_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/_component_template/probe-component-template",
        ));
        assert_eq!(delete_response.status, 200);
        assert_eq!(delete_response.body["acknowledged"], Value::Bool(true));

        let missing_get = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_component_template/probe-component-template",
        ));
        assert_eq!(missing_get.status, 404);

        let missing_head = node.handle_rest_request(RestRequest::new(
            RestMethod::Head,
            "/_component_template/probe-component-template",
        ));
        assert_eq!(missing_head.status, 404);

        let missing_delete = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/_component_template/probe-component-template",
        ));
        assert_eq!(missing_delete.status, 404);
        assert_eq!(
            missing_delete.body["error"]["type"],
            Value::String("index_template_missing_exception".to_string())
        );
    }

    #[test]
    fn index_template_named_and_simulate_routes_support_full_contract() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let put_response = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/_index_template/probe-index-template?cluster_manager_timeout=30s&create=false&cause=api",
            )
            .with_json_body(serde_json::json!({
                    "index_patterns": ["logs-sim-*"],
                    "priority": 7,
                    "template": {
                        "settings": {
                            "index": {
                                "number_of_replicas": 0
                            }
                        }
                    }
                })),
        );
        assert_eq!(put_response.status, 200);
        assert_eq!(put_response.body["acknowledged"], Value::Bool(true));

        let local_get_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_index_template/probe-index-template?local=true&master_timeout=30s",
        ));
        assert_eq!(local_get_response.status, 200);

        let invalid_cluster_manager_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_index_template/_simulate?cluster_manager_timeout=soon",
        ));
        assert_eq!(invalid_cluster_manager_timeout.status, 400);
        assert_eq!(
            invalid_cluster_manager_timeout.body["error"]["type"],
            "illegal_argument_exception"
        );
        assert_eq!(
            invalid_cluster_manager_timeout.body["error"]["reason"],
            "failed to parse setting [cluster_manager_timeout] with value [soon] as a time value"
        );

        let duplicate_timeout_alias = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_index_template/_simulate/probe-index-template?master_timeout=30s&cluster_manager_timeout=30s",
        ));
        assert_eq!(duplicate_timeout_alias.status, 400);
        assert_eq!(
            duplicate_timeout_alias.body["error"]["type"],
            "parse_exception"
        );
        assert_eq!(
            duplicate_timeout_alias.body["error"]["reason"],
            "Please only use one of the request parameters [master_timeout, cluster_manager_timeout]."
        );

        let unsupported_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_index_template/_simulate_index/logs-sim-000001?timeout=30s",
        ));
        assert_eq!(unsupported_timeout.status, 400);

        let get_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_index_template/probe-index-template",
        ));
        assert_eq!(get_response.status, 200);
        assert_eq!(
            get_response.body["index_templates"][0]["name"],
            "probe-index-template"
        );

        let head_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Head,
            "/_index_template/probe-index-template",
        ));
        assert_eq!(head_response.status, 200);

        let simulate_response = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_index_template/_simulate").with_json_body(
                serde_json::json!({
                    "index_patterns": ["logs-sim-*"],
                    "template": {
                        "settings": {
                            "index": {
                                "refresh_interval": "30s"
                            }
                        }
                    }
                }),
            ),
        );
        assert_eq!(simulate_response.status, 200);
        assert!(simulate_response.body["template"].is_object());

        let named_simulate_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_index_template/_simulate/probe-index-template",
        ));
        assert_eq!(named_simulate_response.status, 200);
        assert_eq!(
            named_simulate_response.body["template"]["settings"]["index"]["number_of_replicas"],
            "0"
        );

        let index_simulate_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_index_template/_simulate_index/logs-sim-000001",
        ));
        assert_eq!(index_simulate_response.status, 200);
        assert_eq!(
            index_simulate_response.body["template"]["settings"]["index"]["number_of_replicas"],
            "0"
        );

        let invalid_simulate_body = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_index_template/_simulate")
                .with_body(b"{\"index_patterns\":[".to_vec()),
        );
        assert_eq!(invalid_simulate_body.status, 400);
        assert_eq!(
            invalid_simulate_body.body["error"]["type"],
            "parse_exception"
        );

        let invalid_simulate_index_body = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/_index_template/_simulate_index/logs-sim-000001",
            )
            .with_body(b"{\"template\":".to_vec()),
        );
        assert_eq!(invalid_simulate_index_body.status, 400);
        assert_eq!(
            invalid_simulate_index_body.body["error"]["type"],
            "parse_exception"
        );

        let missing_named_simulate = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_index_template/_simulate/missing-index-template",
        ));
        assert_eq!(missing_named_simulate.status, 400);
        assert_eq!(
            missing_named_simulate.body["error"]["type"],
            "illegal_argument_exception"
        );

        let post_response = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_index_template/probe-index-template")
                .with_json_body(serde_json::json!({
                    "index_patterns": ["logs-sim-*"],
                    "template": {
                        "mappings": {
                            "properties": {
                                "tenant": {
                                    "type": "keyword"
                                }
                            }
                        }
                    }
                })),
        );
        assert_eq!(post_response.status, 200);
        assert_eq!(post_response.body["acknowledged"], Value::Bool(true));

        let post_readback = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_index_template/probe-index-template",
        ));
        assert_eq!(post_readback.status, 200);
        assert_eq!(
            post_readback.body["index_templates"][0]["index_template"]["template"]["mappings"]
                ["properties"]["tenant"]["type"],
            "keyword"
        );

        let delete_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/_index_template/probe-index-template",
        ));
        assert_eq!(delete_response.status, 200);
        assert_eq!(delete_response.body["acknowledged"], Value::Bool(true));

        let missing_get = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_index_template/probe-index-template",
        ));
        assert_eq!(missing_get.status, 404);

        let missing_head = node.handle_rest_request(RestRequest::new(
            RestMethod::Head,
            "/_index_template/probe-index-template",
        ));
        assert_eq!(missing_head.status, 404);
    }

    #[test]
    fn create_index_applies_matching_composable_and_component_templates() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let component_put = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/_component_template/logs-component-template",
            )
            .with_json_body(serde_json::json!({
                "template": {
                    "settings": {
                        "index": {
                            "number_of_replicas": 0
                        }
                    },
                    "mappings": {
                        "properties": {
                            "tenant": {
                                "type": "keyword"
                            }
                        }
                    },
                    "aliases": {
                        "logs-component-read": {}
                    }
                }
            })),
        );
        assert_eq!(component_put.status, 200);

        let index_template_put = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_index_template/logs-composable-template")
                .with_json_body(serde_json::json!({
                    "index_patterns": ["logs-composable-*"],
                    "composed_of": ["logs-component-template"],
                    "priority": 10,
                    "template": {
                        "settings": {
                            "index": {
                                "number_of_shards": 1
                            }
                        },
                        "aliases": {
                            "logs-template-read": {}
                        }
                    }
                })),
        );
        assert_eq!(index_template_put.status, 200);

        let create_index =
            node.handle_rest_request(RestRequest::new(RestMethod::Put, "/logs-composable-000001"));
        assert_eq!(create_index.status, 200);

        let get_index =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/logs-composable-000001"));
        assert_eq!(get_index.status, 200);
        let index_body = &get_index.body["logs-composable-000001"];
        assert_eq!(
            index_body["mappings"]["properties"]["tenant"]["type"],
            Value::String("keyword".to_string())
        );
        assert!(index_body["aliases"]["logs-component-read"].is_object());
        assert!(index_body["aliases"]["logs-template-read"].is_object());
        assert_eq!(
            index_body["settings"]["index"]["number_of_replicas"],
            Value::String("0".to_string())
        );
        assert_eq!(
            index_body["settings"]["index"]["number_of_shards"],
            Value::String("1".to_string())
        );
    }

