    #[test]
    fn index_block_route_marks_targeted_block_state() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-block-probe")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(create.status, 200);

        let block_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Put,
            "/logs-block-probe/_block/write",
        ));
        assert_eq!(block_response.status, 200);
        assert_eq!(block_response.body["acknowledged"], Value::Bool(true));
        assert_eq!(
            block_response.body["shards_acknowledged"],
            Value::Bool(true)
        );
        assert_eq!(block_response.body["indices"][0], "logs-block-probe");

        let manifest = node
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        assert_eq!(
            manifest["indices"]["logs-block-probe"]["blocks"]["write"],
            Value::Bool(true)
        );
        drop(manifest);

        let invalid_block = node.handle_rest_request(RestRequest::new(
            RestMethod::Put,
            "/logs-block-probe/_block/not_a_block",
        ));
        assert_eq!(invalid_block.status, 400);
        assert_eq!(
            invalid_block.body["error"]["reason"],
            "No block found with name not_a_block"
        );

        let missing_index = node.handle_rest_request(RestRequest::new(
            RestMethod::Put,
            "/missing-block-probe/_block/write",
        ));
        assert_eq!(missing_index.status, 404);
        assert_eq!(
            missing_index.body["error"]["type"],
            "index_not_found_exception"
        );

        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-block-selector-000001")
                .with_json_body(serde_json::json!({})),
        );
        let selector = node.handle_rest_request(RestRequest::new(
            RestMethod::Put,
            "/logs-block-selector-*/_block/read",
        ));
        assert_eq!(selector.status, 200);
        assert_eq!(selector.body["indices"][0], "logs-block-selector-000001");
        let manifest = node
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        assert_eq!(
            manifest["indices"]["logs-block-selector-000001"]["blocks"]["read"],
            Value::Bool(true)
        );
    }

    #[test]
    fn index_resize_routes_create_target_indices_for_clone_shrink_split_and_scale() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-resize-probe")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(create.status, 200);

        let clone_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Put,
            "/logs-resize-probe/_clone/logs-clone-probe",
        ));
        assert_eq!(clone_response.status, 200);
        assert_eq!(clone_response.body["acknowledged"], Value::Bool(true));
        assert_eq!(
            clone_response.body["shards_acknowledged"],
            Value::Bool(true)
        );
        assert_eq!(clone_response.body["index"], "logs-clone-probe");

        let shrink_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-resize-probe/_shrink/logs-shrink-probe",
        ));
        assert_eq!(shrink_response.status, 400);
        assert_eq!(
            shrink_response.body["error"]["type"],
            "illegal_argument_exception"
        );
        assert_eq!(
            shrink_response.body["error"]["reason"],
            "can't shrink an index with only one shard"
        );

        let split_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Put,
            "/logs-resize-probe/_split/logs-split-probe",
        ));
        assert_eq!(split_response.status, 400);
        assert_eq!(
            split_response.body["error"]["type"],
            "action_request_validation_exception"
        );
        assert_eq!(
            split_response.body["error"]["reason"],
            "Validation Failed: 1: index.number_of_shards is required for split operations;"
        );

        let selector_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Put,
            "/logs-resize-probe/_clone/logs-clone-selector?timeout=30s&cluster_manager_timeout=30s&wait_for_active_shards=1&wait_for_completion=true&copy_settings=true",
        ));
        assert_eq!(selector_response.status, 200);
        assert_eq!(selector_response.body["index"], "logs-clone-selector");

        let shrink_selector_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-resize-probe/_shrink/logs-shrink-selector?timeout=30s&cluster_manager_timeout=30s&wait_for_active_shards=1&wait_for_completion=true&copy_settings=true",
        ));
        assert_eq!(shrink_selector_response.status, 400);
        assert_eq!(
            shrink_selector_response.body["error"]["reason"],
            "can't shrink an index with only one shard"
        );

        let split_selector_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Put,
            "/logs-resize-probe/_split/logs-split-selector?timeout=30s&cluster_manager_timeout=30s&wait_for_active_shards=1&wait_for_completion=true&copy_settings=true",
        ));
        assert_eq!(split_selector_response.status, 400);
        assert_eq!(
            split_selector_response.body["error"]["reason"],
            "Validation Failed: 1: index.number_of_shards is required for split operations;"
        );

        let invalid_wait = node.handle_rest_request(RestRequest::new(
            RestMethod::Put,
            "/logs-resize-probe/_clone/logs-clone-invalid-wait?wait_for_completion=maybe",
        ));
        assert_eq!(invalid_wait.status, 400);
        assert_eq!(
            invalid_wait.body["error"]["reason"],
            "Failed to parse value [maybe] as only [true] or [false] are allowed."
        );

        let duplicate_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Put,
            "/logs-resize-probe/_clone/logs-clone-duplicate-timeout?master_timeout=30s&cluster_manager_timeout=30s",
        ));
        assert_eq!(duplicate_timeout.status, 400);
        assert_eq!(duplicate_timeout.body["error"]["type"], "parse_exception");

        let copy_settings_false = node.handle_rest_request(RestRequest::new(
            RestMethod::Put,
            "/logs-resize-probe/_clone/logs-clone-copy-settings-false?copy_settings=false",
        ));
        assert_eq!(copy_settings_false.status, 400);
        assert_eq!(
            copy_settings_false.body["error"]["reason"],
            "parameter [copy_settings] can not be explicitly set to [false]"
        );

        let scale_response = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-resize-probe/_scale")
                .with_json_body(serde_json::json!({ "search_only": true })),
        );
        assert_eq!(scale_response.status, 400);
        assert_eq!(
            scale_response.body["error"]["reason"],
            "To scale to zero, index.remote_store.enabled must be enabled for index: logs-resize-probe"
        );

        let scale_up_response = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-resize-probe/_scale")
                .with_json_body(serde_json::json!({ "search_only": false })),
        );
        assert_eq!(scale_up_response.status, 500);
        assert_eq!(
            scale_up_response.body["error"]["reason"],
            "Index [logs-resize-probe] is not in search-only mode"
        );

        let invalid_scale_body = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-resize-probe/_scale")
                .with_json_body(serde_json::json!({ "target": "logs-scale-probe" })),
        );
        assert_eq!(invalid_scale_body.status, 400);
        assert_eq!(
            invalid_scale_body.body["error"]["reason"],
            "Unknown parameter [target]. Only [search_only] is allowed."
        );

        let manifest = node
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        for (target, operation) in [
            ("logs-clone-probe", "clone"),
            ("logs-clone-selector", "clone"),
        ] {
            assert_eq!(
                manifest["indices"][target]["resize_source"],
                "logs-resize-probe"
            );
            assert_eq!(manifest["indices"][target]["resize_operation"], operation);
        }
        assert_eq!(
            manifest["indices"]["logs-resize-probe"]["settings"]["index.blocks.search_only"],
            Value::Null
        );
        assert_eq!(
            manifest["indices"]["logs-resize-probe"]["blocks"]["search_only"],
            Value::Null
        );
    }

    #[test]
    fn rollover_routes_support_unnamed_and_named_target_contracts() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-rollover-000001")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(create.status, 200);

        let alias = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/logs-rollover-000001/_alias/logs-rollover-write",
            )
            .with_json_body(serde_json::json!({
                "is_write_index": true
            })),
        );
        assert_eq!(alias.status, 200);

        let unnamed = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-rollover-write/_rollover",
        ));
        assert_eq!(unnamed.status, 200);
        assert_eq!(unnamed.body["old_index"], "logs-rollover-000001");
        assert_eq!(unnamed.body["new_index"], "logs-rollover-000002");
        assert_eq!(unnamed.body["rolled_over"], Value::Bool(true));

        let named = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-rollover-write/_rollover/logs-rollover-000123",
            )
            .with_json_body(serde_json::json!({
                "settings": {
                    "index.number_of_replicas": 0
                },
                "aliases": {
                    "logs-rollover-read": {}
                }
            })),
        );
        assert_eq!(named.status, 200);
        assert_eq!(named.body["old_index"], "logs-rollover-000002");
        assert_eq!(named.body["new_index"], "logs-rollover-000123");
        assert_eq!(named.body["rolled_over"], Value::Bool(true));

        let dry_run = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-rollover-write/_rollover/logs-rollover-000124?dry_run=true&timeout=30s&cluster_manager_timeout=30s&wait_for_active_shards=1",
        ));
        assert_eq!(dry_run.status, 200);
        assert_eq!(dry_run.body["old_index"], "logs-rollover-000123");
        assert_eq!(dry_run.body["new_index"], "logs-rollover-000124");
        assert_eq!(dry_run.body["rolled_over"], Value::Bool(false));
        assert_eq!(dry_run.body["dry_run"], Value::Bool(true));

        let invalid_dry_run = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-rollover-write/_rollover/logs-rollover-invalid?dry_run=maybe",
        ));
        assert_eq!(invalid_dry_run.status, 400);
        assert_eq!(
            invalid_dry_run.body["error"]["reason"],
            "Failed to parse value [maybe] as only [true] or [false] are allowed."
        );

        let duplicate_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-rollover-write/_rollover/logs-rollover-duplicate-timeout?master_timeout=30s&cluster_manager_timeout=30s",
        ));
        assert_eq!(duplicate_timeout.status, 400);
        assert_eq!(duplicate_timeout.body["error"]["type"], "parse_exception");

        let manifest = node
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        assert_eq!(
            manifest["indices"]["logs-rollover-000001"]["aliases"]["logs-rollover-write"]
                ["is_write_index"],
            Value::Bool(false)
        );
        assert_eq!(
            manifest["indices"]["logs-rollover-000002"]["aliases"]["logs-rollover-write"]
                ["is_write_index"],
            Value::Bool(false)
        );
        assert_eq!(
            manifest["indices"]["logs-rollover-000123"]["aliases"]["logs-rollover-write"]
                ["is_write_index"],
            Value::Bool(true)
        );
        assert_eq!(
            manifest["indices"]["logs-rollover-000123"]["settings"]["index.number_of_replicas"],
            "0"
        );
        assert!(manifest["indices"]["logs-rollover-000123"]["aliases"]
            .get("logs-rollover-read")
            .is_some());
        assert!(
            manifest["indices"].get("logs-rollover-000124").is_none(),
            "dry-run rollover must not create target index"
        );
    }

    #[test]
