    #[test]
    fn rollover_max_docs_condition_true_mutates_alias_target() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-condition-met-000001")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(create.status, 200);

        let alias = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/logs-condition-met-000001/_alias/logs-condition-met-write",
            )
            .with_json_body(serde_json::json!({
                "is_write_index": true
            })),
        );
        assert_eq!(alias.status, 200);

        let doc = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/logs-condition-met-000001/_doc/doc-1?refresh=true",
            )
            .with_json_body(serde_json::json!({
                "message": "ready for rollover"
            })),
        );
        assert_eq!(doc.status, 201);

        let response = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-condition-met-write/_rollover/logs-condition-met-000002",
            )
            .with_json_body(serde_json::json!({
                "conditions": {
                    "max_docs": 1
                }
            })),
        );
        assert_eq!(response.status, 200);
        assert_eq!(response.body["old_index"], "logs-condition-met-000001");
        assert_eq!(response.body["new_index"], "logs-condition-met-000002");
        assert_eq!(response.body["rolled_over"], Value::Bool(true));
        assert_eq!(response.body["acknowledged"], Value::Bool(true));
        assert_eq!(response.body["shards_acknowledged"], Value::Bool(true));
        assert_eq!(
            response.body["conditions"]["[max_docs: 1]"],
            Value::Bool(true)
        );

        let manifest = node
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        assert_eq!(
            manifest["indices"]["logs-condition-met-000001"]["aliases"]["logs-condition-met-write"]
                ["is_write_index"],
            Value::Bool(false)
        );
        assert_eq!(
            manifest["indices"]["logs-condition-met-000002"]["aliases"]["logs-condition-met-write"]
                ["is_write_index"],
            Value::Bool(true)
        );
    }

    #[test]
    fn rollover_unknown_condition_fails_without_mutating_alias_target() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-unknown-condition-000001")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(create.status, 200);

        let alias = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/logs-unknown-condition-000001/_alias/logs-unknown-condition-write",
            )
            .with_json_body(serde_json::json!({
                "is_write_index": true
            })),
        );
        assert_eq!(alias.status, 200);

        let response = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-unknown-condition-write/_rollover/logs-unknown-condition-000002",
            )
            .with_json_body(serde_json::json!({
                "conditions": {
                    "min_docs": 1
                }
            })),
        );
        assert_eq!(response.status, 400);
        assert_eq!(response.body["error"]["type"], "x_content_parse_exception");
        assert!(response.body["error"]["reason"]
            .as_str()
            .unwrap_or_default()
            .contains("unknown field [min_docs]"));

        let manifest = node
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        assert_eq!(
            manifest["indices"]["logs-unknown-condition-000001"]["aliases"]
                ["logs-unknown-condition-write"]["is_write_index"],
            Value::Bool(true)
        );
        assert!(
            manifest["indices"]
                .get("logs-unknown-condition-000002")
                .is_none(),
            "unknown rollover condition must not create the candidate index"
        );
    }

    #[test]
    fn rollover_named_target_resolves_create_index_body_write_alias_after_cleanup() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let initial_create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/rollover-logs-000001").with_json_body(
                serde_json::json!({
                    "aliases": {
                        "rollover-write": {
                            "is_write_index": true
                        }
                    }
                }),
            ),
        );
        assert_eq!(initial_create.status, 200);

        let initial_readback =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_alias/rollover-write"));
        assert_eq!(initial_readback.status, 200);

        let cleanup = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/rollover-logs-000001,rollover-logs-000002?ignore_unavailable=true",
        ));
        assert_eq!(cleanup.status, 200);

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/rollover-logs-000001").with_json_body(
                serde_json::json!({
                    "aliases": {
                        "rollover-write": {
                            "is_write_index": true
                        }
                    }
                }),
            ),
        );
        assert_eq!(create.status, 200);

        let readback =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_alias/rollover-write"));
        assert_eq!(readback.status, 200);
        assert_eq!(
            readback.body["rollover-logs-000001"]["aliases"]["rollover-write"]["is_write_index"],
            Value::Bool(true)
        );

        let rollover = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/rollover-write/_rollover/rollover-logs-000002",
        ));
        assert_eq!(rollover.status, 200, "{rollover:?}");
        assert_eq!(rollover.body["old_index"], "rollover-logs-000001");
        assert_eq!(rollover.body["new_index"], "rollover-logs-000002");
        assert_eq!(rollover.body["rolled_over"], Value::Bool(true));
    }

