    #[test]
    fn extension_registry_uses_rust_native_extension_api_descriptors() {
        let registry = ExtensionBoundaryRegistry {
            manifest_path: Some(PathBuf::from("/tmp/steelsearch-extensions.json")),
            knn_plugin_enabled: true,
            ml_commons_enabled: true,
        };
        let descriptors = registry.rust_native_extension_descriptors();
        assert_eq!(descriptors.len(), 3);
        assert!(descriptors.iter().any(|descriptor| {
            descriptor.module == "steelsearch-runtime"
                && descriptor.classname == "org.steelsearch.runtime.Plugin"
                && descriptor.rest_routes
                    == &[
                        "/_cat/plugins",
                        "/_steelsearch/dev/extensions",
                        "/_steelsearch/dev/extensions/_shutdown",
                        "/_steelsearch/dev/extensions/_recovery_failed",
                        "/_steelsearch/readiness",
                    ]
                && descriptor.transport_actions.is_empty()
                && descriptor.search_extension_points == STEELSEARCH_SEARCH_EXTENSION_POINTS
                && descriptor
                    .lifecycle_hooks
                    .contains(&"set_live_shutdown_in_progress")
                && descriptor
                    .lifecycle_hooks
                    .contains(&"set_shared_runtime_state_recovery_failed")
        }));
        assert!(descriptors.iter().any(|descriptor| {
            descriptor.module == "opensearch-knn"
                && descriptor.module == os_plugin_knn::KNN_PLUGIN_NAME
                && descriptor.feature == "knn-rest-compatibility"
                && descriptor.feature == os_plugin_knn::KNN_EXTENSION_FEATURE
                && descriptor.description.contains("Rust-native k-NN")
                && !descriptor.rest_routes.contains(&"/_plugins/_knn/settings")
                && descriptor.transport_actions.is_empty()
                && descriptor.search_extension_points == &["query"]
                && descriptor.lifecycle_hooks.is_empty()
        }));
        assert!(descriptors.iter().any(|descriptor| {
            descriptor.module == "opensearch-ml-commons"
                && descriptor.module == os_ml_commons::ML_COMMONS_EXTENSION_MODULE
                && descriptor.feature == "ml-commons-rest-compatibility"
                && descriptor.feature == os_ml_commons::ML_COMMONS_EXTENSION_FEATURE
                && descriptor.description.contains("Rust-native ML Commons")
                && descriptor.rest_routes.contains(&"/_plugins/_ml/connectors")
                && descriptor.transport_actions.is_empty()
                && descriptor.lifecycle_hooks.is_empty()
        }));
    }

    #[test]
    fn search_extension_point_contract_maps_opensearch_hooks_to_rust_native_boundaries() {
        let contracts = search_extension_point_contracts();
        assert!(contracts.len() >= STEELSEARCH_SEARCH_EXTENSION_POINTS.len());

        for point in STEELSEARCH_SEARCH_EXTENSION_POINTS {
            assert!(
                contracts
                    .iter()
                    .any(|contract| contract.steelsearch_point == *point),
                "missing search extension point contract for {point}"
            );
        }

        let expected_hooks = [
            "registerFromPlugin(SearchPlugin::getAggregations)",
            "registerAggregation(AggregationSpec, ValuesSourceRegistry.Builder)",
            "registerFromPlugin(SearchPlugin::getAggregationExtentions)",
            "registerFetchSubPhase(FetchSubPhase)",
            "registerPipelineAggregation(PipelineAggregationSpec)",
            "registerQuery(QuerySpec)",
            "registerScoreFunction(ScoreFunctionSpec)",
            "registerSuggester(SuggesterSpec)",
        ];
        for hook in expected_hooks {
            assert!(
                contracts.iter().any(|contract| {
                    contract.opensearch_hook == hook
                        && contract.status == "rust-native-boundary"
                        && contract.evidence.contains("registry-visible")
                }),
                "missing OpenSearch search hook contract for {hook}"
            );
        }
    }

