    #[test]
    fn cluster_settings_get_accepts_opensearch_local_and_timeout_params() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/settings?local=true&cluster_manager_timeout=30s&flat_settings=true",
        ));

        assert_eq!(response.status, 200);
        assert!(response.body["persistent"].is_object());
        assert!(response.body["transient"].is_object());

        let invalid_local = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/settings?local=maybe",
        ));
        assert_eq!(invalid_local.status, 400);
        assert_eq!(
            invalid_local.body["error"]["reason"],
            "Failed to parse value [maybe] as only [true] or [false] are allowed."
        );

        let invalid_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/settings?cluster_manager_timeout=soon",
        ));
        assert_eq!(invalid_timeout.status, 400);
        assert_eq!(
            invalid_timeout.body["error"]["reason"],
            "failed to parse setting [cluster_manager_timeout] with value [soon] as a time value"
        );

        let duplicate_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/settings?master_timeout=30s&cluster_manager_timeout=30s",
        ));
        assert_eq!(duplicate_timeout.status, 400);
        assert_eq!(duplicate_timeout.body["error"]["type"], "parse_exception");
        assert_eq!(
            duplicate_timeout.body["error"]["reason"],
            "Please only use one of the request parameters [master_timeout, cluster_manager_timeout]."
        );
    }

    #[test]
    fn cluster_settings_put_accepts_opensearch_timeout_and_format_params() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let response = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/_cluster/settings?timeout=30s&cluster_manager_timeout=30s&flat_settings=true&settings_filter=cluster.info.*",
            )
            .with_json_body(serde_json::json!({
                "persistent": {
                    "cluster.routing.allocation.enable": "primaries"
                },
                "transient": {
                    "cluster.info.update.interval": "45s",
                    "search.default_keep_alive": "2m"
                }
            })),
        );

        assert_eq!(response.status, 200);
        assert_eq!(response.body["acknowledged"], true);
        assert_eq!(
            response.body["persistent"]["cluster.routing.allocation.enable"],
            "primaries"
        );
        assert_eq!(
            response.body["transient"]["search.default_keep_alive"],
            "2m"
        );
        assert!(response.body["transient"]
            .as_object()
            .expect("transient settings object")
            .get("cluster.info.update.interval")
            .is_none());

        let readback = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/settings?flat_settings=true&settings_filter=cluster.routing.*",
        ));
        assert_eq!(readback.status, 200);
        assert!(readback.body["persistent"]
            .as_object()
            .expect("persistent settings object")
            .get("cluster.routing.allocation.enable")
            .is_none());
        assert_eq!(
            readback.body["transient"]["cluster.info.update.interval"],
            "45s"
        );

        let duplicate_timeout = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/_cluster/settings?timeout=30s&master_timeout=30s&cluster_manager_timeout=30s",
            )
            .with_json_body(serde_json::json!({
                "persistent": {}
            })),
        );
        assert_eq!(duplicate_timeout.status, 400);
        assert_eq!(duplicate_timeout.body["error"]["type"], "parse_exception");
        assert_eq!(
            duplicate_timeout.body["error"]["reason"],
            "Please only use one of the request parameters [master_timeout, cluster_manager_timeout]."
        );
    }

