    #[test]
    fn voting_config_exclusions_routes_match_bounded_source_contract() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let post_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_cluster/voting_config_exclusions?node_names=steel-node&timeout=1ms",
        ));
        assert_eq!(post_timeout.status, 500);
        assert_eq!(
            post_timeout.body["error"]["type"],
            Value::String("timeout_exception".to_string())
        );

        let post = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_cluster/voting_config_exclusions?node_names=steel-node",
        ));
        assert_eq!(post.status, 200);
        assert_eq!(post.body, Value::Null);

        let delete = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/_cluster/voting_config_exclusions?wait_for_removal=false",
        ));
        assert_eq!(delete.status, 200);
        assert_eq!(delete.body, Value::Null);
    }

    #[test]
    fn cluster_reroute_route_serves_bounded_state_and_optional_explanations() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        let create_index = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-reroute-probe").with_json_body(
                serde_json::json!({
                    "settings": {
                        "index.number_of_shards": 1,
                        "index.number_of_replicas": 0
                    }
                }),
            ),
        );
        assert_eq!(create_index.status, 200);

        let plain = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_cluster/reroute")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(plain.status, 200);
        assert_eq!(plain.body["acknowledged"], Value::Bool(true));
        assert!(plain.body["state"]["routing_table"]["indices"].is_object());

        let explain = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/_cluster/reroute?dry_run=true&explain=true",
            )
            .with_json_body(serde_json::json!({ "commands": [] })),
        );
        assert_eq!(explain.status, 200);
        assert!(explain.body["explanations"].is_array());

        let invalid_boolean = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_cluster/reroute?dry_run=maybe")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(invalid_boolean.status, 400);
        assert_eq!(
            invalid_boolean.body["error"]["reason"],
            "Failed to parse value [maybe] as only [true] or [false] are allowed."
        );

        let invalid_timeout = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_cluster/reroute?timeout=forever")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(invalid_timeout.status, 400);
    }

    #[test]
    fn cluster_stats_node_variant_routes_serve_cluster_stats_shape() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            nodes: vec![DevelopmentClusterNode {
                node_id: "node-a".to_string(),
                node_name: "steel-node-a".to_string(),
                http_address: Some("127.0.0.1:9200".to_string()),
                transport_address: "127.0.0.1:9300".to_string(),
                roles: vec!["cluster_manager".to_string(), "data".to_string()],
                local: true,
            }],
            coordination: None,
        });
        node.created_indices_state
            .lock()
            .expect("created indices state lock poisoned")
            .insert("logs-cluster-stats-000001".to_string());

        for path in [
            "/_cluster/stats/nodes/_all",
            "/_cluster/stats/nodes/os",
            "/_cluster/stats/nodes/steel-node",
            "/_cluster/stats/indices/nodes/_all",
            "/_cluster/stats/indices/docs/nodes/_all",
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 200, "path {path}");
            assert_eq!(
                response.body["cluster_name"], "steelsearch-dev",
                "path {path}"
            );
            assert_eq!(response.body["cluster_uuid"], "cluster-uuid", "path {path}");
            assert!(response.body["timestamp"].is_number(), "path {path}");
            assert_eq!(response.body["indices"]["count"], 1, "path {path}");
            assert_eq!(
                response.body["indices"]["shards"]["total"], 2,
                "path {path}"
            );
            assert_eq!(
                response.body["indices"]["shards"]["primaries"], 1,
                "path {path}"
            );
            assert!(
                response.body["indices"]["store"]["size_in_bytes"].is_number(),
                "path {path}"
            );
            assert_eq!(response.body["nodes"]["count"]["total"], 1, "path {path}");
            assert!(response.body["nodes"]["versions"].is_array(), "path {path}");
            assert_eq!(
                response.body["nodes"]["versions"][0], "3.7.0",
                "path {path}"
            );
            assert!(
                response.body["nodes"]["jvm"]["versions"].is_array(),
                "path {path}"
            );
            assert!(
                response.body["fs"]["available_in_bytes"].is_number(),
                "path {path}"
            );
        }

        for (path, reason) in [
            (
                "/_cluster/stats/os,indices,_all/nodes/_all",
                "request [/_cluster/stats/os,indices,_all/nodes/_all] contains _all and individual metrics [os,indices,_all]",
            ),
            (
                "/_cluster/stats/indices/docs,_all/nodes/_all",
                "request [/_cluster/stats/indices/docs,_all/nodes/_all] contains _all and individual index metrics [docs,_all]",
            ),
            (
                "/_cluster/stats/os/docs/nodes/_all",
                "request [/_cluster/stats/os/docs/nodes/_all] contains index metrics [docs] but indices stats not requested",
            ),
            (
                "/_cluster/stats/bogus/nodes/_all",
                "request [/_cluster/stats/bogus/nodes/_all] contains unrecognized metric: [bogus]",
            ),
            (
                "/_cluster/stats/indices/bogus/nodes/_all",
                "request [/_cluster/stats/indices/bogus/nodes/_all] contains unrecognized index metric: [bogus]",
            ),
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 400, "path {path}");
            assert_eq!(response.body["error"]["type"], "illegal_argument_exception");
            assert_eq!(response.body["error"]["reason"], reason, "path {path}");
        }
    }

    #[test]
    fn nodes_hot_threads_routes_serve_plaintext_views() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        for path in [
            "/_nodes/hot_threads",
            "/_nodes/_all/hot_threads",
            "/_nodes/hotthreads",
            "/_nodes/_all/hotthreads",
            "/_cluster/nodes/hot_threads",
            "/_cluster/nodes/_all/hot_threads",
            "/_cluster/nodes/hotthreads",
            "/_cluster/nodes/_all/hotthreads",
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 200, "path {path}");
            let text = response.body.as_str().expect("hot_threads text body");
            assert!(text.contains("Hot threads at"), "path {path}");
            assert!(text.contains("cpu usage by thread"), "path {path}");
        }

        let parameterized = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_nodes/steel-node/hot_threads?threads=7&snapshots=2&ignore_idle_threads=false&type=wait&interval=1s",
        ));
        assert_eq!(parameterized.status, 200);
        let text = parameterized.body.as_str().expect("hot_threads text body");
        assert!(text.contains("::: steel-node"));
        assert!(text.contains("interval=1s"));
        assert!(text.contains("busiestThreads=7"));
        assert!(text.contains("ignoreIdleThreads=false"));
        assert!(text.contains("wait usage by thread"));
        assert!(text.contains("1/2 snapshots"));

        for (path, reason) in [
            (
                "/_nodes/hot_threads?ignore_idle_threads=maybe",
                "Failed to parse value [maybe] as only [true] or [false] are allowed.",
            ),
            (
                "/_nodes/hot_threads?threads=abc",
                "Failed to parse value [abc] for [threads] as an integer",
            ),
            (
                "/_nodes/hot_threads?snapshots=abc",
                "Failed to parse value [abc] for [snapshots] as an integer",
            ),
            (
                "/_nodes/hot_threads?type=memory",
                "type not supported [memory]",
            ),
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 400, "path {path}");
            assert_eq!(response.body["error"]["type"], "illegal_argument_exception");
            assert_eq!(response.body["error"]["reason"], reason, "path {path}");
        }
    }

