    #[test]
    fn reload_secure_settings_routes_serve_bounded_nodes_shape() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        for path in [
            "/_nodes/reload_secure_settings",
            "/_nodes/_all/reload_secure_settings",
            "/_nodes/steel-node/reload_secure_settings?timeout=1s",
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Post, path));
            assert_eq!(response.status, 200, "path {path}");
            assert!(response.body["_nodes"]["total"].is_number(), "path {path}");
            assert!(
                response.body["_nodes"]["successful"].is_number(),
                "path {path}"
            );
            assert_eq!(response.body["_nodes"]["failed"], 0, "path {path}");
            assert!(response.body["cluster_name"].is_string(), "path {path}");
            assert!(response.body["nodes"].is_object(), "path {path}");
        }

        let invalid_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_nodes/reload_secure_settings?timeout=forever",
        ));
        assert_eq!(invalid_timeout.status, 400);

        let target_invalid_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_nodes/steel-node/reload_secure_settings?timeout=forever",
        ));
        assert_eq!(target_invalid_timeout.status, 400);
    }

    #[test]
    fn secure_reload_secure_settings_requires_admin_role() {
        let _lock = security_env_lock();
        env::set_var("STEELSEARCH_SECURITY_ENABLED", "true");
        env::set_var("SECURITY_ADMIN_USERNAME", "admin");
        env::set_var("SECURITY_ADMIN_PASSWORD", "admin");
        env::set_var("SECURITY_READER_USERNAME", "reader");
        env::set_var("SECURITY_READER_PASSWORD", "reader");
        env::remove_var("SECURITY_WRITER_USERNAME");
        env::remove_var("SECURITY_WRITER_PASSWORD");
        env::remove_var("SECURITY_AUTHENTICATION_USERS_FILE");

        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        for path in [
            "/_nodes/reload_secure_settings",
            "/_nodes/_all/reload_secure_settings",
        ] {
            let missing = node.handle_rest_request(RestRequest::new(RestMethod::Post, path));
            assert_eq!(missing.status, 401, "path {path}");
            assert_eq!(missing.body["error"]["type"], "security_exception");

            let reader = node.handle_rest_request(
                RestRequest::new(RestMethod::Post, path)
                    .with_header("Authorization", "Basic cmVhZGVyOnJlYWRlcg=="),
            );
            assert_eq!(reader.status, 403, "path {path}");
            assert_eq!(reader.body["error"]["type"], "security_exception");
            assert!(reader.body["error"]["reason"]
                .as_str()
                .expect("security reason")
                .contains("reload secure settings"));

            let admin = node.handle_rest_request(
                RestRequest::new(RestMethod::Post, path)
                    .with_header("Authorization", "Basic YWRtaW46YWRtaW4="),
            );
            assert_eq!(admin.status, 200, "path {path}");
            assert_eq!(admin.body["_nodes"]["failed"], 0, "path {path}");
        }

        env::remove_var("STEELSEARCH_SECURITY_ENABLED");
        env::remove_var("SECURITY_ADMIN_USERNAME");
        env::remove_var("SECURITY_ADMIN_PASSWORD");
        env::remove_var("SECURITY_READER_USERNAME");
        env::remove_var("SECURITY_READER_PASSWORD");
    }

    #[test]
    fn secure_cluster_admin_control_routes_require_admin_role() {
        let _lock = security_env_lock();
        env::set_var("STEELSEARCH_SECURITY_ENABLED", "true");
        env::set_var("SECURITY_ADMIN_USERNAME", "admin");
        env::set_var("SECURITY_ADMIN_PASSWORD", "admin");
        env::set_var("SECURITY_READER_USERNAME", "reader");
        env::set_var("SECURITY_READER_PASSWORD", "reader");
        env::remove_var("SECURITY_WRITER_USERNAME");
        env::remove_var("SECURITY_WRITER_PASSWORD");
        env::remove_var("SECURITY_AUTHENTICATION_USERS_FILE");

        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let cases = [
            (
                "cluster settings",
                RestRequest::new(RestMethod::Put, "/_cluster/settings").with_json_body(
                    serde_json::json!({"persistent": {"cluster.max_shards_per_node": "1000"}}),
                ),
                200,
            ),
            (
                "cluster reroute",
                RestRequest::new(RestMethod::Post, "/_cluster/reroute")
                    .with_json_body(serde_json::json!({})),
                200,
            ),
            (
                "cluster decommission",
                RestRequest::new(RestMethod::Delete, "/_cluster/decommission/awareness"),
                200,
            ),
            (
                "cluster decommission",
                RestRequest::new(
                    RestMethod::Put,
                    "/_cluster/decommission/awareness/zone/zone-a",
                ),
                400,
            ),
            (
                "weighted routing",
                RestRequest::new(RestMethod::Delete, "/_cluster/routing/awareness/weights")
                    .with_json_body(serde_json::json!({"_version": -1})),
                404,
            ),
            (
                "weighted routing",
                RestRequest::new(RestMethod::Put, "/_cluster/routing/awareness/zone/weights")
                    .with_json_body(
                        serde_json::json!({"_version": -1, "weights": {"zone-a": 1.0}}),
                    ),
                400,
            ),
            (
                "voting config exclusions",
                RestRequest::new(
                    RestMethod::Post,
                    "/_cluster/voting_config_exclusions?node_names=node-a",
                ),
                200,
            ),
            (
                "voting config exclusions",
                RestRequest::new(RestMethod::Delete, "/_cluster/voting_config_exclusions"),
                200,
            ),
            (
                "task cancellation",
                RestRequest::new(RestMethod::Post, "/_tasks/_cancel"),
                200,
            ),
            (
                "task cancellation",
                RestRequest::new(RestMethod::Post, "/_tasks/node-a:99/_cancel"),
                200,
            ),
            (
                "task rethrottle",
                RestRequest::new(
                    RestMethod::Post,
                    "/_reindex/node-a:99/_rethrottle?requests_per_second=10",
                ),
                404,
            ),
        ];

        for (route_family, request, admin_status) in cases {
            let missing = node.handle_rest_request(request.clone());
            assert_eq!(missing.status, 401, "route {route_family}");
            assert_eq!(missing.body["error"]["type"], "security_exception");

            let reader = node.handle_rest_request(
                request
                    .clone()
                    .with_header("Authorization", "Basic cmVhZGVyOnJlYWRlcg=="),
            );
            assert_eq!(reader.status, 403, "route {route_family}");
            assert_eq!(reader.body["error"]["type"], "security_exception");
            assert!(reader.body["error"]["reason"]
                .as_str()
                .expect("security reason")
                .contains(route_family));

            let admin = node.handle_rest_request(
                request.with_header("Authorization", "Basic YWRtaW46YWRtaW4="),
            );
            assert_eq!(admin.status, admin_status, "route {route_family}");
        }

        env::remove_var("STEELSEARCH_SECURITY_ENABLED");
        env::remove_var("SECURITY_ADMIN_USERNAME");
        env::remove_var("SECURITY_ADMIN_PASSWORD");
        env::remove_var("SECURITY_READER_USERNAME");
        env::remove_var("SECURITY_READER_PASSWORD");
    }

    #[test]
    fn secure_cluster_observability_routes_require_reader_role() {
        let _lock = security_env_lock();
        env::set_var("STEELSEARCH_SECURITY_ENABLED", "true");
        env::set_var("SECURITY_ADMIN_USERNAME", "admin");
        env::set_var("SECURITY_ADMIN_PASSWORD", "admin");
        env::set_var("SECURITY_READER_USERNAME", "reader");
        env::set_var("SECURITY_READER_PASSWORD", "reader");
        env::set_var("SECURITY_WRITER_USERNAME", "writer");
        env::set_var("SECURITY_WRITER_PASSWORD", "writer");
        env::remove_var("SECURITY_AUTHENTICATION_USERS_FILE");

        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let cases = [
            (RestRequest::new(RestMethod::Get, "/_cluster/health"), 200),
            (RestRequest::new(RestMethod::Get, "/_cluster/state"), 200),
            (
                RestRequest::new(RestMethod::Get, "/_cluster/state/metadata"),
                200,
            ),
            (
                RestRequest::new(RestMethod::Get, "/_cluster/allocation/explain"),
                200,
            ),
            (
                RestRequest::new(RestMethod::Post, "/_cluster/allocation/explain")
                    .with_json_body(serde_json::json!({})),
                400,
            ),
            (RestRequest::new(RestMethod::Get, "/_cluster/settings"), 200),
            (
                RestRequest::new(RestMethod::Get, "/_cluster/pending_tasks"),
                200,
            ),
            (RestRequest::new(RestMethod::Get, "/_tasks"), 200),
            (RestRequest::new(RestMethod::Get, "/_nodes/stats"), 200),
            (RestRequest::new(RestMethod::Get, "/_cluster/stats"), 200),
        ];

        for (request, reader_status) in cases {
            let path = request.path.clone();
            let missing = node.handle_rest_request(request.clone());
            assert_eq!(missing.status, 401, "path {path}");
            assert_eq!(missing.body["error"]["type"], "security_exception");

            let writer = node.handle_rest_request(
                request
                    .clone()
                    .with_header("Authorization", "Basic d3JpdGVyOndyaXRlcg=="),
            );
            assert_eq!(writer.status, 403, "path {path}");
            assert_eq!(writer.body["error"]["type"], "security_exception");
            assert!(writer.body["error"]["reason"]
                .as_str()
                .expect("security reason")
                .contains("cluster read"));

            let reader = node.handle_rest_request(
                request.with_header("Authorization", "Basic cmVhZGVyOnJlYWRlcg=="),
            );
            if path == "/_cluster/allocation/explain" {
                assert_ne!(
                    reader.body["error"]["type"], "security_exception",
                    "path {path}"
                );
            } else {
                assert_eq!(reader.status, reader_status, "path {path}");
            }
        }

        env::remove_var("STEELSEARCH_SECURITY_ENABLED");
        env::remove_var("SECURITY_ADMIN_USERNAME");
        env::remove_var("SECURITY_ADMIN_PASSWORD");
        env::remove_var("SECURITY_READER_USERNAME");
        env::remove_var("SECURITY_READER_PASSWORD");
        env::remove_var("SECURITY_WRITER_USERNAME");
        env::remove_var("SECURITY_WRITER_PASSWORD");
    }

