    #[test]
    fn tasks_cancel_route_supports_task_id_path_variant() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        *node
            .task_queue_state
            .lock()
            .expect("task queue state lock poisoned") =
            Some(PersistedClusterManagerTaskQueueState {
                pending: vec![ClusterManagerTaskRecord {
                    task_id: 11,
                    task: ClusterManagerTask {
                        source: "reroute shards".to_string(),
                        kind: ClusterManagerTaskKind::Reroute,
                    },
                    state: ClusterManagerTaskState::Queued,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                in_flight: vec![ClusterManagerTaskRecord {
                    task_id: 12,
                    task: ClusterManagerTask {
                        source: "publication in flight".to_string(),
                        kind: ClusterManagerTaskKind::Reroute,
                    },
                    state: ClusterManagerTaskState::InFlight,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                ..Default::default()
            });

        let existing = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_tasks/node-a:11/_cancel",
        ));
        assert_eq!(existing.status, 200);
        assert_eq!(
            existing.body["nodes"]["node-a"]["tasks"]["node-a:11"]["cancelled"],
            Value::Bool(true)
        );

        let cancelled_get =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_tasks/node-a:11"));
        assert_eq!(cancelled_get.status, 200);
        assert_eq!(cancelled_get.body["task"]["cancelled"], Value::Bool(true));

        let non_cancellable = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_tasks/node-a:12/_cancel",
        ));
        assert_eq!(non_cancellable.status, 400);
        assert_eq!(
            non_cancellable.body["error"]["type"],
            Value::String("illegal_argument_exception".to_string())
        );

        let missing = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_tasks/node-a:999/_cancel",
        ));
        assert_eq!(missing.status, 200);
        assert_eq!(
            missing.body["node_failures"][0]["type"],
            Value::String("failed_node_exception".to_string())
        );
    }

    #[test]
    fn tasks_cancel_root_route_honors_node_and_action_selectors() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        *node
            .task_queue_state
            .lock()
            .expect("task queue state lock poisoned") =
            Some(PersistedClusterManagerTaskQueueState {
                pending: vec![ClusterManagerTaskRecord {
                    task_id: 21,
                    task: ClusterManagerTask {
                        source: "reroute shards".to_string(),
                        kind: ClusterManagerTaskKind::Reroute,
                    },
                    state: ClusterManagerTaskState::Queued,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                ..Default::default()
            });

        let no_match = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_tasks/_cancel?nodes=node-b&actions=*reroute",
        ));
        assert_eq!(no_match.status, 200);
        assert_eq!(
            no_match.body["nodes"].as_object().map(|nodes| nodes.len()),
            Some(0)
        );

        let cancel = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_tasks/_cancel?nodes=node-a&actions=*reroute",
        ));
        assert_eq!(cancel.status, 200);
        assert_eq!(
            cancel.body["nodes"]["node-a"]["tasks"]["node-a:21"]["cancelled"],
            Value::Bool(true)
        );

        let cancelled_get =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_tasks/node-a:21"));
        assert_eq!(cancelled_get.status, 200);
        assert_eq!(cancelled_get.body["task"]["cancelled"], Value::Bool(true));
    }

    #[test]
    fn tasks_cancel_root_route_without_selectors_cancels_all_cancellable_tasks_like_opensearch() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        *node
            .task_queue_state
            .lock()
            .expect("task queue state lock poisoned") =
            Some(PersistedClusterManagerTaskQueueState {
                pending: vec![
                    ClusterManagerTaskRecord {
                        task_id: 31,
                        task: ClusterManagerTask {
                            source: "root cancel queued probe".to_string(),
                            kind: ClusterManagerTaskKind::Reroute,
                        },
                        state: ClusterManagerTaskState::Queued,
                        parent_task_id: None,
                        headers: BTreeMap::new(),
                        failure_reason: None,
                    },
                    ClusterManagerTaskRecord {
                        task_id: 32,
                        task: ClusterManagerTask {
                            source: "root cancel queued background probe".to_string(),
                            kind: ClusterManagerTaskKind::BackgroundWorker {
                                worker: "maintenance-refresh".to_string(),
                                action: "indices:admin/refresh".to_string(),
                            },
                        },
                        state: ClusterManagerTaskState::Queued,
                        parent_task_id: None,
                        headers: BTreeMap::new(),
                        failure_reason: None,
                    },
                ],
                in_flight: vec![ClusterManagerTaskRecord {
                    task_id: 33,
                    task: ClusterManagerTask {
                        source: "root cancel in-flight probe".to_string(),
                        kind: ClusterManagerTaskKind::Reroute,
                    },
                    state: ClusterManagerTaskState::InFlight,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                ..Default::default()
            });

        let cancel =
            node.handle_rest_request(RestRequest::new(RestMethod::Post, "/_tasks/_cancel"));
        assert_eq!(cancel.status, 200);
        let cancelled_tasks = cancel.body["nodes"]["node-a"]["tasks"]
            .as_object()
            .expect("cancelled task map");
        assert_eq!(cancelled_tasks.len(), 2);
        assert_eq!(cancelled_tasks["node-a:31"]["cancelled"], Value::Bool(true));
        assert_eq!(cancelled_tasks["node-a:32"]["cancelled"], Value::Bool(true));
        assert!(cancelled_tasks.get("node-a:33").is_none());

        for (task_id, expected_cancelled) in [
            ("node-a:31", true),
            ("node-a:32", true),
            ("node-a:33", false),
        ] {
            let get = node.handle_rest_request(RestRequest::new(
                RestMethod::Get,
                &format!("/_tasks/{task_id}"),
            ));
            assert_eq!(get.status, 200, "{task_id}");
            assert_eq!(
                get.body["task"]["cancelled"],
                Value::Bool(expected_cancelled),
                "{task_id}"
            );
        }
    }

    #[test]
    fn tasks_list_rejects_invalid_group_by_like_opensearch() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let response =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_tasks?group_by=bogus"));

        assert_eq!(response.status, 400);
        assert_eq!(response.body["error"]["type"], "illegal_argument_exception");
        assert_eq!(
            response.body["error"]["reason"],
            "[group_by] must be one of [nodes], [parents] or [none] but was [bogus]"
        );
        assert_eq!(
            response.body["error"]["root_cause"][0]["type"],
            "illegal_argument_exception"
        );
        assert_eq!(
            response.body["error"]["root_cause"][0]["reason"],
            "[group_by] must be one of [nodes], [parents] or [none] but was [bogus]"
        );
    }

