    #[test]
    fn rethrottle_rate_persists_across_shared_runtime_restart() {
        let _lock = security_env_lock();
        env::set_var("STEELSEARCH_PERSIST_SHARED_RUNTIME_STATE_PER_WRITE", "1");
        let root = std::env::temp_dir().join(format!(
            "steelsearch-rethrottle-state-{}",
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("system time before unix epoch")
                .as_nanos()
        ));
        std::fs::create_dir_all(&root).expect("create temp root");
        let shared_state_path = root.join("shared-runtime-state.json");

        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.shared_runtime_state_path = Some(shared_state_path.clone());
        node.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            nodes: vec![DevelopmentClusterNode {
                node_id: "node-a".to_string(),
                node_name: "steel-node-a".to_string(),
                http_address: Some("127.0.0.1:9200".to_string()),
                transport_address: "127.0.0.1:9300".to_string(),
                roles: vec!["cluster_manager".to_string(), "data".to_string()],
                local: true,
            }],
            coordination: None,
        });
        *node
            .task_queue_state
            .lock()
            .expect("task queue state lock poisoned") =
            Some(PersistedClusterManagerTaskQueueState {
                pending: vec![ClusterManagerTaskRecord {
                    task_id: 131,
                    task: ClusterManagerTask {
                        source: "rethrottle restart probe".to_string(),
                        kind: ClusterManagerTaskKind::Reroute,
                    },
                    state: ClusterManagerTaskState::Queued,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                ..Default::default()
            });
        node.persist_shared_runtime_state_to_disk();

        let mut rethrottle = RestRequest::new(RestMethod::Post, "/_reindex/node-a:131/_rethrottle");
        rethrottle
            .query_params
            .insert("requests_per_second".to_string(), "4.75".to_string());
        let rethrottle = node.handle_rest_request(rethrottle);
        assert_eq!(rethrottle.status, 200);
        assert_eq!(
            rethrottle.body["task"]["status"]["requests_per_second"],
            serde_json::json!(4.75)
        );

        let mut restarted = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        restarted.shared_runtime_state_path = Some(shared_state_path.clone());
        restarted.sync_shared_runtime_state_from_disk();

        let get =
            restarted.handle_rest_request(RestRequest::new(RestMethod::Get, "/_tasks/node-a:131"));
        assert_eq!(get.status, 200);
        assert_eq!(
            get.body["task"]["status"]["requests_per_second"],
            serde_json::json!(4.75)
        );

        let list = restarted.handle_rest_request(RestRequest::new(RestMethod::Get, "/_tasks"));
        assert_eq!(list.status, 200);
        assert_eq!(
            list.body["nodes"]["node-a"]["tasks"]["node-a:131"]["status"]["requests_per_second"],
            serde_json::json!(4.75)
        );

        env::remove_var("STEELSEARCH_PERSIST_SHARED_RUNTIME_STATE_PER_WRITE");
        let _ = std::fs::remove_file(shared_state_path);
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn rethrottle_request_during_restart_window_syncs_before_mutation() {
        let _lock = security_env_lock();
        env::set_var("STEELSEARCH_PERSIST_SHARED_RUNTIME_STATE_PER_WRITE", "1");
        env::set_var("STEELSEARCH_SYNC_SHARED_RUNTIME_STATE_PER_REQUEST", "1");
        let root = std::env::temp_dir().join(format!(
            "steelsearch-rethrottle-restart-window-{}",
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("system time before unix epoch")
                .as_nanos()
        ));
        std::fs::create_dir_all(&root).expect("create temp root");
        let shared_state_path = root.join("shared-runtime-state.json");

        let mut writer = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        writer.shared_runtime_state_path = Some(shared_state_path.clone());
        writer.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            nodes: vec![DevelopmentClusterNode {
                node_id: "node-a".to_string(),
                node_name: "steel-node-a".to_string(),
                http_address: Some("127.0.0.1:9200".to_string()),
                transport_address: "127.0.0.1:9300".to_string(),
                roles: vec!["cluster_manager".to_string(), "data".to_string()],
                local: true,
            }],
            coordination: None,
        });
        *writer
            .task_queue_state
            .lock()
            .expect("task queue state lock poisoned") =
            Some(PersistedClusterManagerTaskQueueState {
                pending: vec![ClusterManagerTaskRecord {
                    task_id: 811,
                    task: ClusterManagerTask {
                        source: "rethrottle restart window probe".to_string(),
                        kind: ClusterManagerTaskKind::Reroute,
                    },
                    state: ClusterManagerTaskState::Queued,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                ..Default::default()
            });
        writer.persist_shared_runtime_state_to_disk();

        let mut restarted = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        restarted.shared_runtime_state_path = Some(shared_state_path.clone());
        restarted.cluster_view = writer.cluster_view.clone();

        let mut rethrottle = RestRequest::new(RestMethod::Post, "/_reindex/node-a:811/_rethrottle");
        rethrottle
            .query_params
            .insert("requests_per_second".to_string(), "7.75".to_string());
        let rethrottle = restarted.handle_rest_request(rethrottle);
        assert_eq!(rethrottle.status, 200);
        assert_eq!(
            rethrottle.body["task"]["status"]["requests_per_second"],
            serde_json::json!(7.75)
        );

        let get =
            restarted.handle_rest_request(RestRequest::new(RestMethod::Get, "/_tasks/node-a:811"));
        assert_eq!(get.status, 200);
        assert_eq!(
            get.body["task"]["status"]["requests_per_second"],
            serde_json::json!(7.75)
        );

        let persisted = std::fs::read(&shared_state_path).expect("read shared runtime state");
        let persisted: SharedRuntimeState =
            serde_json::from_slice(&persisted).expect("parse shared runtime state");
        assert_eq!(
            persisted.rethrottled_task_rates.get("node-a:811"),
            Some(&"7.75".to_string())
        );

        env::remove_var("STEELSEARCH_SYNC_SHARED_RUNTIME_STATE_PER_REQUEST");
        env::remove_var("STEELSEARCH_PERSIST_SHARED_RUNTIME_STATE_PER_WRITE");
        let _ = std::fs::remove_file(shared_state_path);
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn completed_bulk_by_scroll_tasks_materialize_tasks_index_documents() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        let task_id = node.record_completed_bulk_by_scroll_task(
            "reindex from source",
            "reindex",
            "indices:data/write/reindex",
            &serde_json::json!({
                "total": 4,
                "updated": 0,
                "created": 4,
                "deleted": 0,
                "batches": 1,
                "version_conflicts": 0,
                "noops": 0,
                "throttled_millis": 0,
                "requests_per_second": -1.0,
                "throttled_until_millis": 0,
                "failures": []
            }),
        );

        assert!(task_id.contains(':'));
        assert!(node
            .created_indices_state
            .lock()
            .expect("created indices lock poisoned")
            .contains(".tasks"));
        assert_eq!(node.index_document_count(".tasks"), 1);

        let count = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/.tasks/_count"));
        assert_eq!(count.status, 200);
        assert_eq!(count.body["count"], 1);

        let tasks = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_tasks"));
        assert_eq!(tasks.status, 200);
        assert_eq!(
            tasks.body["nodes"]["node-a"]["tasks"][&task_id]["status"]["created"],
            4
        );
    }

