    #[test]
    fn search_distance_feature_and_wildcard_common_options_match_named_queries() {
        let source = serde_json::json!({
            "service": "checkout",
            "ts": "2026-04-22T00:01:00Z"
        });
        let wildcard = serde_json::json!({
            "query": {
                "wildcard": {
                    "service": {
                        "wildcard": "check*",
                        "rewrite": "constant_score",
                        "boost": 1.0,
                        "_name": "named_wildcard"
                    }
                }
            }
        });
        let distance_feature = serde_json::json!({
            "query": {
                "distance_feature": {
                    "field": "ts",
                    "origin": "2026-04-22T00:00:00Z",
                    "pivot": "5m",
                    "boost": 1.0,
                    "_name": "named_distance_feature"
                }
            }
        });

        assert_eq!(
            evaluate_search_query_source(&source, "doc-1", &wildcard["query"]),
            Some((true, 1.0))
        );
        assert_eq!(
            evaluate_search_query_source(&source, "doc-1", &distance_feature["query"]),
            Some((true, 1.0))
        );
        assert_eq!(
            collect_matched_named_queries(&source, "doc-1", &wildcard, &Value::Null),
            vec![("named_wildcard".to_string(), 1.0)]
        );
        assert_eq!(
            collect_matched_named_queries(&source, "doc-1", &distance_feature, &Value::Null),
            vec![("named_distance_feature".to_string(), 1.0)]
        );
    }

    #[test]
    fn search_nested_accepts_options_and_combines_scores_by_mode() {
        let source = serde_json::json!({
            "events": [
                { "status": "timeout", "weight": 1.0 },
                { "status": "timeout", "weight": 3.0 },
                { "status": "ok", "weight": 10.0 }
            ]
        });

        assert!(validate_search_query_body(&serde_json::json!({
            "nested": {
                "path": "events",
                "query": { "rank_feature": { "field": "weight", "linear": {} } },
                "score_mode": "sum",
                "ignore_unmapped": false,
                "boost": 1.0,
                "_name": "named_nested"
            }
        }))
        .is_none());

        let response = validate_search_query_body(&serde_json::json!({
            "nested": {
                "path": "events",
                "query": { "match_all": {} },
                "score_mode": "total"
            }
        }))
        .expect("OpenSearch nested score_mode uses [sum], not [total]");
        assert_eq!(response.status, 400);

        let nested_query = |score_mode: &str| {
            serde_json::json!({
                "nested": {
                    "path": "events",
                    "query": {
                        "bool": {
                            "must": [
                                { "term": { "status": "timeout" } },
                                { "rank_feature": { "field": "weight", "linear": {} } }
                            ]
                        }
                    },
                    "score_mode": score_mode
                }
            })
        };

        let (_, avg_score) =
            evaluate_search_query_source(&source, "doc-1", &nested_query("avg")).unwrap();
        let (_, min_score) =
            evaluate_search_query_source(&source, "doc-1", &nested_query("min")).unwrap();
        let (_, max_score) =
            evaluate_search_query_source(&source, "doc-1", &nested_query("max")).unwrap();
        let (_, sum_score) =
            evaluate_search_query_source(&source, "doc-1", &nested_query("sum")).unwrap();
        let (none_matched, none_score) =
            evaluate_search_query_source(&source, "doc-1", &nested_query("none")).unwrap();

        assert!((avg_score - 3.0).abs() < f64::EPSILON);
        assert!((min_score - 2.0).abs() < f64::EPSILON);
        assert!((max_score - 4.0).abs() < f64::EPSILON);
        assert!((sum_score - 6.0).abs() < f64::EPSILON);
        assert!(none_matched);
        assert!((none_score - 0.0).abs() < f64::EPSILON);
    }

