    #[test]
    fn search_terms_set_minimum_should_match_field_uses_document_threshold() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/terms-set-msm-field-000001").with_json_body(
                    serde_json::json!({
                        "mappings": {
                            "properties": {
                                "tags": { "type": "keyword" },
                                "required_matches": { "type": "long" }
                            }
                        }
                    })
                )
            )
            .status,
            200
        );
        for (id, body) in [
            (
                "a",
                serde_json::json!({ "tags": ["payment", "checkout"], "required_matches": 2 }),
            ),
            (
                "b",
                serde_json::json!({ "tags": ["payment", "timeout"], "required_matches": 2 }),
            ),
            (
                "c",
                serde_json::json!({ "tags": ["payment", "timeout"], "required_matches": 1 }),
            ),
            (
                "d",
                serde_json::json!({ "tags": ["catalog"], "required_matches": 1 }),
            ),
        ] {
            assert_eq!(
                node.handle_rest_request(
                    RestRequest::new(
                        RestMethod::Put,
                        &format!("/terms-set-msm-field-000001/_doc/{id}")
                    )
                    .with_json_body(body)
                )
                .status,
                201
            );
        }
        assert_eq!(
            node.handle_rest_request(RestRequest::new(RestMethod::Post, "/_refresh"))
                .status,
            200
        );

        let response = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/terms-set-msm-field-000001/_search")
                .with_json_body(serde_json::json!({
                    "query": {
                        "terms_set": {
                            "tags": {
                                "terms": ["payment", "checkout"],
                                "minimum_should_match_field": "required_matches"
                            }
                        }
                    },
                    "sort": [{ "_id": "asc" }]
                })),
        );
        assert_eq!(response.status, 200);
        assert_eq!(response.body["hits"]["total"]["value"], 2);
        assert_eq!(response.body["hits"]["hits"][0]["_id"], "a");
        assert_eq!(response.body["hits"]["hits"][1]["_id"], "c");
        assert_eq!(
            response.body["hits"]["hits"][0]["sort"],
            serde_json::json!(["a"])
        );
        assert_eq!(
            response.body["hits"]["hits"][1]["sort"],
            serde_json::json!(["c"])
        );

        let conflict = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/terms-set-msm-field-000001/_search")
                .with_json_body(serde_json::json!({
                    "query": {
                        "terms_set": {
                            "tags": {
                                "terms": ["payment"],
                                "minimum_should_match_field": "required_matches",
                                "minimum_should_match_script": { "source": "1" }
                            }
                        }
                    }
                })),
        );
        assert_eq!(conflict.status, 400);
        assert_eq!(conflict.body["error"]["type"], "illegal_argument_exception");
        assert_eq!(
            conflict.body["error"]["root_cause"][0]["reason"],
            "A field has already been specified. Cannot specify both a field and script"
        );
    }

    #[test]
    fn point_in_time_field_sort_search_after_keeps_snapshot_after_live_write_like_opensearch() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/pit-search-after").with_json_body(
                serde_json::json!({
                    "mappings": {
                        "properties": {
                            "field1": { "type": "long" },
                            "field2": { "type": "keyword" }
                        }
                    }
                }),
            ),
        );
        assert_eq!(create.status, 200);
        for (id, source) in [
            ("0", serde_json::json!({ "field1": 0 })),
            ("1", serde_json::json!({ "field1": 100, "field2": "toto" })),
            ("2", serde_json::json!({ "field1": 101 })),
            ("3", serde_json::json!({ "field1": 99 })),
        ] {
            let index = node.handle_rest_request(
                RestRequest::new(RestMethod::Put, &format!("/pit-search-after/_doc/{id}"))
                    .with_json_body(source),
            );
            assert_eq!(index.status, 201, "{id}");
        }

        let open_pit = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/pit-search-after/_search/point_in_time?keep_alive=1m",
        ));
        assert_eq!(open_pit.status, 200);
        let pit_id = open_pit.body["pit_id"].as_str().expect("pit id");
        {
            let mut contexts = node
                .pit_contexts
                .lock()
                .expect("pit contexts lock poisoned");
            assert!(contexts.contains_key(pit_id));
            for context in contexts.values_mut() {
                context.creation_time_millis = 0;
            }
        }

        for (after, expected_hits) in [(99, 2), (100, 1), (0, 3)] {
            let response = node.handle_rest_request(
                RestRequest::new(RestMethod::Post, "/_search").with_json_body(serde_json::json!({
                    "pit": { "id": pit_id, "keep_alive": "1m" },
                    "query": { "match_all": {} },
                    "sort": [{ "field1": "asc" }],
                    "search_after": [after]
                })),
            );
            assert_eq!(response.status, 200, "{after}");
            assert_eq!(
                response.body["hits"]["hits"].as_array().map(Vec::len),
                Some(expected_hits),
                "{after}"
            );
        }

        let new_doc = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/pit-search-after/_doc/4")
                .with_json_body(serde_json::json!({ "field1": 102 })),
        );
        assert_eq!(new_doc.status, 201);

        let pit_after_live_write = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_search").with_json_body(serde_json::json!({
                "pit": { "id": pit_id, "keep_alive": "1m" },
                "query": { "match_all": {} },
                "sort": [{ "field1": "asc" }],
                "search_after": [0]
            })),
        );
        assert_eq!(pit_after_live_write.status, 200);
        assert_eq!(
            pit_after_live_write.body["hits"]["hits"]
                .as_array()
                .map(Vec::len),
            Some(3)
        );

        let live_after_write = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/pit-search-after/_search").with_json_body(
                serde_json::json!({
                    "query": { "match_all": {} },
                    "sort": [{ "field1": "asc" }],
                    "search_after": [0]
                }),
            ),
        );
        assert_eq!(live_after_write.status, 200);
        assert_eq!(
            live_after_write.body["hits"]["hits"]
                .as_array()
                .map(Vec::len),
            Some(4)
        );
    }

    #[test]
    fn point_in_time_index_stats_track_open_contexts_per_shard_like_opensearch() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/pit-stats-index").with_json_body(
                serde_json::json!({
                    "settings": {
                        "index": {
                            "number_of_shards": 2,
                            "number_of_replicas": 0
                        }
                    }
                }),
            ),
        );
        assert_eq!(create.status, 200);
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/pit-stats-index/_doc/1")
                    .with_json_body(serde_json::json!({ "field": "value" })),
            )
            .status,
            201
        );

        let open_pit = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/pit-stats-index/_search/point_in_time?keep_alive=1m",
        ));
        assert_eq!(open_pit.status, 200);
        let pit_id = open_pit.body["pit_id"].as_str().expect("pit id");

        let index_stats =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/pit-stats-index/_stats"));
        assert_eq!(index_stats.status, 200);
        assert_eq!(
            index_stats.body["indices"]["pit-stats-index"]["total"]["search"]
                ["point_in_time_current"],
            2
        );
        assert_eq!(
            index_stats.body["indices"]["pit-stats-index"]["total"]["search"]
                ["point_in_time_total"],
            2
        );
        assert_eq!(
            index_stats.body["indices"]["pit-stats-index"]["total"]["search"]["open_contexts"],
            2
        );
        assert_eq!(
            index_stats.body["indices"]["pit-stats-index"]["primaries"]["search"]
                ["point_in_time_current"],
            2
        );
        assert_eq!(
            index_stats.body["_all"]["total"]["search"]["point_in_time_current"],
            2
        );

        let global_stats =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_stats/search"));
        assert_eq!(global_stats.status, 200);
        assert_eq!(
            global_stats.body["indices"]["pit-stats-index"]["total"]["search"]
                ["point_in_time_current"],
            2
        );
        assert_eq!(
            global_stats.body["indices"]["pit-stats-index"]["total"]["search"]
                ["point_in_time_total"],
            2
        );

        std::thread::sleep(std::time::Duration::from_millis(2));
        let delete_pit = node.handle_rest_request(
            RestRequest::new(RestMethod::Delete, "/_search/point_in_time")
                .with_json_body(serde_json::json!({ "pit_id": [pit_id] })),
        );
        assert_eq!(delete_pit.status, 200);
        let recorded_pit_time_millis = node
            .pit_time_millis_by_index
            .lock()
            .expect("pit time millis lock poisoned")
            .get("pit-stats-index")
            .copied()
            .unwrap_or_default();
        assert!(
            recorded_pit_time_millis >= 2,
            "PIT time should be recorded per primary shard, got {recorded_pit_time_millis}"
        );

        let stats_after_delete =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/pit-stats-index/_stats"));
        assert_eq!(stats_after_delete.status, 200);
        assert_eq!(
            stats_after_delete.body["indices"]["pit-stats-index"]["total"]["search"]
                ["point_in_time_current"],
            0
        );
        assert_eq!(
            stats_after_delete.body["indices"]["pit-stats-index"]["total"]["search"]
                ["point_in_time_total"],
            2
        );
        assert!(
            stats_after_delete.body["indices"]["pit-stats-index"]["total"]["search"]
                ["point_in_time_time_in_millis"]
                .as_u64()
                .unwrap_or_default()
                >= 2
        );
        assert_eq!(
            stats_after_delete.body["indices"]["pit-stats-index"]["primaries"]["search"]
                ["point_in_time_time_in_millis"],
            stats_after_delete.body["indices"]["pit-stats-index"]["total"]["search"]
                ["point_in_time_time_in_millis"]
        );
        let mut cat_indices_time_request =
            RestRequest::new(RestMethod::Get, "/_cat/indices/pit-stats-index");
        cat_indices_time_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        cat_indices_time_request
            .query_params
            .insert("h".to_string(), "search.point_in_time_time".to_string());
        let cat_indices_time = node.handle_rest_request(cat_indices_time_request);
        assert_eq!(cat_indices_time.status, 200);
        assert_ne!(
            cat_indices_time.body[0]["search.point_in_time_time"]
                .as_str()
                .unwrap_or_default(),
            "0s"
        );
        assert_eq!(
            stats_after_delete.body["indices"]["pit-stats-index"]["total"]["search"]
                ["open_contexts"],
            0
        );

        let second_open_pit = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/pit-stats-index/_search/point_in_time?keep_alive=1m",
        ));
        assert_eq!(second_open_pit.status, 200);
        let stats_after_second_open =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/pit-stats-index/_stats"));
        assert_eq!(stats_after_second_open.status, 200);
        assert_eq!(
            stats_after_second_open.body["indices"]["pit-stats-index"]["total"]["search"]
                ["point_in_time_current"],
            2
        );
        assert_eq!(
            stats_after_second_open.body["indices"]["pit-stats-index"]["total"]["search"]
                ["point_in_time_total"],
            4
        );
    }

    #[test]
    fn point_in_time_shard_doc_search_after_paginates_like_opensearch_rest_spec() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/sharddoc-paging").with_json_body(
                serde_json::json!({
                    "settings": {
                        "number_of_shards": 4,
                        "number_of_replicas": 0
                    },
                    "mappings": {
                        "properties": {
                            "id": { "type": "integer" },
                            "txt": { "type": "keyword" }
                        }
                    }
                }),
            ),
        );
        assert_eq!(create.status, 200);

        for id in 1..=22 {
            let doc = node.handle_rest_request(
                RestRequest::new(RestMethod::Post, "/sharddoc-paging/_doc").with_json_body(
                    serde_json::json!({
                        "id": id,
                        "txt": char::from(b'a' + (id as u8) - 1).to_string()
                    }),
                ),
            );
            assert_eq!(doc.status, 201, "{id}");
        }

        let open_pit = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/sharddoc-paging/_search/point_in_time?keep_alive=1m",
        ));
        assert_eq!(open_pit.status, 200);
        let pit_id = open_pit.body["pit_id"].as_str().expect("pit id");

        let page_1 = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_search").with_json_body(serde_json::json!({
                "size": 10,
                "pit": {
                    "id": pit_id,
                    "keep_alive": "1m"
                },
                "sort": [
                    { "_shard_doc": {} }
                ]
            })),
        );
        assert_eq!(page_1.status, 200);
        assert_eq!(page_1.body["_shards"]["failed"], 0);
        assert_eq!(page_1.body["hits"]["hits"].as_array().unwrap().len(), 10);
        let after_1 = page_1.body["hits"]["hits"][9]["sort"].clone();
        assert!(after_1.is_array());

        let page_2 = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_search").with_json_body(serde_json::json!({
                "size": 10,
                "pit": {
                    "id": pit_id,
                    "keep_alive": "1m"
                },
                "sort": [
                    { "_shard_doc": {} }
                ],
                "search_after": after_1
            })),
        );
        assert_eq!(page_2.status, 200);
        assert_eq!(page_2.body["_shards"]["failed"], 0);
        let page_2_hits = page_2.body["hits"]["hits"].as_array().unwrap();
        assert_eq!(page_2_hits.len(), 10);
        for window in page_2_hits.windows(2) {
            let left = window[0]["sort"][0].as_i64().unwrap();
            let right = window[1]["sort"][0].as_i64().unwrap();
            assert!(left < right, "{left} < {right}");
        }
        let after_2 = page_2_hits[9]["sort"].clone();

        let page_3 = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_search").with_json_body(serde_json::json!({
                "size": 10,
                "pit": {
                    "id": pit_id,
                    "keep_alive": "1m"
                },
                "sort": [
                    { "_shard_doc": {} }
                ],
                "search_after": after_2
            })),
        );
        assert_eq!(page_3.status, 200);
        assert_eq!(page_3.body["_shards"]["failed"], 0);
        assert_eq!(page_3.body["hits"]["hits"].as_array().unwrap().len(), 2);

        let close_pit = node.handle_rest_request(
            RestRequest::new(RestMethod::Delete, "/_search/point_in_time")
                .with_json_body(serde_json::json!({ "pit_id": [pit_id] })),
        );
        assert_eq!(close_pit.status, 200);
    }

    #[test]
    fn point_in_time_shard_doc_scan_has_strict_order_and_no_duplicates() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/sharddoc-scan").with_json_body(serde_json::json!({
                "settings": {
                    "number_of_shards": 2,
                    "number_of_replicas": 0
                },
                "mappings": {
                    "properties": {
                        "v": { "type": "long" }
                    }
                }
            })),
        );
        assert_eq!(create.status, 200);

        for id in 1..=41 {
            let doc = node.handle_rest_request(
                RestRequest::new(RestMethod::Put, &format!("/sharddoc-scan/_doc/{id}"))
                    .with_json_body(serde_json::json!({ "v": id })),
            );
            assert_eq!(doc.status, 201, "{id}");
        }

        for (order, page_size) in [("asc", 7), ("desc", 11)] {
            let open_pit = node.handle_rest_request(RestRequest::new(
                RestMethod::Post,
                "/sharddoc-scan/_search/point_in_time?keep_alive=1m",
            ));
            assert_eq!(open_pit.status, 200, "{order}");
            let pit_id = open_pit.body["pit_id"]
                .as_str()
                .expect("pit id")
                .to_string();
            let mut seen_ids = BTreeSet::new();
            let mut shard_doc_keys = Vec::new();
            let mut search_after = None;

            loop {
                let mut body = serde_json::json!({
                    "size": page_size,
                    "pit": {
                        "id": pit_id,
                        "keep_alive": "1m"
                    },
                    "sort": [
                        { "_shard_doc": order }
                    ]
                });
                if let Some(after) = search_after.take() {
                    body["search_after"] = after;
                }

                let page = node.handle_rest_request(
                    RestRequest::new(RestMethod::Post, "/_search").with_json_body(body),
                );
                assert_eq!(page.status, 200, "{order}: {page:?}");
                let hits = page.body["hits"]["hits"].as_array().expect("hits");
                for hit in hits {
                    let id = hit["_id"].as_str().expect("hit id").to_string();
                    assert!(
                        seen_ids.insert(id.clone()),
                        "duplicate hit {id} for {order}"
                    );
                    shard_doc_keys.push(hit["sort"][0].as_i64().expect("_shard_doc sort"));
                }
                if hits.len() < page_size {
                    break;
                }
                search_after = Some(hits[hits.len() - 1]["sort"].clone());
            }

            assert_eq!(seen_ids.len(), 41, "{order}");
            assert_eq!(shard_doc_keys.len(), 41, "{order}");
            for window in shard_doc_keys.windows(2) {
                match order {
                    "asc" => assert!(window[0] < window[1], "{order}: {window:?}"),
                    "desc" => assert!(window[0] > window[1], "{order}: {window:?}"),
                    _ => unreachable!(),
                }
            }

            let close_pit = node.handle_rest_request(
                RestRequest::new(RestMethod::Delete, "/_search/point_in_time")
                    .with_json_body(serde_json::json!({ "pit_id": [pit_id] })),
            );
            assert_eq!(close_pit.status, 200, "{order}");
        }
    }

