    #[test]
    fn point_in_time_background_reaper_prunes_expired_contexts_without_request() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        let now_millis = current_epoch_millis();
        let expired_pit_id = build_local_pit_id(301);
        let active_pit_id = build_local_pit_id(302);
        {
            let mut contexts = node
                .pit_contexts
                .lock()
                .expect("pit contexts lock poisoned");
            contexts.insert(
                expired_pit_id.clone(),
                PitContext {
                    indices: vec!["logs-pit-reaper-expired".to_string()],
                    documents: Arc::new(BTreeMap::new()),
                    keep_alive_millis: 1,
                    expires_at_millis: now_millis.saturating_sub(1),
                    creation_time_millis: now_millis.saturating_sub(2),
                },
            );
            contexts.insert(
                active_pit_id.clone(),
                PitContext {
                    indices: vec!["logs-pit-reaper-active".to_string()],
                    documents: Arc::new(BTreeMap::new()),
                    keep_alive_millis: 60_000,
                    expires_at_millis: now_millis + 60_000,
                    creation_time_millis: now_millis,
                },
            );
        }

        let should_stop = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let reaper_stop = std::sync::Arc::clone(&should_stop);
        let reaper = node.spawn_pit_expiry_reaper_until(Duration::from_millis(1), move || {
            reaper_stop.load(std::sync::atomic::Ordering::SeqCst)
        });
        for _ in 0..100 {
            if !node
                .pit_contexts
                .lock()
                .expect("pit contexts lock poisoned")
                .contains_key(&expired_pit_id)
            {
                break;
            }
            std::thread::sleep(Duration::from_millis(5));
        }
        should_stop.store(true, std::sync::atomic::Ordering::SeqCst);
        reaper
            .join()
            .expect("PIT expiry reaper should stop cleanly");

        let contexts = node
            .pit_contexts
            .lock()
            .expect("pit contexts lock poisoned");
        assert!(!contexts.contains_key(&expired_pit_id));
        assert!(contexts.contains_key(&active_pit_id));
    }

    #[test]
    fn search_routes_support_span_gap_inside_span_near_queries() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        assert_eq!(
            node.handle_rest_request(RestRequest::new(RestMethod::Put, "/logs-span-gap-000001"))
                .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-span-gap-000001/_doc/doc-1")
                    .with_json_body(serde_json::json!({
                        "message": "alpha beta gamma delta"
                    })),
            )
            .status,
            201
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-span-gap-000001/_doc/doc-2")
                    .with_json_body(serde_json::json!({
                        "message": "alpha beta delta"
                    })),
            )
            .status,
            201
        );

        let span_gap_match = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-span-gap-000001/_search").with_json_body(
                serde_json::json!({
                    "query": {
                        "span_near": {
                            "clauses": [
                                { "span_term": { "message": "alpha" } },
                                { "span_gap": { "message": 2 } },
                                { "span_term": { "message": "delta" } }
                            ],
                            "slop": 0,
                            "in_order": true
                        }
                    }
                }),
            ),
        );
        assert_eq!(span_gap_match.status, 200);
        assert_eq!(span_gap_match.body["hits"]["total"]["value"], 1);
        assert_eq!(span_gap_match.body["hits"]["hits"][0]["_id"], "doc-1");

        let span_gap_width_one_match = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-span-gap-000001/_search").with_json_body(
                serde_json::json!({
                    "query": {
                        "span_near": {
                            "clauses": [
                                { "span_term": { "message": "alpha" } },
                                { "span_gap": { "message": 1 } },
                                { "span_term": { "message": "delta" } }
                            ],
                            "slop": 0,
                            "in_order": true
                        }
                    }
                }),
            ),
        );
        assert_eq!(span_gap_width_one_match.status, 200);
        assert_eq!(span_gap_width_one_match.body["hits"]["total"]["value"], 1);
        assert_eq!(
            span_gap_width_one_match.body["hits"]["hits"][0]["_id"],
            "doc-2"
        );
    }

