    #[test]
    fn snapshot_repository_fs_location_respects_configured_path_repo_boundary() {
        let _guard = security_env_lock();
        let previous = env::var_os("SNAPSHOT_REPOSITORY_BASE_DIR");
        env::set_var(
            "SNAPSHOT_REPOSITORY_BASE_DIR",
            "/tmp/steelsearch-allowed-snapshot-repositories",
        );
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let rejected = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_snapshot/repo-outside-path-repo").with_json_body(
                serde_json::json!({
                    "type": "fs",
                    "settings": {"location": "/tmp/repo-outside-path-repo"}
                }),
            ),
        );
        assert_eq!(rejected.status, 500);
        assert_eq!(
            rejected.body["error"]["type"],
            Value::String("repository_exception".to_string())
        );
        assert!(rejected.body["error"]["reason"]
            .as_str()
            .unwrap_or_default()
            .contains("doesn't match any of the locations specified by path.repo"));

        let accepted = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_snapshot/repo-inside-path-repo").with_json_body(
                serde_json::json!({
                    "type": "fs",
                    "settings": {"location": "repo-inside-path-repo"}
                }),
            ),
        );
        assert_eq!(accepted.status, 200);

        if let Some(previous) = previous {
            env::set_var("SNAPSHOT_REPOSITORY_BASE_DIR", previous);
        } else {
            env::remove_var("SNAPSHOT_REPOSITORY_BASE_DIR");
        }
    }

    #[test]
    fn snapshot_repository_routes_round_trip_expected_shapes() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_snapshot/repo-route-probe").with_json_body(
                serde_json::json!({
                    "type": "fs",
                    "settings": {"location": "/tmp/repo-route-probe"}
                }),
            ),
        );
        assert_eq!(create.status, 200);
        assert_eq!(create.body["acknowledged"], Value::Bool(true));

        let selector_create = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/_snapshot/repo-route-probe-selector?verify=false&timeout=30s&cluster_manager_timeout=30s",
            )
            .with_json_body(serde_json::json!({
                "type": "fs",
                "settings": {"location": "/tmp/repo-route-probe-selector"},
                "ignored_by_opensearch_source": true
            })),
        );
        assert_eq!(selector_create.status, 200);
        assert_eq!(selector_create.body["acknowledged"], Value::Bool(true));

        let missing_type = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_snapshot/repo-route-missing-type").with_json_body(
                serde_json::json!({
                    "settings": {"location": "/tmp/repo-route-missing-type"}
                }),
            ),
        );
        assert_eq!(missing_type.status, 400);
        assert_eq!(
            missing_type.body["error"]["type"],
            Value::String("action_request_validation_exception".to_string())
        );
        assert_eq!(
            missing_type.body["error"]["reason"],
            Value::String("Validation Failed: 1: type is missing;".to_string())
        );

        let duplicate_timeout = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/_snapshot/repo-route-duplicate-timeout?master_timeout=30s&cluster_manager_timeout=30s",
            )
            .with_json_body(serde_json::json!({
                "type": "fs",
                "settings": {"location": "/tmp/repo-route-duplicate-timeout"}
            })),
        );
        assert_eq!(duplicate_timeout.status, 400);
        assert_eq!(
            duplicate_timeout.body["error"]["type"],
            Value::String("parse_exception".to_string())
        );
        assert_eq!(
            duplicate_timeout.body["error"]["reason"],
            Value::String(
                "Please only use one of the request parameters [master_timeout, cluster_manager_timeout]."
                    .to_string()
            )
        );

        let readback = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_snapshot/repo-route-probe",
        ));
        assert_eq!(readback.status, 200);
        assert_eq!(readback.body["repo-route-probe"]["type"], "fs");
        assert_eq!(
            readback.body["repo-route-probe"]["settings"]["location"],
            "/tmp/repo-route-probe"
        );

        let delete = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/_snapshot/repo-route-probe",
        ));
        assert_eq!(delete.status, 200);
        assert_eq!(delete.body["acknowledged"], Value::Bool(true));

        let missing = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_snapshot/repo-route-probe",
        ));
        assert_eq!(missing.status, 200);
        assert_eq!(missing.body, serde_json::json!({}));
    }

    #[test]
    fn snapshot_cleanup_route_serves_bounded_cleanup_shape() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let repository_response = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_snapshot/repo-cleanup-probe").with_json_body(
                serde_json::json!({
                    "type": "fs",
                    "settings": {"location": "/tmp/repo-cleanup-probe"}
                }),
            ),
        );
        assert_eq!(repository_response.status, 200);

        let cleanup = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_snapshot/repo-cleanup-probe/_cleanup",
        ));
        assert_eq!(cleanup.status, 200);
        assert_eq!(cleanup.body["results"]["deleted_bytes"], Value::from(0));
        assert_eq!(cleanup.body["results"]["deleted_blobs"], Value::from(0));

        let cleanup_with_timeouts = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_snapshot/repo-cleanup-probe/_cleanup?timeout=30s&cluster_manager_timeout=30s",
        ));
        assert_eq!(cleanup_with_timeouts.status, 200);
        assert_eq!(
            cleanup_with_timeouts.body["results"]["deleted_bytes"],
            Value::from(0)
        );

        let invalid_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_snapshot/repo-cleanup-probe/_cleanup?timeout=forever",
        ));
        assert_eq!(invalid_timeout.status, 400);
        assert_eq!(
            invalid_timeout.body["error"]["type"],
            Value::String("illegal_argument_exception".to_string())
        );
        assert!(invalid_timeout.body["error"]["reason"]
            .as_str()
            .is_some_and(|reason| reason.contains(
                "failed to parse setting [timeout] with value [forever] as a time value"
            )));

        let duplicate_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_snapshot/repo-cleanup-probe/_cleanup?master_timeout=30s&cluster_manager_timeout=30s",
        ));
        assert_eq!(duplicate_timeout.status, 400);
        assert_eq!(
            duplicate_timeout.body["error"]["type"],
            Value::String("parse_exception".to_string())
        );

        let missing_cleanup = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_snapshot/repo-cleanup-missing/_cleanup",
        ));
        assert_eq!(missing_cleanup.status, 404);
        assert_eq!(
            missing_cleanup.body["error"]["type"],
            Value::String("repository_missing_exception".to_string())
        );
        assert_eq!(
            missing_cleanup.body["error"]["reason"],
            Value::String("[repo-cleanup-missing] missing".to_string())
        );
    }

