    #[test]
    fn snapshot_lifecycle_routes_support_get_post_and_delete_contracts() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let repository_response = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_snapshot/repo-lifecycle-probe").with_json_body(
                serde_json::json!({
                    "type": "fs",
                    "settings": {"location": "/tmp/repo-lifecycle-probe"}
                }),
            ),
        );
        assert_eq!(repository_response.status, 200);

        let create = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/_snapshot/repo-lifecycle-probe/snapshot-post-probe",
            )
            .with_json_body(serde_json::json!({
                "indices": "logs-a,logs-b",
                "include_global_state": false
            })),
        );
        assert_eq!(create.status, 200);
        assert_eq!(create.body["accepted"], Value::Bool(true));
        assert_eq!(create.body["snapshot"]["snapshot"], "snapshot-post-probe");

        let readback = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_snapshot/repo-lifecycle-probe/snapshot-post-probe",
        ));
        assert_eq!(readback.status, 200);
        assert_eq!(
            readback.body["snapshots"][0]["snapshot"],
            "snapshot-post-probe"
        );
        assert_eq!(
            readback.body["snapshots"][0]["indices"],
            serde_json::json!(["logs-a", "logs-b"])
        );
        assert!(readback.body["snapshots"][0]["stats"].is_object());

        let readback_selector = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_snapshot/repo-lifecycle-probe/snapshot-post-probe,missing-snapshot?ignore_unavailable=true&verbose=false&cluster_manager_timeout=30s",
        ));
        assert_eq!(readback_selector.status, 200);
        assert_eq!(
            readback_selector.body["snapshots"][0]["snapshot"],
            "snapshot-post-probe"
        );
        assert!(readback_selector.body["snapshots"][0]
            .get("stats")
            .is_none());
        assert_eq!(
            readback_selector.body["snapshots"]
                .as_array()
                .expect("snapshot readback selector array expected")
                .len(),
            1
        );

        let invalid_boolean = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_snapshot/repo-lifecycle-probe/snapshot-post-probe?ignore_unavailable=maybe",
        ));
        assert_eq!(invalid_boolean.status, 400);
        assert_eq!(
            invalid_boolean.body["error"]["reason"],
            "Could not convert [ignore_unavailable] to boolean"
        );

        let duplicate_get_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_snapshot/repo-lifecycle-probe/snapshot-post-probe?master_timeout=30s&cluster_manager_timeout=30s",
        ));
        assert_eq!(duplicate_get_timeout.status, 400);
        assert_eq!(
            duplicate_get_timeout.body["error"]["type"],
            Value::String("parse_exception".to_string())
        );

        let duplicate_delete_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/_snapshot/repo-lifecycle-probe/snapshot-post-probe?master_timeout=30s&cluster_manager_timeout=30s",
        ));
        assert_eq!(duplicate_delete_timeout.status, 400);
        assert_eq!(
            duplicate_delete_timeout.body["error"]["type"],
            Value::String("parse_exception".to_string())
        );

        let delete = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/_snapshot/repo-lifecycle-probe/snapshot-post-probe",
        ));
        assert_eq!(delete.status, 200);
        assert_eq!(delete.body["acknowledged"], Value::Bool(true));
        assert_eq!(delete.body["snapshot"]["snapshot"], "snapshot-post-probe");

        let missing = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_snapshot/repo-lifecycle-probe/snapshot-post-probe",
        ));
        assert_eq!(missing.status, 404);
        assert_eq!(missing.body["error"]["type"], "snapshot_missing_exception");
    }

    #[test]
    fn snapshot_create_rejects_duplicate_name_like_opensearch() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        let repository = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_snapshot/repo-duplicate-create").with_json_body(
                serde_json::json!({
                    "type": "fs",
                    "settings": {
                        "location": "target/test-snapshots/repo-duplicate-create"
                    }
                }),
            ),
        );
        assert_eq!(repository.status, 200);

        let first = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_snapshot/repo-duplicate-create/snap-one")
                .with_json_body(serde_json::json!({
                    "indices": "logs-a",
                    "metadata": {
                        "owner": "first"
                    }
                })),
        );
        assert_eq!(first.status, 200);

        let duplicate = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_snapshot/repo-duplicate-create/snap-one")
                .with_json_body(serde_json::json!({
                    "indices": "logs-b",
                    "metadata": {
                        "owner": "second"
                    }
                })),
        );
        assert_eq!(duplicate.status, 400);
        assert_eq!(
            duplicate.body["error"]["type"],
            "invalid_snapshot_name_exception"
        );
        assert!(duplicate.body["error"]["reason"]
            .as_str()
            .expect("duplicate snapshot reason")
            .contains("snapshot with the same name already exists"));

        let readback = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_snapshot/repo-duplicate-create/snap-one",
        ));
        assert_eq!(readback.status, 200);
        assert_eq!(
            readback.body["snapshots"][0]["indices"],
            serde_json::json!(["logs-a"])
        );
        assert_eq!(readback.body["snapshots"][0]["metadata"]["owner"], "first");
    }

