    #[test]
    fn remote_store_metadata_and_stats_routes_match_bounded_source_shapes() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let missing_metadata = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_remotestore/metadata/missing-index",
        ));
        assert_eq!(missing_metadata.status, 404);
        assert_eq!(
            missing_metadata.body["error"]["type"],
            "index_not_found_exception"
        );
        assert_eq!(missing_metadata.body["error"]["index"], "missing-index");

        let missing_stats = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_remotestore/stats/missing-index",
        ));
        assert_eq!(missing_stats.status, 404);
        assert_eq!(
            missing_stats.body["error"]["type"],
            "index_not_found_exception"
        );
        assert_eq!(missing_stats.body["error"]["index"], "missing-index");

        let mut node = node;
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/remote-store-probe")
                .with_json_body(serde_json::json!({})),
        );

        let metadata = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_remotestore/metadata/remote-store-probe",
        ));
        assert_eq!(metadata.status, 200);
        assert_eq!(metadata.body["_shards"]["total"], 1);
        assert_eq!(metadata.body["_shards"]["successful"], 0);
        assert_eq!(metadata.body["_shards"]["failed"], 1);
        assert_eq!(
            metadata.body["_shards"]["failures"][0]["reason"]["type"],
            "illegal_state_exception"
        );
        assert_eq!(metadata.body["indices"], serde_json::json!({}));

        let stats = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_remotestore/stats/remote-store-probe",
        ));
        assert_eq!(stats.status, 200);
        assert_eq!(stats.body["_shards"]["total"], 0);
        assert_eq!(stats.body["_shards"]["successful"], 0);
        assert_eq!(stats.body["_shards"]["failed"], 0);
        assert_eq!(stats.body["indices"], serde_json::json!({}));

        let shard_metadata = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_remotestore/metadata/remote-store-probe/0",
        ));
        assert_eq!(shard_metadata.status, 400);
        assert_eq!(
            shard_metadata.body["error"]["type"],
            "illegal_state_exception"
        );
        assert!(shard_metadata.body.get("_shards").is_none());
        assert!(shard_metadata.body.get("indices").is_none());

        let shard_stats = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_remotestore/stats/remote-store-probe/0",
        ));
        assert_eq!(shard_stats.status, 200);
        assert_eq!(shard_stats.body["_shards"]["total"], 0);
        assert_eq!(shard_stats.body["_shards"]["successful"], 0);
        assert_eq!(shard_stats.body["_shards"]["failed"], 0);
        assert_eq!(shard_stats.body["indices"], serde_json::json!({}));
    }

    #[test]
    fn wlm_stats_routes_serve_bounded_global_node_and_workload_group_shapes() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        for path in [
            "/_list/wlm_stats",
            "/_list/wlm_stats/stats/default",
            "/_list/wlm_stats/_all/stats",
            "/_list/wlm_stats/_all/stats/default",
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 400, "path {path}");
            assert_eq!(
                response.body["error"]["type"], "illegal_argument_exception",
                "path {path}"
            );
            assert!(response.body.get("_nodes").is_none(), "path {path}");
        }

        for path in ["/_wlm/stats", "/_wlm/_all/stats"] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 200, "path {path}");
            assert!(response.body["_nodes"].is_object(), "path {path}");
            assert!(
                response.body["steel-node"]["workload_groups"].is_object(),
                "path {path}"
            );
            assert!(
                response.body["steel-node"]["workload_groups"]["DEFAULT_WORKLOAD_GROUP"]
                    .is_object(),
                "path {path}"
            );
        }

        for path in ["/_wlm/stats/default", "/_wlm/_all/stats/default"] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 200, "path {path}");
            assert_eq!(response.body["_nodes"]["successful"], 0);
            assert_eq!(response.body["_nodes"]["failed"], 1);
            assert!(response.body.get("steel-node").is_none(), "path {path}");
        }

        let filtered = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_wlm/missing-node/stats/default",
        ));
        assert_eq!(filtered.status, 200);
        assert_eq!(filtered.body["_nodes"]["total"], 0);

        let enable = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_cluster/settings").with_json_body(
                serde_json::json!({
                    "persistent": {
                        "wlm.workload_group.mode": "enabled"
                    }
                }),
            ),
        );
        assert_eq!(enable.status, 200);
        let created = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_wlm/workload_group/").with_json_body(
                serde_json::json!({
                    "name": "stats-probe",
                    "resource_limits": {
                        "cpu": 0.2
                    }
                }),
            ),
        );
        assert_eq!(created.status, 200);
        let created_id = created.body["_id"].as_str().expect("created id");
        let second_created = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_wlm/workload_group/").with_json_body(
                serde_json::json!({
                    "name": "stats-probe-two",
                    "resource_limits": {
                        "cpu": 0.1
                    }
                }),
            ),
        );
        assert_eq!(second_created.status, 200);

        let all_stats = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_wlm/stats"));
        assert_eq!(all_stats.status, 200);
        assert!(
            all_stats.body["steel-node"]["workload_groups"][created_id].is_object(),
            "created group should be visible in _all WLM stats"
        );
        let named_stats = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            format!("/_wlm/stats/{created_id}"),
        ));
        assert_eq!(named_stats.status, 200);
        assert_eq!(named_stats.body["_nodes"]["successful"], 1);
        assert!(
            named_stats.body["steel-node"]["workload_groups"][created_id].is_object(),
            "created group should be selectable by workload group id"
        );
        let list_stats = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            format!("/_list/wlm_stats/stats/{created_id}"),
        ));
        assert_eq!(list_stats.status, 400);
        assert_eq!(
            list_stats.body["error"]["type"],
            "illegal_argument_exception"
        );
    }

    #[test]
    fn wlm_workload_group_routes_follow_opensearch_mode_gate_and_crud_shape() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let default_get =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_wlm/workload_group/"));
        assert_eq!(default_get.status, 200);
        assert_eq!(default_get.body["workload_groups"], serde_json::json!([]));

        let disabled_create = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_wlm/workload_group/").with_json_body(
                serde_json::json!({
                    "name": "analytics",
                    "resiliency_mode": "enforced",
                    "resource_limits": {
                        "cpu": 0.4,
                        "memory": 0.2
                    }
                }),
            ),
        );
        assert_eq!(disabled_create.status, 500);
        assert_eq!(
            disabled_create.body["error"]["type"],
            "illegal_state_exception"
        );

        let enable = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_cluster/settings").with_json_body(
                serde_json::json!({
                    "persistent": {
                        "wlm.workload_group.mode": "enabled"
                    }
                }),
            ),
        );
        assert_eq!(enable.status, 200);

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/_wlm/workload_group/").with_json_body(
                serde_json::json!({
                    "name": "analytics",
                    "resiliency_mode": "enforced",
                    "resource_limits": {
                        "cpu": 0.4,
                        "memory": 0.2
                    },
                    "search_settings": {
                        "query_group_routing": "enabled"
                    }
                }),
            ),
        );
        assert_eq!(create.status, 200);
        assert_eq!(create.body["name"], "analytics");
        assert_eq!(create.body["resiliency_mode"], "enforced");
        assert_eq!(create.body["resource_limits"]["cpu"], 0.4);
        assert_eq!(create.body["resource_limits"]["memory"], 0.2);
        assert!(create.body["updated_at"].as_u64().unwrap_or_default() > 0);
        let id = create.body["_id"].clone();

        let named_get = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_wlm/workload_group/analytics",
        ));
        assert_eq!(named_get.status, 200);
        assert_eq!(named_get.body["workload_groups"][0]["_id"], id);

        let update = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_wlm/workload_group/analytics").with_json_body(
                serde_json::json!({
                    "resiliency_mode": "monitor",
                    "resource_limits": {
                        "cpu": 0.5
                    },
                    "search_settings": {}
                }),
            ),
        );
        assert_eq!(update.status, 200);
        assert_eq!(update.body["_id"], id);
        assert_eq!(update.body["resiliency_mode"], "monitor");
        assert_eq!(update.body["resource_limits"]["cpu"], 0.5);
        assert_eq!(update.body["resource_limits"]["memory"], 0.2);
        assert_eq!(update.body["search_settings"], serde_json::json!({}));

        let delete = node.handle_rest_request(RestRequest::new(
            RestMethod::Delete,
            "/_wlm/workload_group/analytics",
        ));
        assert_eq!(delete.status, 200);
        assert_eq!(delete.body["acknowledged"], true);

        let missing_get = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_wlm/workload_group/analytics",
        ));
        assert_eq!(missing_get.status, 404);
        assert_eq!(
            missing_get.body["error"]["type"],
            "resource_not_found_exception"
        );
    }

