    #[test]
    fn recovery_routes_serve_global_and_targeted_index_recovery_shapes() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-recovery-000001")
                .with_json_body(serde_json::json!({})),
        );
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/metrics-recovery-000001")
                .with_json_body(serde_json::json!({})),
        );
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-recovery-hidden-000001").with_json_body(
                serde_json::json!({
                    "settings": {"index": {"hidden": true}}
                }),
            ),
        );

        let global = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_recovery"));
        assert_eq!(global.status, 200);
        assert!(global.body["logs-recovery-000001"]["shards"].is_array());
        assert!(global.body["metrics-recovery-000001"]["shards"].is_array());
        assert!(global.body.get("logs-recovery-hidden-000001").is_none());

        let targeted =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/logs-*/_recovery"));
        assert_eq!(targeted.status, 200);
        assert!(targeted.body.get("logs-recovery-000001").is_some());
        assert!(targeted.body.get("metrics-recovery-000001").is_none());
        assert!(targeted.body.get("logs-recovery-hidden-000001").is_none());
        assert_eq!(
            targeted.body["logs-recovery-000001"]["shards"][0]["stage"],
            "DONE"
        );

        let invalid_active_only = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-*/_recovery?active_only=maybe",
        ));
        assert_eq!(invalid_active_only.status, 400);
        assert_eq!(
            invalid_active_only.body["error"]["reason"],
            "Failed to parse value [maybe] as only [true] or [false] are allowed."
        );

        let unrecognized_param = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-*/_recovery?not_a_param=x",
        ));
        assert_eq!(unrecognized_param.status, 400);
        assert_eq!(
            unrecognized_param.body["error"]["reason"],
            "request [/logs-*/_recovery] contains unrecognized parameter: [not_a_param]"
        );
    }

    #[test]
    fn segments_routes_serve_global_and_targeted_segment_shapes() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-segments-000001")
                .with_json_body(serde_json::json!({})),
        );
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/metrics-segments-000001")
                .with_json_body(serde_json::json!({})),
        );
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-segments-hidden-000001").with_json_body(
                serde_json::json!({
                    "settings": {"index": {"hidden": true}}
                }),
            ),
        );

        let global = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_segments"));
        assert_eq!(global.status, 200);
        assert_eq!(global.body["_shards"]["total"], 2);
        assert!(global.body["indices"]["logs-segments-000001"]["shards"]["0"].is_array());
        assert!(global.body["indices"]["metrics-segments-000001"]["shards"]["0"].is_array());
        assert!(global.body["indices"]
            .get("logs-segments-hidden-000001")
            .is_none());

        let targeted =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/logs-*/_segments"));
        assert_eq!(targeted.status, 200);
        assert_eq!(targeted.body["_shards"]["total"], 1);
        assert!(targeted.body["indices"]
            .get("logs-segments-000001")
            .is_some());
        assert!(targeted.body["indices"]
            .get("metrics-segments-000001")
            .is_none());
        assert_eq!(
            targeted.body["indices"]["logs-segments-000001"]["shards"]["0"][0]["segments"]["_0"]
                ["committed"],
            false
        );

        let invalid_allow_no_indices = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-*/_segments?allow_no_indices=maybe",
        ));
        assert_eq!(invalid_allow_no_indices.status, 400);
        assert_eq!(
            invalid_allow_no_indices.body["error"]["reason"],
            "Could not convert [allow_no_indices] to boolean"
        );

        let invalid_verbose = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-*/_segments?verbose=maybe",
        ));
        assert_eq!(invalid_verbose.status, 400);
        assert_eq!(
            invalid_verbose.body["error"]["reason"],
            "Failed to parse value [maybe] as only [true] or [false] are allowed."
        );

        let invalid_expand_wildcards = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-*/_segments?expand_wildcards=bogus",
        ));
        assert_eq!(invalid_expand_wildcards.status, 400);
        assert_eq!(
            invalid_expand_wildcards.body["error"]["reason"],
            "No valid expand wildcard value [bogus]"
        );

        let unrecognized_param = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-*/_segments?not_a_param=x",
        ));
        assert_eq!(unrecognized_param.status, 400);
        assert_eq!(
            unrecognized_param.body["error"]["reason"],
            "request [/logs-*/_segments] contains unrecognized parameter: [not_a_param]"
        );
    }

