    #[test]
    fn analyze_routes_serve_global_and_targeted_token_streams() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let global_get = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_analyze?text=Quick%20Fox",
        ));
        assert_eq!(global_get.status, 200);
        assert_eq!(global_get.body["tokens"][0]["token"], "quick");
        assert_eq!(global_get.body["tokens"][1]["token"], "fox");

        let global_post = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_analyze")
                .with_json_body(serde_json::json!({"text": "Jumped Over"})),
        );
        assert_eq!(global_post.status, 200);
        assert_eq!(global_post.body["tokens"][0]["token"], "jumped");
        assert_eq!(global_post.body["tokens"][1]["token"], "over");

        let keyword_post = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_analyze")
                .with_json_body(serde_json::json!({"analyzer": "keyword", "text": "Jumped Over"})),
        );
        assert_eq!(keyword_post.status, 200);
        assert_eq!(keyword_post.body["tokens"][0]["token"], "Jumped Over");
        assert_eq!(keyword_post.body["tokens"].as_array().unwrap().len(), 1);

        let missing_text = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_analyze")
                .with_json_body(serde_json::json!({"analyzer": "standard"})),
        );
        assert_eq!(missing_text.status, 400);
        assert_eq!(
            missing_text.body["error"]["type"],
            "action_request_validation_exception"
        );
        assert_eq!(
            missing_text.body["error"]["reason"],
            "Validation Failed: 1: text is missing;"
        );

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-settings-000001")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(create.status, 200);

        let targeted_get = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-settings-000001/_analyze?text=Hello%20World",
        ));
        assert_eq!(targeted_get.status, 200);
        assert_eq!(targeted_get.body["tokens"][0]["token"], "hello");

        let targeted_post = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-settings-000001/_analyze")
                .with_json_body(serde_json::json!({"text": ["Steel", "Search"]})),
        );
        assert_eq!(targeted_post.status, 200);
        assert_eq!(targeted_post.body["tokens"][0]["token"], "steel");
        assert_eq!(targeted_post.body["tokens"][1]["token"], "search");

        let missing_target = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/missing-analyze-index/_analyze")
                .with_json_body(serde_json::json!({"text": "missing"})),
        );
        assert_eq!(missing_target.status, 404);
        assert_eq!(
            missing_target.body["error"]["type"],
            "index_not_found_exception"
        );
    }

    #[test]
    fn flush_routes_serve_global_and_targeted_shard_counts() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-flush-000001")
                .with_json_body(serde_json::json!({})),
        );
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-flush-000002")
                .with_json_body(serde_json::json!({})),
        );
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/metrics-flush-000001")
                .with_json_body(serde_json::json!({})),
        );

        for (method, path, expected_total, expected_successful) in [
            (RestMethod::Get, "/_flush", 6, 3),
            (RestMethod::Post, "/_flush", 6, 3),
            (RestMethod::Get, "/_flush/synced", 6, 3),
            (RestMethod::Post, "/_flush/synced", 6, 3),
            (RestMethod::Get, "/logs-*/_flush", 4, 2),
            (RestMethod::Post, "/logs-*/_flush", 4, 2),
            (RestMethod::Get, "/logs-*/_flush/synced", 4, 2),
            (RestMethod::Post, "/logs-*/_flush/synced", 4, 2),
        ] {
            let response = node.handle_rest_request(RestRequest::new(method, path));
            assert_eq!(response.status, 200, "path {path}");
            assert_eq!(
                response.body["_shards"]["total"], expected_total,
                "path {path}"
            );
            assert_eq!(
                response.body["_shards"]["successful"], expected_successful,
                "path {path}"
            );
            assert_eq!(response.body["_shards"]["failed"], 0, "path {path}");
        }

        let invalid_allow_no_indices = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-*/_flush?allow_no_indices=maybe",
        ));
        assert_eq!(invalid_allow_no_indices.status, 400);
        assert_eq!(
            invalid_allow_no_indices.body["error"]["reason"],
            "Could not convert [allow_no_indices] to boolean"
        );

        let invalid_force = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-*/_flush?force=maybe",
        ));
        assert_eq!(invalid_force.status, 400);
        assert_eq!(
            invalid_force.body["error"]["reason"],
            "Failed to parse value [maybe] as only [true] or [false] are allowed."
        );

        let invalid_expand_wildcards = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-*/_flush?expand_wildcards=bogus",
        ));
        assert_eq!(invalid_expand_wildcards.status, 400);
        assert_eq!(
            invalid_expand_wildcards.body["error"]["reason"],
            "No valid expand wildcard value [bogus]"
        );

        let unrecognized_param = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-*/_flush?not_a_param=x",
        ));
        assert_eq!(unrecognized_param.status, 400);
        assert_eq!(
            unrecognized_param.body["error"]["reason"],
            "request [/logs-*/_flush] contains unrecognized parameter: [not_a_param]"
        );

        let synced_selector = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-*/_flush/synced?expand_wildcards=open&allow_no_indices=true&ignore_unavailable=false",
        ));
        assert_eq!(synced_selector.status, 200);
        assert_eq!(synced_selector.body["_shards"]["total"], 4);
        assert_eq!(synced_selector.body["_shards"]["successful"], 2);

        let invalid_synced_ignore_unavailable = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-flush-000001/_flush/synced?ignore_unavailable=maybe",
        ));
        assert_eq!(invalid_synced_ignore_unavailable.status, 400);
        assert_eq!(
            invalid_synced_ignore_unavailable.body["error"]["reason"],
            "Could not convert [ignore_unavailable] to boolean"
        );

        let unsupported_synced_force = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-flush-000001/_flush/synced?force=true",
        ));
        assert_eq!(unsupported_synced_force.status, 400);
        assert_eq!(
            unsupported_synced_force.body["error"]["reason"],
            "request [/logs-flush-000001/_flush/synced] contains unrecognized parameter: [force]"
        );
    }

