    #[test]
    fn close_routes_mark_global_and_targeted_indices_closed() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-close-000001")
                .with_json_body(serde_json::json!({})),
        );
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/metrics-close-000001")
                .with_json_body(serde_json::json!({})),
        );

        let targeted =
            node.handle_rest_request(RestRequest::new(RestMethod::Post, "/logs-*/_close"));
        assert_eq!(targeted.status, 200);
        assert_eq!(targeted.body["acknowledged"], Value::Bool(true));
        assert_eq!(targeted.body["shards_acknowledged"], Value::Bool(true));

        let repeated_targeted =
            node.handle_rest_request(RestRequest::new(RestMethod::Post, "/logs-*/_close"));
        assert_eq!(repeated_targeted.status, 200);
        assert_eq!(repeated_targeted.body["acknowledged"], Value::Bool(true));
        assert_eq!(
            repeated_targeted.body["indices"]["logs-close-000001"]["closed"],
            Value::Bool(true)
        );

        let global = node.handle_rest_request(RestRequest::new(RestMethod::Post, "/_close"));
        assert_eq!(global.status, 400);
        assert_eq!(
            global.body["error"]["type"],
            "action_request_validation_exception"
        );
        assert_eq!(
            global.body["error"]["reason"],
            "Validation Failed: 1: index is missing;"
        );

        let repeated = node.handle_rest_request(RestRequest::new(RestMethod::Post, "/_close"));
        assert_eq!(repeated.status, 400);
        assert_eq!(
            repeated.body["error"]["reason"],
            "Validation Failed: 1: index is missing;"
        );

        let invalid_allow_no_indices = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/_close?allow_no_indices=maybe",
        ));
        assert_eq!(invalid_allow_no_indices.status, 400);
        assert_eq!(
            invalid_allow_no_indices.body["error"]["reason"],
            "Could not convert [allow_no_indices] to boolean"
        );

        let invalid_expand_wildcards = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-*/_close?expand_wildcards=bogus",
        ));
        assert_eq!(invalid_expand_wildcards.status, 400);
        assert_eq!(
            invalid_expand_wildcards.body["error"]["reason"],
            "No valid expand wildcard value [bogus]"
        );

        let unrecognized_param = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-*/_close?not_a_param=x",
        ));
        assert_eq!(unrecognized_param.status, 400);
        assert_eq!(
            unrecognized_param.body["error"]["reason"],
            "request [/logs-*/_close] contains unrecognized parameter: [not_a_param]"
        );

        let manifest = node
            .metadata_manifest_state
            .lock()
            .expect("metadata manifest state lock poisoned");
        assert_eq!(manifest["indices"]["logs-close-000001"]["state"], "close");
        assert_ne!(
            manifest["indices"]["metrics-close-000001"]["state"],
            "close"
        );
    }

    #[test]
    fn maintenance_routes_reject_closed_target_and_global_refresh_excludes_closed_indices() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-maint-closed-000001")
                .with_json_body(serde_json::json!({})),
        );
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-maint-open-000001")
                .with_json_body(serde_json::json!({})),
        );

        let close = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-maint-closed-000001/_close",
        ));
        assert_eq!(close.status, 200);

        let global_refresh =
            node.handle_rest_request(RestRequest::new(RestMethod::Post, "/_refresh"));
        assert_eq!(global_refresh.status, 200);
        assert_eq!(global_refresh.body["_shards"]["total"], 2);
        assert_eq!(global_refresh.body["_shards"]["successful"], 1);

        for path in [
            "/logs-maint-closed-000001/_refresh",
            "/logs-maint-closed-000001/_flush",
            "/logs-maint-closed-000001/_cache/clear",
            "/logs-maint-closed-000001/_forcemerge",
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Post, path));
            assert_eq!(response.status, 400, "path {path}");
            assert_eq!(
                response.body["error"]["type"], "index_closed_exception",
                "path {path}"
            );
            assert_eq!(response.body["error"]["reason"], "closed", "path {path}");
        }

        for path in [
            "/logs-maint-*/_refresh",
            "/logs-maint-*/_flush",
            "/logs-maint-*/_cache/clear",
            "/logs-maint-*/_forcemerge",
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Post, path));
            assert_eq!(response.status, 200, "path {path}");
            assert_eq!(response.body["_shards"]["total"], 2, "path {path}");
            assert_eq!(response.body["_shards"]["successful"], 1, "path {path}");
        }

        for path in [
            "/logs-maint-*/_refresh?expand_wildcards=all",
            "/logs-maint-*/_flush?expand_wildcards=all",
            "/logs-maint-*/_cache/clear?expand_wildcards=all",
            "/logs-maint-*/_forcemerge?expand_wildcards=all",
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Post, path));
            assert_eq!(response.status, 400, "path {path}");
            assert_eq!(
                response.body["error"]["type"], "index_closed_exception",
                "path {path}"
            );
            assert_eq!(response.body["error"]["reason"], "closed", "path {path}");
        }
    }

    #[test]
    fn search_expand_wildcards_closed_resolves_closed_targets_and_fails_closed() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-search-open-000001")
                .with_json_body(serde_json::json!({})),
        );
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-search-closed-000001")
                .with_json_body(serde_json::json!({})),
        );
        let open_doc = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-search-open-000001/_doc/open-doc")
                .with_json_body(serde_json::json!({"message": "open"})),
        );
        assert_eq!(open_doc.status, 201);
        let closed_doc = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Put,
                "/logs-search-closed-000001/_doc/closed-doc",
            )
            .with_json_body(serde_json::json!({"message": "closed"})),
        );
        assert_eq!(closed_doc.status, 201);
        let refresh = node.handle_rest_request(RestRequest::new(RestMethod::Post, "/_refresh"));
        assert_eq!(refresh.status, 200);
        let close = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-search-closed-000001/_close",
        ));
        assert_eq!(close.status, 200);

        let default_wildcard = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-search-*/_search")
                .with_json_body(serde_json::json!({"query": {"match_all": {}}})),
        );
        assert_eq!(default_wildcard.status, 200);
        assert_eq!(default_wildcard.body["hits"]["total"]["value"], 1);
        assert_eq!(
            default_wildcard.body["hits"]["hits"][0]["_index"],
            "logs-search-open-000001"
        );

        let closed_wildcard = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-search-*/_search?expand_wildcards=closed",
            )
            .with_json_body(serde_json::json!({"query": {"match_all": {}}})),
        );
        assert_eq!(closed_wildcard.status, 400);
        assert_eq!(
            closed_wildcard.body["error"]["type"],
            "illegal_argument_exception"
        );

        for path in [
            "/logs-search-*/_search?expand_wildcards=all",
            "/logs-search-closed-000001/_search",
        ] {
            let response = node.handle_rest_request(
                RestRequest::new(RestMethod::Post, path)
                    .with_json_body(serde_json::json!({"query": {"match_all": {}}})),
            );
            assert_eq!(response.status, 400, "path {path}");
            assert_eq!(response.body["error"]["type"], "index_closed_exception");
        }
    }

