    #[test]
    fn upgrade_routes_serve_global_and_targeted_upgrade_shapes() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-upgrade-000001")
                .with_json_body(serde_json::json!({})),
        );
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/metrics-upgrade-000001")
                .with_json_body(serde_json::json!({})),
        );

        for (method, path, expected_logs, expected_metrics) in [
            (RestMethod::Get, "/_upgrade", true, true),
            (
                RestMethod::Post,
                "/_upgrade?only_ancient_segments=true",
                true,
                true,
            ),
            (RestMethod::Get, "/logs-*/_upgrade", true, false),
            (
                RestMethod::Post,
                "/logs-*/_upgrade?expand_wildcards=open&ignore_unavailable=false",
                true,
                false,
            ),
        ] {
            let response = node.handle_rest_request(RestRequest::new(method, path));
            assert_eq!(response.status, 200, "path {path}");
            assert!(
                response.body["indices"]["logs-upgrade-000001"].is_object() == expected_logs,
                "path {path}"
            );
            assert!(
                response.body["indices"]["metrics-upgrade-000001"].is_object() == expected_metrics,
                "path {path}"
            );
            assert_eq!(response.body["size_in_bytes"], 0, "path {path}");
        }

        let invalid_only_ancient_segments = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-*/_upgrade?only_ancient_segments=maybe",
        ));
        assert_eq!(invalid_only_ancient_segments.status, 400);
        assert_eq!(
            invalid_only_ancient_segments.body["error"]["reason"],
            "Failed to parse value [maybe] as only [true] or [false] are allowed."
        );

        let get_only_ancient_segments = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-*/_upgrade?only_ancient_segments=true",
        ));
        assert_eq!(get_only_ancient_segments.status, 400);
        assert_eq!(
            get_only_ancient_segments.body["error"]["reason"],
            "request [/logs-*/_upgrade] contains unrecognized parameter: [only_ancient_segments]"
        );

        let invalid_expand_wildcards = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/logs-*/_upgrade?expand_wildcards=bogus",
        ));
        assert_eq!(invalid_expand_wildcards.status, 400);
        assert_eq!(
            invalid_expand_wildcards.body["error"]["reason"],
            "No valid expand wildcard value [bogus]"
        );
    }

    #[test]
    fn index_state_routes_match_closed_index_selection_semantics() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        for index in [
            "/logs-state-closed-000001",
            "/logs-state-open-000001",
            "/metrics-state-open-000001",
        ] {
            let response = node.handle_rest_request(
                RestRequest::new(RestMethod::Put, index).with_json_body(serde_json::json!({})),
            );
            assert_eq!(response.status, 200, "create {index}");
        }
        let close = node.handle_rest_request(RestRequest::new(
            RestMethod::Post,
            "/logs-state-closed-000001/_close",
        ));
        assert_eq!(close.status, 200);

        for path in ["/_segments", "/_stats", "/_upgrade"] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 200, "path {path}");
            assert!(
                response.body["indices"]["logs-state-closed-000001"].is_null(),
                "path {path}"
            );
            assert!(
                response.body["indices"]["logs-state-open-000001"].is_object(),
                "path {path}"
            );
        }

        for path in [
            "/logs-state-*/_segments",
            "/logs-state-*/_stats",
            "/logs-state-*/_stats/docs",
            "/logs-state-*/_upgrade",
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 200, "path {path}");
            assert!(
                response.body["indices"]["logs-state-closed-000001"].is_null(),
                "path {path}"
            );
            assert!(
                response.body["indices"]["logs-state-open-000001"].is_object(),
                "path {path}"
            );
            assert!(
                response.body["indices"]["metrics-state-open-000001"].is_null(),
                "path {path}"
            );
        }

        for path in [
            "/logs-state-*/_segments?expand_wildcards=all",
            "/logs-state-*/_stats?expand_wildcards=all",
            "/logs-state-*/_stats/docs?expand_wildcards=all",
            "/logs-state-*/_upgrade?expand_wildcards=all",
            "/logs-state-closed-000001/_segments",
            "/logs-state-closed-000001/_stats",
            "/logs-state-closed-000001/_upgrade",
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 400, "path {path}");
            assert_eq!(
                response.body["error"]["type"], "index_closed_exception",
                "path {path}"
            );
        }
    }

    #[test]
    fn ingestion_state_route_serves_bounded_index_state_shape() {
        let _lock = security_env_lock();
        unsafe {
            env::set_var("STEELSEARCH_SECURITY_ENABLED", "true");
            env::set_var("SECURITY_ADMIN_USERNAME", "admin");
            env::set_var("SECURITY_ADMIN_PASSWORD", "admin");
            env::set_var("SECURITY_READER_USERNAME", "reader");
            env::set_var("SECURITY_READER_PASSWORD", "reader");
        }
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let response = node.handle_rest_request(
            RestRequest::new(RestMethod::Get, "/logs-ingestion-000001/ingestion/_state")
                .with_header("Authorization", "Basic cmVhZGVyOnJlYWRlcg=="),
        );
        assert_eq!(response.status, 404);

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-ingestion-000001")
                .with_header("Authorization", "Basic YWRtaW46YWRtaW4=")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(create.status, 200);
        let response = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Get,
                "/logs-ingestion-000001/ingestion/_state?shards=0&size=10&sort=asc",
            )
            .with_header("Authorization", "Basic cmVhZGVyOnJlYWRlcg=="),
        );
        assert_eq!(response.status, 200);
        assert_eq!(response.body["index"], "logs-ingestion-000001");
        assert_eq!(response.body["state"], "RUNNING");
        assert!(response.body["indices"]["logs-ingestion-000001"].is_object());
        assert!(response.body["pipelines"].is_array());
        assert_eq!(response.body["metadata"]["version"], 1);

        let invalid_shard = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Get,
                "/logs-ingestion-000001/ingestion/_state?shards=bogus",
            )
            .with_header("Authorization", "Basic cmVhZGVyOnJlYWRlcg=="),
        );
        assert_eq!(invalid_shard.status, 400);
    }

    #[test]
    fn ingestion_pause_and_resume_routes_update_index_state() {
        let _lock = security_env_lock();
        unsafe {
            env::set_var("STEELSEARCH_SECURITY_ENABLED", "true");
            env::set_var("SECURITY_ADMIN_USERNAME", "admin");
            env::set_var("SECURITY_ADMIN_PASSWORD", "admin");
            env::set_var("SECURITY_READER_USERNAME", "reader");
            env::set_var("SECURITY_READER_PASSWORD", "reader");
        }
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-ingestion-ops-000001")
                .with_header("Authorization", "Basic YWRtaW46YWRtaW4=")
                .with_json_body(serde_json::json!({})),
        );
        assert_eq!(create.status, 200);

        let pause = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-ingestion-ops-000001/ingestion/_pause",
            )
            .with_header("Authorization", "Basic YWRtaW46YWRtaW4="),
        );
        assert_eq!(pause.status, 200);
        assert_eq!(pause.body["index"], "logs-ingestion-ops-000001");
        assert_eq!(pause.body["state"], "PAUSED");
        assert_eq!(pause.body["acknowledged"], Value::Bool(true));

        let invalid_pause = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-ingestion-ops-000001/ingestion/_pause?allow_no_indices=maybe",
            )
            .with_header("Authorization", "Basic YWRtaW46YWRtaW4="),
        );
        assert_eq!(invalid_pause.status, 400);
        assert_eq!(
            invalid_pause.body["error"]["reason"],
            "Could not convert [allow_no_indices] to boolean"
        );

        let paused_state = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Get,
                "/logs-ingestion-ops-000001/ingestion/_state",
            )
            .with_header("Authorization", "Basic cmVhZGVyOnJlYWRlcg=="),
        );
        assert_eq!(paused_state.status, 200);
        assert_eq!(paused_state.body["state"], "PAUSED");

        let resume = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-ingestion-ops-000001/ingestion/_resume",
            )
            .with_header("Authorization", "Basic YWRtaW46YWRtaW4="),
        );
        assert_eq!(resume.status, 200);
        assert_eq!(resume.body["state"], "RUNNING");
        assert_eq!(resume.body["acknowledged"], Value::Bool(true));

        let resumed_state = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Get,
                "/logs-ingestion-ops-000001/ingestion/_state",
            )
            .with_header("Authorization", "Basic cmVhZGVyOnJlYWRlcg=="),
        );
        assert_eq!(resumed_state.status, 200);
        assert_eq!(resumed_state.body["state"], "RUNNING");

        let reset_resume = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-ingestion-ops-*/ingestion/_resume?expand_wildcards=open",
            )
            .with_header("Authorization", "Basic YWRtaW46YWRtaW4=")
            .with_json_body(serde_json::json!({
                "reset_settings": [
                    {
                        "shard": 0,
                        "mode": "offset",
                        "value": "0"
                    }
                ]
            })),
        );
        assert_eq!(reset_resume.status, 200);
        assert_eq!(reset_resume.body["indices"][0], "logs-ingestion-ops-000001");

        let invalid_resume_body = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/logs-ingestion-ops-000001/ingestion/_resume",
            )
            .with_header("Authorization", "Basic YWRtaW46YWRtaW4=")
            .with_json_body(serde_json::json!({
                "reset_settings": [
                    {
                        "shard": 0,
                        "mode": "bogus",
                        "value": "0"
                    }
                ]
            })),
        );
        assert_eq!(invalid_resume_body.status, 400);
        assert_eq!(
            invalid_resume_body.body["error"]["reason"],
            "Invalid value for 'mode': bogus"
        );
    }

    #[test]
    fn mget_routes_serve_root_and_targeted_docs_for_get_and_post() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-mget-000001")
                    .with_json_body(serde_json::json!({})),
            )
            .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/metrics-mget-000001")
                    .with_json_body(serde_json::json!({})),
            )
            .status,
            200
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/logs-mget-000001/_doc/doc-1")
                    .with_json_body(serde_json::json!({"message":"log-1"})),
            )
            .status,
            201
        );
        assert_eq!(
            node.handle_rest_request(
                RestRequest::new(RestMethod::Put, "/metrics-mget-000001/_doc/doc-2")
                    .with_json_body(serde_json::json!({"message":"metric-2"})),
            )
            .status,
            201
        );

        let root_get = node.handle_rest_request(
            RestRequest::new(RestMethod::Get, "/_mget").with_json_body(serde_json::json!({
                "docs": [
                    {"_index":"logs-mget-000001","_id":"doc-1"},
                    {"_index":"metrics-mget-000001","_id":"doc-2"}
                ]
            })),
        );
        assert_eq!(root_get.status, 200);
        assert_eq!(root_get.body["docs"][0]["found"], Value::Bool(true));
        assert_eq!(root_get.body["docs"][0]["_source"]["message"], "log-1");
        assert_eq!(root_get.body["docs"][1]["_source"]["message"], "metric-2");

        let root_post = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_mget").with_json_body(serde_json::json!({
                "docs": [
                    {"_index":"logs-mget-000001","_id":"doc-1"},
                    {"_index":"logs-mget-000001","_id":"missing-doc"}
                ]
            })),
        );
        assert_eq!(root_post.status, 200);
        assert_eq!(root_post.body["docs"][0]["found"], Value::Bool(true));
        assert_eq!(root_post.body["docs"][1]["found"], Value::Bool(false));

        let targeted_get = node.handle_rest_request(
            RestRequest::new(RestMethod::Get, "/logs-mget-000001/_mget").with_json_body(
                serde_json::json!({
                    "ids": ["doc-1", "missing-doc"]
                }),
            ),
        );
        assert_eq!(targeted_get.status, 200);
        assert_eq!(targeted_get.body["docs"][0]["_index"], "logs-mget-000001");
        assert_eq!(targeted_get.body["docs"][0]["found"], Value::Bool(true));
        assert_eq!(targeted_get.body["docs"][1]["found"], Value::Bool(false));

        let targeted_post = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/logs-mget-000001/_mget").with_json_body(
                serde_json::json!({
                    "docs": [{"_id":"doc-1"}]
                }),
            ),
        );
        assert_eq!(targeted_post.status, 200);
        assert_eq!(targeted_post.body["docs"][0]["_source"]["message"], "log-1");
    }

