    #[test]
    fn search_shards_routes_serve_global_and_targeted_shapes_for_get_and_post() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-search-shards-000001")
                .with_json_body(serde_json::json!({})),
        );
        node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/metrics-search-shards-000001")
                .with_json_body(serde_json::json!({})),
        );

        for (method, path, expected_groups) in [
            (RestMethod::Get, "/_search_shards", 2usize),
            (RestMethod::Post, "/_search_shards", 2usize),
            (
                RestMethod::Get,
                "/logs-search-shards-*/_search_shards",
                1usize,
            ),
            (
                RestMethod::Post,
                "/logs-search-shards-*/_search_shards",
                1usize,
            ),
        ] {
            let request = if method == RestMethod::Post {
                RestRequest::new(method, path)
                    .with_json_body(serde_json::json!({"query": {"match_all": {}}}))
            } else {
                RestRequest::new(method, path)
            };
            let response = node.handle_rest_request(request);
            assert_eq!(response.status, 200, "path {path}");
            assert!(response.body["nodes"].is_object(), "path {path}");
            assert!(response.body["indices"].is_object(), "path {path}");
            assert_eq!(
                response.body["shards"]
                    .as_array()
                    .map(Vec::len)
                    .unwrap_or_default(),
                expected_groups,
                "path {path}"
            );
            assert!(
                response.body["shards"][0][0].get("searchOnly").is_none(),
                "path {path}"
            );
        }
    }

    #[test]
    fn cluster_allocation_explain_routes_match_bounded_get_and_post_shapes() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        let create_index = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-stateful-probe").with_json_body(
                serde_json::json!({
                    "settings": {
                        "index.number_of_shards": 1,
                        "index.number_of_replicas": 1
                    }
                }),
            ),
        );
        assert_eq!(create_index.status, 200);

        let get_response = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/allocation/explain",
        ));
        assert_eq!(get_response.status, 200);
        assert_eq!(
            get_response.body["current_state"],
            Value::String("unassigned".to_string())
        );

        let post_response = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_cluster/allocation/explain").with_json_body(
                serde_json::json!({
                    "index": "logs-stateful-probe",
                    "shard": 0,
                    "primary": true
                }),
            ),
        );
        assert_eq!(post_response.status, 200);
        assert_eq!(
            post_response.body["index"],
            Value::String("logs-stateful-probe".to_string())
        );
        assert_eq!(post_response.body["primary"], Value::Bool(true));
        assert_eq!(
            post_response.body["current_state"],
            Value::String("started".to_string())
        );
        assert_eq!(
            post_response.body["current_node"]["weight_ranking"],
            Value::Number(1.into())
        );
        assert!(post_response.body["current_node"]["roles"].is_array());
        assert_eq!(
            post_response.body["can_rebalance_cluster"],
            Value::String("no".to_string())
        );
        assert_eq!(
            post_response.body["can_move_to_other_node"],
            Value::String("no".to_string())
        );
        let post_with_selector = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/_cluster/allocation/explain?include_yes_decisions=true&include_disk_info=true",
            )
            .with_json_body(serde_json::json!({
                "index": "logs-stateful-probe",
                "shard": 0,
                "primary": true
            })),
        );
        assert_eq!(post_with_selector.status, 200);
        assert_eq!(
            post_with_selector.body["index"],
            Value::String("logs-stateful-probe".to_string())
        );
        let invalid_selector = node.handle_rest_request(
            RestRequest::new(
                RestMethod::Post,
                "/_cluster/allocation/explain?include_yes_decisions=maybe",
            )
            .with_json_body(serde_json::json!({
                "index": "logs-stateful-probe",
                "shard": 0,
                "primary": true
            })),
        );
        assert_eq!(invalid_selector.status, 400);
        assert_eq!(
            invalid_selector.body["error"]["type"],
            "illegal_argument_exception"
        );
        assert!(post_response.body["move_explanation"].as_str().is_some());
        assert!(post_response.body["cluster_info"]["nodes"].is_object());
        assert!(post_response.body["cluster_info"]["shard_sizes"].is_object());
        assert_eq!(
            get_response.body["node_allocation_decisions"][0]["deciders"][0]["decision"],
            Value::String("NO".to_string())
        );
        assert_eq!(get_response.body["configured_delay"], "0ms");
        assert_eq!(get_response.body["remaining_delay_in_millis"], 0);
        assert_eq!(
            get_response.body["unassigned_info"]["failed_allocation_attempts"],
            0
        );
        assert!(
            get_response.body["node_allocation_decisions"][0]["deciders"][0]["explanation"]
                .as_str()
                .unwrap_or_default()
                .contains("bounded development allocation explain")
        );

        let no_unassigned = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        assert_eq!(
            no_unassigned
                .handle_rest_request(
                    RestRequest::new(RestMethod::Put, "/logs-no-unassigned").with_json_body(
                        serde_json::json!({
                            "settings": {
                                "index.number_of_shards": 1,
                                "index.number_of_replicas": 0
                            }
                        }),
                    ),
                )
                .status,
            200
        );
        let no_unassigned_get = no_unassigned.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/allocation/explain",
        ));
        assert_eq!(no_unassigned_get.status, 400);
        assert_eq!(
            no_unassigned_get.body["error"]["type"],
            "illegal_argument_exception"
        );
    }

    #[test]
    fn cluster_state_route_surfaces_index_metadata_and_routing_entries() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            nodes: vec![DevelopmentClusterNode {
                node_id: "node-a".to_string(),
                node_name: "steel-node-a".to_string(),
                http_address: Some("127.0.0.1:9200".to_string()),
                transport_address: "127.0.0.1:9300".to_string(),
                roles: vec!["cluster_manager".to_string(), "data".to_string()],
                local: true,
            }],
            coordination: None,
        });

        let create_index = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/logs-cluster-state-000001").with_json_body(
                serde_json::json!({
                    "settings": {
                        "index.number_of_shards": 1,
                        "index.number_of_replicas": 1
                    },
                    "mappings": {
                        "properties": {
                            "tenant": { "type": "keyword" }
                        }
                    }
                }),
            ),
        );
        assert_eq!(create_index.status, 200);

        {
            let mut manifest = node
                .metadata_manifest_state
                .lock()
                .expect("metadata manifest state lock poisoned");
            manifest["indices"]["logs-cluster-state-000001"]["aliases"] = serde_json::json!({
                "logs-cluster-state-alias": {}
            });
        }

        let state = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_cluster/state"));
        assert_eq!(state.status, 200);
        assert_eq!(state.body["cluster_name"], "steelsearch-dev");
        assert_eq!(
            state.body["metadata"]["indices"]["logs-cluster-state-000001"]["settings"]["index"]
                ["number_of_replicas"],
            "1"
        );
        assert_eq!(
            state.body["metadata"]["indices"]["logs-cluster-state-000001"]["mappings"]
                ["properties"]["tenant"]["type"],
            "keyword"
        );
        assert_eq!(
            state.body["metadata"]["indices"]["logs-cluster-state-000001"]["aliases"],
            serde_json::json!(["logs-cluster-state-alias"])
        );
        assert_eq!(
            state.body["routing_table"]["indices"]["logs-cluster-state-000001"]["shards"]["0"][0]
                ["state"],
            "STARTED"
        );
        assert_eq!(
            state.body["routing_table"]["indices"]["logs-cluster-state-000001"]["shards"]["0"][0]
                ["allocation_id"]["id"],
            "logs-cluster-state-000001-p-0"
        );
        assert!(
            state.body["routing_table"]["indices"]["logs-cluster-state-000001"]["shards"]["0"][0]
                ["recovery_source"]
                .is_null()
        );
        assert_eq!(
            state.body["routing_nodes"]["nodes"]["node-a"][0]["index"],
            "logs-cluster-state-000001"
        );
        assert_eq!(
            state.body["routing_nodes"]["nodes"]["node-a"][0]["allocation_id"],
            "logs-cluster-state-000001-p-0"
        );
    }

    #[test]
    fn cluster_state_route_validates_wait_and_timeout_params_like_opensearch() {
        let node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });

        for (path, expected_reason) in [
            (
                "/_cluster/state?local=maybe",
                "Failed to parse value [maybe] as only [true] or [false] are allowed.",
            ),
            (
                "/_cluster/state?cluster_manager_timeout=soon",
                "failed to parse setting [cluster_manager_timeout] with value [soon] as a time value: unit is missing or unrecognized",
            ),
            (
                "/_cluster/state?master_timeout=soon",
                "failed to parse setting [master_timeout] with value [soon] as a time value: unit is missing or unrecognized",
            ),
            (
                "/_cluster/state?wait_for_timeout=soon",
                "failed to parse setting [wait_for_timeout] with value [soon] as a time value: unit is missing or unrecognized",
            ),
            (
                "/_cluster/state?wait_for_metadata_version=abc",
                "Failed to parse long parameter [wait_for_metadata_version] with value [abc]",
            ),
        ] {
            let response = node.handle_rest_request(RestRequest::new(RestMethod::Get, path));
            assert_eq!(response.status, 400, "{path}");
            assert_eq!(response.body["error"]["type"], "illegal_argument_exception");
            assert_eq!(response.body["error"]["reason"], expected_reason, "{path}");
        }

        let duplicate_timeout = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/state?master_timeout=30s&cluster_manager_timeout=30s",
        ));
        assert_eq!(duplicate_timeout.status, 400);
        assert_eq!(duplicate_timeout.body["error"]["type"], "parse_exception");
        assert_eq!(
            duplicate_timeout.body["error"]["reason"],
            "Please only use one of the request parameters [master_timeout, cluster_manager_timeout]."
        );

        let waited = node.handle_rest_request(RestRequest::new(
            RestMethod::Get,
            "/_cluster/state?wait_for_metadata_version=1&wait_for_timeout=1s",
        ));
        assert_eq!(waited.status, 200);
        assert_eq!(waited.body["wait_for_timed_out"], Value::Bool(false));
    }

    #[test]
    fn cluster_pending_tasks_route_surfaces_task_metadata_visibility() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            nodes: vec![DevelopmentClusterNode {
                node_id: "node-a".to_string(),
                node_name: "steel-node-a".to_string(),
                http_address: Some("127.0.0.1:9200".to_string()),
                transport_address: "127.0.0.1:9300".to_string(),
                roles: vec!["cluster_manager".to_string(), "data".to_string()],
                local: true,
            }],
            coordination: None,
        });
        *node
            .task_queue_state
            .lock()
            .expect("task queue state lock poisoned") =
            Some(PersistedClusterManagerTaskQueueState {
                pending: vec![ClusterManagerTaskRecord {
                    task_id: 7,
                    task: ClusterManagerTask {
                        source: "reroute shards".to_string(),
                        kind: ClusterManagerTaskKind::Reroute,
                    },
                    state: ClusterManagerTaskState::Queued,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                in_flight: vec![ClusterManagerTaskRecord {
                    task_id: 8,
                    task: ClusterManagerTask {
                        source: "publish state".to_string(),
                        kind: ClusterManagerTaskKind::Reroute,
                    },
                    state: ClusterManagerTaskState::InFlight,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                ..Default::default()
            });

        let response =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_cluster/pending_tasks"));
        assert_eq!(response.status, 200);
        let tasks = response.body["tasks"]
            .as_array()
            .expect("pending tasks array");
        assert_eq!(tasks.len(), 2);
        assert_eq!(tasks[0]["node"], "node-a");
        assert_eq!(tasks[0]["node_name"], "steel-node-a");
        assert_eq!(tasks[0]["action"], "cluster:admin/reroute");
        assert!(tasks[0]["description"].as_str().is_some());
        assert_eq!(tasks[0]["priority"], "URGENT");
        assert_eq!(tasks[0]["time_in_queue_millis"], 0);
        assert_eq!(tasks[0]["executing"], false);
        assert_eq!(tasks[1]["executing"], true);
    }

    #[test]
    fn cluster_health_tasks_and_cat_pending_tasks_share_runtime_queue_depth() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            nodes: vec![DevelopmentClusterNode {
                node_id: "node-a".to_string(),
                node_name: "steel-node-a".to_string(),
                http_address: Some("127.0.0.1:9200".to_string()),
                transport_address: "127.0.0.1:9300".to_string(),
                roles: vec!["cluster_manager".to_string(), "data".to_string()],
                local: true,
            }],
            coordination: None,
        });
        *node
            .task_queue_state
            .lock()
            .expect("task queue state lock poisoned") =
            Some(PersistedClusterManagerTaskQueueState {
                pending: vec![
                    ClusterManagerTaskRecord {
                        task_id: 21,
                        task: ClusterManagerTask {
                            source: "queued reroute".to_string(),
                            kind: ClusterManagerTaskKind::Reroute,
                        },
                        state: ClusterManagerTaskState::Queued,
                        parent_task_id: None,
                        headers: BTreeMap::new(),
                        failure_reason: None,
                    },
                    ClusterManagerTaskRecord {
                        task_id: 22,
                        task: ClusterManagerTask {
                            source: "queued mapping update".to_string(),
                            kind: ClusterManagerTaskKind::Reroute,
                        },
                        state: ClusterManagerTaskState::Queued,
                        parent_task_id: None,
                        headers: BTreeMap::new(),
                        failure_reason: None,
                    },
                ],
                in_flight: vec![ClusterManagerTaskRecord {
                    task_id: 23,
                    task: ClusterManagerTask {
                        source: "publishing state".to_string(),
                        kind: ClusterManagerTaskKind::Reroute,
                    },
                    state: ClusterManagerTaskState::InFlight,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                ..Default::default()
            });

        let health =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_cluster/health"));
        assert_eq!(health.status, 200);
        assert_eq!(health.body["number_of_pending_tasks"], 3);

        let pending =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_cluster/pending_tasks"));
        assert_eq!(pending.status, 200);
        assert_eq!(
            pending.body["tasks"]
                .as_array()
                .expect("pending tasks array")
                .len(),
            3
        );

        let tasks = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_tasks"));
        assert_eq!(tasks.status, 200);
        let node_tasks = tasks.body["nodes"]["node-a"]["tasks"]
            .as_object()
            .expect("node task map");
        assert_eq!(node_tasks.len(), 3);
        assert!(node_tasks.contains_key("node-a:21"));
        assert!(node_tasks.contains_key("node-a:23"));

        let mut cat_request = RestRequest::new(RestMethod::Get, "/_cat/pending_tasks");
        cat_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        let cat = node.handle_rest_request(cat_request);
        assert_eq!(cat.status, 200);
        let cat_rows = cat.body.as_array().expect("cat pending task rows");
        assert_eq!(cat_rows.len(), 3);
        assert_eq!(cat_rows[0]["insertOrder"], "21");
        assert_eq!(cat_rows[2]["executing"], "true");

        let mut thread_pool_request =
            RestRequest::new(RestMethod::Get, "/_cat/thread_pool/management");
        thread_pool_request
            .query_params
            .insert("format".to_string(), "json".to_string());
        let thread_pool = node.handle_rest_request(thread_pool_request);
        assert_eq!(thread_pool.status, 200);
        let thread_pool_rows = thread_pool.body.as_array().expect("thread pool rows");
        assert_eq!(thread_pool_rows.len(), 1);
        assert_eq!(thread_pool_rows[0]["active"], "1");
        assert_eq!(thread_pool_rows[0]["queue"], "2");

        let stats = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_nodes/stats"));
        assert_eq!(stats.status, 200);
        let first_node = stats.body["nodes"]
            .as_object()
            .and_then(|nodes| nodes.values().next())
            .expect("node stats body to contain one node");
        assert_eq!(first_node["thread_pool"]["management"]["active"], 1);
        assert_eq!(first_node["thread_pool"]["management"]["queue"], 2);
    }

    #[test]
    fn empty_and_non_empty_runtime_queue_visibility_transitions_are_distinct() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            nodes: vec![DevelopmentClusterNode {
                node_id: "node-a".to_string(),
                node_name: "steel-node-a".to_string(),
                http_address: Some("127.0.0.1:9200".to_string()),
                transport_address: "127.0.0.1:9300".to_string(),
                roles: vec!["cluster_manager".to_string(), "data".to_string()],
                local: true,
            }],
            coordination: None,
        });

        assert_runtime_queue_visibility(
            &node,
            0,
            0,
            0,
            &[],
            "empty runtime queue should stay invisible as pending work",
        );

        *node
            .task_queue_state
            .lock()
            .expect("task queue state lock poisoned") =
            Some(PersistedClusterManagerTaskQueueState {
                pending: vec![ClusterManagerTaskRecord {
                    task_id: 631,
                    task: ClusterManagerTask {
                        source: "queued visibility transition probe".to_string(),
                        kind: ClusterManagerTaskKind::Reroute,
                    },
                    state: ClusterManagerTaskState::Queued,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                in_flight: vec![ClusterManagerTaskRecord {
                    task_id: 632,
                    task: ClusterManagerTask {
                        source: "in-flight visibility transition probe".to_string(),
                        kind: ClusterManagerTaskKind::BackgroundWorker {
                            worker: "maintenance-refresh".to_string(),
                            action: "indices:admin/refresh".to_string(),
                        },
                    },
                    state: ClusterManagerTaskState::InFlight,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                ..Default::default()
            });

        assert_runtime_queue_visibility(
            &node,
            2,
            1,
            1,
            &["node-a:631", "node-a:632"],
            "non-empty runtime queue should surface queued and in-flight work",
        );

        *node
            .task_queue_state
            .lock()
            .expect("task queue state lock poisoned") =
            Some(PersistedClusterManagerTaskQueueState {
                acknowledged: vec![ClusterManagerTaskRecord {
                    task_id: 631,
                    task: ClusterManagerTask {
                        source: "queued visibility transition probe".to_string(),
                        kind: ClusterManagerTaskKind::Reroute,
                    },
                    state: ClusterManagerTaskState::Acknowledged,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                failed: vec![ClusterManagerTaskRecord {
                    task_id: 632,
                    task: ClusterManagerTask {
                        source: "in-flight visibility transition probe".to_string(),
                        kind: ClusterManagerTaskKind::BackgroundWorker {
                            worker: "maintenance-refresh".to_string(),
                            action: "indices:admin/refresh".to_string(),
                        },
                    },
                    state: ClusterManagerTaskState::Failed,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: Some("simulated drain failure".to_string()),
                }],
                ..Default::default()
            });

        assert_runtime_queue_visibility(
            &node,
            0,
            0,
            0,
            &["node-a:631", "node-a:632"],
            "terminal records should remain task-visible without pending depth",
        );
    }

    fn assert_runtime_queue_visibility(
        node: &SteelNode,
        expected_pending: usize,
        expected_active: u64,
        expected_queued: u64,
        expected_task_ids: &[&str],
        context: &str,
    ) {
        let health =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_cluster/health"));
        assert_eq!(health.status, 200, "{context}");
        assert_eq!(
            health.body["number_of_pending_tasks"],
            serde_json::json!(expected_pending),
            "{context}"
        );

        let pending =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_cluster/pending_tasks"));
        assert_eq!(pending.status, 200, "{context}");
        assert_eq!(
            pending.body["tasks"]
                .as_array()
                .expect("pending tasks array")
                .len(),
            expected_pending,
            "{context}"
        );

        let mut cat_pending = RestRequest::new(RestMethod::Get, "/_cat/pending_tasks");
        cat_pending
            .query_params
            .insert("format".to_string(), "json".to_string());
        let cat_pending = node.handle_rest_request(cat_pending);
        assert_eq!(cat_pending.status, 200, "{context}");
        assert_eq!(
            cat_pending
                .body
                .as_array()
                .expect("cat pending tasks array")
                .len(),
            expected_pending,
            "{context}"
        );

        let mut cat_thread_pool = RestRequest::new(RestMethod::Get, "/_cat/thread_pool/management");
        cat_thread_pool
            .query_params
            .insert("format".to_string(), "json".to_string());
        let cat_thread_pool = node.handle_rest_request(cat_thread_pool);
        assert_eq!(cat_thread_pool.status, 200, "{context}");
        let thread_pool_rows = cat_thread_pool
            .body
            .as_array()
            .expect("cat thread pool rows");
        assert_eq!(thread_pool_rows.len(), 1, "{context}");
        assert_eq!(
            thread_pool_rows[0]["active"],
            Value::String(expected_active.to_string()),
            "{context}"
        );
        assert_eq!(
            thread_pool_rows[0]["queue"],
            Value::String(expected_queued.to_string()),
            "{context}"
        );

        let stats = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_nodes/stats"));
        assert_eq!(stats.status, 200, "{context}");
        assert_eq!(
            stats.body["nodes"]["node-a"]["thread_pool"]["management"]["active"],
            serde_json::json!(expected_active),
            "{context}"
        );
        assert_eq!(
            stats.body["nodes"]["node-a"]["thread_pool"]["management"]["queue"],
            serde_json::json!(expected_queued),
            "{context}"
        );

        let tasks = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_tasks"));
        assert_eq!(tasks.status, 200, "{context}");
        let task_map = tasks.body["nodes"]["node-a"]["tasks"]
            .as_object()
            .map(|tasks| {
                tasks
                    .iter()
                    .filter(|(_, task)| {
                        task.get("action").and_then(Value::as_str)
                            != Some("cluster:monitor/tasks/lists")
                    })
                    .map(|(task_id, task)| (task_id.clone(), task.clone()))
                    .collect::<serde_json::Map<_, _>>()
            });
        for task_id in expected_task_ids {
            let task_map = task_map.as_ref().expect("task map");
            assert!(
                task_map.contains_key(*task_id),
                "{context}: missing {task_id}"
            );
        }
        if expected_task_ids.is_empty() {
            assert!(
                task_map.as_ref().map_or(true, |tasks| tasks.is_empty()),
                "{context}"
            );
        }
    }

    #[test]
    fn multi_node_task_queue_visibility_uses_remote_node_metadata() {
        let mut node = SteelNode::new(NodeInfo {
            name: "steel-node-a".to_string(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
        });
        node.cluster_view = Some(DevelopmentClusterView {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            nodes: vec![
                DevelopmentClusterNode {
                    node_id: "node-a".to_string(),
                    node_name: "steel-node-a".to_string(),
                    http_address: Some("127.0.0.1:9200".to_string()),
                    transport_address: "127.0.0.1:9300".to_string(),
                    roles: vec!["cluster_manager".to_string(), "data".to_string()],
                    local: true,
                },
                DevelopmentClusterNode {
                    node_id: "node-b".to_string(),
                    node_name: "steel-node-b".to_string(),
                    http_address: Some("127.0.0.1:9201".to_string()),
                    transport_address: "127.0.0.1:9301".to_string(),
                    roles: vec!["data".to_string()],
                    local: false,
                },
            ],
            coordination: None,
        });
        *node
            .task_queue_state
            .lock()
            .expect("task queue state lock poisoned") =
            Some(PersistedClusterManagerTaskQueueState {
                task_node_ids: BTreeMap::from([
                    (410, "node-a".to_string()),
                    (420, "node-b".to_string()),
                    (421, "node-b".to_string()),
                ]),
                pending: vec![
                    ClusterManagerTaskRecord {
                        task_id: 410,
                        task: ClusterManagerTask {
                            source: "local queued reroute".to_string(),
                            kind: ClusterManagerTaskKind::Reroute,
                        },
                        state: ClusterManagerTaskState::Queued,
                        parent_task_id: None,
                        headers: BTreeMap::new(),
                        failure_reason: None,
                    },
                    ClusterManagerTaskRecord {
                        task_id: 420,
                        task: ClusterManagerTask {
                            source: "remote queued shard move".to_string(),
                            kind: ClusterManagerTaskKind::Reroute,
                        },
                        state: ClusterManagerTaskState::Queued,
                        parent_task_id: None,
                        headers: BTreeMap::new(),
                        failure_reason: None,
                    },
                ],
                in_flight: vec![ClusterManagerTaskRecord {
                    task_id: 421,
                    task: ClusterManagerTask {
                        source: "remote executing recovery".to_string(),
                        kind: ClusterManagerTaskKind::BackgroundWorker {
                            worker: "peer-recovery".to_string(),
                            action: "indices:data/write/recovery".to_string(),
                        },
                    },
                    state: ClusterManagerTaskState::InFlight,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                ..Default::default()
            });
        node.record_remote_transport_queue_snapshot(
            "node-b",
            RemoteTransportQueueSnapshot {
                active: 1,
                queued: 1,
                rejected: 1,
                completed: 2,
            },
        );

        let health =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_cluster/health"));
        assert_eq!(health.status, 200);
        assert_eq!(health.body["number_of_pending_tasks"], 3);

        let pending =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_cluster/pending_tasks"));
        assert_eq!(pending.status, 200);
        let pending_tasks = pending.body["tasks"]
            .as_array()
            .expect("pending tasks array");
        assert_eq!(pending_tasks.len(), 3);
        let remote_queued = pending_tasks
            .iter()
            .find(|task| task["id"] == 420)
            .expect("remote queued task");
        assert_eq!(remote_queued["node"], "node-b");
        assert_eq!(remote_queued["node_name"], "steel-node-b");
        assert_eq!(remote_queued["executing"], Value::Bool(false));
        let remote_in_flight = pending_tasks
            .iter()
            .find(|task| task["id"] == 421)
            .expect("remote in-flight task");
        assert_eq!(remote_in_flight["node"], "node-b");
        assert_eq!(remote_in_flight["node_name"], "steel-node-b");
        assert_eq!(remote_in_flight["executing"], Value::Bool(true));

        let tasks = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_tasks"));
        assert_eq!(tasks.status, 200);
        assert_eq!(
            tasks.body["nodes"]["node-a"]["name"],
            Value::String("steel-node-a".to_string())
        );
        assert_eq!(
            tasks.body["nodes"]["node-b"]["name"],
            Value::String("steel-node-b".to_string())
        );
        assert!(tasks.body["nodes"]["node-a"]["tasks"]
            .get("node-a:410")
            .is_some());
        assert!(tasks.body["nodes"]["node-b"]["tasks"]
            .get("node-b:420")
            .is_some());
        assert_eq!(
            tasks.body["nodes"]["node-b"]["tasks"]["node-b:421"]["status"]["background_worker"],
            Value::String("peer-recovery".to_string())
        );

        let mut cat_pending = RestRequest::new(RestMethod::Get, "/_cat/pending_tasks");
        cat_pending
            .query_params
            .insert("format".to_string(), "json".to_string());
        let cat_pending = node.handle_rest_request(cat_pending);
        assert_eq!(cat_pending.status, 200);
        let rows = cat_pending.body.as_array().expect("cat pending task rows");
        assert_eq!(rows.len(), 3);
        assert!(rows
            .iter()
            .any(|row| row["id"] == "420" && row["executing"] == "false"));
        assert!(rows
            .iter()
            .any(|row| row["id"] == "421" && row["executing"] == "true"));

        let mut cat_thread_pool = RestRequest::new(RestMethod::Get, "/_cat/thread_pool/management");
        cat_thread_pool
            .query_params
            .insert("format".to_string(), "json".to_string());
        let cat_thread_pool = node.handle_rest_request(cat_thread_pool);
        assert_eq!(cat_thread_pool.status, 200);
        let thread_pool_rows = cat_thread_pool
            .body
            .as_array()
            .expect("cat thread pool rows");
        assert_eq!(thread_pool_rows.len(), 2);
        let local_row = thread_pool_rows
            .iter()
            .find(|row| row["node_id"] == "node-a")
            .expect("local management row");
        let remote_row = thread_pool_rows
            .iter()
            .find(|row| row["node_id"] == "node-b")
            .expect("remote management row");
        assert_eq!(local_row["node_name"], "steel-node-a");
        assert_eq!(local_row["active"], "0");
        assert_eq!(local_row["queue"], "1");
        assert_eq!(remote_row["node_name"], "steel-node-b");
        assert_eq!(remote_row["active"], "1");
        assert_eq!(remote_row["queue"], "1");

        let mut cat_remote_transport =
            RestRequest::new(RestMethod::Get, "/_cat/thread_pool/remote_transport");
        cat_remote_transport
            .query_params
            .insert("format".to_string(), "json".to_string());
        let cat_remote_transport = node.handle_rest_request(cat_remote_transport);
        assert_eq!(cat_remote_transport.status, 200);
        let remote_transport_rows = cat_remote_transport
            .body
            .as_array()
            .expect("remote transport thread pool rows");
        assert_eq!(remote_transport_rows.len(), 2);
        let remote_transport_row = remote_transport_rows
            .iter()
            .find(|row| row["node_id"] == "node-b")
            .expect("remote transport row");
        assert_eq!(remote_transport_row["node_name"], "steel-node-b");
        assert_eq!(remote_transport_row["active"], "1");
        assert_eq!(remote_transport_row["queue"], "1");
        assert_eq!(remote_transport_row["rejected"], "1");
        assert_eq!(remote_transport_row["completed"], "2");

        for index in ["multi-node-submit-source", "multi-node-submit-dest"] {
            let create = node.handle_rest_request(
                RestRequest::new(RestMethod::Put, format!("/{index}"))
                    .with_json_body(serde_json::json!({})),
            );
            assert_eq!(create.status, 200);
        }
        let put_doc = node.handle_rest_request(
            RestRequest::new(RestMethod::Put, "/multi-node-submit-source/_doc/doc-1")
                .with_json_body(serde_json::json!({"message": "multi-node overload"})),
        );
        assert_eq!(put_doc.status, 201);

        {
            let mut counters = node
                .runtime_thread_pool_counters
                .lock()
                .expect("runtime thread pool counters lock poisoned");
            counters.insert(
                "task_submission".to_string(),
                RuntimeThreadPoolCounters {
                    active: 1,
                    queue: 1000,
                    rejected: 0,
                    completed: 0,
                },
            );
        }
        let submit = node.handle_rest_request(
            RestRequest::new(RestMethod::Post, "/_reindex").with_json_body(serde_json::json!({
                "source": {"index": "multi-node-submit-source"},
                "dest": {"index": "multi-node-submit-dest"}
            })),
        );
        assert_eq!(submit.status, 429);
        assert_eq!(
            submit.body["error"]["type"],
            "es_rejected_execution_exception"
        );

        let stats = node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_nodes/stats"));
        assert_eq!(stats.status, 200);
        assert_eq!(
            stats.body["nodes"]["node-a"]["thread_pool"]["management"]["active"],
            0
        );
        assert_eq!(
            stats.body["nodes"]["node-a"]["thread_pool"]["management"]["queue"],
            1
        );
        assert_eq!(
            stats.body["nodes"]["node-a"]["thread_pool"]["task_submission"]["rejected"],
            1
        );
        assert_eq!(
            stats.body["nodes"]["node-b"]["thread_pool"]["management"]["active"],
            1
        );
        assert_eq!(
            stats.body["nodes"]["node-b"]["thread_pool"]["management"]["queue"],
            1
        );
        assert_eq!(
            stats.body["nodes"]["node-b"]["thread_pool"]["task_submission"]["rejected"],
            0
        );
        assert_eq!(
            stats.body["nodes"]["node-b"]["thread_pool"]["remote_transport"]["active"],
            1
        );
        assert_eq!(
            stats.body["nodes"]["node-b"]["thread_pool"]["remote_transport"]["queue"],
            1
        );
        assert_eq!(
            stats.body["nodes"]["node-b"]["thread_pool"]["remote_transport"]["rejected"],
            1
        );
        assert_eq!(
            stats.body["nodes"]["node-b"]["thread_pool"]["remote_transport"]["completed"],
            2
        );

        let tasks_after_reject =
            node.handle_rest_request(RestRequest::new(RestMethod::Get, "/_tasks"));
        assert_eq!(tasks_after_reject.status, 200);
        assert_eq!(
            tasks_after_reject.body["nodes"]["node-b"]["name"],
            Value::String("steel-node-b".to_string())
        );
        assert!(tasks_after_reject.body["nodes"]["node-b"]["tasks"]
            .get("node-b:420")
            .is_some());
    }

