    #[test]
    fn join_peer_replaces_placeholder_seed_with_actual_identity() {
        let discovery = DiscoveryConfig {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            local_node_name: "steel-a".to_string(),
            local_version: OPENSEARCH_3_7_0_TRANSPORT,
            min_compatible_version: OPENSEARCH_3_7_0_TRANSPORT,
            cluster_manager_eligible: true,
            local_membership_epoch: 1,
            seed_peers: vec![DiscoveryPeer {
                node_id: "seed-2-127-0-0-1-19302".to_string(),
                node_name: "seed-2".to_string(),
                host: "127.0.0.1".to_string(),
                port: 19302,
                cluster_name: "steelsearch-dev".to_string(),
                cluster_uuid: "cluster-uuid".to_string(),
                version: OPENSEARCH_3_7_0_TRANSPORT,
                cluster_manager_eligible: true,
                membership_epoch: 1,
            }],
        };
        let mut coordination = ClusterCoordinationState::bootstrap(&discovery);

        coordination
            .join_peer(
                &discovery,
                DiscoveryPeer {
                    node_id: "node-b".to_string(),
                    node_name: "steel-b".to_string(),
                    host: "127.0.0.1".to_string(),
                    port: 19302,
                    cluster_name: "steelsearch-dev".to_string(),
                    cluster_uuid: "cluster-uuid".to_string(),
                    version: OPENSEARCH_3_7_0_TRANSPORT,
                    cluster_manager_eligible: true,
                    membership_epoch: 2,
                },
            )
            .unwrap();

        assert!(coordination
            .joined_nodes()
            .iter()
            .any(|peer| peer.node_id == "node-b" && peer.node_name == "steel-b"));
        assert!(!coordination
            .joined_nodes()
            .iter()
            .any(|peer| peer.node_id == "seed-2-127-0-0-1-19302"));
        assert!(!coordination
            .last_accepted_voting_configuration
            .contains("node-b"));
        assert!(!coordination
            .last_accepted_voting_configuration
            .contains("seed-2-127-0-0-1-19302"));
        assert!(coordination
            .pending_voting_config_additions
            .contains("node-b"));

        coordination.apply_voting_config_reconfiguration_proposals();

        assert!(coordination
            .last_accepted_voting_configuration
            .contains("node-b"));
        assert!(coordination
            .last_committed_voting_configuration
            .contains("node-b"));
        assert!(!coordination
            .pending_voting_config_additions
            .contains("node-b"));
    }

    #[test]
    fn publication_validation_events_record_invalid_address_failures() {
        let config = DiscoveryConfig {
            cluster_name: "steelsearch-dev".to_string(),
            cluster_uuid: "cluster-uuid".to_string(),
            local_node_id: "node-a".to_string(),
            local_node_name: "steel-a".to_string(),
            local_version: OPENSEARCH_3_7_0_TRANSPORT,
            min_compatible_version: OPENSEARCH_3_7_0_TRANSPORT,
            cluster_manager_eligible: true,
            local_membership_epoch: 1,
            seed_peers: Vec::new(),
        };
        let peer = DiscoveryPeer {
            node_id: "node-b".to_string(),
            node_name: "steel-b".to_string(),
            host: "not a socket address".to_string(),
            port: 19301,
            cluster_name: config.cluster_name.clone(),
            cluster_uuid: config.cluster_uuid.clone(),
            version: OPENSEARCH_3_7_0_TRANSPORT,
            cluster_manager_eligible: true,
            membership_epoch: 1,
        };

        let proposal = collect_live_publication_acknowledgement_details(
            &config,
            std::slice::from_ref(&peer),
            "cluster-uuid-dev-state-1",
            1,
            1,
            Duration::from_millis(5),
        );
        assert_eq!(
            proposal.validation_events,
            vec![PublicationValidationEvent {
                phase: "proposal".to_string(),
                node_id: "node-b".to_string(),
                step: "connect".to_string(),
                status: "failed".to_string(),
                reason: Some("invalid publication transport address".to_string()),
            }]
        );
        assert_eq!(
            proposal.proposal_transport_failures,
            vec![(
                "node-b".to_string(),
                "invalid publication transport address".to_string(),
            )]
        );

        let apply = collect_live_publication_apply_details(
            &config,
            std::slice::from_ref(&peer),
            "cluster-uuid-dev-state-1",
            1,
            1,
            Duration::from_millis(5),
        );
        assert_eq!(
            apply.validation_events,
            vec![PublicationValidationEvent {
                phase: "apply".to_string(),
                node_id: "node-b".to_string(),
                step: "connect".to_string(),
                status: "failed".to_string(),
                reason: Some("invalid publication apply transport address".to_string()),
            }]
        );
        assert_eq!(
            apply.apply_transport_failures,
            vec![(
                "node-b".to_string(),
                "invalid publication apply transport address".to_string(),
            )]
        );
    }

